CARDIO.register({"item":"225","meta":{"num":225,"short":"AOMI / anévrismes","title":"Artériopathie de l'aorte, des artères viscérales et des membres inférieurs ; anévrismes","section":"I","chapter":7,"pages":"164-190","sdd":[{"num":3,"label":"Distension abdominale"},{"num":4,"label":"Douleur abdominale"},{"num":15,"label":"Anomalies de couleur des extrémités"},{"num":19,"label":"Découverte d'un souffle vasculaire"},{"num":30,"label":"Dénutrition/malnutrition"},{"num":42,"label":"Hypertension artérielle"},{"num":63,"label":"Troubles sexuels et troubles de l'érection"},{"num":66,"label":"Apparition d'une difficulté à la marche"},{"num":68,"label":"Boiterie"},{"num":69,"label":"Claudication intermittente d'un membre"},{"num":71,"label":"Douleur d'un membre (supérieur ou inférieur)"},{"num":92,"label":"Ulcère cutané"},{"num":195,"label":"Analyse du bilan lipidique"},{"num":231,"label":"Demande d'un examen d'imagerie"},{"num":232,"label":"Demande d'explication d'un patient sur le déroulement, les risques et les bénéfices attendus d'un examen d'imagerie"},{"num":248,"label":"Prescription et suivi d'un traitement par anticoagulant et/ou antiagrégant"},{"num":252,"label":"Prescription d'un hypolipémiant"},{"num":259,"label":"Évaluation et prise en charge de la douleur aiguë"},{"num":260,"label":"Évaluation et prise en charge de la douleur chronique"},{"num":271,"label":"Prescription et surveillance d'une voie d'abord vasculaire"},{"num":281,"label":"Prescription médicamenteuse, consultation de suivi et éducation d'un patient diabétique de type 2 ou ayant un diabète secondaire"},{"num":282,"label":"Prescription médicamenteuse, consultation de suivi et éducation d'un patient hypertendu"},{"num":300,"label":"Consultation pré-anesthésique"},{"num":314,"label":"Prévention des risques liés au tabac"},{"num":328,"label":"Annonce d'une maladie chronique"}]},"objectives":[{"id":"225-obj-01","rank":"A","rubric":"Définition","title":"Définition et fréquence de l'AOMI","desc":"Connaître la définition et la fréquence de l'artériopathie oblitérante des membres inférieurs (AOMI)."},{"id":"225-obj-02","rank":"B","rubric":"Physiopathologie","title":"Étiologie et facteurs de risque de l'AOMI","desc":"Connaître l'étiologie et les facteurs de risque de l'AOMI."},{"id":"225-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Manifestations cliniques et classification de l'AOMI","desc":"Connaître les manifestations cliniques et la classification de l'AOMI et savoir évoquer les diagnostics différentiels."},{"id":"225-obj-04","rank":"A","rubric":"Examens complémentaires","title":"Examens complémentaires de 1re intention de l'AOMI","desc":"Savoir prescrire les examens complémentaires de 1re intention."},{"id":"225-obj-05","rank":"A","rubric":"Prise en charge","title":"Traitement médical et principes du traitement chirurgical de l'AOMI","desc":"Connaître le traitement médical : traitement médicamenteux et principes du traitement chirurgical."},{"id":"225-obj-06","rank":"A","rubric":"Suivi et/ou pronostic","title":"Complications et pronostic de l'AOMI","desc":"Connaître les complications et le pronostic : ischémie aiguë des membres inférieurs, morbimortalité cardiovasculaire."},{"id":"225-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Manifestations cliniques de l'ischémie aiguë de membre","desc":"Savoir définir et identifier les manifestations cliniques d'ischémie aiguë complète ou incomplète."},{"id":"225-obj-08","rank":"B","rubric":"Étiologies","title":"Autres causes de l'ischémie aiguë","desc":"Connaître les autres causes de l'ischémie aiguë."},{"id":"225-obj-09","rank":"A","rubric":"Identifier une urgence","title":"Principes du traitement en urgence de l'ischémie aiguë","desc":"Connaître les principes d'un traitement en urgence."},{"id":"225-obj-10","rank":"A","rubric":"Définition","title":"Définition et histoire naturelle de l'anévrisme de l'aorte abdominale","desc":"Connaître la définition et l'histoire naturelle d'un anévrisme de l'aorte abdominale et savoir rechercher d'autres localisations anévrismales."},{"id":"225-obj-11","rank":"B","rubric":"Étiologies","title":"Étiologies des anévrismes de l'aorte abdominale et dépistage","desc":"Connaître les principales étiologies des anévrismes de l'aorte abdominale et les principes du dépistage."},{"id":"225-obj-12","rank":"A","rubric":"Diagnostic positif","title":"Signes cliniques des anévrismes de l'aorte","desc":"Connaître les signes cliniques des anévrismes de l'aorte."},{"id":"225-obj-13","rank":"A","rubric":"Examens complémentaires","title":"Diagnostic des anévrismes de l'aorte abdominale","desc":"Savoir comment faire le diagnostic des anévrismes de l'aorte abdominale."},{"id":"225-obj-14","rank":"B","rubric":"Prise en charge","title":"Principes thérapeutiques de l'anévrisme de l'aorte abdominale","desc":"Connaître les principes thérapeutiques d'un anévrisme de l'aorte abdominale."},{"id":"225-obj-15","rank":"A","rubric":"Identifier une urgence","title":"Urgence chez le porteur d'un anévrisme de l'aorte abdominale","desc":"Savoir reconnaître et prendre en charge une situation d'urgence chez les patients porteurs d'un anévrisme de l'aorte abdominale."},{"id":"225-obj-16","rank":"A","rubric":"Définition","title":"Définition de l'ischémie intestinale aiguë et chronique","desc":"Connaître la définition de l'ischémie intestinale aiguë et chronique."},{"id":"225-obj-17","rank":"A","rubric":"Diagnostic positif","title":"Sémiologie de l'ischémie intestinale aiguë et chronique","desc":"Connaître la sémiologie de l'ischémie intestinale aiguë et chronique : signes fonctionnels et signes physiques."}],"course":{"sections":[{"id":"225-sec-01","title":"Aorte et artères viscérales : athérome et ischémies mésentériques","rank":"A","objectives":["225-obj-16","225-obj-17"],"content":"**Athérome aortique** : l'aorte peut porter des lésions d'athérome dès le jeune âge (stries lipidiques, plaques jeunes). Tous ses segments peuvent être atteints, avec des **sièges préférentiels** : la **bifurcation aortique** (naissance des artères iliaques) et l'**origine de toute branche** naissant de l'aorte. À l'imagerie, on retrouve des plaques chez **25 % des hommes et 20 % des femmes de 40-55 ans** ; le **tabagisme** est le facteur de risque le plus fortement associé.\n\n- Ces plaques sont le plus souvent **asymptomatiques** et de découverte fortuite (calcifications sur le trajet aortique à une imagerie thoracique ou abdominale).\n- Elles peuvent se manifester par une ulcération de la paroi ou par des **embolies** de matériel fibrinocruorique : cerveau (plaques de l'aorte ascendante ou horizontale), membres, viscères abdominaux.\n- Leur présence est un **marqueur de risque cardiovasculaire** : le risque augmente avec la présence et l'extension des calcifications, même asymptomatiques.\n- Elles sont souvent associées à une atteinte d'autres artères naissant de l'aorte (coronaires, digestives, rénales).\n\n> L'athérome des artères rénales peut entraîner une sténose avec ischémie rénale, qui active le système rénine-angiotensine-aldostérone : c'est l'**HTA rénovasculaire**, une cause d'HTA secondaire.\n\nLes autres artères viscérales peuvent être touchées, le plus souvent sans symptôme. Les sténoses du **tronc cœliaque** et/ou des **artères mésentériques** supérieure et/ou inférieure peuvent donner une **ischémie mésentérique** (digestive), chronique ou aiguë.\n\n### Ischémie mésentérique chronique\n\n- **Clinique** : typiquement un **angor digestif**, c'est-à-dire des douleurs abdominales survenant **après le repas**. Dans les cas graves : altération de l'état général et **amaigrissement**, car le patient limite ses repas pour éviter la douleur.\n- **Signe physique** : seulement un éventuel **souffle abdominal** évoquant une sténose artérielle viscérale.\n- [B] **Diagnostic** : **échodoppler des artères digestives** ou imagerie en coupe (**angioscanner** ou **angio-IRM**) ; l'artériographie n'est réalisée que lors d'une revascularisation par voie endovasculaire.\n\n### Ischémie mésentérique aiguë\n\n[A] Interruption **brutale** de la perfusion d'une partie de l'intestin par occlusion d'une ou plusieurs artères digestives, par **thrombose in situ ou embolie**. Grâce aux nombreuses collatérales, l'infarctus digestif est rare. C'est une **urgence vitale** (urgence chirurgicale) dont le pronostic dépend de la rapidité de la prise en charge ; le patient est le plus souvent polyathéromateux.\n\n- **Triade** (occlusion de l'artère mésentérique dans la majorité des cas) : **douleur abdominale aiguë avec paucité des signes physiques** ; **vidange digestive accélérée** (vomissements et/ou diarrhée) ; **indices d'une cause embolique**, notamment une **fibrillation atriale**.\n- Des signes d'embolie dans d'autres territoires renforcent la présomption d'une cause embolique ; des formes plus frustes exposent à des errances diagnostiques.","keyPoints":["L'athérome peut toucher tous les segments de l'aorte, avec des sièges préférentiels à la bifurcation aortique et à l'origine des branches de l'aorte.","L'ischémie mésentérique chronique se traduit typiquement par un angor digestif (douleurs abdominales après le repas).","[B] Son diagnostic repose sur l'échodoppler des artères digestives ou l'angioscanner / angio-IRM.","L'ischémie mésentérique aiguë associe douleur abdominale pauvre en signes physiques, vidange digestive accélérée et contexte embolique (fibrillation atriale).","L'ischémie mésentérique aiguë est une urgence vitale (chirurgicale) dont le pronostic dépend de la rapidité de la prise en charge."],"pitfalls":["Ne pas se laisser rassurer par un examen abdominal pauvre : la douleur aiguë avec paucité des signes physiques fait partie de la triade.","Ne pas confondre la forme chronique (angor digestif postprandial) et la forme aiguë (urgence vitale)."],"src":"p. 166-167, 187"},{"id":"225-sec-02","title":"AOMI : généralités, épidémiologie et facteurs de risque","rank":"A","objectives":["225-obj-01","225-obj-02"],"content":"[A] **Définition** : l'AOMI correspond à toute atteinte **athéromateuse** significative des artères situées entre l'**aorte terminale** et les **artères digitales** (orteils). Les lésions ont un aspect et un développement semblables à ceux des autres localisations athéromateuses.\n\n**Épidémiologie** :\n\n- Après les atteintes coronarienne et cérébrale, l'AOMI est, par sa fréquence, la **3e localisation de l'athérosclérose**.\n- Dans sa forme symptomatique, elle est plus fréquente chez l'**homme** ; pic de présentation entre **60 et 75 ans** chez l'homme et entre **70 et 80 ans** chez la femme.\n- Prévalence des formes cliniques : **1 à 5 % après 60 ans**, jusqu'à **10-15 %** dans cette tranche d'âge si l'on inclut les formes asymptomatiques. Pour **un cas clinique**, **deux à quatre** patients ont une forme infraclinique : d'où l'intérêt du **dépistage** des formes infracliniques pour une meilleure prévention.\n- Plus d'un million de personnes sont atteintes en France, le plus souvent sous une forme modérée, voire paucisymptomatique ; incidence de l'ordre de **2-5 ‰**.\n\n[B] **Facteurs de risque** : les principaux sont le **tabagisme** et le **diabète**. Le tabagisme est plus fréquent chez le sujet plus jeune ; le diabète est plus souvent responsable de **formes graves d'emblée**, avec une atteinte **plus distale** et un **pronostic plus sévère**. L'**hypercholestérolémie** et l'**hypertension artérielle** sont les autres facteurs fréquemment associés.","keyPoints":["L'AOMI est une atteinte athéromateuse des artères situées entre l'aorte terminale et les artères digitales.","C'est la 3e localisation de l'athérosclérose après les atteintes coronarienne et cérébrale.","[B] Les principaux facteurs de risque de l'AOMI sont le tabac et le diabète.","[B] Le diabète est plus souvent responsable de formes graves d'emblée, plus distales et de pronostic plus sévère.","Pour chaque cas d'AOMI clinique, deux à quatre patients ont une forme infraclinique."],"pitfalls":["Ne pas sous-estimer l'AOMI infraclinique : pour un cas clinique, deux à quatre patients ont une forme infraclinique."],"src":"p. 167-168, 187"},{"id":"225-sec-03","title":"AOMI : manifestations cliniques et stades","rank":"A","objectives":["225-obj-03"],"content":"Au début, le patient reste longtemps **asymptomatique** (retentissement hémodynamique modéré, développement progressif d'une **circulation collatérale**). Les premiers symptômes apparaissent à l'effort, quand le débit artériel ne suffit plus à oxygéner le muscle : c'est l'**ischémie d'effort**. L'évolution peut se faire vers une souffrance tissulaire permanente, avec douleurs de décubitus et troubles trophiques : c'est l'**ischémie permanente**. Les manifestations dépendent du siège, de l'étendue et de la gravité des lésions, de la collatéralité et de la capacité du patient à se mobiliser.\n\n### Classifications (tableau 7.1)\n\nLa classification de **Leriche et Fontaine** est le plus souvent supplantée de nos jours par la classification internationale de **Rutherford**.\n\n| Leriche et Fontaine | Symptômes | Rutherford | Symptômes |\n|---|---|---|---|\n| Stade I | Asymptomatique | Grade 0 | Asymptomatique |\n| Stade II | Claudication intermittente | Grade I | Claudication légère, modérée ou sévère |\n| Stade III | Douleur ischémique de repos | Grade II | Douleur ischémique de repos |\n| Stade IV | Ulcération ou gangrène | Grade III | Perte de substance (faible ou majeure) |\n\n### Claudication intermittente (ischémie d'effort)\n\n- **Forme typique** : douleur de type **crampe au mollet**, déclenchée après une certaine distance (distance de gêne) et obligeant à s'arrêter au bout d'un certain parcours (**distance de marche**) ; elle disparaît habituellement en **moins de 5 minutes**. La distance de marche est classiquement stable ; elle s'évalue sur terrain plat ou lors d'un test de marche.\n- La claudication est dite **sévère** si la distance de marche est **< 100 m**.\n- **Formes atypiques fréquentes** : distances variables d'un jour à l'autre ; autres sièges (pied, cuisse, ou **claudication fessière** par atteinte aorto-iliaque) ; douleurs de faible intensité, parfois de repos et d'effort, voire remplacées par des paresthésies ou un engourdissement d'effort ; patient qui ralentit le pas sans devoir s'arrêter.\n- **AOMI masquée** : une atteinte sévère peut rester asymptomatique en cas de collatéralité importante, chez le sujet très âgé dont les comorbidités empêchent de marcher (insuffisance cardiaque ou respiratoire, atteintes articulaires…) ou en cas de **neuropathie** (diabète, insuffisance rénale, âge avancé). Dans ces deux derniers cas, le patient peut se présenter d'emblée en ischémie permanente : il faut d'abord **s'assurer que le patient marche**.\n- **Syndrome de Leriche** (homme) : claudication fessière et/ou fatigabilité à la marche et **impuissance**, en rapport avec une atteinte **aorto-iliaque**.\n\n### Ischémie permanente (stades III et IV)\n\n- **Douleurs de décubitus** (stade III) : brûlures des orteils et de l'avant-pied, après quelques minutes à quelques heures de décubitus, **soulagées en position déclive** (jambes pendantes au bord du lit, levers nocturnes) ; douleurs intenses nécessitant des antalgiques d'intensité croissante ; pied froid, pâle ou cyanosé ; œdème de déclivité possible.\n- **Troubles trophiques** (stade IV) : peau mince, fragile, dépilée, puis plaies, **ulcères** et **gangrènes**, souvent très douloureux et portes d'entrée infectieuses (cellulite, arthrite, ostéite, septicémie). Les ulcères siègent surtout aux **zones de frottement ou d'appui** (orteil, dos et bord externe du pied, talon), parfois à la face antérieure de jambe (ulcère « suspendu »). La gangrène touche surtout les orteils ou le talon et est **plus fréquente chez le diabétique**.\n- L'ischémie permanente comporte des douleurs **durant plus de 15 jours**, résistant aux antalgiques usuels. Avec des pressions de perfusion effondrées (**< 50 mmHg à la cheville** ou **< 30 mmHg à l'hallux**), on parle d'**ischémie critique** : le pronostic du membre est engagé, avec un haut risque d'amputation sans revascularisation.\n- L'AOMI peut aussi se révéler par une **ischémie aiguë ou subaiguë**.\n\nL'interrogatoire recherche systématiquement des signes d'autres atteintes athéromateuses (**angor**, symptômes déficitaires cérébraux).","keyPoints":["L'AOMI évolue de la forme asymptomatique vers l'ischémie d'effort (claudication) puis l'ischémie permanente.","La claudication est sévère si la distance de marche est < 100 m ; la douleur cède habituellement en moins de 5 minutes.","Le syndrome de Leriche associe claudication fessière et/ou fatigabilité à la marche et impuissance, par atteinte aorto-iliaque.","L'ischémie critique associe une ischémie permanente et une pression de cheville < 50 mmHg ou d'hallux < 30 mmHg.","Les ulcères siègent aux zones de frottement ou d'appui ; la gangrène est plus fréquente chez le diabétique."],"pitfalls":["Une AOMI sévère peut être masquée chez le sujet âgé peu mobile ou neuropathe : toujours vérifier que le patient marche réellement.","Ne pas confondre claudication artérielle et claudication veineuse ou neurologique (canal lombaire étroit)."],"src":"p. 168-169"},{"id":"225-sec-04","title":"AOMI : examen clinique, index de pression systolique et examens complémentaires","rank":"A","objectives":["225-obj-04"],"content":"### Examen physique (bilatéral et comparatif)\n\n- **Inspection** : pied de couleur normale, pâle ou cyanosée ; recherche systématique de **troubles trophiques** (espaces interdigitaux).\n- **Palpation** : pied froid ; une douleur à la pression des masses musculaires du mollet témoigne d'une ischémie sévère ; recherche d'un amortissement ou d'une abolition des **pouls** fémoral, poplité, tibial postérieur et pédieux (le pédieux peut manquer de façon congénitale chez **5 %** de la population) ; **temps de recoloration** allongé (normalement **< 3 secondes**) ; recherche systématique d'un **anévrisme** abdominal et poplité.\n- **Auscultation** : souffle sur les trajets vasculaires.\n- L'examen est systématiquement complété par la mesure de l'**IPS** (suspicion d'AOMI ou dépistage) et par un **examen cardiovasculaire général** (maladie coronarienne et atteinte cérébrovasculaire fréquemment associées).\n\n### Index de pression systolique (IPS)\n\nC'est l'examen à réaliser **en 1re ligne** devant une suspicion d'AOMI (il peut être mesuré au cabinet). Rapport **pression systolique de cheville / pression systolique du bras**, mesuré avec un brassard et un **doppler de poche**. Pour chaque membre : la **plus élevée** des pressions tibiale postérieure et pédieuse (la fibulaire n'est pas mesurée), divisée par la **plus élevée** des pressions des deux bras.\n\n> Normal : **1,00 à 1,40** · AOMI si **< 0,90** sur au moins une cheville · AOMI sévère si **< 0,70** · IPS **> 1,40** = rigidité artérielle anormale par **médiacalcose** (diabétique âgé, dialysé) : la pression de cheville est alors remplacée par la **pression d'orteil** (index de pression d'orteil **< 0,70** = AOMI ; pression d'orteil **< 30 mmHg** = ischémie critique).\n\n- Chez le diabétique, l'insuffisant rénal et le sujet très âgé, l'IPS de repos peut être pris en défaut : il est conseillé de mesurer une **pression d'orteil**, et, chez les patients symptomatiques à IPS de repos normal, de faire des **tests d'effort** (IPS après effort, TcPO2 à l'effort).\n- Un IPS **< 0,90** est aussi un **marqueur de risque cardiovasculaire** élevé (accident coronarien ou cérébral, fatal ou non).\n\n### Examens paracliniques\n\nIls évaluent objectivement le handicap fonctionnel, la sévérité hémodynamique et la localisation des lésions.\n\n- **Test de marche de 6 minutes** : non spécifique de l'AOMI ; évalue le handicap fonctionnel global.\n- **Test de marche sur tapis roulant** (protocole de Strandness : **3,2 km/h, pente 10 %**), spécifique de l'AOMI : mesure les distances de gêne et de marche, et réévalue les pressions de cheville après l'effort. Chez un claudicant dont l'IPS de repos est > 0,90, une baisse de la pression de cheville **> 30 mmHg** et/ou de l'IPS **> 20 %** juste après la marche est évocatrice d'AOMI (utile au diagnostic différentiel).\n- **TcPO2** (pression transcutanée en oxygène), mesurée après une **hyperémie par la chaleur** (à l'état basal, elle est très basse, 3 à 4 mmHg, sans différence entre peau saine et ischémique) : utile au diagnostic et à l'évaluation de l'**ischémie critique**. Au dos du pied : normale **> 50 mmHg** ; **> 35 mmHg** = bonne compensation ; **10 à 35 mmHg** = hypoxie continue ; **< 10 mmHg** = hypoxie critique.\n- **Échodoppler artériel des membres inférieurs** : l'exploration la plus utilisée, car **non invasive** ; il apporte des données anatomiques (siège, type des lésions) et hémodynamiques et permet, dans l'immense majorité des cas, de **localiser et quantifier** les sténoses.\n- **Angioscanner** et **angio-IRM** : demandés **uniquement s'il existe une indication de revascularisation**, pour en étudier la faisabilité et les modalités (vision de tout l'arbre artériel). L'angioscanner impose une injection d'iode (vérifier les allergies et la fonction rénale). L'angio-IRM évite les rayonnements ionisants, mais le gadolinium est contre-indiqué si la clairance est **< 30 mL/min/1,73 m²** et elle ne visualise pas les **calcifications**, importantes pour le chirurgien avant un pontage. Performances équivalentes (sensibilité et spécificité de l'ordre de **95 %** par rapport à l'artériographie).\n- **Artériographie** : ponction artérielle directe ; aujourd'hui essentiellement limitée aux **procédures de revascularisation** ; souvent nécessaire pour visualiser le réseau jambier et pédieux en cas de revascularisation distale.","keyPoints":["L'IPS est l'examen de 1re ligne devant une suspicion d'AOMI : AOMI si < 0,90, AOMI sévère si < 0,70.","Un IPS > 1,40 traduit une médiacalcose : il faut alors mesurer la pression d'orteil.","Le test de marche démasque une AOMI à IPS de repos normal (baisse de pression de cheville > 30 mmHg et/ou d'IPS > 20 %).","L'échodoppler artériel des membres inférieurs localise et quantifie les sténoses.","L'angioscanner et l'angio-IRM ne sont demandés qu'en cas d'indication de revascularisation ; l'artériographie est réservée aux procédures de revascularisation.","La TcPO2 après hyperémie aide au diagnostic et à l'évaluation de l'ischémie critique."],"pitfalls":["Chez le diabétique, l'insuffisant rénal ou le sujet très âgé, l'IPS de repos peut être pris en défaut (médiacalcose) : mesurer une pression d'orteil.","Ne pas prescrire d'angioscanner, d'angio-IRM ou d'artériographie en dehors d'une indication de revascularisation."],"src":"p. 170-173"},{"id":"225-sec-05","title":"AOMI : diagnostics différentiels et étiologiques","rank":"A","objectives":["225-obj-02","225-obj-03"],"content":"### Diagnostic différentiel\n\nSelon le tableau, d'autres causes sont à évoquer ; plusieurs peuvent **coexister**, notamment chez le sujet âgé.\n\n- **Douleurs à la marche** :\n  - neurologiques : **canal lombaire étroit** (douleur ou paresthésies du mollet ou du pied à l'effort, cédant au repos), sciatalgie, atteinte médullaire (parésie du membre sans douleur, avec dérobement des jambes) ;\n  - rhumatologiques : arthrose, tendinite, anomalies posturostaturales, rhumatismes ;\n  - veineuses : **claudication veineuse** (post-thrombotique) ;\n  - autres : kyste poplité, piège poplité, syndrome des loges, endofibrose iliaque, malformations vasculaires (fistules artérioveineuses, artère ischiatique) ;\n  - musculaires : les **douleurs musculaires sous statines** peuvent mimer une AOMI (attention aux tableaux intriqués).\n- **Douleurs de décubitus** : neuropathie sensorielle (diabétique, toxique, carentielle…), syndromes douloureux régionaux complexes (anciennes algodystrophies et causalgies), compression radiculaire.\n- **Ulcères** : veineux, microcirculatoire, neuropathique, traumatique.\n\n### Diagnostic étiologique\n\n[B] L'AOMI (atteinte athéromateuse) représente **plus de 95 %** des atteintes artérielles oblitérantes des membres inférieurs. Les artériopathies **non athéromateuses** des membres inférieurs sont :\n\n- les artériopathies inflammatoires : maladie de **Buerger**, maladie de **Takayasu**, maladie de **Horton**, certaines collagénoses (périartérite noueuse, lupus…) ;\n- la **dysplasie fibromusculaire** (iliaque ou poplitée) ;\n- la **coarctation de l'aorte** (hypodébit en aval) ;\n- les atteintes postradiques, post-traumatiques et toxiques (dérivés de l'ergot de seigle…) ; les gelures ; les compressions extrinsèques ;\n- les atteintes spécifiques de l'artère poplitée : artère poplitée piégée, kyste poplité sous-adventiciel.","keyPoints":["Plusieurs causes de douleur de jambe peuvent coexister chez le sujet âgé : penser au canal lombaire étroit et à la claudication veineuse.","Les douleurs musculaires sous statines peuvent mimer une AOMI.","[B] Plus de 95 % des artériopathies oblitérantes des membres inférieurs sont athéromateuses.","[B] Causes non athéromateuses : artériopathies inflammatoires (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation de l'aorte, causes radiques, traumatiques, toxiques, gelures, compressions, atteintes poplitées spécifiques."],"pitfalls":["Attention aux tableaux intriqués : des douleurs sous statines ou un canal lombaire étroit peuvent coexister avec une authentique AOMI."],"src":"p. 174"},{"id":"225-sec-06","title":"AOMI : traitement et pronostic","rank":"A","objectives":["225-obj-05","225-obj-06"],"content":"Le traitement a deux volets : **à visée générale**, pour améliorer le pronostic cardiovasculaire et vital ; **à visée locale**, pour traiter les symptômes et améliorer le pronostic du membre.\n\n### Traitement à visée générale (à tout stade)\n\n- **Contrôle des facteurs de risque**, au premier chef **arrêt du tabac** et contrôle du **diabète** : PAS **≤ 120-129 mmHg** et PAD **≤ 70-79 mmHg** ; **HbA1c < 7 %** ; **LDL-cholestérol < 0,55 g/L (< 1,4 mmol/L)** ; régime méditerranéen ; IMC entre **20 et 25 kg/m²** ; exercice modéré (réentraînement : **3 fois/semaine pendant 12 semaines**).\n- **Antiagrégant plaquettaire** (**aspirine ou clopidogrel**) chez **tout patient avec AOMI symptomatique**, pour réduire le risque d'infarctus et d'AVC. En cas d'AOMI asymptomatique (IPS < 0,90), il est débattu, sauf si le patient a une autre atteinte athéromateuse (ex. : cardiopathie ischémique).\n- **Statine systématique** : LDL-cholestérol < 0,55 g/L **et** baisse d'au moins **50 %** par rapport à la valeur initiale.\n- **IEC** : intérêt pronostique, en maintenant la PA < 140/90 mmHg ; un IEC ou un sartan peut être considéré chez tous les patients avec AOMI, quel que soit leur niveau de PA, en l'absence de contre-indication.\n- **Bêtabloquants** : possibles en cas d'indication formelle (cardiopathie ischémique, insuffisance cardiaque à fraction d'éjection altérée, certaines arythmies), avec prudence en cas d'ischémie critique sans revascularisation possible.\n\n### Traitement à visée locale\n\n- **Arrêt du tabac et marche régulière** : ils favorisent la circulation collatérale et le métabolisme musculaire et allongent la distance de marche. Au minimum **30-45 minutes, au moins 3 fois/semaine**, en ralentissant ou en s'arrêtant quelques minutes au seuil de la douleur. La **réadaptation supervisée** (en centre ou en ambulatoire) est fortement conseillée (meilleurs résultats que la marche seule) et toujours complétée par l'**éducation thérapeutique**.\n- **Médicaments** : une statine peut s'accompagner d'une augmentation du périmètre de marche. [B] Les vasoactifs (ex. : pentoxifylline) améliorent modestement le périmètre de marche, **sans bénéfice pronostique** ; les **prostaglandines** peuvent être proposées en cas d'**ischémie critique non revascularisable** (perfusions quotidiennes pendant plusieurs semaines en milieu spécialisé).\n- **Revascularisation** :\n  - proposée **autant que possible en cas d'ischémie permanente** ;\n  - possible en cas de **claudication sévère** altérant la qualité de vie, notamment après un traitement médical bien mené incluant la réadaptation, ou parfois d'emblée si le périmètre de marche est **< 100 m** avec handicap fonctionnel important et/ou s'il existe une atteinte **aorto-iliaque sévère** ;\n  - technique choisie selon l'étendue et la sévérité des lésions et l'état du patient : **endovasculaire** (angioplastie intraluminale au ballonnet, ± stent) ou **chirurgie** (**pontage**, de préférence veineux, sinon prothétique : aorto-bi-iliaque ou bifémoral, fémoropoplité, fémorojambier ; pontages extra-anatomiques croisé fémorofémoral, voire axillofémoral ; **endartériectomie**, notamment de la bifurcation fémorale) ; les gestes peuvent être associés (techniques hybrides) ;\n  - [B] angioplastie sous-adventicielle possible pour les occlusions longues ; résultats d'autant meilleurs que les lésions sont **courtes et proximales** ; après angioplastie avec ou sans stent, **bithérapie antiplaquettaire de 1 à 6 mois** selon le geste et sa localisation ;\n  - quelle que soit la méthode : **surveillance clinique et échodoppler** (thrombose de stent ou de pontage, dégradation des pontages et des anastomoses).\n- **Soins de plaies** sous la supervision d'une équipe multidisciplinaire spécialisée.\n- **Amputation** : geste ultime, à défaut de toute possibilité de revascularisation, pour traiter la douleur et/ou limiter les complications infectieuses ; en **zone saine et bien oxygénée** (intérêt de la **TcPO2**), en préservant autant que possible l'appui (orteil, transmétatarsienne) ou le genou pour permettre un appareillage.\n\n### Stratégie\n\n- Dans tous les cas : contrôle des facteurs de risque ; antiplaquettaire si AOMI symptomatique ; recherche des autres atteintes (coronaires, cérébrovasculaires), orientée par la clinique.\n- **Claudication intermittente** (fig. 7.6) : facteurs de risque + **statine + antiplaquettaire** (+ IEC si HTA ou insuffisance cardiaque). Si la claudication est très invalidante (périmètre < 100 m) ou s'il existe une atteinte aorto-iliaque sévère et extensive : **envisager une revascularisation**, suivie d'une réadaptation à la marche ; sinon, **réadaptation à la marche** (de préférence supervisée) d'emblée, visant la disparition de la claudication ou un allongement significatif du périmètre de marche.\n- **Ischémie critique** : revasculariser le membre autant que possible ; en cas d'impossibilité ou d'échec sans autre option, envisager l'amputation.\n\n### Pronostic\n\nGrave. En **ischémie permanente**, l'espérance de vie équivaut à celle de certains cancers. Chez le **claudicant** : espérance de vie réduite en moyenne de **10 ans** ; à **5 ans**, **20 %** de complications cardiovasculaires et **20 %** de décès (pour moitié cardiovasculaires) ; sur le plan local, **25 %** s'aggravent, dont **1/5** subissent une amputation majeure ; risque d'amputation à 5 ans de l'ordre de **5 %**, notamment si les facteurs de risque (tabac) sont mal contrôlés. En **ischémie critique**, la mortalité à 5 ans est proche de **70 %** : les mesures préventives s'imposent, même chez les patients revascularisés devenus asymptomatiques.","keyPoints":["Contrôle des facteurs de risque à tout stade ; antiagrégant (aspirine ou clopidogrel) et statine chez tout patient avec AOMI symptomatique.","Cibles : LDL < 0,55 g/L avec baisse ≥ 50 %, HbA1c < 7 %, PAS ≤ 120-129 et PAD ≤ 70-79 mmHg.","La revascularisation est proposée autant que possible en cas d'ischémie permanente.","Sans claudication très invalidante ni atteinte aorto-iliaque sévère, on propose d'abord la réadaptation à la marche, de préférence supervisée.","L'amputation est le geste ultime en l'absence de toute possibilité de revascularisation.","La mortalité à 5 ans est proche de 70 % en ischémie critique."],"pitfalls":["Ne pas négliger la recherche et le traitement des autres atteintes athéromateuses (coronaire, carotidienne) chez tout patient avec AOMI."],"src":"p. 175-178"},{"id":"225-sec-07","title":"Ischémie aiguë des membres inférieurs : physiopathologie et diagnostic clinique","rank":"A","objectives":["225-obj-07"],"content":"**Définition** : interruption **brutale** du flux artériel d'un membre, responsable d'une hypoxie tissulaire abrupte pouvant aboutir à une nécrose. C'est une **urgence vasculaire** : le pronostic du membre, voire le pronostic vital, est engagé.\n\n### Physiopathologie\n\n- La gravité de la baisse de débit dépend de **3 facteurs** : la **pression artérielle systémique** (à maintenir à un niveau correct), l'abondance de la **circulation collatérale** et la qualité du **réseau artériel d'aval**.\n- Les **cellules nerveuses** souffrent les premières (dans les **2 heures**), puis les **cellules musculaires** (dans les **6-8 heures** : rhabdomyolyse). La **nécrose cutanée** apparaît à partir de la **24e heure**.\n- **Syndrome des loges** : l'anoxie musculaire entraîne une vasodilatation capillaire, un œdème et une hausse de la pression interstitielle ; dans les loges aponévrotiques inextensibles, l'œdème comprime les tissus jusqu'à l'arrêt circulatoire. Seule une **aponévrotomie de décharge** libère le muscle.\n- **Reperfusion** : la remise en circulation libère acides et radicaux libres (**syndrome de revascularisation**) et peut paradoxalement entraîner des conséquences sévères :\n  - troubles métaboliques : **hyperkaliémie**, **acidose métabolique**, hyperuricémie, **myoglobinémie et myoglobinurie**, hausse de la créatininémie, hypocalcémie, hyperphosphorémie ; CIVD possible ;\n  - **insuffisance rénale aiguë** par nécrose tubulaire (choc et instabilité de la perfusion rénale, précipitation intratubulaire de myoglobine, toxicité de la myoglobine en milieu acide et des produits de contraste) ;\n  - plus rarement, choc hypovolémique (exsudation plasmatique) ou infectieux (muscles nécrosés).\n\n### Diagnostic clinique\n\nLe diagnostic est essentiellement **clinique** :\n\n- **Signes fonctionnels** : douleur intense, **à type de broiement**, de début **brutal** (l'installation se fait parfois en quelques heures dans la forme subaiguë), le membre étant en impotence fonctionnelle.\n- **Signes physiques** (comparés au membre opposé) : membre **froid, livide** ; douleur à la palpation des masses musculaires ; **abolition des pouls** en aval de l'occlusion ; **anesthésie et paralysie** (notamment du nerf fibulaire commun : impossibilité de relever le pied).\n- La topographie de l'occlusion est estimée par le siège de la froideur et des pouls abolis. Dans le cas le plus grave, l'occlusion de la **bifurcation aortique** donne une ischémie bilatérale sévère avec paralysie sensitivomotrice ; les signes généraux sont alors au premier plan, jusqu'au **collapsus cardiovasculaire**.\n\n**Niveaux de sévérité (Rutherford, recommandations ESC 2024)** :\n\n| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate, urgence relative |\n| IIa | Ischémie discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Ischémie immédiatement menaçante | Présent, dépassant les orteils | Modéré | Récupérable si prise en charge immédiate |\n| III | Irréversible | Anesthésie importante | Paralysie, déficit important | Déficit séquellaire et perte de tissus inévitables |\n\n### Diagnostic paraclinique\n\n- Le diagnostic restant clinique, l'**équipe chirurgicale est alertée au plus tôt** : **aucune exploration ne doit retarder l'intervention**, notamment en cas d'atteinte neurologique (grade II).\n- Un **échodoppler** peut être réalisé sans perte de temps **si et seulement si** les conditions locales et la sévérité le permettent (notamment grade I, sans atteinte neurologique).\n- L'**artériographie** est le plus souvent réalisée **au bloc opératoire** pour orienter le geste : elle localise l'occlusion, en précise l'aspect (athérome, anévrisme, dissection…), apprécie surtout le réseau d'aval (important pour un geste percutané ou un pontage) et, en cas d'embolie, révèle d'autres emboles asymptomatiques (homo- ou controlatéraux).","keyPoints":["L'ischémie aiguë de membre est une urgence vasculaire : le pronostic du membre, voire le pronostic vital, est engagé.","Les cellules nerveuses souffrent dans les 2 h, les cellules musculaires dans les 6-8 h ; la nécrose cutanée apparaît à partir de la 24e heure.","Le syndrome des loges se traite par aponévrotomie de décharge.","Le diagnostic est clinique : douleur brutale, membre froid et livide, pouls abolis, anesthésie et paralysie.","La classification de Rutherford (I, IIa, IIb, III) gradue la sévérité et le degré d'urgence.","Aucune exploration ne doit retarder l'intervention, notamment en cas d'atteinte neurologique."],"pitfalls":["Ne jamais retarder l'intervention par des examens d'imagerie inutiles, surtout en cas d'atteinte neurologique (grade II).","La reperfusion peut paradoxalement entraîner des conséquences sévères (hyperkaliémie, acidose, insuffisance rénale aiguë)."],"src":"p. 178-180"},{"id":"225-sec-08","title":"Ischémie aiguë des membres inférieurs : étiologies et bilan","rank":"A","objectives":["225-obj-08"],"content":"[B] Deux grands tableaux étiologiques s'opposent ; dès la première phase de la prise en charge, on cherche un faisceau d'arguments en faveur de l'un d'eux.\n\n**Thrombose artérielle in situ** :\n\n- sujet le plus souvent **âgé**, avec des facteurs de risque cardiovasculaire, voire une AOMI préexistante (à rechercher sur l'autre membre) ;\n- douleur d'**intensité moyenne**, d'installation progressive ou rapide (grâce à la collatéralité préalable) ;\n- causes : AOMI ; artériopathies non athéromateuses (inflammatoires, radiques…) ; **anévrisme poplité thrombosé** ; déshydratation et/ou hémoconcentration du sujet âgé ; causes sur des artères pouvant être initialement saines (kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies) ; causes iatrogènes (cathétérisme, thrombopénie à l'héparine, ergotisme).\n\n**Embolie sur artères saines** :\n\n- sujet classiquement **jeune**, sans antécédent vasculaire connu (mais pouvant avoir une cardiopathie connue) ;\n- douleur **brutale, aiguë et sévère** (absence de collatérales), parfois précédée d'épisodes de **palpitations** ;\n- causes **cardiaques** : troubles du rythme (**fibrillation atriale**), foramen ovale perméable et anévrisme du septum interatrial, infarctus du myocarde (notamment avec faux anévrisme de paroi), endocardite infectieuse, valvulopathies et prothèses valvulaires, tumeurs cardiaques (myxome de l'atrium), dyskinésie ou anévrisme du ventricule gauche ;\n- causes **aortiques** : athérome aortique, anévrisme, aortites, tumeurs aortiques ; pièges vasculaires.\n\nCes deux tableaux ne sont pas toujours distincts : une embolie peut survenir sur des artères déjà atteintes d'AOMI, et une thrombose in situ peut compliquer la rupture d'une plaque initialement non occlusive chez un sujet sans AOMI connue.\n\n### Bilan initial et évaluation du terrain\n\n[A] L'examen clinique est **toujours complété** par une **auscultation cardiaque** et un **ECG** (recherche d'arythmie), une **palpation abdominale** (anévrisme aortique) et un **bilan de coagulation**. Les autres examens sont repoussés **après la revascularisation** :\n\n- côté cardiaque : ETT, Holter ECG, voire ETO ou IRM ;\n- côté artériel : échodoppler artériel de l'aorte et des membres inférieurs, voire angioscanner ou artériographie.\n\n**Terrain** : rechercher d'autres localisations ischémiques (embolies multiples) ; évaluer rapidement l'état général, la fonction cardiaque et les comorbidités (pathologie incurable ou fortement handicapante) ; une prise en charge palliative est parfois la seule solution chez un malade très âgé et moribond.","keyPoints":["[B] Deux tableaux s'opposent : thrombose in situ chez un sujet ayant déjà une AOMI, et embolie sur artères saines.","[B] L'embolie survient classiquement chez un sujet jeune sans antécédent vasculaire, avec une douleur brutale et sévère ; la fibrillation atriale fait partie des causes cardiaques.","Bilan initial systématique : auscultation cardiaque, ECG, palpation abdominale et bilan de coagulation ; les autres examens après la revascularisation.","[B] Les deux tableaux peuvent se superposer chez un même patient."],"pitfalls":["Ne pas oublier de rechercher une arythmie (ECG) ou un anévrisme aortique devant toute ischémie aiguë de membre.","[B] Une embolie peut survenir sur des artères déjà artériopathes, et une thrombose in situ sur des artères sans AOMI connue."],"src":"p. 181-182"},{"id":"225-sec-09","title":"Ischémie aiguë des membres inférieurs : traitement","rank":"A","objectives":["225-obj-09"],"content":"La phase diagnostique doit être la plus courte possible, pour traiter vite et selon la sévérité (fig. 7.7).\n\n### Conduite selon le grade (fig. 7.7)\n\n- **Pour tous, dès que possible** : **héparine**, **antalgiques**, **soins locaux**.\n- **Grade I (viable)** : **imagerie en urgence**, puis **revascularisation dans les heures à venir** (thrombolyse, thrombectomie ou pontage).\n- **Grade II (viable avec déficit sensitif)** : **revascularisation en urgence absolue** (thrombectomie ou pontage).\n- **Grade III (irréversible)** : **amputation**.\n- **Ensuite, pour tous** : traitement médical avec anticoagulation, analgésie et équilibration des troubles hydroélectrolytiques, et **bilan étiologique**.\n\n### Traitement médical\n\n- **Héparine non fractionnée**, à débuter dès le diagnostic, **une fois le bilan de coagulation prélevé** : bolus de **5 000 UI** puis perfusion continue de **500 UI/kg/j**, objectif **TCA entre 2 et 3**.\n- Antalgie : **niveau 3**, souvent nécessaire d'emblée.\n- **Oxygénothérapie** nasale.\n- Si nécessaire, équilibration de l'état hémodynamique (remplissage macromoléculaire).\n- **Soins locaux** immédiats, poursuivis au-delà de la revascularisation : protection par mousse ou coton, position **légèrement déclive**, éviction de tout frottement ou traumatisme cutané.\n\n### Revascularisation\n\n- **Embolectomie par sonde de Fogarty** sous contrôle angiographique : méthode de **référence** des embolies sur artère saine (parfois utilisée aussi sur artère athéromateuse).\n- **Thrombolyse in situ** par voie intra-artérielle et **thromboaspiration** : si le lit d'aval jambier est de **mauvaise qualité** et l'ischémie **peu sévère** ; le fibrinolytique est injecté dans le thrombus par un cathéter laissé en place plusieurs heures, avec surveillance en milieu spécialisé et contrôles angiographiques répétés.\n- Dans les deux cas, une **angioplastie** complète le geste s'il persiste une sténose ; un **pontage** (souvent distal) peut être envisagé en dernier ressort.\n- **Aponévrotomie de décompression** (le plus souvent de la loge antéroexterne de jambe) : généralement systématique en cas de **revascularisation tardive**, pour éviter le syndrome des loges.\n- **Amputation** : d'emblée si l'ischémie est **dépassée** ; parfois aussi pour limiter les désordres métaboliques majeurs d'un syndrome de revascularisation, ou après échec de la revascularisation, notamment sur terrain débilité.\n\n### Conséquences métaboliques de la revascularisation\n\n- Rechercher systématiquement une **acidose métabolique hyperkaliémique** et une **insuffisance rénale aiguë** : surveillance de la **diurèse** (sonde urinaire, diurèse horaire), **ionogramme sanguin**, urée, **créatininémie**, **CPK**.\n- Traitement : compensation progressive de l'acidose par **bicarbonates IV** ; hyperkaliémie traitée par un chélateur du potassium (**polystyrène sulfonate de sodium**), voire par **dialyse** ; lavage du membre au sérum physiologique.\n\n### À distance\n\n- Cause **embolique** : traitement étiologique (ex. : **anticoagulation au long cours** en cas de fibrillation atriale).\n- Cause **thrombotique** : **antiagrégant plaquettaire** et bon contrôle des facteurs de risque cardiovasculaire, indispensables.","keyPoints":["Héparine non fractionnée (bolus 5 000 UI puis 500 UI/kg/j, TCA entre 2 et 3) dès le diagnostic, après prélèvement du bilan de coagulation.","Grade I : imagerie en urgence puis revascularisation dans les heures ; grade II : revascularisation en urgence absolue ; grade III : amputation.","L'embolectomie par sonde de Fogarty est la référence pour l'embolie sur artère saine.","Une aponévrotomie de décompression est généralement systématique en cas de revascularisation tardive.","Acidose hyperkaliémique et insuffisance rénale aiguë doivent être systématiquement recherchées et traitées."],"pitfalls":["Prélever le bilan de coagulation avant l'héparine, mais débuter l'héparine dès le diagnostic.","Rechercher systématiquement les conséquences métaboliques de la revascularisation et un syndrome des loges."],"src":"p. 180, 182-183"},{"id":"225-sec-10","title":"Anévrisme de l'aorte abdominale : épidémiologie, étiologie et diagnostic","rank":"A","objectives":["225-obj-10","225-obj-11","225-obj-12","225-obj-13"],"content":"[A] **Définition** : un anévrisme est une dilatation **focale et permanente** d'une artère, avec **perte du parallélisme** des parois et augmentation de diamètre de **plus de 50 %** par rapport au diamètre d'amont. En dehors des artères cérébrales, les sièges les plus fréquents sont l'**aorte** (surtout sous-rénale, mais aussi ascendante), les artères **poplitées** et les artères **iliaques**.\n\n**Mécanisme** : la média aortique s'altère (destruction des fibres élastiques, fragmentation des fibres de collagène) et perd sa capacité à lutter contre la distension ; cette destruction est favorisée par la suractivité d'enzymes détruisant la matrice (ex. : **métalloprotéases**). Dans la grande majorité des cas, l'AAA est **sous-rénal**.\n\n### Épidémiologie\n\n- Prévalence en baisse en Occident : **2 à 5 %** des hommes de plus de 65 ans ; entre 75 et 84 ans, environ **5 %** des hommes et **3 %** des femmes.\n- **Facteurs de risque** (en dehors de l'âge) : **tabagisme** et **antécédents familiaux d'anévrisme** ; risque plus élevé en cas d'autre localisation aortique (thoracique) ou artérielle périphérique ; les **diabétiques sont moins souvent atteints**.\n- **Risque annuel de rupture** (anévrisme sous-rénal) selon le diamètre : **0,4 %/an** si < 40 mm, puis hausse exponentielle (**3 %** à 50-59 mm, **15 %** au-delà de 60 mm) ; à diamètre égal, risque près de **4 fois plus élevé chez la femme**.\n- Environ **12 000 décès par an** par rupture d'AAA en Europe ; mais le porteur d'AAA risque **10 fois plus** de mourir d'une autre atteinte cardiovasculaire (coronarienne ou AVC) que d'une rupture, d'où l'importance des mesures préventives générales.\n\n### Étiologie\n\n[B] Dans **80-90 %** des cas, l'AAA survient chez un sujet **athéromateux** (AOMI surtout, mais aussi atteinte coronarienne ou carotidienne). Il existe des **formes familiales**, parfois liées à une maladie génétique des tissus élastiques (**Marfan**, **Ehlers-Danlos**, **Loeys-Dietz**). L'AAA peut aussi être l'évolution d'une **aortite** (maladies de **Takayasu**, de **Behçet** ou de **Horton**). Par le passé, les aortites infectieuses (syphilis) étaient fréquentes.\n\n### Diagnostic clinique\n\n[A] **Forme asymptomatique** :\n\n- le plus souvent **découverte fortuite**, lors d'une palpation abdominale (**masse battante et expansive** paraombilicale, avec ou sans souffle) ou, plus souvent, d'une imagerie abdominale (échographie, scanner ou IRM) ;\n- **dépistage échographique** dans le bilan du patient polyathéromateux, **notamment chez l'homme après 65 ans** (item 221, p. 41).\n\n[B] Population à dépister selon l'item 225 : **hommes > 65 ans**, ou plus jeunes avec des facteurs de risque (tabagisme, maladie athéromateuse, antécédents familiaux d'anévrisme).\n\n**Forme symptomatique** :\n\n- **Fissuration ou rupture** : douleur **abdominale ou lombaire**, avec ou sans **choc hémorragique** : **urgence vitale**. Un anévrisme douloureux fait craindre une rupture imminente : le patient est adressé **en urgence** à un centre spécialisé de chirurgie vasculaire, où un **scanner abdominal** confirme le diagnostic et précise la localisation. La rupture intrapéritonéale est habituellement cataclysmique, sans possibilité d'intervenir à temps. Beaucoup plus rarement, la fissuration se fait dans un organe voisin : **fistule aortocave** (insuffisance cardiaque à débit élevé) ou **aortodigestive** (hémorragie digestive).\n- Beaucoup plus rarement : **embolie** à partir du thrombus intra-anévrismal ; **compression** des organes voisins (érosion vertébrale, compression cave ou urétérale) ; **syndrome inflammatoire** (fièvre, altération de l'état général, VS et CRP élevées).\n\n### Diagnostic paraclinique\n\n- **Échographie abdominale** : dépistage, mesure du **diamètre maximal** et suivi ; elle dépiste aussi les localisations associées les plus fréquentes (poplitées, iliaques).\n- **Scanner abdominopelvien avec injection** : demandé quand une intervention est envisagée (diamètre, anatomie) ; c'est l'**examen préthérapeutique de référence**.\n- **IRM abdominale** : alternative, notamment si le scanner est contre-indiqué.\n- **Artériographie : pas utile** (elle ne montre que la lumière artérielle et ne mesure pas fiablement la taille, du fait du thrombus mural fréquent).","keyPoints":["Anévrisme : dilatation focale et permanente, avec perte du parallélisme des parois et diamètre augmenté de plus de 50 % par rapport à l'amont.","Facteurs de risque d'AAA : âge, tabagisme, antécédents familiaux d'anévrisme ; les diabétiques sont moins souvent atteints.","[B] 80-90 % des AAA surviennent sur terrain athéromateux ; sinon penser aux maladies du tissu élastique et aux aortites.","Le risque de rupture augmente avec le diamètre et est près de 4 fois plus élevé chez la femme à diamètre égal.","Le porteur d'AAA risque 10 fois plus de mourir d'une autre atteinte cardiovasculaire que d'une rupture.","L'échographie dépiste et surveille l'AAA ; le scanner injecté est l'examen préthérapeutique de référence."],"pitfalls":["Ne pas oublier de rechercher d'autres localisations anévrismales (poplitées, iliaques) et une maladie coronarienne ou carotidienne associée.","L'artériographie ne doit pas être utilisée pour mesurer le diamètre d'un AAA (sous-estimation par le thrombus mural)."],"src":"p. 183-185"},{"id":"225-sec-11","title":"Anévrisme de l'aorte abdominale : prise en charge, suivi, anévrisme poplité","rank":"A","objectives":["225-obj-14","225-obj-15"],"content":"### Forme asymptomatique\n\n[B] Le **diamètre** de l'aorte est le principal facteur prédictif du risque de rupture.\n\n- Croissance moyenne **2-4 mm/an**, non linéaire, avec de grandes variations individuelles ; plus rapide chez l'**homme**, **fumeur**, avec un anévrisme déjà volumineux.\n- Les petits anévrismes sont surveillés par **échographies répétées**, d'autant plus rapprochées que le diamètre approche du seuil d'intervention (**tous les 6 mois si > 45 mm**).\n- **Contrôle des facteurs de risque** indispensable pendant le suivi : la progression est **3 fois plus rapide** si le tabagisme se poursuit.\n\n[B] **Au-delà de 50-55 mm**, une intervention est indiquée : chirurgie classique ou endoprothèse par voie endovasculaire.\n\n[A] L'item 221 (p. 42) retient la chirurgie d'un AAA si le diamètre atteint **55 mm** (**50 mm chez la femme**) ou s'il **augmente de 5 mm/an ou plus**.\n\n[B] L'intervention « à froid » est programmée :\n\n- **chirurgie conventionnelle à ciel ouvert** (mise à plat-greffe) : exclusion de la zone anévrismale et interposition d'une **prothèse vasculaire** ;\n- **traitement endovasculaire** : **endoprothèse** introduite par voie artérielle fémorale, **moins invasive** ; proposée aux sujets à **haut risque chirurgical**, mais nécessitant des conditions anatomiques particulières ; si l'anatomie est favorable, elle peut être proposée même à bas risque, après information éclairée ; elle impose des **imageries répétées** (scanner, échographie de contraste) pour surveiller le sac anévrismal et la position de l'endoprothèse.\n\n### Forme symptomatique : rupture\n\n[A] La **rupture d'AAA est une urgence absolue** ; son diagnostic est confirmé par un **scanner** avant la prise en charge thérapeutique.\n\n[B] Aucune imagerie autre que ce scanner ne doit retarder l'intervention chez un patient en choc hémorragique ; la survie est d'autant meilleure que la prise en charge est rapide. L'**endoprothèse** est aussi proposée pour l'anévrisme rompu (résultats satisfaisants dans les équipes expérimentées), d'autant plus que le sujet est à très haut risque périopératoire. En cas d'**ischémie aiguë par embolie** à partir de l'AAA, la **revascularisation du membre** est l'urgence, la cure de l'AAA venant secondairement.\n\n### Suivi à long terme\n\n[B] Même après une intervention réussie, le patient reste à **haut risque cardiovasculaire** : il doit être surveillé et ses facteurs de risque contrôlés.\n\n- Prothèse de chirurgie conventionnelle : **échodoppler** à long terme (risque de **faux anévrismes anastomotiques** ; la thrombose est exceptionnelle).\n- Endoprothèse : surveillance au long cours par scanner ou échographie à la recherche d'**endofuites**, responsables d'une poursuite de l'évolution de l'anévrisme, voire d'une rupture. Ce sont des flux maintenant une pression dans le sac : défaut de coaptation des extrémités avec la paroi, défaut d'hermétisme entre deux endoprothèses, porosité, ou flux d'une branche connectée à l'aorte (ex. : artères lombaires).\n- Prothèse artérielle : risque d'infection lors d'une bactériémie, pouvant justifier une **antibioprophylaxie** lors de tout acte à risque bactérien.\n\n### Anévrisme de l'artère poplitée (AP)\n\n[A] Fréquemment associé à un AAA (**30 %** des cas), il est **bilatéral** dans près de la **moitié** des cas. Il est découvert par la palpation d'une **masse battante** (pouls trop bien perçu) au creux poplité, lors d'un **échodoppler** (notamment en cas de risque élevé : AAA ou AP controlatéral), ou dans un tableau d'artériopathie progressive, voire d'**ischémie aiguë**.\n\n> Chez tout patient porteur d'une AOMI ou d'un AAA, penser à rechercher une **maladie coronarienne** sous-jacente ou une **sténose carotidienne**.","keyPoints":["[B] Le diamètre de l'AAA est le principal facteur prédictif de rupture ; échographie tous les 6 mois au-delà de 45 mm.","[B] Une intervention est indiquée au-delà de 50-55 mm : chirurgie ouverte ou endoprothèse selon le risque opératoire et l'anatomie.","Item 221 : chirurgie d'un AAA si 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an.","La rupture d'AAA est une urgence absolue ; le scanner confirme le diagnostic avant le traitement.","[B] Après endoprothèse, surveillance au long cours à la recherche d'endofuites.","L'anévrisme poplité est associé à un AAA dans 30 % des cas et bilatéral près d'une fois sur deux."],"pitfalls":["[B] Ne pas retarder le traitement d'un AAA rompu par d'autres examens que le scanner diagnostique.","[B] Ne pas oublier la surveillance au long cours des endoprothèses (endofuites) et des prothèses chirurgicales (faux anévrismes anastomotiques).","Penser à rechercher un anévrisme poplité controlatéral ou un AAA associé devant tout anévrisme poplité."],"src":"p. 185-186, 188"},{"id":"225-sec-12","title":"Prise en charge complète par situation","rank":"A","objectives":["225-obj-04","225-obj-05","225-obj-09","225-obj-13","225-obj-14","225-obj-15","225-obj-17"],"content":"Chaque situation est résumée dans l'ordre : urgence et orientation → examens → traitements → surveillance → long cours. Les éléments marqués [B] sont de rang B.\n\n### 1. AOMI avec claudication intermittente (stade II)\n\n1. **Interrogatoire** : claudication typique ou atypique, en vérifiant que le patient marche réellement ; autres atteintes athéromateuses (angor, symptômes déficitaires cérébraux, troubles de l'érection).\n2. **Examen bilatéral et comparatif** : pouls, recoloration, troubles trophiques, souffles, recherche d'un anévrisme abdominal et poplité ; examen cardiovasculaire général.\n3. **IPS en 1re ligne** : AOMI si < 0,90, sévère si < 0,70 ; si > 1,40 (médiacalcose), pression d'orteil.\n4. **Examens** : test de marche sur tapis si IPS de repos normal chez un symptomatique (baisse de pression de cheville > 30 mmHg et/ou d'IPS > 20 %) ; **échodoppler artériel** pour localiser et quantifier les lésions ; angioscanner ou angio-IRM seulement si une revascularisation est envisagée.\n5. **Traitement général** : arrêt du tabac ; diabète (HbA1c < 7 %) ; PAS ≤ 120-129 et PAD ≤ 70-79 mmHg ; régime méditerranéen, IMC 20-25 kg/m² ; **statine** (LDL < 0,55 g/L et baisse ≥ 50 %) ; **aspirine ou clopidogrel** ; IEC (ou sartan) à considérer, notamment si HTA ou insuffisance cardiaque.\n6. **Traitement local** : **réadaptation à la marche**, de préférence supervisée (30-45 min, au moins 3 fois/semaine ; réentraînement 3 fois/semaine pendant 12 semaines), avec éducation thérapeutique.\n7. **Revascularisation** si claudication très invalidante (< 100 m), atteinte aorto-iliaque sévère et extensive, ou claudication sévère altérant la qualité de vie après un traitement médical bien mené incluant la réadaptation : angioplastie ± stent ou pontage, puis réadaptation. [B] Après angioplastie : bithérapie antiplaquettaire 1 à 6 mois.\n8. **Surveillance** : clinique et échodoppler après revascularisation ; contrôle des facteurs de risque au long cours ; recherche d'une maladie coronarienne ou d'une sténose carotidienne.\n\n### 2. AOMI en ischémie permanente ou critique (stades III-IV)\n\n1. **Reconnaître** : douleurs de décubitus soulagées en position déclive, troubles trophiques, douleurs > 15 jours résistant aux antalgiques ; **ischémie critique** si pression de cheville < 50 mmHg ou d'hallux < 30 mmHg : pronostic du membre engagé.\n2. **Examens** : IPS ou pression d'orteil, **TcPO2** (< 10 mmHg = hypoxie critique), échodoppler, puis angioscanner, angio-IRM ou artériographie pour planifier la revascularisation.\n3. **Revascularisation autant que possible** (endovasculaire, pontage, techniques hybrides).\n4. **Traitements associés** : antalgiques ; **soins de plaies** par une équipe multidisciplinaire ; traitement général (statine, antiagrégant, facteurs de risque) ; bêtabloquant seulement si indication formelle, avec prudence si non revascularisable ; [B] prostaglandines si ischémie critique non revascularisable.\n5. **Si revascularisation impossible ou en échec** : **amputation** en zone saine et bien oxygénée (TcPO2), en préservant l'appui ou le genou.\n6. **Long cours** : surveillance clinique et échodoppler des gestes ; prévention maintenue même chez les revascularisés (mortalité à 5 ans proche de 70 % en ischémie critique).\n\n### 3. Ischémie aiguë d'un membre inférieur\n\n1. **Urgence** : diagnostic clinique, grade de Rutherford, **alerte immédiate de l'équipe chirurgicale** ; aucune exploration ne doit retarder l'intervention.\n2. **Immédiatement** : prélever le bilan de coagulation puis **héparine non fractionnée** (bolus 5 000 UI, puis 500 UI/kg/j ; TCA entre 2 et 3) ; **antalgiques de niveau 3** ; **oxygène** nasal ; remplissage si nécessaire ; **soins locaux** (protection, position légèrement déclive).\n3. **Bilan initial** : auscultation cardiaque, **ECG**, palpation abdominale (anévrisme), bilan de coagulation ; échodoppler seulement si les conditions le permettent (grade I sans atteinte neurologique) ; évaluation du terrain.\n4. **Selon le grade** : I → imagerie en urgence puis revascularisation dans les heures à venir (thrombolyse, thrombectomie, pontage) ; II (déficit sensitif) → revascularisation en urgence absolue (thrombectomie, pontage) ; III → amputation.\n5. **Gestes** : embolectomie par sonde de **Fogarty** (embolie sur artère saine) ; thrombolyse in situ ou thromboaspiration (lit d'aval de mauvaise qualité et ischémie peu sévère) ; angioplastie si sténose résiduelle ; pontage en dernier ressort ; **aponévrotomie** de décompression si revascularisation tardive.\n6. **Après la revascularisation** : diurèse (sonde urinaire), ionogramme, urée, créatininémie, CPK ; bicarbonates IV si acidose ; polystyrène sulfonate de sodium, voire dialyse, si hyperkaliémie ; lavage du membre ; soins locaux poursuivis.\n7. **Bilan étiologique** après le geste : Holter ECG, ETT, voire ETO ou IRM ; échodoppler de l'aorte et des membres inférieurs, voire angioscanner ou artériographie.\n8. **Long cours** : cause embolique → traitement étiologique (anticoagulation au long cours si fibrillation atriale) ; cause thrombotique → antiagrégant plaquettaire et contrôle des facteurs de risque.\n\n### 4. AAA asymptomatique\n\n1. **Dépistage échographique**, notamment chez l'homme après 65 ans (item 221) ; sinon, découverte fortuite (palpation, imagerie). [B] Dépistage aussi chez le plus jeune avec tabagisme, maladie athéromateuse ou antécédents familiaux d'anévrisme.\n2. **Bilan** : échographie (diamètre maximal, recherche d'anévrismes poplités et iliaques) ; recherche d'une maladie coronarienne ou d'une sténose carotidienne.\n3. **Traitement médical** : contrôle des facteurs de risque, **arrêt du tabac**.\n4. [B] **Surveillance** par échographies répétées, tous les 6 mois si diamètre > 45 mm.\n5. **Avant une intervention** : scanner abdominopelvien injecté (bilan préthérapeutique de référence ; IRM si contre-indication). Seuil de l'item 221 : 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an. [B] Item 225 : intervention au-delà de 50-55 mm, chirurgie ouverte ou endoprothèse.\n6. [B] **Après l'intervention** : échodoppler à long terme après chirurgie (faux anévrismes anastomotiques) ; scanner ou échographie au long cours après endoprothèse (endofuites) ; antibioprophylaxie lors des actes à risque bactérien ; contrôle des facteurs de risque.\n\n### 5. AAA symptomatique (fissuration, rupture)\n\n1. Douleur abdominale ou lombaire, avec ou sans choc hémorragique, chez un porteur d'AAA → **urgence absolue** : orientation immédiate vers un centre spécialisé de chirurgie vasculaire.\n2. **Scanner** pour confirmer le diagnostic. [B] Aucune autre imagerie ne doit retarder l'intervention en cas de choc hémorragique.\n3. **Intervention en urgence**. [B] Chirurgie ou endoprothèse (surtout si très haut risque périopératoire).\n4. [B] Ischémie aiguë de membre par embolie à partir de l'AAA : revascularisation du membre en urgence, puis cure de l'AAA.\n5. **Suivi** comme après une intervention programmée.\n\n### 6. Ischémie mésentérique aiguë\n\n1. **Urgence vitale (chirurgicale)** : triade douleur abdominale aiguë avec paucité des signes physiques, vidange digestive accélérée, contexte embolique (fibrillation atriale) ; patient souvent polyathéromateux.\n\n### 7. Ischémie mésentérique chronique\n\n1. **Angor digestif** (douleurs après le repas), amaigrissement, souffle abdominal.\n2. [B] **Échodoppler des artères digestives**, angioscanner ou angio-IRM ; artériographie seulement lors d'une revascularisation endovasculaire.","keyPoints":["Claudication : IPS, échodoppler, statine + antiplaquettaire + contrôle des facteurs de risque, réadaptation à la marche ; revascularisation si très invalidante ou atteinte aorto-iliaque sévère.","Ischémie critique : revasculariser autant que possible, sinon amputation.","Ischémie aiguë : héparine, antalgiques, soins locaux, puis geste selon le grade de Rutherford.","[B] AAA asymptomatique (item 225) : surveillance échographique, intervention au-delà de 50-55 mm.","Rupture d'AAA = urgence absolue confirmée par scanner ; chirurgie d'un AAA asymptomatique si 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an (item 221).","Ischémie mésentérique aiguë : urgence vitale (chirurgicale), à évoquer devant une douleur abdominale pauvre en signes physiques avec vidange digestive accélérée et contexte embolique."],"pitfalls":["Aucun examen ne doit retarder la prise en charge d'une ischémie aiguë de membre.","Penser à la maladie coronarienne et carotidienne chez tout patient avec AOMI ou AAA."],"src":"p. 166-188"}],"essentials":[{"id":"225-ess-01","rank":"A","text":"L'AOMI est une atteinte athéromateuse significative des artères entre l'aorte terminale et les artères digitales.","src":"p. 167","q":"Définissez l'artériopathie oblitérante des membres inférieurs (AOMI) ?"},{"id":"225-ess-02","rank":"A","text":"L'AOMI est la 3e localisation de l'athérosclérose après les atteintes coronarienne et cérébrale.","src":"p. 167","q":"Quel rang occupe l'AOMI parmi les localisations de l'athérosclérose ?"},{"id":"225-ess-03","rank":"B","text":"Le tabagisme et le diabète sont les deux principaux facteurs de risque de l'AOMI.","src":"p. 168, 187","q":"Quels sont les deux principaux facteurs de risque de l'AOMI ?"},{"id":"225-ess-04","rank":"B","text":"Le diabète est plus souvent responsable de formes graves d'emblée, avec une atteinte plus distale et un pronostic plus sévère.","src":"p. 168","q":"Quelle particularité de l'AOMI du diabétique (localisation, pronostic) ?"},{"id":"225-ess-05","rank":"A","text":"La classification de Leriche et Fontaine comporte 4 stades : asymptomatique, claudication, douleur de repos, troubles trophiques.","src":"p. 168","q":"Quels sont les 4 stades de la classification de Leriche et Fontaine ?"},{"id":"225-ess-06","rank":"A","text":"La classification de Leriche et Fontaine est le plus souvent supplantée de nos jours par la classification internationale de Rutherford.","src":"p. 168","q":"Quelle classification de l'AOMI tend aujourd'hui à remplacer celle de Leriche et Fontaine ?"},{"id":"225-ess-07","rank":"A","text":"La claudication intermittente est dite sévère lorsque la distance de marche est inférieure à 100 m.","src":"p. 169","q":"À quelle distance de marche la claudication intermittente est-elle dite sévère ?"},{"id":"225-ess-08","rank":"A","text":"Claudication fessière et/ou fatigabilité à la marche et impuissance (troubles de l'érection), en rapport avec une atteinte aorto-iliaque.","src":"p. 169","q":"Quels éléments composent le syndrome de Leriche, et quelle atteinte artérielle le provoque ?"},{"id":"225-ess-09","rank":"A","text":"Ischémie permanente avec pressions de perfusion effondrées : < 50 mmHg à la cheville ou < 30 mmHg à l'hallux (pronostic du membre engagé).","src":"p. 169","q":"Comment définit-on l'ischémie critique (pressions de cheville et d'hallux) ?"},{"id":"225-ess-10","rank":"A","text":"Le pouls pédieux peut être physiologiquement absent chez environ 5 % de la population.","src":"p. 170","q":"Chez quelle proportion de la population le pouls pédieux peut-il être physiologiquement absent ?"},{"id":"225-ess-11","rank":"A","text":"L'index de pression systolique (IPS), qui peut être mesuré au cabinet, est l'examen à réaliser en 1re ligne devant une suspicion d'AOMI.","src":"p. 170, 579","q":"Quel est l'examen de première intention devant une suspicion d'AOMI ?"},{"id":"225-ess-12","rank":"A","text":"Un IPS inférieur à 0,90 sur au moins une cheville affirme le diagnostic d'AOMI.","src":"p. 171","q":"Quelle valeur d'IPS affirme le diagnostic d'AOMI ?"},{"id":"225-ess-13","rank":"A","text":"Un IPS inférieur à 0,70 définit une AOMI sévère.","src":"p. 171","q":"Quelle valeur d'IPS définit une AOMI sévère ?"},{"id":"225-ess-14","rank":"A","text":"Un IPS supérieur à 1,40 traduit une médiacalcose et impose de recourir à la pression d'orteil.","src":"p. 171","q":"Que traduit un IPS supérieur à 1,40 et que faut-il alors faire ?"},{"id":"225-ess-15","rank":"A","text":"Il est associé à un risque cardiovasculaire élevé (accident coronarien ou cérébral, fatal ou non) : l'IPS est un marqueur de risque cardiovasculaire.","src":"p. 171","q":"Quelle valeur pronostique générale a un IPS inférieur à 0,90 ?"},{"id":"225-ess-16","rank":"A","text":"Le test de marche sur tapis roulant (Strandness : 3,2 km/h, pente 10 %) : baisse de la pression de cheville > 30 mmHg et/ou de l'IPS > 20 % juste après la marche.","src":"p. 171","q":"Quel examen démasque une AOMI chez un claudicant à IPS de repos normal, et avec quels critères ?"},{"id":"225-ess-17","rank":"A","text":"L'échodoppler artériel des membres inférieurs, exploration la plus utilisée car non invasive : il identifie les lésions et quantifie leur sévérité dans l'immense majorité des cas.","src":"p. 172","q":"Quel examen d'imagerie non invasif localise et quantifie les sténoses de l'AOMI ?"},{"id":"225-ess-18","rank":"A","text":"L'angioscanner et l'angio-IRM uniquement s'il existe une indication de revascularisation ; l'artériographie est essentiellement limitée aux procédures de revascularisation.","src":"p. 172-173","q":"Quand demande-t-on angioscanner, angio-IRM ou artériographie dans l'AOMI ?"},{"id":"225-ess-19","rank":"B","text":"Plus de 95 % des AOMI ont une origine athéromateuse.","src":"p. 174","q":"Quelle proportion des AOMI est d'origine athéromateuse ?"},{"id":"225-ess-20","rank":"A","text":"Le contrôle des facteurs de risque cardiovasculaire s'applique à tous les stades de l'AOMI.","src":"p. 175","q":"À quels stades de l'AOMI applique-t-on le contrôle des facteurs de risque cardiovasculaire ?"},{"id":"225-ess-21","rank":"A","text":"Un antiagrégant plaquettaire (aspirine ou clopidogrel) chez tout patient avec AOMI symptomatique, pour réduire le risque d'infarctus et d'AVC.","src":"p. 175","q":"Quel traitement médicamenteux est indiqué chez tout patient atteint d'AOMI symptomatique ?"},{"id":"225-ess-22","rank":"A","text":"L'objectif de LDL-cholestérol sous statine chez le patient AOMI est inférieur à 0,55 g/L, avec une réduction d'au moins 50 %.","src":"p. 175","q":"Quel est l'objectif de LDL-cholestérol sous statine chez le patient AOMI, et quelle réduction viser ?"},{"id":"225-ess-23","rank":"A","text":"En cas d'ischémie permanente (stades III et IV).","src":"p. 176","q":"Dans quelle forme d'AOMI la revascularisation doit-elle être proposée autant que possible ?"},{"id":"225-ess-24","rank":"A","text":"L'espérance de vie des patients claudicants est en moyenne réduite de 10 ans.","src":"p. 177","q":"Quel est l'impact de la claudication sur l'espérance de vie des patients ?"},{"id":"225-ess-25","rank":"A","text":"La mortalité à 5 ans des patients en ischémie critique est proche de 70 %.","src":"p. 178","q":"Quelle est la mortalité à 5 ans des patients en ischémie critique ?"},{"id":"225-ess-26","rank":"A","text":"L'ischémie aiguë de membre est une urgence vasculaire pouvant engager le pronostic du membre et du patient.","src":"p. 178","q":"Quel est le caractère de l'ischémie aiguë de membre en termes de gravité et de pronostic ?"},{"id":"225-ess-27","rank":"A","text":"Les cellules nerveuses souffrent les premières, dans les 2 heures, puis les cellules musculaires dans les 6-8 heures (rhabdomyolyse).","src":"p. 178","q":"Au bout de combien de temps les cellules nerveuses puis musculaires souffrent-elles dans l'ischémie aiguë ?"},{"id":"225-ess-28","rank":"A","text":"Grade I : viable ; IIa : ischémie discrètement menaçante ; IIb : ischémie immédiatement menaçante ; III : irréversible.","src":"p. 179","q":"Quels grades distingue la classification de Rutherford de l'ischémie aiguë ?"},{"id":"225-ess-29","rank":"A","text":"Le diagnostic est essentiellement clinique ; aucune exploration ne doit retarder l'intervention, notamment en cas d'atteinte neurologique (grade II).","src":"p. 180","q":"Sur quoi repose le diagnostic de l'ischémie aiguë de membre, et que faire en cas de déficit neurologique ?"},{"id":"225-ess-30","rank":"B","text":"Thrombose in situ : sujet le plus souvent âgé, avec facteurs de risque, voire AOMI préexistante. Embolie : sujet classiquement jeune, sans antécédent vasculaire connu, sur artères saines.","src":"p. 181","q":"Comparez le terrain de la thrombose in situ et celui de l'embolie dans l'ischémie aiguë ?"},{"id":"225-ess-31","rank":"B","text":"Troubles du rythme (fibrillation atriale), foramen ovale perméable et anévrisme du septum interatrial, infarctus du myocarde (faux anévrisme de paroi), endocardite infectieuse, valvulopathies et prothèses valvulaires, myxome de l'atrium, dyskinésie ou anévrisme du VG.","src":"p. 181","q":"Quelles sont les causes cardiaques d'embolie artérielle des membres ?"},{"id":"225-ess-32","rank":"A","text":"L'embolectomie à la sonde de Fogarty est le traitement de référence de l'ischémie aiguë par embolie sur artère saine.","src":"p. 182","q":"Quel est le traitement de référence de l'ischémie aiguë par embolie sur artère saine ?"},{"id":"225-ess-33","rank":"A","text":"Troubles métaboliques (hyperkaliémie, acidose métabolique, myoglobinémie/myoglobinurie…), insuffisance rénale aiguë par nécrose tubulaire ; plus rarement choc hypovolémique ou infectieux.","src":"p. 178-183","q":"Quelles conséquences générales la reperfusion d'un membre ischémique peut-elle entraîner ?"},{"id":"225-ess-34","rank":"A","text":"Dilatation focale et permanente avec perte du parallélisme des parois et augmentation de diamètre de plus de 50 % par rapport au diamètre d'amont.","src":"p. 183","q":"Comment définit-on un anévrisme (critère de diamètre) ?"},{"id":"225-ess-35","rank":"B","text":"Dans 80 à 90 % des cas, l'anévrisme de l'aorte abdominale survient chez un patient athéromateux.","src":"p. 184","q":"Dans quelle proportion l'anévrisme de l'aorte abdominale survient-il chez un patient athéromateux ?"},{"id":"225-ess-36","rank":"A","text":"Il augmente de façon exponentielle avec le diamètre (0,4 %/an si < 40 mm, 3 % à 50-59 mm, 15 % au-delà de 60 mm) et est près de 4 fois plus élevé chez la femme à diamètre égal.","src":"p. 184","q":"Comment le risque annuel de rupture d'un AAA varie-t-il avec le diamètre et le sexe ?"},{"id":"225-ess-37","rank":"A","text":"Il risque 10 fois plus de décéder d'une autre atteinte cardiovasculaire (coronarienne ou AVC) que d'une rupture d'AAA.","src":"p. 184","q":"Comparez le risque de décès cardiovasculaire et le risque de décès par rupture chez un porteur d'AAA ?"},{"id":"225-ess-38","rank":"A","text":"L'échographie abdominale est l'examen de dépistage et de surveillance de l'AAA.","src":"p. 184","q":"Quel examen sert au dépistage et à la surveillance de l'AAA ?"},{"id":"225-ess-39","rank":"A","text":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence de l'AAA.","src":"p. 185","q":"Quel est l'examen préthérapeutique de référence de l'AAA ?"},{"id":"225-ess-40","rank":"A","text":"Urgence absolue ; le diagnostic est confirmé par un scanner avant la prise en charge thérapeutique.","src":"p. 184, 188","q":"Quel degré d'urgence représente la rupture d'AAA, et comment confirmer le diagnostic ?"},{"id":"225-ess-51","rank":"A","q":"Citez la triade clinique de l'ischémie mésentérique aiguë ?","text":"1) Douleur abdominale aiguë avec **paucité de signes physiques** ; 2) **vidange digestive accélérée** (vomissements et/ou diarrhée) ; 3) indices d'une cause embolique, notamment une **fibrillation atriale**.","src":"p. 167","kind":"liste"},{"id":"225-ess-52","rank":"A","q":"Citez les formes atypiques de claudication intermittente (5) ?","text":"Distances de marche variables d'un jour à l'autre ; autres sièges (pied, cuisse, fesse par atteinte aorto-iliaque) ; douleurs de faible intensité, parfois de repos et d'effort ; paresthésies ou engourdissement d'effort ; patient qui ralentit le pas sans s'arrêter.","src":"p. 169","kind":"liste"},{"id":"225-ess-53","rank":"A","q":"Pourquoi une AOMI sévère peut-elle rester asymptomatique (3 raisons) ?","text":"Importante circulation collatérale ; sujet très âgé avec comorbidités empêchant de marcher (IC, IR, arthrose) ; neuropathie altérant la sensibilité (diabète, IR, âge).","src":"p. 169","kind":"liste"},{"id":"225-ess-54","rank":"A","q":"Citez les signes physiques de l'examen d'un patient AOMI (inspection, palpation, auscultation) ?","text":"Inspection : pied pâle ou cyanosé, troubles trophiques (espaces interdigitaux). Palpation : pied froid, douleur à la pression du mollet, pouls (fémoral, poplité, tibial postérieur, pédieux), recoloration allongée (normale < 3 s), anévrisme abdominal et poplité. Auscultation : souffles. Examen bilatéral et comparatif.","src":"p. 170","kind":"liste"},{"id":"225-ess-55","rank":"A","q":"Quelles causes de douleur à la marche évoquer en diagnostic différentiel de l'AOMI ?","text":"Neurologiques (canal lombaire étroit, sciatalgie, atteinte médullaire) ; rhumatologiques ; claudication veineuse ; piège poplité, kyste poplité, endofibrose iliaque, syndrome des loges ; malformations vasculaires ; douleurs musculaires sous statines.","src":"p. 174","kind":"liste"},{"id":"225-ess-56","rank":"B","q":"Citez les artériopathies non athéromateuses des membres inférieurs ?","text":"Inflammatoires (Buerger, Takayasu, Horton, collagénoses) ; dysplasie fibromusculaire ; coarctation de l'aorte ; postradiques ; post-traumatiques ; toxiques (ergot de seigle) ; gelures ; compressions extrinsèques ; atteintes poplitées spécifiques (artère poplitée piégée, kyste sous-adventiciel).","src":"p. 174","kind":"liste"},{"id":"225-ess-57","rank":"A","q":"Citez les cibles du traitement général de l'AOMI (PA, HbA1c, LDL, IMC, entraînement) ?","text":"PAS ≤ 120-129 et PAD ≤ 70-79 mmHg ; HbA1c < 7 % ; LDL-C < 0,55 g/L (< 1,4 mmol/L) ; IMC 20-25 kg/m² ; réentraînement 3 fois/semaine pendant 12 semaines ; IEC ou sartan à considérer chez tous.","src":"p. 175","kind":"liste"},{"id":"225-ess-58","rank":"A","q":"Citez les facteurs qui déterminent la gravité de la baisse de débit dans l'ischémie aiguë ?","text":"1) Pression artérielle systémique ; 2) abondance de la circulation collatérale ; 3) qualité du réseau artériel d'aval.","src":"p. 178","kind":"liste"},{"id":"225-ess-59","rank":"A","q":"Citez les signes cliniques de l'ischémie aiguë d'un membre inférieur ?","text":"Douleur brutale intense « en broiement », impotence fonctionnelle ; membre froid et livide ; douleur à la palpation musculaire ; pouls abolis en aval ; anesthésie et paralysie (nerf fibulaire commun).","src":"p. 179","kind":"liste"},{"id":"225-ess-60","rank":"A","q":"Citez les troubles métaboliques du syndrome de revascularisation (7 éléments) ?","text":"Hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie/myoglobinurie, élévation de la créatininémie, hypocalcémie, hyperphosphorémie ; CIVD possible.","src":"p. 178","kind":"liste"},{"id":"225-ess-61","rank":"A","q":"Citez les 5 volets du traitement médical de l'ischémie aiguë ?","text":"Héparine non fractionnée IV ; antalgiques de niveau 3 ; oxygénothérapie nasale ; équilibration hémodynamique (remplissage) ; soins locaux (protection mousse, position légèrement déclive, éviter frottements).","src":"p. 182","kind":"liste"},{"id":"225-ess-62","rank":"A","q":"Comment calcule-t-on l'IPS pour chaque membre (quelles pressions retenir) ?","text":"**Pression la plus élevée des deux artères de cheville** (tibiale postérieure, pédieuse ; la fibulaire n'est pas mesurée) divisée par la **pression systolique la plus élevée des deux bras**, mesurées au doppler.","src":"p. 170-171","kind":"piege"},{"id":"225-ess-63","rank":"A","q":"Quels sont les seuils de TcPO2 au dos du pied : normal, bonne compensation, hypoxie continue, critique ?","text":"Normal **> 50 mmHg** ; bonne compensation **> 35** ; hypoxie continue **10-35** ; hypoxie critique **< 10 mmHg**. Mesure après hyperémie par la chaleur.","src":"p. 171","kind":"piege"},{"id":"225-ess-64","rank":"A","q":"Comment définit-on l'ischémie permanente, et quand parle-t-on d'ischémie critique ?","text":"Stades III et IV avec douleurs **> 15 jours** résistant aux antalgiques usuels. Critique si pression de cheville **< 50 mmHg** ou d'hallux **< 30 mmHg** : pronostic du membre engagé.","src":"p. 169","kind":"piege"},{"id":"225-ess-65","rank":"A","q":"Comment se comporte la douleur de décubitus de l'AOMI en fonction de la position ?","text":"Brûlures des orteils et de l'avant-pied après quelques minutes à heures de décubitus, **améliorées en position déclive** (jambes pendantes au bord du lit) ; pied froid, pâle ou cyanosé.","src":"p. 169","kind":"piege"},{"id":"225-ess-66","rank":"A","q":"Quand propose-t-on la revascularisation pour une claudication intermittente ?","text":"Claudication sévère altérant la qualité de vie **après traitement médical et réadaptation** bien menés, ou d'emblée si périmètre **< 100 m** avec handicap important, ou atteinte aorto-iliaque sévère.","src":"p. 176","kind":"piege"},{"id":"225-ess-67","rank":"B","q":"Quelle place pour la pentoxifylline et les prostaglandines dans l'AOMI ?","text":"Vasoactifs (pentoxifylline) : bénéfice modeste sur le périmètre de marche, **sans bénéfice pronostique**. Prostaglandines : ischémie critique **non revascularisable**, perfusions quotidiennes en milieu spécialisé.","src":"p. 176","kind":"piege"},{"id":"225-ess-68","rank":"A","q":"Quelle est la prise en charge de l'ischémie aiguë selon le grade de Rutherford ?","text":"Pour tous : héparine, antalgiques, soins locaux. Grade I (viable) : imagerie en urgence puis revascularisation dans les heures à venir. Grade II (déficit sensitif) : revascularisation en urgence absolue. Grade III (irréversible) : amputation. Puis traitement médical et bilan étiologique.","src":"p. 180","kind":"piege"},{"id":"225-ess-69","rank":"A","q":"Quels examens peuvent être faits dans l'ischémie aiguë sans retarder le geste ?","text":"Échodoppler seulement si les conditions locales et la sévérité le permettent (notamment grade I, sans atteinte neurologique) ; artériographie au bloc ; auscultation cardiaque, ECG, palpation abdominale, bilan de coagulation. Autres examens après revascularisation.","src":"p. 180, 182","kind":"piege"},{"id":"225-ess-70","rank":"A","q":"Quand préférer la thrombolyse in situ à l'embolectomie dans l'ischémie aiguë ?","text":"Si le **lit d'aval jambier est mauvais** et l'ischémie **peu sévère** : thrombolyse intra-artérielle ou thromboaspiration. Embolectomie de Fogarty = référence pour l'embolie sur artère saine.","src":"p. 182","kind":"piege"},{"id":"225-ess-71","rank":"A","q":"Quand associer une aponévrotomie à la revascularisation, et quel traitement des conséquences métaboliques ?","text":"Aponévrotomie de décompression si revascularisation **tardive** (loge antéroexterne) pour éviter le syndrome des loges. Acidose : bicarbonates IV ; hyperkaliémie : polystyrène sulfonate, voire dialyse ; lavage du membre.","src":"p. 183","kind":"piege"},{"id":"225-ess-72","rank":"B","q":"Comment différencier thrombose in situ et embolie sur artères saines (terrain, douleur) ?","text":"Thrombose : sujet âgé avec FDR, voire AOMI ; douleur d'intensité moyenne, installation progressive ou rapide. Embolie : sujet jeune sans antécédent vasculaire ; douleur brutale et sévère (pas de collatérales) ; palpitations possibles.","src":"p. 181","kind":"piege"},{"id":"225-ess-73","rank":"B","q":"À quel rythme surveiller un AAA par échographie, et quel effet du tabac sur sa croissance ?","text":"Tous les **6 mois si diamètre > 45 mm** ; croissance moyenne 2-4 mm/an ; progression **3 fois plus rapide** si le tabagisme continue ; plus rapide chez l'homme fumeur à gros diamètre.","src":"p. 185-186","kind":"piege"},{"id":"225-ess-74","rank":"A","q":"Quelle est la relation entre risque de rupture d'AAA, sexe et risque cardiovasculaire ?","text":"À diamètre égal, risque de rupture près de **4 fois plus important chez la femme**. Le porteur d'AAA a **10 fois plus** de risque de mourir d'une autre atteinte CV (coronaire, AVC) que de rupture.","src":"p. 184","kind":"piege"},{"id":"225-ess-75","rank":"B","q":"Quelles sont les causes d'AAA familial ou non athéromateux ?","text":"Maladies des tissus élastiques (Marfan, Ehlers-Danlos, Loeys-Dietz) ; évolution d'une aortite (Takayasu, Behçet ou Horton) ; par le passé, aortites infectieuses (syphilis). L'athérome reste la cause dans 80-90 % des cas.","src":"p. 184","kind":"B"},{"id":"225-ess-76","rank":"A","q":"Quel est le mécanisme de l'altération de la média dans l'AAA ?","text":"Destruction des fibres élastiques et fragmentation du collagène, favorisées par des enzymes détruisant la matrice collagénique (ex. **métalloprotéases**) ; AAA le plus souvent sous-rénal.","src":"p. 183","kind":""},{"id":"225-ess-77","rank":"A","q":"Quelles sont les manifestations rares d'un AAA symptomatique, hors rupture classique ?","text":"Fistule aortocave (IC à haut débit) ou aortodigestive (hémorragie digestive) ; embolie depuis le thrombus ; compression (vertèbre, cave, uretère) ; syndrome inflammatoire (fièvre, VS, CRP).","src":"p. 184","kind":""},{"id":"225-ess-78","rank":"B","q":"Quels sont les mécanismes des endofuites après endoprothèse d'AAA ?","text":"Défaut de coaptation aux extrémités, défaut d'hermétisme entre deux endoprothèses, porosité de l'endoprothèse, flux d'une branche connectée (artères lombaires) ; surveillance scanner/échographie au long cours.","src":"p. 186","kind":"B"},{"id":"225-ess-79","rank":"B","q":"Comment surveiller une prothèse aortique de chirurgie conventionnelle et quelle prophylaxie ?","text":"Échodoppler à long terme (risque de **faux anévrismes** aux anastomoses, thrombose exceptionnelle) ; antibioprophylaxie lors de tout acte à risque bactérien (infection de prothèse).","src":"p. 186","kind":"B"},{"id":"225-ess-80","rank":"A","q":"Quelles particularités de l'anévrisme poplité ?","text":"Associé à un AAA dans 30 % des cas, bilatéral dans près de la moitié ; découvert par une masse battante au creux poplité, par échodoppler (si AAA ou AP controlatéral) ou dans un tableau d'artériopathie progressive, voire d'ischémie aiguë.","src":"p. 186","kind":""},{"id":"225-ess-81","rank":"A","q":"Quelle est la fréquence des plaques d'athérome aortiques à l'imagerie, et leur facteur de risque principal ?","text":"Plaques chez **25 % des hommes et 20 % des femmes de 40-55 ans** ; le tabagisme est le facteur le plus fortement associé ; marqueur de risque CV, possible source d'emboles.","src":"p. 166","kind":""},{"id":"225-ess-82","rank":"B","q":"Quel est le tableau de l'ischémie mésentérique chronique et son diagnostic ?","text":"Angor digestif : douleurs abdominales **postprandiales**, amaigrissement ; souffle abdominal ; échodoppler des artères digestives, angioscanner ou angio-IRM ; artériographie seulement lors d'une revascularisation endovasculaire.","src":"p. 166, 187","kind":"B"},{"id":"225-ess-83","rank":"A","q":"Quelle est l'évolution des claudicants à 5 ans sur le plan local et vital ?","text":"20 % de complications CV, 20 % de décès (la moitié CV) ; 25 % aggravation de l'artériopathie dont 1/5 d'amputation majeure ; amputation à 5 ans ≈ 5 %. Espérance de vie réduite de 10 ans.","src":"p. 177","kind":""},{"id":"225-ess-84","rank":"A","q":"Quelle est la physiopathologie du syndrome des loges dans l'ischémie aiguë ?","text":"L'anoxie musculaire entraîne vasodilatation capillaire, œdème et hausse de pression interstitielle ; les loges aponévrotiques inextensibles compriment les tissus jusqu'à l'arrêt circulatoire ; seule une **aponévrotomie** libère le muscle.","src":"p. 178","kind":""},{"id":"225-ess-85","rank":"A","q":"Quels sont les mécanismes de l'insuffisance rénale dans le syndrome de revascularisation ?","text":"Nécrose tubulaire aiguë due au choc, à l'instabilité de la perfusion rénale, à la précipitation intratubulaire de myoglobine, à sa toxicité en milieu acide et aux produits de contraste.","src":"p. 178-179","kind":""},{"id":"225-ess-86","rank":"B","q":"Quelles sont les causes de thrombose artérielle in situ sur artère initialement saine ?","text":"Kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, causes iatrogènes (cathétérisme, thrombopénie à l'héparine, ergotisme), déshydratation du sujet âgé.","src":"p. 181","kind":"B"},{"id":"225-ess-87","rank":"B","q":"À partir de quel diamètre un AAA asymptomatique doit-il être traité, et par quelles techniques ?","text":"Au-delà de 50-55 mm : chirurgie conventionnelle à ciel ouvert (mise à plat-greffe avec prothèse) ou endoprothèse par voie endovasculaire.","src":"p. 186, 188"},{"id":"225-ess-88","rank":"A","q":"Quels sont les principaux facteurs de risque d'AAA en dehors de l'âge ?","text":"Le tabagisme et les antécédents familiaux d'anévrisme ; risque plus élevé si autre localisation aortique (thoracique) ou artérielle périphérique. Les diabétiques sont moins souvent atteints.","src":"p. 183, 187"},{"id":"225-ess-89","rank":"B","q":"Chez qui faut-il dépister un AAA, et par quel examen ?","text":"Par échographie, chez les patients à risque : hommes > 65 ans, ou plus jeunes avec facteurs de risque (tabagisme, maladie athéromateuse, antécédents familiaux d'anévrisme).","src":"p. 184"},{"id":"225-ess-90","rank":"A","q":"Que faut-il penser à rechercher chez un patient porteur d'une AOMI ou d'un AAA ?","text":"Une maladie coronarienne sous-jacente ou une sténose carotidienne.","src":"p. 188"},{"id":"225-ess-93","rank":"A","q":"Quelle est la stratégie de prise en charge d'une claudication intermittente (fig. 7.6) ?","text":"Pour tous : facteurs de risque, statine + antiplaquettaire (+ IEC si HTA ou insuffisance cardiaque). Si périmètre < 100 m ou atteinte aorto-iliaque sévère et extensive : envisager une revascularisation puis réadaptation ; sinon réadaptation à la marche, de préférence supervisée.","src":"p. 177"},{"id":"225-ess-94","rank":"A","q":"Quelle est la prise en charge de l'ischémie critique de l'AOMI ?","text":"Revasculariser le membre autant que possible ; en cas d'impossibilité ou d'échec sans autre option, envisager l'amputation.","src":"p. 177"},{"id":"225-ess-95","rank":"A","q":"Quelle est la forme la plus grave d'ischémie aiguë des membres inférieurs, et comment se présente-t-elle ?","text":"L'occlusion de la bifurcation aortique : ischémie bilatérale sévère avec paralysie sensitivomotrice ; signes généraux au premier plan, jusqu'au collapsus cardiovasculaire.","src":"p. 179"},{"id":"225-ess-96","rank":"A","q":"Où siègent habituellement les ulcères artériels de l'AOMI ?","text":"Aux zones de frottement ou d'appui (orteil, dos et bord externe du pied, talon), parfois à la face antérieure de jambe (ulcère « suspendu »).","src":"p. 169"},{"id":"225-ess-97","rank":"A","q":"Quels sont les principes d'une amputation dans l'AOMI ?","text":"Geste ultime, à défaut de toute revascularisation possible, pour traiter la douleur et/ou limiter l'infection ; en zone saine et bien oxygénée (TcPO2), en préservant l'appui (orteil, transmétatarsienne) ou le genou pour l'appareillage.","src":"p. 176-177"},{"id":"225-ess-98","rank":"A","q":"Quel bilan étiologique réaliser après la revascularisation d'une ischémie aiguë de membre ?","text":"Bilan cardiaque (Holter ECG, ETT, voire ETO ou IRM) et bilan artériel (échodoppler de l'aorte et des membres inférieurs, voire angioscanner ou artériographie).","src":"p. 182"},{"id":"225-ess-99","rank":"A","q":"Quel traitement au long cours après une ischémie aiguë de membre, selon son mécanisme ?","text":"Cause embolique : traitement étiologique (ex. : anticoagulation au long cours si fibrillation atriale). Cause thrombotique : antiagrégant plaquettaire et contrôle des facteurs de risque cardiovasculaire.","src":"p. 183"},{"id":"225-ess-100","rank":"A","q":"Comment se révèle une fissuration ou rupture d'AAA, et quelle est la conduite à tenir ?","text":"Douleur abdominale ou lombaire, avec ou sans choc hémorragique : urgence vitale ; adresser en urgence à un centre de chirurgie vasculaire, où un scanner confirme le diagnostic.","src":"p. 184"},{"id":"225-ess-101","rank":"A","q":"Pourquoi l'artériographie n'est-elle pas utile au bilan d'un AAA ?","text":"Elle ne montre que la lumière artérielle et ne donne pas une mesure fiable de la taille de l'AAA, du fait du thrombus mural intra-anévrismal fréquent.","src":"p. 185"},{"id":"225-ess-102","rank":"A","q":"Quels apports de l'artériographie réalisée au bloc dans l'ischémie aiguë de membre ?","text":"Localiser l'oblitération, préciser l'aspect de l'occlusion (athérome, anévrisme, dissection…), apprécier le réseau artériel d'aval et, en cas d'embolie, révéler d'autres emboles asymptomatiques.","src":"p. 180"},{"id":"225-ess-103","rank":"A","q":"Quel dépistage aortique fait partie du bilan d'extension du patient polyathéromateux, et chez qui surtout ?","text":"Un dépistage de l'anévrisme de l'aorte abdominale (échographie), notamment chez l'homme après 65 ans.","src":"p. 41, 184"},{"id":"225-ess-104","rank":"A","q":"Selon l'item 221, à partir de quand opère-t-on un anévrisme de l'aorte abdominale asymptomatique ?","text":"Si le diamètre atteint 55 mm (50 mm chez la femme) ou s'il augmente de 5 mm/an ou plus (l'item 225 dit au-delà de 50-55 mm, rang B).","src":"p. 42"}],"numbers":[{"id":"225-num-01","rank":"A","label":"Rang de l'AOMI parmi les localisations de l'athérosclérose","value":"3e (après coronaire et cérébrale)","src":"p. 167"},{"id":"225-num-02","rank":"A","label":"Pic d'âge de l'AOMI symptomatique (homme / femme)","value":"60-75 ans / 70-80 ans","src":"p. 167"},{"id":"225-num-03","rank":"A","label":"Prévalence de l'AOMI clinique après 60 ans","value":"1-5 %","src":"p. 168"},{"id":"225-num-04","rank":"A","label":"Prévalence de l'AOMI (clinique + infraclinique) après 60 ans","value":"10-15 %","src":"p. 168"},{"id":"225-num-05","rank":"A","label":"Ratio formes infracliniques / clinique d'AOMI","value":"2 à 4 pour 1","src":"p. 168"},{"id":"225-num-06","rank":"A","label":"Distance de marche définissant une claudication sévère","value":"< 100 m","src":"p. 169"},{"id":"225-num-07","rank":"A","label":"Délai de disparition de la douleur de claudication au repos","value":"< 5 minutes","src":"p. 168"},{"id":"225-num-08","rank":"A","label":"Fréquence d'absence congénitale du pouls pédieux","value":"5 % de la population","src":"p. 170"},{"id":"225-num-09","rank":"A","label":"Temps de recoloration cutanée normal","value":"< 3 secondes","src":"p. 170"},{"id":"225-num-10","rank":"A","label":"IPS normal","value":"1,00 à 1,40","src":"p. 171"},{"id":"225-num-11","rank":"A","label":"Seuil d'IPS diagnostique d'AOMI","value":"< 0,90","src":"p. 171"},{"id":"225-num-12","rank":"A","label":"Seuil d'IPS d'AOMI sévère","value":"< 0,70","src":"p. 171"},{"id":"225-num-13","rank":"A","label":"Seuil d'IPS évoquant une médiacalcose","value":"> 1,40","src":"p. 171"},{"id":"225-num-14","rank":"A","label":"Seuil pathologique de l'index de pression d'orteil","value":"< 0,70","src":"p. 171"},{"id":"225-num-15","rank":"A","label":"Pression d'orteil définissant l'ischémie critique","value":"< 30 mmHg","src":"p. 171"},{"id":"225-num-16","rank":"A","label":"Pression de cheville définissant l'ischémie critique","value":"< 50 mmHg","src":"p. 169"},{"id":"225-num-17","rank":"A","label":"Protocole du test de marche sur tapis roulant (Strandness)","value":"3,2 km/h, pente 10 %","src":"p. 171"},{"id":"225-num-18","rank":"A","label":"Baisse de pression de cheville après marche évocatrice d'AOMI","value":"> 30 mmHg","src":"p. 171"},{"id":"225-num-19","rank":"A","label":"Baisse d'IPS après marche évocatrice d'AOMI","value":"> 20 %","src":"p. 171"},{"id":"225-num-20","rank":"A","label":"TcPO2 normale au dos du pied","value":"> 50 mmHg","src":"p. 171"},{"id":"225-num-21","rank":"A","label":"TcPO2 seuil d'hypoxie critique","value":"< 10 mmHg","src":"p. 171"},{"id":"225-num-22","rank":"A","label":"Sensibilité/spécificité de l'angioscanner et de l'angio-IRM (vs artériographie)","value":"≈ 95 %","src":"p. 173"},{"id":"225-num-23","rank":"A","label":"Cible de pression artérielle chez l'AOMI","value":"PAS ≤ 120-129 mmHg, PAD ≤ 70-79 mmHg","src":"p. 175"},{"id":"225-num-24","rank":"A","label":"Cible d'HbA1c chez l'AOMI","value":"< 7 %","src":"p. 175"},{"id":"225-num-25","rank":"A","label":"Cible de LDL-cholestérol chez l'AOMI","value":"< 0,55 g/L (< 1,4 mmol/L), réduction ≥ 50 %","src":"p. 175"},{"id":"225-num-27","rank":"A","label":"Rythme de marche recommandé dans l'AOMI","value":"30-45 min, ≥ 3 fois/semaine","src":"p. 175"},{"id":"225-num-28","rank":"B","label":"Durée de la bithérapie antiplaquettaire après angioplastie","value":"1 à 6 mois","src":"p. 176"},{"id":"225-num-29","rank":"A","label":"Réduction de l'espérance de vie des claudicants","value":"≈ 10 ans","src":"p. 177"},{"id":"225-num-30","rank":"A","label":"Complications cardiovasculaires et décès à 5 ans chez les claudicants","value":"20 % et 20 %","src":"p. 177"},{"id":"225-num-31","rank":"A","label":"Risque d'amputation à 5 ans dans l'AOMI","value":"≈ 5 %","src":"p. 177"},{"id":"225-num-32","rank":"A","label":"Mortalité à 5 ans en ischémie critique","value":"≈ 70 %","src":"p. 178"},{"id":"225-num-33","rank":"A","label":"Délai de souffrance des cellules nerveuses en ischémie aiguë","value":"2 heures","src":"p. 178"},{"id":"225-num-34","rank":"A","label":"Délai de souffrance des cellules musculaires (rhabdomyolyse)","value":"6-8 heures","src":"p. 178"},{"id":"225-num-35","rank":"A","label":"Délai d'apparition de la nécrose cutanée","value":"24 heures","src":"p. 178"},{"id":"225-num-36","rank":"A","label":"Posologie de l'héparine non fractionnée en ischémie aiguë","value":"bolus 5 000 UI puis perfusion continue de 500 UI/kg/j","src":"p. 182"},{"id":"225-num-37","rank":"A","label":"Cible de TCA sous héparine en ischémie aiguë","value":"entre 2 et 3","src":"p. 182"},{"id":"225-num-38","rank":"A","label":"Seuil de dilatation définissant un anévrisme","value":"augmentation de diamètre > 50 % du diamètre d'amont","src":"p. 183"},{"id":"225-num-39","rank":"A","label":"Prévalence de l'AAA chez l'homme > 65 ans","value":"2-5 %","src":"p. 183"},{"id":"225-num-40","rank":"A","label":"Risque annuel de rupture d'AAA selon le diamètre","value":"0,4 %/an si < 40 mm ; 3 %/an à 50-59 mm ; 15 %/an au-delà de 60 mm","src":"p. 184"},{"id":"225-num-41","rank":"A","label":"Prévalence de l'AAA entre 75 et 84 ans (homme / femme)","value":"≈ 5 % / 3 %","src":"p. 183"},{"id":"225-num-42","rank":"B","label":"Diamètre d'AAA au-delà duquel une intervention est indiquée (item 225)","value":"50-55 mm","src":"p. 186, 188"},{"id":"225-num-43","rank":"B","label":"Rythme de l'échographie de surveillance d'un AAA > 45 mm","value":"tous les 6 mois","src":"p. 185"},{"id":"225-num-44","rank":"B","label":"Vitesse moyenne de croissance d'un AAA","value":"2-4 mm/an","src":"p. 185"},{"id":"225-num-45","rank":"A","label":"Fréquence d'association d'un anévrisme poplité à un AAA","value":"30 %","src":"p. 186"},{"id":"225-num-46","rank":"B","label":"Part des AAA survenant sur terrain athéromateux","value":"80-90 %","src":"p. 184"},{"id":"225-num-47","rank":"A","label":"TcPO2 témoignant d'une bonne compensation métabolique","value":"> 35 mmHg","src":"p. 171"},{"id":"225-num-48","rank":"A","label":"Incidence de l'AOMI","value":"2-5 ‰","src":"p. 168"},{"id":"225-num-49","rank":"A","label":"Clairance contre-indiquant le gadolinium (angio-IRM)","value":"< 30 mL/min/1,73 m²","src":"p. 173"},{"id":"225-num-50","rank":"A","label":"Plaques aortiques à l'imagerie entre 40 et 55 ans (hommes / femmes)","value":"25 % / 20 %","src":"p. 166"},{"id":"225-num-51","rank":"A","label":"Décès annuels par rupture d'AAA en Europe","value":"≈ 12 000","src":"p. 184"},{"id":"225-num-52","rank":"A","label":"Risque de rupture d'AAA chez la femme par rapport à l'homme, à diamètre égal","value":"près de 4 fois plus","src":"p. 184"},{"id":"225-num-53","rank":"A","label":"Durée des douleurs définissant l'ischémie permanente","value":"> 15 jours","src":"p. 169"},{"id":"225-num-54","rank":"B","label":"Progression d'un AAA en cas de poursuite du tabagisme","value":"3 fois plus rapide","src":"p. 186"},{"id":"225-num-55","rank":"A","label":"Fréquence de la bilatéralité de l'anévrisme poplité","value":"près de la moitié des cas","src":"p. 186"},{"id":"225-num-56","rank":"B","label":"Part athéromateuse des artériopathies oblitérantes des membres inférieurs","value":"> 95 %","src":"p. 174"},{"id":"225-num-57","rank":"A","label":"Seuils de chirurgie d'un AAA selon l'item 221","value":"55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an","src":"p. 42"}],"mnemonics":[{"id":"225-mn-01","rank":"B","title":"Facteurs de risque de l'AOMI","mnemonic":"Tout Diabétique A du Cholestérol","expansion":"**T**abagisme · **D**iabète · HT**A** · **Cholestérol** (hypercholestérolémie) — les quatre facteurs de risque associés à l'AOMI.","src":"p. 168"},{"id":"225-mn-02","rank":"A","title":"Signes physiques de l'ischémie aiguë de membre","mnemonic":"Froid, Livide, Douloureux, Pouls Perdus, Paralysé","expansion":"**F**roideur du membre · **L**ivide · **D**ouleur à la palpation des masses musculaires · **P**ouls abolis en aval · **P**aralysie et anesthésie (déficit neurologique).","src":"p. 179"},{"id":"225-mn-03","rank":"A","title":"Stades de l'AOMI (Leriche-Fontaine)","mnemonic":"Après un Certain temps, Douleur puis Ulcère","expansion":"**A**symptomatique (I) · **C**laudication intermittente (II) · **D**ouleur ischémique de repos (III) · **U**lcération ou gangrène (IV).","src":"p. 168"},{"id":"225-mn-04","rank":"B","title":"Causes cardiaques d'embolie artérielle des membres","mnemonic":"Mon Vieux cœur Infarci Fibrille et s'Endocardite","expansion":"**M**yxome de l'atrium · **V**alvulopathie ou prothèse valvulaire · **I**nfarctus du myocarde (faux anévrisme) · **F**ibrillation atriale · **Endocardite** infectieuse — cinq des causes cardiaques d'embolie sur artère saine (s'y ajoutent foramen ovale perméable avec anévrisme du septum interatrial, et dyskinésie ou anévrisme du VG).","src":"p. 181"},{"id":"225-mn-05","rank":"A","title":"Conséquences métaboliques de la revascularisation","mnemonic":"Hyper Acide, Myoglobine, Calcium bas, Phosphore haut","expansion":"**H**yperkaliémie · **A**cidose métabolique · **M**yoglobinémie/myoglobinurie · hypo**C**alcémie · hyper**P**hosphorémie — le syndrome de revascularisation à dépister après désobstruction d'une ischémie aiguë.","src":"p. 178-179"},{"id":"225-mn-06","rank":"A","title":"Diagnostics différentiels de la claudication","mnemonic":"Nerveux, Rhumato, Veines, Muscles","expansion":"**N**eurologique (canal lombaire étroit, sciatalgie) · **Rhumato**logique (arthrose, tendinite) · **Veines** (claudication post-thrombotique) · **Muscles** (douleurs sous statines) — grandes catégories de diagnostics différentiels de la douleur de jambe à la marche.","src":"p. 174"},{"id":"225-mn-07","rank":"B","title":"Artériopathies non athéromateuses des membres inférieurs","mnemonic":"Buerger Taquine Horton, Dysplasie et Coarctation","expansion":"Maladie de **B**uerger · maladie de **T**akayasu · maladie de **Horton** · **D**ysplasie fibromusculaire · **C**oarctation de l'aorte — parmi les causes non athéromateuses d'artériopathie des membres inférieurs.","src":"p. 174"}]},"questions":[{"id":"225-qcm-001","type":"QRM","rank":"A","objective":"225-obj-01","tags":["définition","épidémiologie"],"difficulty":1,"stem":"Parmi les propositions suivantes concernant l'AOMI, lesquelles sont exactes ?","options":[{"t":"Elle correspond à une atteinte athéromateuse significative entre l'aorte terminale et les artères digitales","ok":true,"why":"Toute atteinte athéromateuse significative de l'aorte terminale jusqu'aux artères des orteils définit l'AOMI ; les lésions ressemblent à celles des autres territoires athéromateux (p. 167)."},{"t":"La forme infraclinique est plus fréquente que la forme clinique","ok":true,"why":"Pour 1 AOMI clinique, 2 à 4 patients ont une forme infraclinique : la prévalence passe de 1-5 % à 10-15 % après 60 ans si l'on compte les asymptomatiques, d'où l'intérêt du dépistage (p. 168)."},{"t":"Sa forme symptomatique est plus fréquente chez l'homme","ok":true,"why":"Prédominance masculine de la forme symptomatique, avec un pic de présentation plus précoce chez l'homme (60-75 ans) que chez la femme (70-80 ans) (p. 167)."},{"t":"Elle est la 2e localisation de l'athérosclérose en fréquence","ok":false,"why":"Par fréquence, l'AOMI est la 3e localisation de l'athérosclérose, après les atteintes coronarienne et cérébrale (p. 167)."},{"t":"Elle ne concerne jamais les artères digitales","ok":false,"why":"La définition s'étend justement jusqu'aux artères digitales des orteils (p. 167) ; « jamais » est donc faux."}],"explanation":"L'AOMI est une atteinte athéromateuse des artères entre l'aorte terminale et les artères digitales, 3e localisation de l'athérosclérose, plus fréquente et plus souvent infraclinique qu'elle n'y paraît.","trap":"Ne pas confondre 2e et 3e rang des localisations athéromateuses.","src":"p. 167-168","deep":"**Pourquoi** : l'AOMI est toute atteinte athéromateuse significative entre l'aorte terminale et les artères digitales (orteils) ; c'est la 3e localisation de l'athérosclérose, après le cœur et le cerveau (p. 167-168).\n**À relier** : pour 1 cas clinique, 2 à 4 cas infracliniques, d'où l'intérêt du dépistage ; forme symptomatique plus fréquente chez l'homme.\n**Piège** : ne pas écrire « 2e localisation »."},{"id":"225-qcm-002","type":"QRM","rank":"B","objective":"225-obj-02","tags":["étiologie","physiopathologie"],"difficulty":1,"stem":"Quels sont les deux facteurs de risque les plus fortement associés à l'AOMI ?","options":[{"t":"Le tabagisme","ok":true,"why":"Un des deux facteurs de risque principaux, surtout retrouvé chez le sujet plus jeune (p. 168)."},{"t":"L'hypercholestérolémie","ok":false,"why":"Elle fait partie des facteurs « fréquemment associés » avec l'HTA, mais les deux principaux sont le tabac et le diabète (p. 168)."},{"t":"L'hypertension artérielle","ok":false,"why":"Facteur fréquemment associé, au même titre que l'hypercholestérolémie, mais pas l'un des deux principaux (tabac, diabète) (p. 168)."},{"t":"Le diabète","ok":true,"why":"Deuxième facteur principal : il donne plus souvent des formes graves d'emblée, plus distales, de pronostic plus sévère (p. 168)."},{"t":"L'hypertriglycéridémie isolée","ok":false,"why":"Le Collège ne la mentionne pas : il retient tabac et diabète comme principaux, puis hypercholestérolémie et HTA comme fréquemment associés (p. 168)."}],"explanation":"Le tabac et le diabète sont les deux principaux facteurs de risque de l'AOMI ; l'hypercholestérolémie et l'HTA y sont seulement fréquemment associées.","src":"p. 168","deep":"**Pourquoi** : tabac et diabète sont les deux facteurs de risque principaux ; le tabac est plus fréquent chez le sujet jeune, le diabète donne des formes graves d'emblée, plus distales, de pronostic plus sévère (p. 168).\n**À relier** : hypercholestérolémie et HTA sont des facteurs fréquemment associés, mais pas les deux principaux.\n**Astuce** : T + D = Tabac et Diabète (le diabète = distal et grave).\n**Piège** : ne pas inverser les profils : tabac = plutôt le sujet jeune ; diabète = formes graves d'emblée, plus distales (p. 168)."},{"id":"225-qcm-003","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"stem":"Un homme de 64 ans décrit une crampe du mollet apparaissant après 300 mètres de marche, cédant à l'arrêt. Quelles propositions sont exactes ?","options":[{"t":"La claudication est dite sévère car la distance de marche est inférieure à 100 m","ok":false,"why":"Le seuil de sévérité est une distance de marche < 100 m ; à 300 m la claudication n'est pas sévère (p. 169)."},{"t":"Il s'agit probablement d'une claudication intermittente d'origine artérielle","ok":true,"why":"Forme typique : crampe du mollet après une distance de marche stable, obligeant à s'arrêter et cédant au repos : c'est le stade d'ischémie d'effort (p. 168-169)."},{"t":"La douleur cède habituellement en moins de 5 minutes","ok":true,"why":"Douleur d'effort réversible : elle disparaît habituellement en moins de 5 minutes après l'arrêt (p. 168) ; une douleur de repos signerait l'ischémie permanente."},{"t":"Cette présentation permet d'éliminer une atteinte athéromateuse coronarienne ou cérébrovasculaire associée","ok":false,"why":"L'AOMI s'associe fréquemment à d'autres atteintes athéromateuses (coronaire, cérébrovasculaire) : il faut les rechercher systématiquement (p. 169-170)."},{"t":"Une localisation fessière évoquerait une atteinte aorto-iliaque","ok":true,"why":"La claudication fessière évoque une atteinte aorto-iliaque ; associée à des troubles de l'érection chez l'homme, elle réalise le syndrome de Leriche (p. 169)."}],"explanation":"La claudication typique cède en moins de 5 minutes ; elle est dite sévère seulement si la distance de marche est < 100 m. Une localisation fessière oriente vers une atteinte aorto-iliaque.","trap":"Le seuil de sévérité (< 100 m) est souvent confondu avec le seuil déclenchant la douleur.","src":"p. 168-169","deep":"**Pourquoi** : la claudication typique est une crampe du mollet déclenchée à la marche après une distance stable, cédant en moins de 5 min à l'arrêt ; elle est sévère seulement si la distance de marche est < 100 m (p. 168-169).\n**À relier** : claudication fessière = atteinte aorto-iliaque (syndrome de Leriche si troubles de l'érection associés).\n**Piège** : 300 m n'est pas « sévère » ; l'AOMI s'associe souvent à d'autres atteintes athéromateuses."},{"id":"225-qcm-004","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","pièges"],"difficulty":2,"stem":"Quelles situations peuvent masquer une AOMI sévère malgré une absence de plainte fonctionnelle ?","options":[{"t":"Des comorbidités limitant la marche (insuffisance cardiaque, atteinte articulaire)","ok":true,"why":"Chez le sujet très âgé ou polypathologique (insuffisance cardiaque ou respiratoire, atteinte articulaire), le patient ne marche pas assez pour exprimer sa maladie (p. 169) : vérifier d'abord qu'il marche."},{"t":"Une circulation collatérale bien développée","ok":true,"why":"Une collatéralité importante compense la perte de débit : une atteinte sévère peut rester muette (p. 169)."},{"t":"Une neuropathie diabétique altérant la sensibilité","ok":true,"why":"Une neuropathie altérant la sensibilité (diabète, insuffisance rénale, âge avancé) masque la douleur ; le patient peut alors se révéler d'emblée en ischémie permanente (p. 169)."},{"t":"Un IPS supérieur à 1,40","ok":false,"why":"Un IPS > 1,40 est un problème de mesure (médiacalcose, pression de cheville non interprétable), pas une cause d'absence de symptômes (p. 171)."},{"t":"Un âge inférieur à 50 ans","ok":false,"why":"C'est l'inverse : le Collège cite le sujet très âgé (comorbidités qui l'empêchent de marcher) et l'âge avancé (neuropathie) comme causes d'AOMI masquée (p. 169)."}],"explanation":"La collatéralité, la neuropathie et les comorbidités limitant la marche peuvent masquer une AOMI sévère : il faut toujours vérifier que le patient marche réellement avant d'interroger sur la claudication.","src":"p. 169","deep":"**Pourquoi** : une AOMI sévère peut rester muette si les collatérales sont abondantes, si le patient marche trop peu (insuffisance cardiaque ou respiratoire, atteintes articulaires) ou s'il a une neuropathie (diabète, insuffisance rénale, âge avancé) (p. 169).\n**À relier** : ces formes « masquées » peuvent se révéler d'emblée en ischémie permanente.\n**Piège** : un IPS > 1,40 traduit une médiacalcose et fausse la mesure ; ce n'est pas un facteur de masquage des symptômes."},{"id":"225-qcm-005","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","urgence"],"difficulty":2,"stem":"Concernant l'ischémie permanente (stades III-IV) et l'ischémie critique, quelles propositions sont exactes ?","options":[{"t":"Les douleurs de décubitus durent typiquement moins de 48 heures","ok":false,"why":"L'ischémie permanente (stades III et IV) comporte des douleurs de plus de 15 jours résistant aux antalgiques usuels (p. 169) ; 48 h ne correspond à aucun seuil."},{"t":"La pression d'hallux seuil est de 50 mmHg","ok":false,"why":"50 mmHg est le seuil de la cheville ; à l'hallux, l'ischémie critique est définie par une pression < 30 mmHg (p. 169)."},{"t":"Une pression de cheville inférieure à 50 mmHg est l'un des deux seuils hémodynamiques de l'ischémie critique","ok":true,"why":"Ischémie permanente + effondrement des pressions (cheville < 50 mmHg ou hallux < 30 mmHg) = ischémie critique, pronostic du membre engagé (p. 169)."},{"t":"Les douleurs de décubitus sont soulagées par la surélévation des jambes","ok":false,"why":"Elles s'améliorent en position déclive : jambe pendante au bord du lit, voire lever nocturne (p. 169) ; surélever aggrave l'hypoperfusion."},{"t":"La gangrène est plus fréquente chez le patient diabétique","ok":true,"why":"Elle siège surtout aux orteils et au talon et prédomine chez le diabétique, souvent avec des lésions infectées (p. 169)."}],"explanation":"L'ischémie critique associe des douleurs de plus de 15 jours et un effondrement des pressions de perfusion (cheville < 50 mmHg ou hallux < 30 mmHg).","trap":"Ne pas confondre les seuils de cheville (50 mmHg) et d'hallux (30 mmHg).","src":"p. 169","deep":"**Pourquoi** : ischémie permanente = stade III (douleurs de décubitus) + stade IV (troubles trophiques) ; elle devient critique si douleurs > 15 jours résistant aux antalgiques et pression de cheville < 50 mmHg ou d'hallux < 30 mmHg (p. 169).\n**À relier** : haut risque d'amputation sans revascularisation.\n**Piège** : 50 mmHg = cheville, 30 mmHg = hallux ; la position déclive soulage, la surélévation aggrave."},{"id":"225-qcm-006","type":"QRM","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Quelles affirmations concernant l'index de pression systolique (IPS) sont exactes ?","options":[{"t":"L'IPS est mesuré uniquement au bras droit","ok":false,"why":"La pression brachiale se mesure aux deux bras et on retient la plus élevée comme dénominateur (p. 170-171)."},{"t":"Un IPS inférieur à 0,90 doit être retrouvé aux deux chevilles pour affirmer l'AOMI","ok":false,"why":"Une seule cheville < 0,90 suffit : l'IPS se calcule pour chaque membre (p. 171)."},{"t":"Un IPS supérieur à 1,40 élimine toute AOMI","ok":false,"why":"> 1,40 = rigidité par médiacalcose (diabétique âgé, dialysé) : la cheville n'est plus interprétable et on passe à la pression d'orteil (p. 171)."},{"t":"Un IPS entre 1,00 et 1,40 est normal","ok":true,"why":"Chez le sujet sain, l'IPS se situe habituellement entre 1,00 et 1,40 (p. 171), et le diagnostic d'AOMI se pose sous 0,90."},{"t":"Un IPS inférieur à 0,70 définit une AOMI sévère","ok":true,"why":"< 0,90 = AOMI ; < 0,70 = AOMI sévère (p. 171). Piège : les points clés impriment « > 0,7 » (coquille, p. 187)."}],"explanation":"L'IPS normal est entre 1,00 et 1,40 ; il est pathologique si < 0,90 (AOMI) ou < 0,70 (sévère). Un IPS > 1,40 signe une médiacalcose et impose la mesure de la pression d'orteil, sans éliminer une AOMI.","trap":"Un IPS > 1,40 ne rassure pas : il témoigne d'une médiacalcose (fréquente chez le diabétique âgé et/ou dialysé) et impose de mesurer la pression d'orteil (Collège p. 171).","src":"p. 171","deep":"**Pourquoi** : IPS = PAS de cheville (la plus élevée des 2 artères) / PAS du bras (la plus élevée des 2 bras) ; normal 1,00-1,40 ; AOMI si < 0,90 sur au moins une cheville ; sévère si < 0,70 (p. 171).\n**À relier** : > 1,40 = médiacalcose (diabétique âgé, dialysé) : cheville non interprétable, on mesure la pression d'orteil.\n**Piège** : un IPS élevé n'élimine pas l'AOMI."},{"id":"225-qcm-007","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Un patient diabétique âgé, suspect d'AOMI, a un IPS mesuré à 1,55. Quelles propositions sont exactes ?","options":[{"t":"Conclure à l'absence d'AOMI devant cet IPS élevé","ok":false,"why":"Un IPS > 1,40 traduit une médiacalcose qui fausse la pression de cheville : il ne rassure pas et impose la pression d'orteil (p. 171)."},{"t":"Mesurer la pression d'orteil","ok":true,"why":"En cas de médiacalcose, la pression de cheville est remplacée par la pression d'orteil, mesurée avec un manchon adapté (p. 171) ; elle est aussi conseillée chez le diabétique, l'insuffisant rénal et le très âgé (p. 170)."},{"t":"Considérer qu'un index de pression d'orteil inférieur à 0,70 témoigne d'une AOMI","ok":true,"why":"Index de pression d'orteil < 0,70 = AOMI (p. 171) : même chiffre que le seuil de sévérité de l'IPS, à ne pas confondre."},{"t":"Demander d'emblée une artériographie diagnostique","ok":false,"why":"L'artériographie, ancien examen de référence, n'est plus utilisée qu'au cours des procédures de revascularisation (p. 173) ; elle n'a pas sa place pour poser le diagnostic."},{"t":"Considérer qu'une pression d'orteil inférieure à 30 mmHg traduit une ischémie critique","ok":true,"why":"Pression d'orteil < 30 mmHg = ischémie critique (p. 171), comme la pression d'hallux < 30 mmHg (p. 169)."}],"explanation":"Chez le diabétique âgé, un IPS élevé évoque une médiacalcose : la pression d'orteil (pathologique si < 0,70 ; ischémie critique si < 30 mmHg) doit alors être mesurée.","src":"p. 171","deep":"**Pourquoi** : IPS > 1,40 = artère rigide (médiacalcose) ; la pression de cheville n'est plus estimée correctement, on la remplace par la pression d'orteil, avec un manchon adapté (p. 171).\n**À relier** : index de pression d'orteil < 0,70 = AOMI ; pression d'orteil < 30 mmHg = ischémie critique.\n**Piège** : conclure « pas d'AOMI » devant un IPS élevé ; l'artériographie n'est pas un examen diagnostique."},{"id":"225-qcm-008","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":1,"stem":"Quel(s) examen(s) est (sont) réservé(s) à un projet de revascularisation dans l'AOMI ?","options":[{"t":"L'artériographie des membres inférieurs","ok":true,"why":"Elle nécessite une ponction artérielle ; elle est aujourd'hui essentiellement limitée aux procédures de revascularisation, notamment pour voir le réseau jambier et pédieux (p. 173)."},{"t":"L'angioscanner des membres inférieurs","ok":true,"why":"Comme l'angio-IRM, il n'est demandé que s'il existe une indication de revascularisation, pour en étudier la faisabilité (p. 172) ; il impose de vérifier allergie et fonction rénale."},{"t":"L'échodoppler artériel des membres inférieurs","ok":false,"why":"C'est l'exploration d'imagerie la plus fréquemment utilisée, non invasive, dès le diagnostic : elle n'est pas réservée à un projet de revascularisation (p. 172)."},{"t":"Le test de marche sur tapis roulant","ok":false,"why":"Il évalue la distance de gêne et la distance de marche et sensibilise le diagnostic (baisse de la pression de cheville après la marche) : il n'est pas réservé à un projet de revascularisation (p. 171)."},{"t":"L'index de pression systolique","ok":false,"why":"L'IPS complète systématiquement l'examen clinique en cas de suspicion d'AOMI ou de dépistage (p. 170) : c'est l'outil du diagnostic, pas du bilan préopératoire."}],"explanation":"L'échodoppler, l'IPS et le test de marche sur tapis roulant servent au diagnostic et à l'évaluation ; l'angioscanner, l'angio-IRM et l'artériographie ne sont demandés qu'en vue d'une revascularisation.","src":"p. 172-173","deep":"**Pourquoi** : le diagnostic repose sur l'IPS, qui complète systématiquement l'examen (p. 170), puis l'échodoppler, exploration non invasive la plus utilisée (p. 172) ; angioscanner, angio-IRM et artériographie servent à étudier la faisabilité et les modalités d'une revascularisation (p. 172-173).\n**À relier** : l'artériographie reste utile pour le réseau jambier et pédieux en cas de revascularisation distale.\n**Piège** : le test de marche sur tapis n'est pas un examen de revascularisation : il évalue la gêne et sensibilise le diagnostic."},{"id":"225-qcm-009","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Concernant l'angio-IRM des membres inférieurs, quelles propositions sont exactes ?","options":[{"t":"Elle constitue l'examen de 1re intention devant une suspicion d'AOMI","ok":false,"why":"Le diagnostic repose sur l'IPS puis l'échodoppler, exploration la plus utilisée ; l'angio-IRM n'est demandée qu'en cas d'indication de revascularisation (p. 170-172)."},{"t":"Elle n'utilise pas de rayonnement ionisant","ok":true,"why":"Elle visualise tout l'arbre artériel sans radiations ionisantes, ce qui en fait l'alternative à l'angioscanner (p. 173)."},{"t":"Ses performances diagnostiques sont proches de celles de l'angioscanner","ok":true,"why":"Angioscanner et ARM ont des performances équivalentes, sensibilité et spécificité ≈ 95 % par rapport à l'artériographie (p. 173)."},{"t":"Elle permet de bien visualiser les calcifications artérielles","ok":false,"why":"L'ARM ne voit pas les calcifications, pourtant importantes pour le chirurgien qui envisage un pontage (p. 173) : c'est un avantage de l'angioscanner."},{"t":"Elle est contre-indiquée dès que la clairance de la créatinine est inférieure à 60 mL/min/1,73 m²","ok":false,"why":"Le gadolinium n'est contre-indiqué qu'en cas d'insuffisance rénale sévère, avec une clairance inférieure à 30 mL/min/1,73 m² (p. 173)."}],"explanation":"L'angio-IRM a des performances proches de l'angioscanner (≈ 95 %) sans irradiation, mais est contre-indiquée si la clairance est < 30 mL/min/1,73 m² et ne montre pas les calcifications.","src":"p. 173","deep":"**Pourquoi** : angio-IRM et angioscanner ont des performances équivalentes (≈ 95 % de sensibilité et spécificité vs artériographie) ; l'IRM évite les rayons X mais le gadolinium est contre-indiqué si clairance < 30 mL/min/1,73 m² (p. 173).\n**À relier** : l'angioscanner impose de vérifier allergies et fonction rénale ; l'angio-IRM ne visualise pas les calcifications, utiles au chirurgien avant un pontage.\n**Piège** : seuil de 30 (pas 60) ; ni l'une ni l'autre n'est un examen de 1re intention."},{"id":"225-qcm-010","type":"QRM","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Une femme de 72 ans présente des douleurs des mollets à la marche, variables selon les jours, cédant au repos. Quels diagnostics différentiels doivent être évoqués ?","options":[{"t":"Une douleur musculaire sous statines, qui permet alors d'écarter une AOMI associée","ok":false,"why":"Les myalgies sous statines peuvent mimer une AOMI, mais les tableaux sont souvent intriqués chez le sujet âgé : elles n'excluent pas une AOMI (p. 174)."},{"t":"Un canal lombaire étroit","ok":true,"why":"Cause neurologique de douleur à la marche : douleurs ou paresthésies du mollet ou du pied à l'effort, cédant au repos (p. 174) ; les distances variables sont aussi une forme atypique d'AOMI (p. 169)."},{"t":"Un anévrisme poplité asymptomatique","ok":false,"why":"Asymptomatique, il ne peut pas expliquer une douleur : il se découvre par une masse battante au creux poplité ou un échodoppler (p. 186). Les différentiels poplités cités sont le piège poplité et le kyste poplité (p. 174)."},{"t":"Une ischémie mésentérique chronique","ok":false,"why":"Elle donne un angor digestif (douleurs abdominales postprandiales), pas une douleur des membres à la marche (p. 166)."},{"t":"Un syndrome de Leriche","ok":false,"why":"C'est une AOMI aorto-iliaque (claudication fessière, fatigabilité à la marche, troubles de l'érection chez l'homme) (p. 169) : une cause, pas un différentiel."}],"explanation":"Devant des douleurs de jambe à la marche, on évoque notamment un canal lombaire étroit, une cause rhumatologique, une claudication veineuse post-thrombotique ou des douleurs musculaires sous statines, qui peuvent coexister avec une AOMI chez le sujet âgé (tableaux intriqués). Le syndrome de Leriche est une forme d'AOMI aorto-iliaque, pas un diagnostic différentiel.","trap":"Une cause non artérielle de douleur à la marche (par exemple des douleurs musculaires sous statines) n'élimine pas une AOMI associée : attention aux tableaux intriqués (Collège p. 174).","src":"p. 174","deep":"**Pourquoi** : une douleur à la marche n'est pas toujours artérielle : canal lombaire étroit (douleurs ou paresthésies à l'effort cédant au repos), causes rhumatologiques, claudication veineuse, piège poplité, syndrome des loges, douleurs sous statines (p. 174).\n**À relier** : chez le sujet âgé, plusieurs causes peuvent coexister avec l'AOMI (tableaux intriqués).\n**Piège** : le syndrome de Leriche est une AOMI aorto-iliaque, pas un diagnostic différentiel."},{"id":"225-qcm-011","type":"QRM","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"stem":"Parmi les propositions suivantes, lesquelles sont des artériopathies non athéromateuses des membres inférieurs citées par le référentiel ?","options":[{"t":"Une hypercholestérolémie familiale isolée sans autre facteur","ok":false,"why":"C'est un facteur de risque d'athérome, donc d'AOMI athéromateuse (p. 168), pas une artériopathie non athéromateuse."},{"t":"Une dysplasie fibromusculaire","ok":true,"why":"Artériopathie non athéromateuse localisée aux artères iliaques ou poplitées (p. 174)."},{"t":"Une athérosclérose classique","ok":false,"why":"L'athérome représente plus de 95 % des atteintes oblitérantes des membres inférieurs : c'est l'AOMI elle-même (p. 174)."},{"t":"Une coarctation de l'aorte","ok":true,"why":"Le rétrécissement aortique entraîne un hypodébit d'aval, membres inférieurs compris (p. 174)."},{"t":"Une maladie de Buerger","ok":true,"why":"Artériopathie inflammatoire, citée avec Takayasu, Horton et certaines collagénoses (PAN, lupus) (p. 174)."}],"explanation":"L'athérome représente plus de 95 % des atteintes artérielles oblitérantes des membres inférieurs ; les artériopathies non athéromateuses citées comprennent les artériopathies inflammatoires (Buerger, Takayasu, Horton, certaines collagénoses), la dysplasie fibromusculaire, la coarctation de l'aorte, les atteintes postradiques, post-traumatiques, toxiques, etc.","src":"p. 174","deep":"**Pourquoi** : l'athérome explique plus de 95 % des atteintes artérielles oblitérantes des membres inférieurs ; les artériopathies non athéromateuses sont minoritaires (p. 174).\n**À relier** : inflammatoires (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation, postradiques, post-traumatiques, toxiques (ergot), artère poplitée piégée.\n**Piège** : un facteur de risque (cholestérol) n'est pas une cause non athéromateuse."},{"id":"225-qcm-012","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Quelles sont les cibles thérapeutiques recommandées chez un patient AOMI ?","options":[{"t":"HbA1c < 7 %","ok":true,"why":"Le contrôle du diabète fait partie, avec l'arrêt du tabac, des mesures « au premier chef » ; la cible est une HbA1c < 7 % (p. 175)."},{"t":"Pression artérielle systolique cible ≤ 120-129 mmHg","ok":true,"why":"PAS ≤ 120-129 et PAD ≤ 70-79 mmHg ; un IEC ou sartan peut être considéré chez tout AOMI quelle que soit la PA, sauf contre-indication (p. 175)."},{"t":"IMC cible entre 25 et 30 kg/m²","ok":false,"why":"La cible d'IMC est 20-25 kg/m², avec régime méditerranéen et exercice modéré (p. 175)."},{"t":"Réentraînement 3 fois par semaine pendant 4 semaines","ok":false,"why":"La cible est 3 séances/semaine pendant 12 semaines (p. 175), avec des marches de 30-45 min au seuil de la douleur."},{"t":"LDL-cholestérol < 0,70 g/L avec réduction d'au moins 50 %","ok":false,"why":"Cible LDL < 0,55 g/L (1,4 mmol/L) ET baisse d'au moins 50 % par rapport à la valeur initiale, sous statine systématique (p. 175)."}],"explanation":"Les cibles chez le patient AOMI incluent LDL < 0,55 g/L (réduction ≥ 50 %), HbA1c < 7 %, PAS ≤ 120-129 / PAD ≤ 70-79 mmHg, IMC 20-25 kg/m² et un réentraînement 3 fois/semaine pendant 12 semaines.","src":"p. 175","deep":"**Pourquoi** : le contrôle des facteurs de risque améliore le pronostic cardiovasculaire : PAS ≤ 120-129 / PAD ≤ 70-79 mmHg, HbA1c < 7 %, LDL < 0,55 g/L (baisse ≥ 50 %), IMC 20-25, réentraînement 3 fois/semaine pendant 12 semaines (p. 175).\n**À relier** : IEC ou sartan à considérer chez tous, quelle que soit la PA ; arrêt du tabac, régime méditerranéen.\n**Piège** : LDL 0,55 (pas 0,70), IMC 20-25 (pas 25-30), 12 semaines (pas 4)."},{"id":"225-qcm-013","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant le traitement antithrombotique dans l'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'antiplaquettaire vise à réduire le risque de complications cardiovasculaires (infarctus, AVC)","ok":true,"why":"Le but est pronostique et général : réduire infarctus et AVC chez un patient polyathéromateux (p. 175), pas d'allonger la distance de marche."},{"t":"L'antiplaquettaire est systématiquement indiqué même en cas d'AOMI totalement asymptomatique isolée","ok":false,"why":"En cas d'AOMI asymptomatique (IPS < 0,90), il est débattu, sauf autre atteinte athéromateuse (ex. cardiopathie ischémique) (p. 175)."},{"t":"Le clopidogrel est une alternative à l'aspirine","ok":true,"why":"Le Collège cite indifféremment aspirine ou clopidogrel (p. 175)."},{"t":"Une anticoagulation curative au long cours est le traitement antithrombotique de référence de l'AOMI","ok":false,"why":"Le traitement antithrombotique de fond de l'AOMI symptomatique est un antiplaquettaire (aspirine ou clopidogrel) (p. 175) ; l'anticoagulation sert à l'ischémie aiguë ou à une cause embolique (p. 182-183)."},{"t":"Un antiplaquettaire est indiqué chez tout patient AOMI symptomatique","ok":true,"why":"Tout AOMI symptomatique reçoit un antiplaquettaire (p. 175, rappelé dans les stratégies p. 177), associé à la statine systématique."}],"explanation":"L'antiplaquettaire (aspirine ou clopidogrel) est systématique si l'AOMI est symptomatique, pour réduire le risque d'infarctus et d'AVC ; il est débattu en cas d'AOMI asymptomatique isolée.","trap":"Ne pas prescrire systématiquement un antiplaquettaire dans une AOMI asymptomatique isolée : il y est débattu.","src":"p. 175","deep":"**Pourquoi** : l'antiplaquettaire (aspirine ou clopidogrel) réduit le risque d'infarctus et d'AVC chez l'artéritique symptomatique, patient polyathéromateux (p. 175).\n**À relier** : AOMI asymptomatique (IPS < 0,90) : débattu, sauf autre atteinte athéromateuse (ex. cardiopathie ischémique) ; statine systématique.\n**Piège** : l'anticoagulation n'est pas le traitement de fond de l'AOMI."},{"id":"225-qcm-014","type":"QRM","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Chez un patient claudicant, quelles propositions concernant la prise en charge sont exactes ?","options":[{"t":"Une bithérapie antiplaquettaire est proposée pendant 1 à 6 mois après une angioplastie avec ou sans stent","ok":true,"why":"Après angioplastie avec ou sans stent, bithérapie antiplaquettaire 1 à 6 mois selon le geste et sa localisation (p. 176, rang B)."},{"t":"La réadaptation à la marche, de préférence supervisée, est proposée en 1re intention si le périmètre de marche n'est pas très altéré","ok":true,"why":"Fig. 7.6 : sans périmètre < 100 m ni atteinte aorto-iliaque sévère, on commence par la réadaptation, de préférence supervisée, après FdR + statine + antiplaquettaire (p. 177)."},{"t":"Une revascularisation peut être discutée après échec du traitement médical bien conduit","ok":true,"why":"Elle peut être proposée si la claudication reste sévère et altère la qualité de vie, notamment après un traitement médical bien mené incluant la réadaptation (p. 176)."},{"t":"La chirurgie de pontage privilégie le matériel veineux lorsque c'est possible","ok":true,"why":"Pontage de préférence veineux, à défaut prothétique, pour court-circuiter sténoses ou occlusions (p. 176)."},{"t":"L'angioplastie donne de meilleurs résultats sur des lésions longues et distales que sur des lésions courtes et proximales","ok":false,"why":"C'est l'inverse : résultats d'autant meilleurs que les lésions sont courtes et proximales ; les occlusions longues relèvent d'autres techniques (sous-adventicielle) (p. 176, rang B)."}],"explanation":"La réadaptation supervisée est proposée en 1re ligne ; une revascularisation (angioplastie sur lésions courtes/proximales, ou chirurgie de pontage veineux de préférence) est discutée après échec du traitement médical.","src":"p. 175-176","deep":"**Pourquoi** : sauf claudication très invalidante (< 100 m) ou atteinte aorto-iliaque sévère, on fait d'abord FDR + statine + antiplaquettaire + réadaptation supervisée ; la revascularisation vient après échec du traitement médical bien mené (p. 175-176).\n**À relier** : après angioplastie ± stent, bithérapie antiplaquettaire 1 à 6 mois ; pontage de préférence veineux ; surveillance échodoppler.\n**Piège** : l'angioplastie réussit mieux sur lésions courtes et proximales."},{"id":"225-qcm-015","type":"QRM","rank":"A","objective":"225-obj-06","tags":["suivi","complications"],"difficulty":3,"stem":"Concernant le pronostic des patients claudicants, quelles propositions sont exactes ?","options":[{"t":"À 5 ans, environ 20 % présentent des complications cardiovasculaires","ok":true,"why":"Schématiquement, chez le claudicant à 5 ans : 20 % de complications cardiovasculaires (p. 177) ; le risque est surtout général, pas local."},{"t":"Le risque d'amputation à 5 ans avoisine 25 %","ok":false,"why":"Le risque d'amputation à 5 ans est d'environ 5 % (surtout si FdR mal contrôlés, tabac) ; 25 % est le taux d'aggravation locale (p. 177)."},{"t":"25 % voient leur artériopathie s'aggraver localement à 5 ans, dont 1/5 avec amputation majeure","ok":true,"why":"Sur le plan local, 25 % s'aggravent, dont 1/5 subit une amputation majeure, soit ≈ 5 % (p. 177)."},{"t":"À 5 ans, environ 20 % décèdent, pour moitié de cause cardiovasculaire","ok":true,"why":"20 % de décès à 5 ans, pour moitié cardiovasculaires (p. 177) : l'AOMI est un marqueur de maladie athéromateuse diffuse."},{"t":"Leur espérance de vie est réduite d'environ 2 ans en moyenne","ok":false,"why":"L'espérance de vie du claudicant est réduite en moyenne de 10 ans (p. 177) ; en ischémie permanente, elle équivaut à celle de certains cancers."}],"explanation":"Chez les claudicants, l'espérance de vie est réduite d'environ 10 ans ; à 5 ans : 20 % de complications cardiovasculaires, 20 % de décès (moitié CV), 25 % d'aggravation locale (dont 1/5 d'amputation majeure) et environ 5 % de risque global d'amputation.","trap":"Ne pas confondre le taux d'aggravation locale globale (25 %) et le risque global d'amputation (5 %).","src":"p. 177","deep":"**Pourquoi** : l'AOMI est une maladie systémique au pronostic grave : espérance de vie du claudicant réduite d'environ 10 ans (p. 177).\n**À relier** : à 5 ans : 20 % de complications CV, 20 % de décès (la moitié CV), 25 % d'aggravation locale dont 1/5 d'amputation majeure (amputation ≈ 5 %) ; ischémie critique : mortalité ≈ 70 %.\n**Piège** : 25 % = aggravation locale, pas amputation."},{"id":"225-qru-001","type":"QRU","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":1,"stem":"Quel est l'examen à réaliser en première intention devant une suspicion d'AOMI ?","options":[{"t":"La mesure de la TcPO2","ok":false,"why":"Elle évalue l'oxygénation cutanée (après hyperémie) pour diagnostiquer et évaluer l'ischémie critique, et guider le niveau d'amputation (p. 171, 177)."},{"t":"L'index de pression systolique","ok":true,"why":"En cas de suspicion clinique d'AOMI ou de dépistage, l'examen clinique est systématiquement complété par l'IPS (p. 170) ; < 0,90 sur une cheville = AOMI (p. 171)."},{"t":"Le test de marche sur tapis roulant","ok":false,"why":"Il sert surtout quand l'IPS de repos est > 0,90 malgré une claudication : baisse de PAS de cheville > 30 mmHg ou d'IPS > 20 % après effort (p. 171)."},{"t":"Le scanner injecté","ok":false,"why":"L'angioscanner n'est demandé qu'en cas d'indication de revascularisation (p. 172) et impose de vérifier allergie et fonction rénale."},{"t":"L'artériographie","ok":false,"why":"Invasive (ponction artérielle), elle est essentiellement limitée aux procédures de revascularisation (p. 173)."}],"explanation":"L'IPS est l'examen à réaliser d'emblée devant toute suspicion d'AOMI ; il permet de retenir le diagnostic si < 0,90 sur au moins une cheville.","src":"p. 170-171","deep":"**Pourquoi** : l'IPS se mesure avec un brassard tensionnel et un doppler de poche : < 0,90 sur au moins une cheville confirme l'AOMI (p. 170-171).\n**À relier** : l'échodoppler vient ensuite localiser et quantifier les lésions ; scanner, ARM et artériographie sont réservés à la revascularisation.\n**Piège** : ne pas sauter l'IPS pour demander d'emblée une imagerie."},{"id":"225-qru-002","type":"QRU","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"stem":"Quel syndrome associe claudication fessière, fatigabilité à la marche et troubles de l'érection ?","options":[{"t":"Le syndrome de revascularisation","ok":false,"why":"Il désigne l'aggravation cellulaire à la reperfusion d'une ischémie aiguë (acides, radicaux libres, hyperkaliémie) (p. 178)."},{"t":"Le syndrome des loges","ok":false,"why":"Compression des muscles par l'œdème dans une loge aponévrotique inextensible au cours de l'ischémie aiguë, traitée par aponévrotomie (p. 178)."},{"t":"Le syndrome de Rutherford","ok":false,"why":"Rutherford désigne une classification de sévérité, pas un syndrome clinique (tableau 7.1, p. 168)."},{"t":"Le syndrome de Fontaine","ok":false,"why":"Fontaine désigne également une classification, pas un syndrome clinique spécifique (tableau 7.1, p. 168)."},{"t":"Le syndrome de Leriche","ok":true,"why":"Atteinte aorto-iliaque : claudication fessière et/ou fatigabilité à la marche + troubles de l'érection chez l'homme (p. 169) ; à rechercher à l'interrogatoire de tout artériopathe masculin."}],"explanation":"Le syndrome de Leriche associe claudication fessière, fatigabilité à la marche et troubles de l'érection, en rapport avec une atteinte aorto-iliaque.","src":"p. 169","deep":"**Pourquoi** : atteinte aorto-iliaque = claudication fessière et/ou fatigabilité à la marche + troubles de l'érection chez l'homme : syndrome de Leriche (p. 169).\n**À relier** : « Leriche et Fontaine » est aussi le nom d'une classification des stades de l'AOMI.\n**Piège** : Fontaine et Rutherford sont des classifications, pas des syndromes."},{"id":"225-qru-003","type":"QRU","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"Chez un patient symptomatique dont l'IPS de repos est normal, quel examen permet de sensibiliser le diagnostic d'AOMI ?","options":[{"t":"Le test de marche sur tapis roulant","ok":true,"why":"Protocole de Strandness (3,2 km/h, pente 10 %) : une baisse de PAS de cheville > 30 mmHg et/ou d'IPS > 20 % juste après la marche évoque l'AOMI (p. 171)."},{"t":"L'angioscanner des membres inférieurs","ok":false,"why":"Il n'est indiqué qu'en vue d'une revascularisation, pas pour sensibiliser un diagnostic douteux (p. 172)."},{"t":"L'artériographie","ok":false,"why":"Invasive, elle est essentiellement réservée aux procédures de revascularisation (p. 173) ; elle ne sert pas à confirmer un diagnostic douteux."},{"t":"La palpation des pouls périphériques","ok":false,"why":"Elle fait partie de l'examen bilatéral et comparatif, mais un pouls pédieux peut manquer de façon congénitale (5 %) : elle ne sensibilise pas un IPS normal (p. 170)."},{"t":"Le test de marche de 6 minutes","ok":false,"why":"Non spécifique de l'AOMI, il évalue le handicap fonctionnel global ; c'est le test sur tapis roulant, avec mesure des pressions de cheville après l'effort, qui sensibilise le diagnostic (p. 171)."}],"explanation":"Le test de marche sur tapis roulant (protocole de Strandness) démasque une AOMI à IPS de repos normal via une chute de la pression de cheville ou de l'IPS après effort.","src":"p. 171","deep":"**Pourquoi** : certains claudicants ont un IPS de repos > 0,90 ; le test sur tapis roulant (protocole de Strandness) réévalue les pressions de cheville juste après la marche (p. 171).\n**À relier** : baisse de PAS cheville > 30 mmHg et/ou de l'IPS > 20 % = évocatrice d'AOMI ; aide aussi au diagnostic différentiel des douleurs à la marche.\n**Piège** : le test de marche de 6 min évalue le handicap global et n'est pas spécifique de l'AOMI."},{"id":"225-qru-004","type":"QRU","rank":"A","objective":"225-obj-17","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Quel tableau clinique évoque typiquement une ischémie mésentérique chronique ?","options":[{"t":"Une claudication fessière bilatérale","ok":false,"why":"Elle évoque une atteinte aorto-iliaque (syndrome de Leriche), pas une ischémie digestive (p. 169)."},{"t":"Une douleur de décubitus des orteils","ok":false,"why":"Elle évoque une ischémie permanente des membres inférieurs, pas une ischémie digestive (p. 169)."},{"t":"Une masse battante et expansive péri-ombilicale","ok":false,"why":"Masse battante para-ombilicale = découverte clinique d'un AAA (p. 184), pas d'une sténose digestive."},{"t":"Une douleur abdominale aiguë avec vidange digestive accélérée","ok":false,"why":"Triade de l'ischémie mésentérique AIGUË : douleur abdominale aiguë avec peu de signes physiques, vidange digestive accélérée, indices emboliques (FA) (p. 167)."},{"t":"Un angor digestif : douleurs abdominales postprandiales","ok":true,"why":"Douleurs abdominales après le repas ; dans les formes graves, le patient limite ses repas, d'où altération de l'état général et amaigrissement (p. 166)."}],"explanation":"L'ischémie mésentérique chronique se traduit typiquement par un angor digestif : douleurs abdominales postprandiales pouvant conduire à une restriction alimentaire et un amaigrissement.","src":"p. 166","deep":"**Pourquoi** : une sténose du tronc cœliaque ou des mésentériques donne une ischémie après le repas (« angor digestif »), avec restriction alimentaire et amaigrissement dans les formes graves (p. 166).\n**À relier** : seul signe physique : éventuel souffle abdominal ; diagnostic par échodoppler, angioscanner ou angio-IRM ; forme aiguë = douleur brutale + vidange digestive.\n**Astuce** : angor digestif = angor d'effort, mais déclenché par le repas.\n**Piège** : douleur abdominale aiguë + vidange digestive accélérée = forme AIGUË (p. 167), pas l'angor digestif."},{"id":"225-qroc-001","type":"QROC","rank":"A","objective":"225-obj-01","tags":["définition"],"difficulty":1,"question":"Entre quelles structures artérielles se situent les lésions définissant l'AOMI ?","answer":"Entre l'aorte terminale et les artères digitales","accept":["aorte terminale - artères digitales","aorte distale aux orteils","de l'aorte terminale aux artères digitales","aorte terminale et artères digitales","aorte terminale aux orteils"],"keywords":["aorte","digitales"],"explanation":"L'AOMI regroupe toute atteinte athéromateuse significative des artères situées entre l'aorte terminale et les artères digitales des orteils.","src":"p. 167","deep":"**Pourquoi** : l'AOMI couvre tout l'arbre artériel du membre inférieur, de l'aorte terminale aux artères digitales des orteils, dès que l'atteinte athéromateuse est significative (p. 167).\n**À relier** : 3e localisation de l'athérosclérose après le cœur et le cerveau ; > 95 % des atteintes oblitérantes des membres inférieurs sont athéromateuses (p. 174).\n**Piège** : « jusqu'aux orteils » : les artères digitales font partie de la définition."},{"id":"225-qroc-002","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"Quel est le rang de l'AOMI parmi les localisations de l'athérosclérose ?","answer":"3e localisation, après les atteintes coronarienne et cérébrale","accept":["troisième","3e","3ème","troisième localisation","3e rang","3"],"keywords":["3e","localisation"],"explanation":"Après le cœur et le cerveau, l'AOMI est la 3e localisation de l'athérosclérose par sa fréquence.","src":"p. 167","deep":"**Pourquoi** : par sa fréquence, l'AOMI vient après l'atteinte coronarienne et cérébrale (p. 167).\n**À relier** : prévalence clinique 1-5 % après 60 ans, 10-15 % avec les formes asymptomatiques.\n**Piège** : ni 1re ni 2e."},{"id":"225-qroc-003","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Comment nomme-t-on le stade où l'AOMI ne se manifeste qu'à l'effort ?","answer":"Ischémie d'effort","accept":["ischémie à l'effort","ischémie d'effort","stade d'ischémie d'effort"],"keywords":["ischémie","effort"],"explanation":"Avant l'ischémie permanente, l'AOMI se manifeste d'abord à l'effort par une hypoxie musculaire lors de la marche : c'est le stade d'ischémie d'effort.","src":"p. 168","deep":"**Pourquoi** : au début, collatérales et retentissement modéré rendent le patient asymptomatique ; les symptômes apparaissent à l'effort, quand le débit ne suffit plus à oxygéner le muscle (p. 168).\n**À relier** : stade suivant = ischémie permanente (douleurs de repos, troubles trophiques).\n**Piège** : douleurs de décubitus et troubles trophiques ne sont plus l'ischémie d'effort mais l'ischémie permanente (p. 168)."},{"id":"225-qroc-004","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"En dessous de quelle distance de marche la claudication intermittente est-elle considérée comme sévère ?","answer":"100 mètres","accept":["100 m","< 100 mètres","100m","moins de 100 m","inférieure à 100 m","100"],"keywords":["100"],"explanation":"La claudication est dite sévère lorsque la distance de marche est inférieure à 100 mètres.","src":"p. 169","deep":"**Pourquoi** : le seuil de 100 m sépare la claudication « sévère » du reste ; il oriente aussi vers la revascularisation (p. 169).\n**À relier** : périmètre de marche < 100 m avec handicap = revascularisation à discuter.\n**Piège** : distance de marche (arrêt forcé) ≠ distance de gêne."},{"id":"225-qroc-005","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Quelle proportion de la population n'a pas de pouls pédieux perceptible de façon congénitale ?","answer":"Environ 5 %","accept":["5 %","5 pour cent","5%","environ 5%"],"keywords":["5"],"explanation":"Le pouls pédieux peut être absent de manière congénitale chez environ 5 % de la population, sans que cela traduise une pathologie.","src":"p. 170","deep":"**Pourquoi** : le pouls pédieux peut être absent de façon congénitale chez 5 % des sujets (p. 170) ; son absence isolée ne prouve donc pas l'AOMI.\n**À relier** : on palpe fémoral, poplité, tibial postérieur et pédieux, de façon bilatérale et comparative, puis on mesure systématiquement l'IPS (p. 170).\n**Piège** : conclure à une AOMI sur un seul pouls pédieux absent."},{"id":"225-qroc-006","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quelle est la valeur seuil de l'IPS en dessous de laquelle le diagnostic d'AOMI est retenu ?","answer":"Inférieur à 0,90","accept":["< 0,90","0,9","<0,9","< 0,9","<0,90","inférieur à 0,9","moins de 0,90","0,90"],"keywords":["0,90"],"explanation":"Un IPS inférieur à 0,90 sur au moins une cheville permet de retenir le diagnostic d'AOMI.","src":"p. 171","deep":"**Pourquoi** : IPS < 0,90 sur au moins une cheville = AOMI ; c'est aussi un marqueur de risque cardiovasculaire élevé (p. 171).\n**À relier** : < 0,70 = AOMI sévère ; > 1,40 = médiacalcose (non interprétable).\n**Astuce** : 0,9 diagnostic, 0,7 sévère, 1,4 artère rigide.\n**Piège** : un IPS > 1,40 n'élimine pas l'AOMI : médiacalcose, mesurer la pression d'orteil (p. 171)."},{"id":"225-qroc-007","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quelle anomalie de la paroi artérielle explique un IPS anormalement élevé (> 1,40) ?","answer":"Une médiacalcose (rigidité artérielle par calcification de la média)","accept":["médiacalcose","calcification de la média","calcification médiale","rigidité artérielle"],"keywords":["médiacalcose"],"explanation":"Une médiacalcose (calcification de la média sans rétrécissement intraluminal), fréquente chez le diabétique âgé et/ou le dialysé, rigidifie l'artère : la pression de cheville ne peut être estimée de manière adéquate et l'IPS dépasse 1,40.","src":"p. 171","deep":"**Pourquoi** : la média calcifiée rend l'artère rigide : la pression de cheville n'est plus estimée correctement et l'IPS dépasse 1,40, sans rétrécissement intraluminal (p. 171).\n**À relier** : fréquente chez le diabétique âgé et le dialysé ; on mesure alors la pression ou l'index d'orteil.\n**Piège** : médiacalcose ≠ athérosclérose."},{"id":"225-qroc-008","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Quel examen d'imagerie non invasif, le plus fréquemment utilisé, permet de localiser et de quantifier les sténoses artérielles des membres inférieurs ?","answer":"L'échodoppler artériel des membres inférieurs","accept":["échodoppler","écho-doppler artériel","echodoppler","écho-doppler","échodoppler artériel","échographie doppler","écho doppler artériel","doppler artériel"],"keywords":["échodoppler"],"explanation":"L'échodoppler artériel est l'exploration d'imagerie la plus fréquemment utilisée, non invasive : il localise et quantifie les lésions dans l'immense majorité des cas.","src":"p. 172","deep":"**Pourquoi** : l'échodoppler associe échographie (anatomie : siège et type des lésions) et doppler (hémodynamique des flux) ; il identifie et quantifie les lésions dans l'immense majorité des cas (p. 172).\n**À relier** : angioscanner, angio-IRM et artériographie ne sont demandés qu'en vue d'une revascularisation (p. 172-173).\n**Piège** : devant une suspicion clinique, la première mesure reste l'IPS, qui complète systématiquement l'examen (p. 170)."},{"id":"225-qroc-009","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":3,"question":"Quel est le nom du protocole standardisé de test de marche sur tapis roulant (3,2 km/h, pente à 10 %) utilisé dans l'AOMI ?","answer":"Protocole de Strandness","accept":["strandness","3,2 km/h pente 10%","protocole de strandness","test de strandness"],"keywords":["strandness"],"explanation":"Le protocole de Strandness (3,2 km/h, pente à 10 %) sur tapis roulant permet de sensibiliser le diagnostic chez un patient symptomatique à IPS de repos normal.","src":"p. 171","deep":"**Pourquoi** : tapis roulant à 3,2 km/h, pente 10 % : test standardisé spécifique de l'AOMI, qui mesure distance de gêne et de marche, puis réévalue les pressions de cheville (p. 171).\n**À relier** : baisse de PAS cheville > 30 mmHg et/ou de l'IPS > 20 % = évocatrice d'AOMI.\n**Piège** : le test de marche de 6 min évalue le handicap global, pas l'AOMI."},{"id":"225-qroc-010","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Citer une artériopathie inflammatoire non athéromateuse pouvant toucher les membres inférieurs.","answer":"Maladie de Buerger (ou Takayasu, Horton, collagénose)","accept":["buerger","takayasu","horton","maladie de buerger","maladie de takayasu","maladie de horton","périartérite noueuse","lupus"],"keywords":["buerger","takayasu","horton"],"explanation":"Les artériopathies inflammatoires non athéromateuses comprennent la maladie de Buerger, la maladie de Takayasu, la maladie de Horton et certaines collagénoses.","src":"p. 174","deep":"**Pourquoi** : plus de 95 % des atteintes artérielles oblitérantes des membres inférieurs sont athéromateuses ; les autres sont inflammatoires (Buerger, Takayasu, Horton, collagénoses), dysplasiques, postradiques, traumatiques, toxiques (p. 174).\n**À relier** : ces causes sont minoritaires (> 95 % des atteintes oblitérantes sont athéromateuses).\n**Astuce** : B-T-H : Buerger, Takayasu, Horton.\n**Piège** : la maladie de Buerger est une artériopathie des membres inférieurs, pas une cause d'AAA (aortites de l'AAA : Takayasu, Behçet, Horton, p. 184)."},{"id":"225-qroc-011","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","paraclinique"],"difficulty":1,"question":"Quelle est la cible de LDL-cholestérol chez un patient atteint d'AOMI ?","answer":"Inférieur à 0,55 g/L, avec une réduction d'au moins 50 %","accept":["< 0,55 g/l","0,55","< 0,55","<0,55 g/L","0,55 g/L","inférieur à 0,55 g/L","1,4 mmol/L"],"keywords":["0,55"],"explanation":"La cible de LDL-cholestérol chez le patient AOMI est inférieure à 0,55 g/L (1,4 mmol/L), avec une réduction d'au moins 50 % par rapport à la valeur initiale.","src":"p. 175","deep":"**Pourquoi** : chez le patient AOMI, statine systématique, LDL < 0,55 g/L (1,4 mmol/L) ET baisse ≥ 50 % par rapport à la valeur initiale (p. 175).\n**À relier** : autres cibles : HbA1c < 7 %, PAS 120-129 mmHg.\n**Piège** : 0,55 g/L (pas 0,70) ; ne pas oublier la baisse ≥ 50 %."},{"id":"225-qroc-012","type":"QROC","rank":"A","objective":"225-obj-06","tags":["suivi","paraclinique"],"difficulty":2,"question":"De combien d'années environ l'espérance de vie des patients claudicants est-elle réduite en moyenne ?","answer":"Environ 10 ans","accept":["10 ans","10","dix ans","environ 10 ans"],"keywords":["10"],"explanation":"L'espérance de vie des sujets atteints de claudication intermittente est en moyenne réduite d'environ 10 ans.","src":"p. 177","deep":"**Pourquoi** : l'AOMI est une maladie systémique : l'espérance de vie du claudicant est réduite d'environ 10 ans ; à 5 ans, 20 % décèdent, pour moitié de cause cardiovasculaire (p. 177).\n**À relier** : à 5 ans, 20 % de complications cardiovasculaires ; amputation ≈ 5 % (p. 177).\n**Astuce** : claudication = marqueur de risque cardiovasculaire global.\n**Piège** : 10 ans = claudicant ; en ischémie permanente, l'espérance de vie équivaut à celle de certains cancers (p. 177)."},{"id":"225-open-01","type":"OPEN","rank":"A","objective":"225-obj-04","tags":["diagnostic","paraclinique"],"difficulty":2,"prompt":"Un homme de 66 ans, tabagique, consulte pour une claudication du mollet gauche apparaissant à la marche. Décrivez la démarche diagnostique à mettre en œuvre, des éléments de l'examen clinique à la place des différents examens complémentaires.","rubric":[{"point":"Examen clinique bilatéral et comparatif : inspection, palpation des pouls, temps de recoloration, auscultation","weight":2},{"point":"Mesure de l'index de pression systolique en 1re intention","weight":2},{"point":"Interprétation des seuils de l'IPS (normal, AOMI, sévère, médiacalcose)","weight":2},{"point":"Test de marche si symptômes avec IPS de repos normal","weight":1},{"point":"Échodoppler artériel des membres inférieurs (imagerie non invasive la plus utilisée) pour localiser et quantifier les lésions","weight":2},{"point":"Angioscanner/angio-IRM/artériographie réservés à un projet de revascularisation","weight":1}],"model":"L'examen clinique doit être bilatéral et comparatif : inspection de la couleur cutanée et des troubles trophiques, palpation des pouls fémoral, poplité, tibial postérieur et pédieux, mesure du temps de recoloration cutanée, auscultation des trajets vasculaires. Devant cette suspicion clinique, l'index de pression systolique est mesuré en 1re intention : un IPS entre 1,00 et 1,40 est normal, inférieur à 0,90 il affirme l'AOMI, inférieur à 0,70 il définit une forme sévère, supérieur à 1,40 il évoque une médiacalcose imposant la mesure de la pression d'orteil. Si l'IPS de repos est normal malgré des symptômes évocateurs, un test de marche sur tapis roulant (protocole de Strandness) peut sensibiliser le diagnostic. L'échodoppler artériel des membres inférieurs, exploration d'imagerie non invasive la plus utilisée, permet ensuite de localiser et quantifier les lésions. L'angioscanner, l'angio-IRM et l'artériographie ne sont demandés qu'en cas de projet de revascularisation.","src":"p. 170-173"},{"id":"225-open-02","type":"OPEN","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":3,"prompt":"Détaillez les grands axes du traitement à visée générale d'un patient présentant une AOMI symptomatique, en précisant les cibles thérapeutiques principales.","rubric":[{"point":"Contrôle des facteurs de risque cardiovasculaire (arrêt du tabac, équilibre du diabète)","weight":2},{"point":"Cibles tensionnelles et de LDL-cholestérol chiffrées","weight":2},{"point":"Traitement antiplaquettaire systématique si AOMI symptomatique","weight":2},{"point":"Statine systématique avec objectif de réduction du LDL","weight":1},{"point":"Intérêt pronostique des IEC et place prudente des bêtabloquants","weight":1},{"point":"Mesures hygiéno-diététiques (IMC, réentraînement, régime méditerranéen)","weight":1}],"model":"Le traitement à visée générale a pour objectif d'améliorer le pronostic cardiovasculaire global. Il repose sur le contrôle strict des facteurs de risque : arrêt du tabac, équilibre du diabète (HbA1c < 7 %), pression artérielle cible autour de 120-129/70-79 mmHg, LDL-cholestérol inférieur à 0,55 g/L avec une réduction d'au moins 50 % sous statine systématique, IMC entre 20 et 25 kg/m², régime méditerranéen et réentraînement supervisé (3 fois par semaine pendant 12 semaines). Un traitement antiplaquettaire (aspirine ou clopidogrel) est indiqué chez tout patient symptomatique. Les IEC ont un intérêt pronostique en abaissant la pression artérielle sous 140/90 mmHg, et les bêtabloquants peuvent être utilisés en cas d'indication formelle, avec prudence en ischémie critique non revascularisable.","src":"p. 175"},{"id":"225-qcm-101","type":"QRM","rank":"A","objective":"225-obj-07","tags":["urgence","clinique"],"difficulty":1,"stem":"Quels signes physiques font partie du tableau clinique de l'ischémie aiguë de membre ?","options":[{"t":"Une hyperthermie cutanée localisée du membre","ok":false,"why":"L'interruption brutale du flux rend le membre froid et livide (p. 179) ; c'est la localisation de la froideur qui aide à situer l'occlusion."},{"t":"Un membre froid et livide","ok":true,"why":"Signe physique majeur, toujours comparé au membre controlatéral ; froideur + abolition des pouls d'aval estiment la topographie de l'occlusion (p. 179)."},{"t":"Une anesthésie ou une paralysie du membre","ok":true,"why":"Les nerfs souffrent en premier (dès 2 h) : anesthésie et paralysie (nerf fibulaire commun, pied qui ne se relève pas) signent la gravité (p. 178-179)."},{"t":"Une douleur à la palpation des masses musculaires","ok":true,"why":"Elle traduit la souffrance musculaire, qui débute vers 6-8 h (rhabdomyolyse) (p. 178-179)."},{"t":"Une abolition des pouls en amont de l'occlusion, les pouls d'aval restant perçus","ok":false,"why":"Les pouls sont abolis en aval de l'occlusion ; avec la froideur, leur niveau d'abolition aide à situer l'occlusion (p. 179)."}],"explanation":"L'ischémie aiguë de membre associe un membre froid, livide, douloureux à la palpation musculaire, avec pouls abolis en aval et éventuels troubles neurologiques (anesthésie, paralysie).","src":"p. 179","deep":"**Pourquoi** : interruption brutale du flux = membre froid, livide, douloureux à la palpation musculaire, pouls abolis en aval, déficit sensitivomoteur (nerf fibulaire commun : impossible de relever le pied) (p. 179).\n**À relier** : froideur et niveau d'abolition des pouls localisent l'occlusion ; examen toujours comparatif au côté sain.\n**Piège** : pouls abolis en AVAL de l'occlusion, pas en amont."},{"id":"225-qcm-102","type":"QRM","rank":"A","objective":"225-obj-07","tags":["physiopathologie","paraclinique"],"difficulty":2,"stem":"Concernant la chronologie de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Les cellules nerveuses souffrent dès 2 heures d'ischémie","ok":true,"why":"Le nerf est le tissu le plus sensible à l'hypoxie : souffrance dans les 2 premières heures (p. 178), d'où l'importance du déficit sensitivomoteur dans la gradation."},{"t":"Le syndrome des loges est sans rapport avec l'œdème musculaire","ok":false,"why":"L'anoxie dilate les capillaires → œdème dans des loges aponévrotiques inextensibles → arrêt circulatoire : syndrome des loges, levé par aponévrotomie (p. 178)."},{"t":"Les cellules musculaires ne souffrent qu'après 24 heures d'ischémie","ok":false,"why":"Les cellules musculaires souffrent dans les 6 à 8 heures (rhabdomyolyse) ; la 24e heure correspond à l'apparition de la nécrose cutanée (p. 178)."},{"t":"Les cellules musculaires souffrent avant les cellules nerveuses","ok":false,"why":"Ordre : nerf (2 h) puis muscle (6-8 h) puis nécrose cutanée (24 h) (p. 178)."},{"t":"La nécrose cutanée apparaît dès la 2e heure","ok":false,"why":"La nécrose cutanée apparaît à partir de la 24e heure ; les 2 premières heures correspondent à la souffrance des cellules nerveuses (p. 178)."}],"explanation":"Les cellules nerveuses souffrent dès 2 heures, les cellules musculaires dès 6-8 heures (rhabdomyolyse), et la nécrose cutanée apparaît vers la 24e heure ; l'œdème musculaire peut causer un syndrome des loges.","trap":"Ne pas inverser l'ordre de souffrance : nerfs avant muscles.","src":"p. 178","deep":"**Pourquoi** : la sensibilité à l'hypoxie suit un ordre : nerf (2 h), muscle (6-8 h, rhabdomyolyse), peau (nécrose dès la 24e h). L'œdème musculaire dans une loge inextensible comprime les tissus : syndrome des loges (p. 178).\n**À relier** : seule l'aponévrotomie de décharge libère le muscle.\n**Astuce** : 2 h – 6/8 h – 24 h = nerf, muscle, peau.\n**Piège** : 24 h = nécrose cutanée, pas souffrance musculaire (6-8 h) (p. 178)."},{"id":"225-qcm-103","type":"QRM","rank":"A","objective":"225-obj-07","tags":["physiopathologie","complications"],"difficulty":2,"stem":"Quelles anomalies métaboliques peuvent survenir lors de la reperfusion d'un membre après ischémie aiguë prolongée ?","options":[{"t":"Une hypokaliémie","ok":false,"why":"Les cellules musculaires lysées relarguent leur potassium : c'est une HYPERkaliémie (p. 178), traitée par chélateur voire dialyse (p. 183)."},{"t":"Une hyperkaliémie","ok":true,"why":"Relargage du contenu des cellules lysées à la reperfusion (p. 178) ; avec l'acidose, c'est l'acidose hyperkaliémique à rechercher systématiquement (p. 183)."},{"t":"Une hypercalcémie","ok":false,"why":"Le Collège cite une hypocalcémie, avec hyperphosphorémie (p. 178)."},{"t":"Une alcalose métabolique","ok":false,"why":"La reperfusion libère des métabolites acides : c'est une acidose métabolique qui est observée (p. 178)."},{"t":"Une myoglobinurie","ok":true,"why":"La rhabdomyolyse libère la myoglobine, qui précipite dans les tubules et favorise la nécrose tubulaire aiguë (p. 178-179)."}],"explanation":"Le syndrome de revascularisation associe hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie/myoglobinurie, hypocalcémie et hyperphosphorémie, pouvant conduire à une insuffisance rénale aiguë.","src":"p. 178-179","deep":"**Pourquoi** : la reperfusion libère cellules lysées, acides et radicaux libres : hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie/urie, hausse de la créatinine, hypocalcémie, hyperphosphorémie, parfois CIVD (p. 178-179).\n**À relier** : risque d'insuffisance rénale aiguë (nécrose tubulaire : myoglobine, produits de contraste).\n**Piège** : le potassium monte, le calcium baisse ; acidose, pas alcalose."},{"id":"225-qcm-104","type":"QRM","rank":"A","objective":"225-obj-07","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Selon la classification de sévérité de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Le grade IIa correspond à une ischémie immédiatement menaçante avec déficit moteur modéré","ok":false,"why":"IIa = discrètement menaçant : déficit sensitif absent ou limité aux orteils, pas de déficit moteur ; c'est le IIb qui a un déficit moteur modéré (p. 179)."},{"t":"Cette classification ne prend en compte que les données de l'imagerie","ok":false,"why":"Elle est clinique : déficit sensitif et moteur (p. 179) ; le diagnostic d'ischémie aiguë reste clinique (p. 180)."},{"t":"Le grade III (irréversible) s'accompagne d'une perte tissulaire et de séquelles inévitables","ok":true,"why":"Grade III = anesthésie importante, paralysie : perte de tissus et séquelles inévitables (p. 179) ; fig. 7.7 : amputation (p. 180)."},{"t":"Le grade IIb impose une prise en charge immédiate pour espérer une récupération","ok":true,"why":"IIb = déficit sensitif au-delà des orteils + déficit moteur modéré : récupération possible seulement si prise en charge immédiate (p. 179)."},{"t":"Le grade I (viable) ne présente ni déficit sensitif ni déficit moteur","ok":true,"why":"Grade I = viable, sans déficit, sans menace immédiate (urgence relative) : seul grade où une imagerie en urgence est prévue avant revascularisation (p. 179-180)."}],"explanation":"La classification de Rutherford de l'ischémie aiguë distingue le grade I (viable, aucun déficit), IIa (discrètement menaçant), IIb (immédiatement menaçant, déficit moteur modéré, urgence de prise en charge) et III (irréversible).","trap":"Ne pas confondre IIa (discrètement menaçant) et IIb (immédiatement menaçant, déficit moteur).","src":"p. 179","deep":"**Pourquoi** : grade I viable (aucun déficit) ; IIa discrètement menaçant (déficit sensitif absent ou limité aux orteils, pas de déficit moteur) ; IIb immédiatement menaçant (sensitif au-delà des orteils, moteur modéré) ; III irréversible (p. 179).\n**À relier** : fig. 7.7 : grade I → imagerie en urgence ; grade II (déficit sensitif) → revascularisation en urgence absolue ; III → amputation.\n**Piège** : a/b : seul le IIb a un déficit moteur modéré."},{"id":"225-qcm-105","type":"QRM","rank":"A","objective":"225-obj-09","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Concernant la démarche diagnostique devant une ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"En cas de déficit neurologique (grade II), une imagerie doit précéder la revascularisation","ok":false,"why":"En cas d'atteinte neurologique (grade II), aucune exploration ne doit retarder l'intervention ; un échodoppler n'est envisageable sans perte de temps qu'en l'absence d'atteinte neurologique (notamment grade I) (p. 180)."},{"t":"Un échodoppler peut être réalisé sans perte de temps si le tableau clinique le permet (grade I sans déficit)","ok":true,"why":"Il est possible seulement si conditions locales et sévérité le permettent, notamment grade I sans atteinte neurologique (p. 180)."},{"t":"L'artériographie est systématiquement réalisée avant le transfert au bloc opératoire","ok":false,"why":"Elle est le plus souvent faite au bloc : elle localise l'occlusion, apprécie le réseau d'aval et révèle d'autres emboles (p. 180)."},{"t":"Le bilan de coagulation doit être différé après la revascularisation","ok":false,"why":"Le bilan de coagulation est nécessaire d'emblée (p. 182) et l'héparine est débutée juste après son prélèvement (p. 182)."},{"t":"Le diagnostic repose sur l'angioscanner, à obtenir avant d'alerter l'équipe chirurgicale","ok":false,"why":"Le diagnostic est essentiellement clinique et l'équipe chirurgicale doit être alertée au plus tôt ; aucune exploration ne doit retarder l'intervention (p. 180)."}],"explanation":"Le diagnostic d'ischémie aiguë est clinique ; aucun examen ne doit retarder l'intervention en cas de déficit neurologique. Un échodoppler est possible sans perte de temps en cas de grade I sans atteinte neurologique, et l'artériographie est le plus souvent réalisée au bloc opératoire.","src":"p. 180","deep":"**Pourquoi** : le diagnostic est clinique et l'équipe chirurgicale est alertée au plus tôt ; aucune exploration ne doit retarder l'intervention, surtout en cas de déficit neurologique (grade II) (p. 180).\n**À relier** : échodoppler seulement sans perte de temps (grade I) ; artériographie le plus souvent au bloc ; bilan de coagulation prélevé avant l'héparine.\n**Piège** : « notion inacceptable » : l'imagerie inutile qui retarde la prise en charge."},{"id":"225-qcm-106","type":"QRM","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"stem":"Quels éléments orientent vers une thrombose artérielle in situ plutôt qu'une embolie devant une ischémie aiguë de membre ?","options":[{"t":"Un sujet âgé avec antécédent d'AOMI","ok":true,"why":"Thrombose in situ = sujet âgé avec FdR, voire AOMI préexistante (à rechercher sur l'autre membre) (p. 181)."},{"t":"Une prothèse valvulaire cardiaque","ok":false,"why":"Les valvulopathies et prothèses valvulaires sont des causes cardiaques d'embolie : elles orientent vers une embolie, non vers une thrombose in situ (p. 181)."},{"t":"Des palpitations précédant la douleur","ok":false,"why":"Cet élément oriente vers une origine cardiaque emboligène, donc vers une embolie (p. 181)."},{"t":"Une douleur d'intensité moyenne d'installation progressive","ok":true,"why":"Grâce aux collatérales déjà développées, la douleur est moyenne et s'installe progressivement ou rapidement (p. 181)."},{"t":"Une douleur brutale et sévère chez un sujet jeune sans antécédent vasculaire","ok":false,"why":"Tableau de l'embolie sur artères saines : sujet jeune sans antécédent vasculaire, sans collatérales, donc douleur brutale et sévère (p. 181)."}],"explanation":"La thrombose in situ touche typiquement un sujet âgé déjà artériopathe, avec une douleur d'installation progressive grâce à la collatéralité ; l'embolie touche un sujet plus jeune sur artères saines, avec douleur brutale et sévère, parfois précédée de palpitations.","src":"p. 181","deep":"**Pourquoi** : thrombose in situ = sujet âgé avec FDR ou AOMI connue ; douleur d'intensité moyenne, d'installation progressive grâce aux collatérales déjà développées (p. 181).\n**À relier** : embolie = sujet plus jeune, artères saines, douleur brutale et sévère (pas de collatérales), parfois après des palpitations, cardiopathie possible.\n**Piège** : les deux tableaux ne sont pas toujours distincts (embolie sur AOMI, thrombose sur plaque rompue)."},{"id":"225-qcm-107","type":"QRM","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"stem":"Quelles causes cardiaques d'embolie artérielle des membres inférieurs sont citées dans le référentiel ?","options":[{"t":"L'endocardite infectieuse","ok":true,"why":"Cause cardiaque d'embolie (végétations), au même titre que valvulopathies et prothèses valvulaires (p. 181)."},{"t":"Le foramen ovale perméable associé à un anévrisme du septum interatrial","ok":true,"why":"FOP et anévrisme du septum interatrial sont cités parmi les sources cardiaques d'embolie (p. 181)."},{"t":"La fibrillation atriale","ok":true,"why":"Premier trouble du rythme emboligène cité ; l'embolie peut suivre des palpitations (p. 181) et justifiera une anticoagulation au long cours (p. 183)."},{"t":"La péricardite aiguë isolée","ok":false,"why":"Absente de la liste : les causes cardiaques citées sont rythme (FA), FOP, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, dyskinésie ou anévrisme du VG (p. 181)."},{"t":"Le myxome de l'atrium","ok":true,"why":"Tumeur cardiaque citée parmi les sources d'embolie (p. 181)."}],"explanation":"Les causes cardiaques d'embolie artérielle citées comprennent la fibrillation atriale, le foramen ovale perméable avec anévrisme du septum, l'infarctus avec faux anévrisme, l'endocardite, les valvulopathies/prothèses et le myxome de l'atrium.","src":"p. 181","deep":"**Pourquoi** : les emboles viennent du cœur (troubles du rythme dont FA, FOP + anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, anévrisme VG) ou de l'aorte (athérome, anévrisme, aortite, tumeur) (p. 181).\n**À relier** : après embolie, ECG et auscultation cardiaque d'emblée, bilan cardiaque complet après revascularisation.\n**Piège** : la péricardite n'est pas une source d'embole."},{"id":"225-qcm-108","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":2,"stem":"Quelles mesures font partie du traitement médical immédiat de l'ischémie aiguë de membre ?","options":[{"t":"Un positionnement du membre strictement horizontal sans soin local particulier","ok":false,"why":"Soins locaux immédiats : protection mousse ou coton, position légèrement déclive, éviter frottements et traumatismes (p. 182)."},{"t":"Une anticoagulation par héparine non fractionnée, débutée seulement après la revascularisation","ok":false,"why":"L'héparine non fractionnée est débutée dès le diagnostic, après prélèvement du bilan de coagulation (bolus de 5 000 UI puis perfusion continue, TCA entre 2 et 3) (p. 182)."},{"t":"Un remplissage vasculaire en cas d'instabilité hémodynamique","ok":true,"why":"Équilibration hémodynamique si nécessaire, par remplissage macromoléculaire (p. 182) : la gravité dépend aussi de la PA systémique (p. 178)."},{"t":"Des antalgiques de palier 3 si nécessaire","ok":true,"why":"La douleur est intense (broiement) : antalgiques de niveau 3 souvent nécessaires d'emblée (p. 179, 182)."},{"t":"Une oxygénothérapie","ok":true,"why":"Oxygénothérapie nasale, dans le traitement médical immédiat avec héparine, antalgiques et soins locaux (p. 182)."}],"explanation":"Le traitement médical immédiat associe héparine non fractionnée, antalgiques de palier 3, oxygénothérapie, correction hémodynamique et soins locaux protecteurs en position légèrement déclive.","src":"p. 182","deep":"**Pourquoi** : traitement médical immédiat, en parallèle de la revascularisation : héparine dès le diagnostic, antalgiques de palier 3, oxygène, correction hémodynamique, soins locaux (p. 182).\n**À relier** : membre en position légèrement déclive, protégé (mousse ou coton), sans frottement.\n**Piège** : ne pas attendre la revascularisation pour anticoaguler, ni surélever le membre."},{"id":"225-qcm-109","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement","paraclinique"],"difficulty":3,"stem":"Concernant l'héparinothérapie initiale de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"La cible de TCA est comprise entre 2 et 3","ok":true,"why":"HNF ajustée pour un TCA entre 2 et 3 (p. 182)."},{"t":"Un bolus initial de 5 000 UI est administré","ok":true,"why":"Bolus de 5 000 UI d'HNF, puis perfusion continue (p. 182)."},{"t":"L'héparine est débutée seulement après le résultat du bilan de coagulation complet","ok":false,"why":"Elle est débutée dès le diagnostic, juste après le prélèvement du bilan de coagulation, sans en attendre le résultat (p. 182)."},{"t":"Une héparine de bas poids moléculaire est privilégiée en 1re intention","ok":false,"why":"Le Collège décrit l'héparine non fractionnée (bolus puis IV continue, TCA 2-3) (p. 182)."},{"t":"La perfusion continue est de 500 UI/kg/jour","ok":true,"why":"Entretien : 500 UI/kg/j en IV continu (p. 182) ; ne pas confondre avec le bolus de 5 000 UI."}],"explanation":"L'anticoagulation initiale associe un bolus de 5 000 UI d'héparine non fractionnée puis une perfusion continue de 500 UI/kg/j, pour une cible de TCA entre 2 et 3, débutée dès le diagnostic après simple prélèvement du bilan de coagulation.","src":"p. 182","deep":"**Pourquoi** : héparine non fractionnée dès le diagnostic, après simple prélèvement du bilan de coagulation (sans attendre le résultat) : bolus 5 000 UI puis 500 UI/kg/j IV continu, pour un TCA entre 2 et 3 (p. 182).\n**À relier** : traitement médical immédiat avec antalgiques de palier 3 ; surveillance du TCA.\n**Piège** : c'est l'HNF qui est citée, pas une HBPM ; ne pas confondre bolus (5 000 UI) et entretien (500 UI/kg/j)."},{"id":"225-qcm-110","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"stem":"Quelles propositions concernant la revascularisation de l'ischémie aiguë de membre sont exactes ?","options":[{"t":"Une aponévrotomie de décompression complète généralement le geste en cas de revascularisation tardive","ok":true,"why":"Après revascularisation tardive, le geste est généralement complété par une aponévrotomie, surtout de la loge antéro-externe de jambe, pour éviter le syndrome des loges (p. 183)."},{"t":"La thrombolyse in situ peut être utilisée en cas de lit d'aval jambier de mauvaise qualité et d'ischémie peu sévère","ok":true,"why":"Si lit d'aval jambier mauvais et ischémie peu sévère : fibrinolytique injecté dans le thrombus par cathéter laissé plusieurs heures, sous contrôles angiographiques (p. 182)."},{"t":"L'embolectomie à la sonde de Fogarty est le traitement de référence de l'embolie sur artère saine","ok":true,"why":"Méthode de référence de l'embolie sur artère saine, sous contrôle angiographique ; parfois aussi utilisée sur artères athéromateuses (p. 182)."},{"t":"L'amputation d'emblée peut être proposée en cas d'ischémie dépassée","ok":true,"why":"Si l'ischémie est dépassée (grade III), voire pour limiter un syndrome de revascularisation majeur ou après échec, surtout sur terrain débilité (p. 183)."},{"t":"Le pontage est la méthode de revascularisation de 1re intention dans tous les cas","ok":false,"why":"Le pontage (souvent distal) n'est envisagé qu'en dernier ressort (p. 182) ; la référence pour l'embolie est l'embolectomie de Fogarty."}],"explanation":"L'embolectomie à la sonde de Fogarty est la méthode de référence pour l'embolie sur artère saine ; la thrombolyse in situ est réservée au lit d'aval de mauvaise qualité avec ischémie peu sévère ; le pontage est un dernier recours ; en cas de revascularisation tardive, une aponévrotomie de décompression complète généralement le geste.","src":"p. 182-183","deep":"**Pourquoi** : embolie sur artère saine = embolectomie de Fogarty (référence) ; lit d'aval jambier de mauvaise qualité + ischémie peu sévère = thrombolyse in situ ou thromboaspiration ; pontage souvent distal en dernier ressort (p. 182-183).\n**À relier** : aponévrotomie de décompression si revascularisation tardive ; amputation d'emblée si ischémie dépassée.\n**Piège** : le pontage n'est pas la 1re intention."},{"id":"225-qcm-111","type":"QRM","rank":"A","objective":"225-obj-10","tags":["définition"],"difficulty":1,"stem":"Comment définit-on un anévrisme artériel selon le référentiel ?","options":[{"t":"Une atteinte qui ne peut concerner que l'aorte thoracique","ok":false,"why":"Hors artères cérébrales, les sièges les plus fréquents sont l'aorte (surtout sous-rénale, mais aussi ascendante), les artères poplitées et iliaques (p. 183)."},{"t":"Une perte du parallélisme des bords vasculaires","ok":true,"why":"La perte de parallélisme des parois fait partie de la définition, avec le caractère focal et permanent et le seuil de > 50 % (p. 183)."},{"t":"Une augmentation de diamètre d'au moins 20 % par rapport au segment d'amont","ok":false,"why":"Le seuil est > 50 % par rapport au diamètre d'amont (p. 183)."},{"t":"Une simple ectasie transitoire réversible de l'artère","ok":false,"why":"L'anévrisme est une dilatation focale et PERMANENTE (p. 183) : la média altérée (fibres élastiques détruites, collagène fragmenté) ne lutte plus contre la distension (p. 183)."},{"t":"Une dilatation focale et permanente avec augmentation de diamètre de plus de 50 % par rapport au segment d'amont","ok":true,"why":"Définition complète : dilatation focale et permanente, perte de parallélisme des parois, diamètre augmenté de plus de 50 % par rapport à l'amont (p. 183)."}],"explanation":"Un anévrisme correspond à une dilatation focale et permanente de l'artère, avec perte du parallélisme des bords vasculaires et augmentation de diamètre de plus de 50 % par rapport au segment d'amont.","src":"p. 183","deep":"**Pourquoi** : anévrisme = dilatation focale et permanente, avec perte du parallélisme des parois et augmentation du diamètre de plus de 50 % par rapport à l'amont (p. 183).\n**À relier** : hors artères cérébrales, sièges fréquents : aorte (sous-rénale surtout), artères poplitées, iliaques.\n**Piège** : seuil de > 50 % (pas 20 %) ; permanent, donc pas une ectasie transitoire."},{"id":"225-qcm-112","type":"QRM","rank":"B","objective":"225-obj-11","difficulty":2,"tags":["étiologie"],"stem":"Quelles causes non athéromateuses d'anévrisme de l'aorte abdominale sont citées dans le référentiel ?","options":[{"t":"La maladie de Marfan","ok":true,"why":"Maladie du tissu élastique, parmi les formes familiales d'AAA à entité génétique identifiée (p. 184)."},{"t":"Le syndrome de Loeys-Dietz","ok":true,"why":"Maladie du tissu élastique citée avec Marfan et Ehlers-Danlos (p. 184)."},{"t":"La maladie de Buerger","ok":false,"why":"Elle est citée parmi les artériopathies inflammatoires des membres inférieurs, pas parmi les causes d'AAA ; les aortites en cause sont les maladies de Takayasu, Behçet ou Horton (p. 174, 184)."},{"t":"Le diabète de type 2","ok":false,"why":"Non : les diabétiques sont MOINS souvent atteints d'AAA (p. 183), alors que le diabète est un FdR majeur d'AOMI."},{"t":"Le syndrome d'Ehlers-Danlos","ok":true,"why":"Maladie du tissu élastique responsable de formes familiales d'AAA (p. 184)."}],"explanation":"Dans 80-90 % des cas, l'AAA est athéromateux ; les formes non athéromateuses comprennent les maladies des tissus élastiques (Marfan, Ehlers-Danlos, Loeys-Dietz) et les aortites (maladies de Takayasu, Behçet ou Horton ; autrefois aortites infectieuses syphilitiques).","src":"p. 184","deep":"**Pourquoi** : l'AAA est athéromateux dans 80-90 % des cas ; les autres sont des maladies des tissus élastiques (Marfan, Ehlers-Danlos, Loeys-Dietz) ou des aortites (Takayasu, Behçet, Horton ; syphilis autrefois) (p. 184).\n**À relier** : formes familiales ; antécédents familiaux = facteur de risque.\n**Piège** : Buerger touche les membres inférieurs ; le diabète n'est pas un facteur de risque d'AAA."},{"id":"225-qcm-113","type":"QRM","rank":"A","objective":"225-obj-12","tags":["clinique","urgence"],"difficulty":2,"stem":"Quels tableaux cliniques peuvent révéler un anévrisme de l'aorte abdominale ?","options":[{"t":"Une hypertension artérielle rénovasculaire isolée","ok":false,"why":"L'HTA rénovasculaire vient d'une sténose athéromateuse de l'artère rénale (activation du SRAA) (p. 166), pas d'un AAA."},{"t":"Une hémorragie digestive par fistule aorto-digestive","ok":true,"why":"Fissuration dans un organe adjacent, beaucoup plus rare : fistule aorto-digestive → hémorragie digestive (p. 184)."},{"t":"Une douleur abdominale ou lombaire avec choc hémorragique","ok":true,"why":"Fissuration ou rupture : urgence vitale ; un AAA douloureux fait craindre une rupture imminente (p. 184)."},{"t":"Une insuffisance cardiaque à débit élevé par fistule aorto-cave","ok":true,"why":"Fistule aorto-cave : le shunt artérioveineux donne une insuffisance cardiaque à haut débit (p. 184)."},{"t":"Une découverte fortuite d'une masse battante et expansive para-ombilicale","ok":true,"why":"Découverte à la palpation abdominale (masse battante et expansive para-ombilicale, avec ou sans souffle) ou, plus souvent, à l'imagerie abdominale (p. 184)."}],"explanation":"L'AAA peut être découvert de façon fortuite (masse battante), ou se révéler par une complication : rupture/fissuration (urgence vitale), fistule aorto-cave ou aorto-digestive, embolie, compression ou syndrome inflammatoire.","src":"p. 183-184","deep":"**Pourquoi** : l'AAA est le plus souvent découvert fortuitement (masse battante et expansive para-ombilicale, imagerie) ; le stade de complication = fissuration/rupture, fistule aorto-cave (IC à haut débit) ou aorto-digestive (hémorragie digestive) (p. 183-184).\n**À relier** : plus rares : embolie, compression d'organes voisins, syndrome inflammatoire.\n**Piège** : une HTA rénovasculaire évoque l'artère rénale, pas l'AAA."},{"id":"225-qcm-114","type":"QRM","rank":"A","objective":"225-obj-13","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Quelles propositions concernant les examens complémentaires de l'AAA sont exactes ?","options":[{"t":"L'échographie abdominale est l'examen de dépistage et de suivi","ok":true,"why":"Elle dépiste l'AAA, mesure son diamètre maximal et assure le suivi (p. 184)."},{"t":"L'IRM est une alternative possible en cas de contre-indication au scanner","ok":true,"why":"L'IRM abdominale remplace le scanner notamment quand celui-ci est contre-indiqué (p. 185)."},{"t":"L'artériographie donne une mesure fiable du diamètre de l'anévrisme","ok":false,"why":"Elle ne visualise que la lumière artérielle : pas de mesure fiable du diamètre à cause du thrombus mural (p. 185)."},{"t":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence","ok":true,"why":"Demandé quand une intervention est envisagée, il précise diamètre et anatomie : examen préthérapeutique de référence (p. 185)."},{"t":"L'échographie permet de rechercher d'autres localisations anévrismales associées","ok":true,"why":"Elle dépiste aussi les localisations associées les plus fréquentes, poplitées et iliaques (p. 184) ; l'AP est associé à un AAA dans 30 % des cas (p. 186)."}],"explanation":"L'échographie dépiste et surveille l'AAA, le scanner injecté est l'examen préthérapeutique de référence, l'IRM est une alternative ; l'artériographie n'est pas fiable pour mesurer le diamètre en raison du thrombus mural.","src":"p. 184-185","deep":"**Pourquoi** : échographie = dépistage, mesure du diamètre maximal et suivi ; scanner injecté = bilan préthérapeutique de référence (diamètre, anatomie) ; IRM = alternative si scanner contre-indiqué (p. 184-185).\n**À relier** : l'échographie recherche aussi les anévrismes poplités et iliaques associés.\n**Piège** : l'artériographie ne montre que la lumière (thrombus mural fréquent) : mesure non fiable."},{"id":"225-qcm-115","type":"QRM","rank":"B","objective":"225-obj-14","tags":["traitement","suivi"],"difficulty":3,"stem":"Concernant la surveillance et le traitement d'un AAA asymptomatique, quelles propositions sont exactes ?","options":[{"t":"Une intervention programmée est envisagée dès 40 mm de diamètre","ok":false,"why":"L'intervention « à froid » est programmée au-delà de 50-55 mm, seuil où le risque de rupture devient important ; en dessous, l'anévrisme est surveillé par échographie (p. 184, 186)."},{"t":"La poursuite du tabagisme accélère la croissance de l'anévrisme","ok":true,"why":"Pendant le suivi, l'anévrisme progresse 3 fois plus vite si le tabac est poursuivi (p. 186)."},{"t":"Le traitement endovasculaire est toujours contre-indiqué chez le sujet à haut risque chirurgical","ok":false,"why":"Au contraire, l'endoprothèse est proposée aux sujets à haut risque chirurgical, sous réserve de conditions anatomiques favorables (p. 186)."},{"t":"La surveillance échographique est renforcée (tous les 6 mois) au-delà de 45 mm","ok":true,"why":"Plus l'AAA est gros et proche du seuil d'intervention, plus les échographies sont rapprochées : tous les 6 mois au-delà de 45 mm (p. 185)."},{"t":"Le diamètre est le principal facteur prédictif du risque de rupture","ok":true,"why":"Le risque de rupture croît de façon exponentielle avec le diamètre : 0,4 %/an < 40 mm, 3 % à 50-59 mm, 15 % > 60 mm (p. 184-185)."}],"explanation":"Le diamètre prédit le risque de rupture ; la surveillance échographique est renforcée à 6 mois au-delà de 45 mm ; l'intervention (chirurgie ou endoprothèse) est programmée au-delà de 50-55 mm, l'endoprothèse étant proposée aux sujets à haut risque chirurgical si l'anatomie le permet.","src":"p. 185-186","deep":"**Pourquoi** : le diamètre est le principal facteur prédictif de rupture ; échographie répétée, tous les 6 mois si > 45 mm ; intervention « à froid » au-delà de 50-55 mm (chirurgie ou endoprothèse) (p. 185-186).\n**À relier** : croissance 2-4 mm/an, ×3 si tabagisme actif ; endoprothèse proposée aux sujets à haut risque chirurgical si l'anatomie est favorable.\n**Piège** : 40 mm n'est pas un seuil d'intervention (rupture 0,4 %/an)."},{"id":"225-qru-101","type":"QRU","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":1,"stem":"Quelle est la méthode de revascularisation de référence d'une ischémie aiguë de membre par embolie sur artère saine ?","options":[{"t":"L'embolectomie à la sonde de Fogarty","ok":true,"why":"Sur artère saine, on extrait l'embole par sonde de Fogarty sous contrôle angiographique : méthode de référence (p. 182)."},{"t":"Le pontage extra-anatomique d'emblée","ok":false,"why":"Le pontage (souvent distal) n'est qu'un dernier recours dans l'ischémie aiguë (p. 182)."},{"t":"L'amputation d'emblée","ok":false,"why":"Réservée à l'ischémie dépassée (grade III) ou à l'échec, notamment sur terrain débilité (p. 183)."},{"t":"L'aponévrotomie isolée","ok":false,"why":"Elle décomprime les loges (prévention du syndrome des loges après revascularisation tardive) mais ne lève pas l'occlusion (p. 183)."},{"t":"La thrombolyse systémique intraveineuse","ok":false,"why":"Le Collège décrit une thrombolyse IN SITU intra-artérielle (fibrinolytique dans le thrombus par cathéter), réservée au lit d'aval mauvais avec ischémie peu sévère (p. 182)."}],"explanation":"L'embolectomie à la sonde de Fogarty sous contrôle angiographique est la méthode de référence pour traiter une embolie sur artère saine.","src":"p. 182","deep":"**Pourquoi** : en cas d'embolie sur artère saine, on extrait le caillot par sonde de Fogarty sous contrôle angiographique (p. 182).\n**À relier** : thrombolyse in situ si lit d'aval mauvais et ischémie peu sévère ; sténose résiduelle = angioplastie ; pontage en dernier ressort.\n**Piège** : l'aponévrotomie traite le syndrome des loges, elle ne revascularise pas."},{"id":"225-qru-102","type":"QRU","rank":"A","objective":"225-obj-10","tags":["paraclinique","définition"],"difficulty":1,"stem":"Quelle augmentation de diamètre par rapport au segment d'amont définit un anévrisme ?","options":[{"t":"Il n'existe pas de seuil chiffré","ok":false,"why":"Le Collège chiffre la définition : diamètre augmenté de plus de 50 % par rapport à l'amont (p. 183)."},{"t":"Plus de 50 %","ok":true,"why":"Seuil de définition : > 50 % du diamètre d'amont, avec dilatation focale et permanente et perte de parallélisme (p. 183)."},{"t":"Plus de 10 %","ok":false,"why":"Le seuil de définition est > 50 % (p. 183) ; 10 % est sans valeur."},{"t":"Plus de 25 %","ok":false,"why":"Le seuil de définition est > 50 % (p. 183)."},{"t":"Plus de 100 %","ok":false,"why":"Le seuil de définition est > 50 % (p. 183) : un doublement du diamètre n'est pas requis."}],"explanation":"Un anévrisme est défini par une augmentation de diamètre de plus de 50 % par rapport au segment artériel sus-jacent, avec perte du parallélisme des bords.","src":"p. 183","deep":"**Pourquoi** : un anévrisme est une dilatation focale et permanente de plus de 50 % par rapport au diamètre d'amont, avec perte de parallélisme des parois (p. 183).\n**À relier** : AAA sous-rénal dans la grande majorité des cas ; intervention à froid au-delà de 50-55 mm.\n**Piège** : ne pas confondre le seuil de définition (> 50 % de l'amont) et celui d'intervention (50-55 mm de diamètre)."},{"id":"225-qru-103","type":"QRU","rank":"A","objective":"225-obj-15","tags":["urgence"],"difficulty":2,"stem":"Devant un anévrisme de l'aorte abdominale rompu avec choc hémorragique, quel est le seul examen d'imagerie qui peut être réalisé avant l'intervention ?","options":[{"t":"L'échographie transœsophagienne","ok":false,"why":"L'ETO explore le cœur et l'aorte thoracique ; pour l'AAA rompu, c'est le scanner abdominal qui confirme le diagnostic (p. 184, 188)."},{"t":"L'IRM abdominale complète","ok":false,"why":"L'IRM est l'alternative au scanner en bilan programmé (contre-indication au scanner) (p. 185), pas chez un patient en choc."},{"t":"Le test de marche","ok":false,"why":"Examen de l'AOMI (p. 171), sans aucune place dans une urgence vitale."},{"t":"L'artériographie diagnostique","ok":false,"why":"Elle ne montre que la lumière artérielle, faussée par le thrombus mural : elle n'est pas utile au diagnostic d'AAA (p. 185)."},{"t":"Le scanner abdominal diagnostique","ok":true,"why":"Le diagnostic de rupture doit être confirmé par un scanner avant la prise en charge thérapeutique, en centre spécialisé (p. 184, 188)."}],"explanation":"En cas de rupture d'AAA avec choc hémorragique, seul le scanner diagnostique ne doit pas retarder la prise en charge chirurgicale ou endovasculaire en urgence absolue.","src":"p. 186","deep":"**Pourquoi** : la rupture d'AAA est une urgence absolue ; le patient est dirigé d'urgence vers un centre spécialisé de chirurgie vasculaire où le scanner abdominal confirme le diagnostic et précise la localisation (p. 184, 188).\n**À relier** : un AAA douloureux fait craindre une rupture imminente ; la rupture intrapéritonéale est souvent cataclysmique (p. 184).\n**Piège** : l'artériographie ne voit que la lumière (thrombus mural) et ne mesure pas l'anévrisme (p. 185)."},{"id":"225-qru-105","type":"QRU","rank":"A","objective":"225-obj-06","tags":["suivi","paraclinique"],"difficulty":2,"stem":"Quelle est approximativement la mortalité à 5 ans des patients en ischémie critique ?","options":[{"t":"Environ 70 %","ok":true,"why":"Mortalité à 5 ans proche de 70 % en ischémie critique (p. 178), d'où la prévention même chez le patient revascularisé."},{"t":"Environ 90 %","ok":false,"why":"Le Collège donne une mortalité à 5 ans proche de 70 % (p. 178)."},{"t":"Environ 50 %","ok":false,"why":"Le chiffre retenu est ≈ 70 % à 5 ans (p. 178) ; l'ischémie permanente a une espérance de vie comparable à certains cancers (p. 177)."},{"t":"Environ 20 %","ok":false,"why":"20 % = décès à 5 ans chez le claudicant (moitié CV) (p. 177), pas en ischémie critique (≈ 70 %)."},{"t":"Environ 5 %","ok":false,"why":"5 % = risque d'amputation à 5 ans chez le claudicant (p. 177)."}],"explanation":"Chez le patient en ischémie critique, la mortalité à 5 ans avoisine 70 %, bien supérieure à celle des claudicants (20 % à 5 ans).","src":"p. 178","deep":"**Pourquoi** : l'ischémie critique est de très mauvais pronostic vital : mortalité à 5 ans proche de 70 % ; l'espérance de vie en ischémie permanente est équivalente à celle de certains cancers (p. 178).\n**À relier** : claudicant : ≈ 20 % de décès à 5 ans ; amputation ≈ 5 %. D'où des mesures préventives même après revascularisation.\n**Piège** : ne pas confondre 70 % (ischémie critique) et 20 % (claudicant)."},{"id":"225-qroc-101","type":"QROC","rank":"A","objective":"225-obj-07","tags":["physiopathologie","paraclinique"],"difficulty":1,"question":"Au bout de combien de temps les cellules nerveuses commencent-elles à souffrir en cas d'ischémie aiguë de membre ?","answer":"Dès 2 heures","accept":["2 h","2 heures","2h","deux heures","dès 2 heures"],"keywords":["2"],"explanation":"Les cellules nerveuses sont les premières à souffrir de l'hypoxie, dès 2 heures d'ischémie.","src":"p. 178","deep":"**Pourquoi** : les cellules nerveuses sont les plus sensibles à l'hypoxie ; l'atteinte sensitive et motrice apparaît donc en premier (p. 178).\n**À relier** : muscle 6-8 h (rhabdomyolyse), peau 24 h.\n**Astuce** : 2 h – 6/8 h – 24 h.\n**Piège** : ne pas confondre 2 h (nerf) et 6-8 h (muscle) ; en cas d'atteinte neurologique (grade II), aucune exploration ne doit retarder l'intervention (p. 180)."},{"id":"225-qroc-102","type":"QROC","rank":"A","objective":"225-obj-07","tags":["complications"],"difficulty":1,"question":"Quel geste chirurgical traite le syndrome des loges au cours d'une ischémie aiguë de membre ?","answer":"L'aponévrotomie de décharge","accept":["aponévrotomie","fasciotomie","aponévrotomie de décompression","aponévrotomie de décharge"],"keywords":["aponévrotomie"],"explanation":"Seule une aponévrotomie (section chirurgicale de l'aponévrose) de décharge permet de libérer le tissu musculaire comprimé et de restaurer la circulation capillaire.","src":"p. 178","deep":"**Pourquoi** : l'œdème musculaire dans une loge aponévrotique inextensible comprime les tissus et arrête la circulation capillaire ; seule la section de l'aponévrose libère le muscle (p. 178).\n**À relier** : geste systématique si revascularisation tardive (souvent loge antéro-externe de jambe).\n**Piège** : l'aponévrotomie décomprime les loges mais ne revascularise pas : elle complète le geste en cas de revascularisation tardive (p. 183)."},{"id":"225-qroc-103","type":"QROC","rank":"A","objective":"225-obj-07","tags":["diagnostic"],"difficulty":2,"question":"Quel nerf, dont l'atteinte empêche de relever le pied, est cité dans l'examen neurologique de l'ischémie aiguë de membre ?","answer":"Le nerf fibulaire commun","accept":["fibulaire commun","sciatique poplité externe","spe","nerf fibulaire","péronier commun","nerf péronier commun"],"keywords":["fibulaire"],"explanation":"L'examen neurologique de l'ischémie aiguë recherche une anesthésie et une paralysie, notamment du nerf fibulaire commun (impossibilité de relever le pied), signe de gravité.","src":"p. 179","deep":"**Pourquoi** : l'examen neurologique de l'ischémie aiguë recherche anesthésie et paralysie, notamment du nerf fibulaire commun (impossibilité de relever le pied) (p. 179).\n**À relier** : un déficit moteur signe un grade IIb ou III : plus aucune exploration ne doit retarder l'intervention.\n**Piège** : le grade IIa n'a pas de déficit moteur ; déficit moteur modéré = IIb, paralysie = III (p. 179)."},{"id":"225-qroc-104","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"question":"Quel terrain est classiquement associé à une thrombose artérielle in situ à l'origine d'une ischémie aiguë ?","answer":"Un sujet âgé avec facteurs de risque cardiovasculaire, souvent déjà artériopathe","accept":["sujet âgé artériopathe","sujet âgé avec facteurs de risque cardiovasculaire","patient âgé artériopathe","âgé avec AOMI"],"keywords":["âgé","artériopathe"],"explanation":"La thrombose in situ concerne le plus souvent un sujet âgé aux facteurs de risque cardiovasculaire, avec souvent une AOMI préexistante.","src":"p. 181","deep":"**Pourquoi** : la thrombose se fait sur une artère déjà malade : sujet âgé à FDR, AOMI préexistante (à rechercher sur l'autre membre), douleur d'intensité moyenne grâce aux collatérales (p. 181).\n**À relier** : embolie = sujet plus jeune, artères saines, douleur brutale sévère.\n**Piège** : les deux tableaux peuvent se chevaucher."},{"id":"225-qroc-105","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":1,"question":"Quel trouble du rythme cardiaque est cité en tête des causes cardiaques d'embolie artérielle des membres ?","answer":"La fibrillation atriale","accept":["fa","arythmie complète par fibrillation atriale","FA","fibrillation auriculaire","ACFA","fibrillation atriale"],"keywords":["fibrillation"],"explanation":"Parmi les causes cardiaques d'embolie, le référentiel cite en premier les troubles du rythme, notamment la fibrillation atriale ; une anticoagulation au long cours est à envisager en cas de FA.","src":"p. 181","deep":"**Pourquoi** : la fibrillation atriale (troubles du rythme) est citée en tête des causes cardiaques d'embolie ; l'embolie survient sur artère saine et peut suivre des épisodes de palpitations (p. 181).\n**À relier** : autres sources cardiaques : FOP, infarctus, endocardite, prothèses, myxome ; anticoagulation au long cours en cas de FA.\n**Piège** : l'embolie touche des artères saines."},{"id":"225-qroc-106","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","paraclinique"],"difficulty":2,"question":"Quelle est la cible de TCA sous héparine non fractionnée dans le traitement de l'ischémie aiguë de membre ?","answer":"Entre 2 et 3","accept":["2-3","2 à 3","entre 2 et 3","2,5","TCA 2-3"],"keywords":["2","3"],"explanation":"L'anticoagulation par héparine non fractionnée (bolus 5 000 UI puis 500 UI/kg/j) vise une cible de TCA comprise entre 2 et 3.","src":"p. 182","deep":"**Pourquoi** : HNF dès le diagnostic, juste après le prélèvement du bilan de coagulation, bolus 5 000 UI puis 500 UI/kg/j, TCA visé entre 2 et 3 (p. 182).\n**À relier** : associée aux antalgiques de palier 3, à l'oxygène, à la correction hémodynamique et aux soins locaux (p. 182) ; à long terme, anticoagulation si FA (p. 183).\n**Astuce** : bolus 5 000 UI, puis 500 UI/kg/j ; TCA entre 2 et 3.\n**Piège** : HNF (pas HBPM) ; le bilan de coagulation est prélevé AVANT de débuter l'héparine (p. 182)."},{"id":"225-qroc-107","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel type de molécule est utilisé pour traiter l'hyperkaliémie sévère lors du syndrome de revascularisation, en dehors de la dialyse ?","answer":"Un chélateur du potassium (polystyrène sulfonate de sodium)","accept":["chélateur de potassium","polystyrène sulfonate","kayexalate","chélateur du potassium","chélateur de K","résine échangeuse","polystyrène sulfonate de sodium"],"keywords":["chélateur","potassium"],"explanation":"L'hyperkaliémie du syndrome de revascularisation est traitée par un chélateur de potassium (polystyrène sulfonate de sodium), voire par une dialyse rénale.","src":"p. 183","deep":"**Pourquoi** : la reperfusion lâche le potassium des cellules lysées : hyperkaliémie avec acidose métabolique, à surveiller par ionogramme (p. 183).\n**À relier** : bicarbonates IV pour l'acidose, dialyse si besoin, lavage du membre au sérum physiologique.\n**Piège** : l'hyperkaliémie du syndrome de revascularisation peut aller jusqu'à la dialyse."},{"id":"225-qroc-108","type":"QROC","rank":"A","objective":"225-obj-10","tags":["définition","épidémiologie"],"difficulty":1,"question":"Quel segment de l'aorte est le plus souvent le siège d'un anévrisme de l'aorte abdominale ?","answer":"Le segment sous-rénal","accept":["sous-rénal","aorte sous-rénale","sous-rénale","segment sous-rénal","au-dessous des artères rénales","sous rénal"],"keywords":["sous-rénal"],"explanation":"Dans la grande majorité des cas, l'AAA est localisé au-dessous des artères rénales, c'est-à-dire sur le segment sous-rénal de l'aorte.","src":"p. 183","deep":"**Pourquoi** : dans la grande majorité des cas, l'AAA siège sous les artères rénales (p. 183) ; c'est aussi la base du risque de rupture chiffré « de l'aorte sous-rénale » (p. 184).\n**À relier** : autres sièges fréquents hors cerveau : aorte ascendante, artères poplitées et iliaques, à rechercher par échographie (p. 183-184).\n**Astuce** : AAA = « sous-rénal » dans l'immense majorité des cas.\n**Piège** : l'aorte ascendante est un autre siège d'anévrisme, mais l'AAA siège sous les artères rénales dans la grande majorité des cas (p. 183)."},{"id":"225-qroc-109","type":"QROC","rank":"A","objective":"225-obj-10","tags":["paraclinique","suivi"],"difficulty":2,"question":"Combien de fois le porteur d'un AAA a-t-il plus de risque de décéder d'une complication cardiovasculaire que de la rupture de son anévrisme ?","answer":"Environ 10 fois plus","accept":["10 fois","10","dix fois","10 fois plus","environ 10 fois"],"keywords":["10"],"explanation":"Le porteur d'un AAA a un risque de décès cardiovasculaire (coronarien ou cérébral) environ 10 fois supérieur à celui de mourir de la rupture de son anévrisme.","src":"p. 184","deep":"**Pourquoi** : le porteur d'AAA est globalement à haut risque cardiovasculaire : il décède 10 fois plus souvent d'une atteinte coronarienne ou d'un AVC que de la rupture (p. 184).\n**À relier** : contrôle des facteurs de risque indispensable même après réparation.\n**Piège** : le danger du porteur d'AAA n'est pas seulement l'anévrisme."},{"id":"225-qroc-110","type":"QROC","rank":"A","objective":"225-obj-13","tags":["paraclinique"],"difficulty":1,"question":"Quel examen constitue la référence pour le bilan préthérapeutique d'un AAA en vue d'une intervention ?","answer":"Le scanner abdominopelvien avec injection de produit de contraste","accept":["scanner injecté","angioscanner abdominal","scanner","angioscanner","scanner abdominopelvien injecté","tdm injectée","scanner abdominal"],"keywords":["scanner"],"explanation":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence, précisant le diamètre et l'anatomie de l'anévrisme.","src":"p. 185","deep":"**Pourquoi** : le scanner injecté, demandé quand une intervention est envisagée, précise le diamètre et l'anatomie de l'anévrisme, nécessaires pour choisir chirurgie ou endoprothèse (p. 185).\n**À relier** : l'échographie dépiste et surveille ; l'IRM est une alternative si le scanner est contre-indiqué (p. 184-185).\n**Piège** : l'artériographie n'est pas utile : elle ne voit que la lumière, le thrombus mural fausse la mesure (p. 185)."},{"id":"225-qroc-111","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement","paraclinique"],"difficulty":2,"question":"À partir de quel diamètre (en mm) un AAA asymptomatique est-il habituellement proposé pour une intervention programmée « à froid » ?","answer":"50 à 55 mm","accept":["50-55 mm","50-55","50 à 55","> 50 mm","50 mm","55 mm","plus de 50 mm"],"keywords":["50","55"],"explanation":"Le risque de rupture devenant important au-delà de 50-55 mm, une intervention programmée (chirurgicale ou endovasculaire) est alors proposée.","src":"p. 186","deep":"**Pourquoi** : le risque de rupture devient important au-delà de 50-55 mm (de 0,4 %/an < 40 mm à 3 % à 50-59 mm et 15 % au-delà de 60 mm, p. 184) ; intervention à froid au-delà de 50-55 mm (p. 186).\n**À relier** : surveillance tous les 6 mois si > 45 mm ; chirurgie à ciel ouvert ou endoprothèse.\n**Piège** : ne pas confondre le seuil de renforcement de la surveillance (45 mm) et celui d'intervention."},{"id":"225-qroc-112","type":"QROC","rank":"B","objective":"225-obj-15","tags":["suivi","complications"],"difficulty":2,"question":"Quelle complication à long terme doit être recherchée par surveillance après la pose d'une endoprothèse aortique ?","answer":"Les endofuites","accept":["endofuite","endofuites","endoleak","fuite de l'endoprothèse"],"keywords":["endofuite"],"explanation":"Après endoprothèse, une surveillance scanner/échographique au long cours recherche des endofuites, qui peuvent faire progresser voire rompre l'anévrisme.","src":"p. 186","deep":"**Pourquoi** : l'endofuite est un flux qui maintient la pression dans le sac anévrismal, d'où la poursuite de l'évolutivité et le risque de rupture (p. 186).\n**À relier** : surveillance au long cours par scanner ou échographie de contraste ; après chirurgie ouverte, on surveille les faux anévrismes anastomotiques.\n**Piège** : endoprothèse = endofuites ; prothèse chirurgicale = faux anévrisme."},{"id":"225-open-11","type":"OPEN","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":3,"prompt":"Un homme de 74 ans en fibrillation atriale non anticoagulée présente, depuis 3 heures, une douleur brutale et intense du membre inférieur droit avec pied froid, pâle, pouls abolis, sans déficit neurologique. Décrivez votre prise en charge diagnostique et thérapeutique immédiate.","rubric":[{"point":"Reconnaître une ischémie aiguë de membre, grade I (viable, sans déficit)","weight":2},{"point":"Diagnostic essentiellement clinique, ne pas retarder la prise en charge par des examens inutiles","weight":1},{"point":"Anticoagulation par héparine non fractionnée dès le diagnostic après prélèvement du bilan de coagulation","weight":2},{"point":"Antalgiques, oxygénothérapie, soins locaux et correction hémodynamique si besoin","weight":1},{"point":"Revascularisation en urgence adaptée au mécanisme probable (embolectomie de Fogarty évoquée devant le contexte de fibrillation atriale)","weight":2},{"point":"Bilan étiologique cardiaque (ECG, auscultation, palpation abdominale) sans retarder le traitement","weight":1},{"point":"Surveillance des conséquences métaboliques de la reperfusion","weight":1}],"model":"Ce tableau correspond à une ischémie aiguë de membre de grade I (viable, sans déficit sensitivomoteur), probablement d'origine embolique compte tenu de la fibrillation atriale non anticoagulée et du caractère brutal de la douleur. Le diagnostic reste clinique et ne doit pas être retardé par des examens complémentaires inutiles ; un échodoppler peut être réalisé sans perte de temps devant ce grade I. Le traitement médical immédiat associe une anticoagulation par héparine non fractionnée (bolus puis perfusion continue pour une cible de TCA entre 2 et 3) débutée dès le diagnostic après simple prélèvement du bilan de coagulation, des antalgiques de palier 3 si besoin, une oxygénothérapie, une correction de l'état hémodynamique et des soins locaux protecteurs. Une revascularisation est organisée en urgence, l'embolectomie à la sonde de Fogarty étant la méthode de référence en cas d'embolie sur artère saine. L'examen clinique est complété par une auscultation cardiaque, un ECG et une palpation abdominale à la recherche d'un anévrisme, dans le cadre du bilan étiologique. Après revascularisation, les conséquences métaboliques (hyperkaliémie, acidose, myoglobinurie) doivent être activement surveillées.","src":"p. 178-182"},{"id":"225-open-12","type":"OPEN","rank":"B","objective":"225-obj-14","tags":["traitement","suivi"],"difficulty":2,"prompt":"Expliquez la stratégie de surveillance et de traitement d'un anévrisme de l'aorte abdominale asymptomatique, depuis sa découverte jusqu'à son éventuelle prise en charge chirurgicale.","rubric":[{"point":"Le diamètre est le principal facteur prédictif de rupture","weight":2},{"point":"Surveillance échographique répétée, renforcée à 6 mois au-delà de 45 mm","weight":2},{"point":"Contrôle des facteurs de risque, en particulier l'arrêt du tabac","weight":1},{"point":"Seuil d'intervention programmée à 50-55 mm","weight":2},{"point":"Choix entre chirurgie conventionnelle et endoprothèse selon le terrain et l'anatomie","weight":2},{"point":"Surveillance post-thérapeutique adaptée à la technique (échodoppler ou scanner/endofuites)","weight":1}],"model":"Le diamètre de l'anévrisme est le principal facteur prédictif du risque de rupture. Tant que le diamètre reste inférieur au seuil d'intervention, une surveillance échographique répétée est mise en place, renforcée tous les 6 mois au-delà de 45 mm. Le contrôle des facteurs de risque, en particulier l'arrêt du tabac (sa poursuite rend la progression 3 fois plus rapide), est indispensable pendant tout le suivi. Au-delà de 50-55 mm, le risque de rupture devient suffisamment important pour proposer une intervention « à froid » : chirurgie conventionnelle à ciel ouvert (exclusion et interposition d'une prothèse) ou traitement endovasculaire par endoprothèse, moins invasif, proposé aux sujets à haut risque chirurgical si l'anatomie est favorable (possible aussi chez le bas risque après information éclairée). Après chirurgie conventionnelle, la surveillance repose sur l'échodoppler (recherche de faux anévrisme anastomotique) ; après endoprothèse, une surveillance scanner/échographique au long cours recherche des endofuites pouvant faire reprogresser l'anévrisme.","src":"p. 185-186"},{"id":"225-open-13","type":"OPEN","rank":"A","objective":"225-obj-15","tags":["urgence","clinique"],"difficulty":2,"prompt":"Un homme de 70 ans, connu porteur d'un anévrisme de l'aorte abdominale de 48 mm suivi par échographie, se présente aux urgences pour une douleur lombaire brutale et une tension artérielle à 85/50 mmHg. Quelle est votre prise en charge ?","rubric":[{"point":"Évoquer une fissuration ou une rupture d'AAA (douleur lombaire brutale + hypotension chez un porteur d'AAA) : urgence vitale absolue","weight":2},{"point":"Un AAA devenu douloureux fait craindre une rupture imminente","weight":1},{"point":"Orientation sans délai vers un centre spécialisé de chirurgie vasculaire","weight":2},{"point":"Scanner abdominal pour confirmer le diagnostic et préciser la localisation avant la prise en charge thérapeutique","weight":2}],"model":"Une douleur lombaire brutale avec hypotension chez un porteur connu d'AAA doit faire évoquer une fissuration ou une rupture de l'anévrisme : c'est une urgence vitale, et le caractère douloureux d'un AAA fait à lui seul craindre une rupture imminente. Le patient est dirigé sans délai vers un centre spécialisé de chirurgie vasculaire, où un scanner abdominal confirme le diagnostic et précise la localisation avant la prise en charge thérapeutique. La rupture d'AAA est une urgence absolue ; le risque de rupture augmente avec le diamètre de l'anévrisme.","src":"p. 184, 187-188"},{"id":"225-qroc-401","type":"QROC","rank":"A","objective":"225-obj-17","tags":["diagnostic"],"difficulty":1,"question":"À quel moment surviennent les douleurs abdominales de l'angor digestif (ischémie mésentérique chronique) ?","answer":"En postprandial","accept":["postprandial","apres les repas","post-prandial","après le repas","après les repas","postprandiales","après manger","post prandial"],"keywords":["prandi"],"explanation":"L'ischémie mésentérique chronique symptomatique réalise un angor digestif : douleurs postprandiales conduisant à une restriction alimentaire et un amaigrissement.","src":"p. 166-167","deep":"**Pourquoi** : les sténoses du tronc cœliaque ou des mésentériques donnent un angor digestif : douleurs abdominales après le repas, d'où restriction alimentaire et amaigrissement dans les formes graves (p. 166).\n**À relier** : seul signe physique éventuel : souffle abdominal ; la forme aiguë associe douleur abdominale aiguë, vidange digestive accélérée et indices emboliques (FA) (p. 167).\n**Astuce** : angor digestif = angor déclenché par le repas.\n**Piège** : douleur abdominale aiguë avec vidange digestive accélérée = ischémie mésentérique AIGUË (p. 167), pas l'angor digestif."},{"id":"225-qroc-403","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":1,"question":"Quel syndrome associe atteinte aorto-iliaque, claudication fessière et troubles de l'érection ?","answer":"Le syndrome de Leriche","accept":["leriche","syndrome de leriche"],"keywords":["leriche"],"explanation":"Le syndrome de Leriche traduit une atteinte aorto-iliaque avec claudication fessière et troubles de l'érection.","src":"p. 168-170","deep":"**Pourquoi** : atteinte aorto-iliaque de l'homme : claudication fessière et/ou fatigabilité à la marche + troubles de l'érection (p. 169).\n**À relier** : à chercher à l'interrogatoire d'un artéritique masculin.\n**Piège** : « Leriche et Fontaine » désigne aussi la classification des stades."},{"id":"225-qroc-404","type":"QROC","rank":"A","objective":"225-obj-03","tags":["définition","diagnostic"],"difficulty":2,"question":"Quelle pression de cheville définit l'ischémie critique ?","answer":"< 50 mmHg","accept":["50","inférieure à 50 mmHg","moins de 50 mmHg","50 mmHg","<50"],"keywords":["50"],"explanation":"L'ischémie critique se définit par une pression de cheville < 50 mmHg ou une pression d'hallux < 30 mmHg, avec douleurs de décubitus > 15 jours.","src":"p. 168-170","deep":"**Pourquoi** : l'ischémie critique est un diagnostic clinico-hémodynamique : douleurs > 15 jours résistant aux antalgiques avec pression de cheville < 50 mmHg ou d'hallux < 30 mmHg (p. 169).\n**À relier** : pronostic du membre engagé ; revascularisation à tenter ; TcPO2 < 10 mmHg = hypoxie critique.\n**Piège** : 50 = cheville ; 30 = hallux."},{"id":"225-qroc-405","type":"QROC","rank":"A","objective":"225-obj-04","tags":["examens","diagnostic"],"difficulty":1,"question":"En dessous de quelle valeur d'IPS l'AOMI est-elle qualifiée de sévère ?","answer":"IPS < 0,70","accept":["0,7","0.7","0,70","<0,7","< 0,7","< 0,70","inférieur à 0,7","moins de 0,70","moins de 0,7"],"keywords":["0,7"],"explanation":"IPS normal 1,00-1,40 ; AOMI si < 0,90 ; AOMI sévère si < 0,70 ; médiacalcose si > 1,40.","src":"p. 170-173","deep":"**Pourquoi** : IPS < 0,70 = AOMI sévère ; < 0,90 = AOMI ; 1,00-1,40 = normal (p. 171).\n**À relier** : IPS > 1,40 = médiacalcose : se fier à la pression d'orteil.\n**Astuce** : 0,9 puis 0,7 : on descend du diagnostic à la gravité.\n**Piège** : les points clés du Collège impriment « > 0,7 » (coquille, p. 187) ; le texte du chapitre dit bien inférieur à 0,70."},{"id":"225-qroc-406","type":"QROC","rank":"A","objective":"225-obj-04","tags":["examens"],"difficulty":3,"question":"Quelle baisse relative de l'IPS (en %) juste après un test de marche est évocatrice d'AOMI ?","answer":"Une baisse > 20 %","accept":["20","20 %","> 20 %","plus de 20 %","20%","supérieure à 20 %"],"keywords":["20"],"explanation":"Après effort, une baisse de pression de cheville > 30 mmHg ou de l'IPS > 20 % est évocatrice d'AOMI chez un patient symptomatique à IPS de repos normal.","src":"p. 170-173","deep":"**Pourquoi** : chez un claudicant à IPS de repos normal, le test de marche démasque l'AOMI : après l'effort, l'IPS chute de plus de 20 % (ou la PAS de cheville de plus de 30 mmHg) (p. 171).\n**À relier** : aide aussi à distinguer une claudication artérielle d'autres douleurs à la marche.\n**Piège** : ce test se fait sur tapis roulant (Strandness), pas au test de marche de 6 min."},{"id":"225-qroc-407","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle classe de traitement antithrombotique est indiquée chez tout patient ayant une AOMI symptomatique ?","answer":"Un antiplaquettaire (aspirine ou clopidogrel)","accept":["antiplaquettaire","antiagregant","aspirine","clopidogrel","antiagrégant plaquettaire","antiplaquettaires","antiagrégants","antiagrégant","anti-agrégant plaquettaire"],"keywords":["plaquet"],"explanation":"Un antiplaquettaire (aspirine ou clopidogrel) est indiqué chez tout AOMI symptomatique ; il est discuté si l'AOMI est asymptomatique isolée.","src":"p. 175-178","deep":"**Pourquoi** : l'artéritique symptomatique est polyathéromateux ; l'antiplaquettaire réduit infarctus et AVC (p. 175).\n**À relier** : asymptomatique isolée (IPS < 0,90) : débattu ; statine systématique ; IEC possible.\n**Piège** : pas d'anticoagulant en routine."},{"id":"225-qroc-408","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"Quelle est la mortalité à 5 ans des patients en ischémie critique ?","answer":"Environ 70 %","accept":["70","70 %","70%","environ 70%","proche de 70 %"],"keywords":["70"],"explanation":"Le pronostic de l'ischémie permanente est grave, comparable à certains cancers : la mortalité à 5 ans en ischémie critique avoisine 70 %.","src":"p. 175-178","deep":"**Pourquoi** : l'ischémie permanente est de pronostic grave, comparable à certains cancers ; la mortalité à 5 ans de l'ischémie critique est proche de 70 % (p. 177-178).\n**À relier** : claudicant : 20 % de décès à 5 ans ; d'où traitement préventif même chez le patient revascularisé.\n**Piège** : 70 % pour l'ischémie critique (pas 20 %)."},{"id":"225-qroc-409","type":"QROC","rank":"A","objective":"225-obj-07","tags":["physiopathologie"],"difficulty":2,"question":"Au bout de combien de temps les cellules musculaires souffrent-elles lors d'une ischémie aiguë de membre ?","answer":"Dès 6 à 8 heures","accept":["6-8","6 a 8","6 à 8 heures","6-8 h","6 à 8 h","6-8 heures","entre 6 et 8 heures"],"keywords":["6"],"explanation":"Les cellules nerveuses souffrent dès 2 heures, les cellules musculaires dès 6-8 heures (rhabdomyolyse), la nécrose cutanée apparaît vers la 24e heure.","src":"p. 178-180","deep":"**Pourquoi** : nerf d'abord (2 h), puis muscle (6-8 h) avec rhabdomyolyse, puis peau (24 h) (p. 178).\n**À relier** : la rhabdomyolyse alimente les désordres métaboliques de la reperfusion (hyperkaliémie, myoglobinurie).\n**Astuce** : 2 – 6/8 – 24.\n**Piège** : 2 h = nerf ; 6-8 h = muscle ; 24 h = nécrose cutanée (p. 178)."},{"id":"225-qroc-410","type":"QROC","rank":"A","objective":"225-obj-07","tags":["diagnostic","urgence"],"difficulty":3,"question":"Quel grade de Rutherford correspond à une ischémie aiguë immédiatement menaçante avec déficit sensitif au-delà des orteils ?","answer":"Grade IIb","accept":["iib","2b","IIb","grade 2b","grade IIb","II b","Rutherford IIb"],"keywords":["iib"],"explanation":"Le grade IIb (immédiatement menaçante) associe un déficit sensitif au-delà des orteils et un déficit moteur modéré ; la récupération n'est possible qu'en urgence immédiate.","src":"p. 178-180","deep":"**Pourquoi** : IIb = déficit sensitif au-delà des orteils + déficit moteur modéré ; récupération possible seulement si prise en charge immédiate (p. 179).\n**À relier** : IIa = discrètement menaçant, I = viable, III = irréversible (anesthésie importante, paralysie).\n**Piège** : IIa n'a pas de déficit moteur."},{"id":"225-qroc-411","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":1,"question":"Quel est le traitement de référence d'une ischémie aiguë par embolie sur artère saine ?","answer":"L'embolectomie à la sonde de Fogarty","accept":["fogarty","embolectomie","embolectomie à la sonde de Fogarty","embolectomie de Fogarty","sonde de Fogarty","thrombectomie à la sonde de Fogarty"],"keywords":["embolectom"],"explanation":"L'embolectomie à la sonde de Fogarty sous contrôle angiographique est la méthode de référence de l'embolie sur artère saine.","src":"p. 182-183","deep":"**Pourquoi** : on extrait mécaniquement l'embole d'une artère saine à la sonde de Fogarty sous contrôle angiographique (p. 182).\n**À relier** : thrombolyse si lit d'aval mauvais et ischémie peu sévère ; angioplastie si sténose résiduelle ; pontage en dernier recours.\n**Piège** : l'artère est saine, donc embolectomie plutôt que pontage."},{"id":"225-qroc-412","type":"QROC","rank":"A","objective":"225-obj-10","tags":["définition"],"difficulty":1,"question":"Quelle augmentation de diamètre par rapport au segment sus-jacent définit un anévrisme ?","answer":"Plus de 50 %","accept":["50","50 %","> 50 %","plus de 50%","supérieure à 50 %","50%"],"keywords":["50"],"explanation":"Un anévrisme est une dilatation localisée et durable dont le diamètre dépasse de plus de 50 % celui du segment sus-jacent.","src":"p. 183-185","deep":"**Pourquoi** : la définition combine dilatation focale et permanente, perte de parallélisme des parois et augmentation de plus de 50 % du diamètre d'amont (p. 183) ; la média détruite (élastine, collagène) ne résiste plus à la distension.\n**À relier** : siège préférentiel : aorte sous-rénale (p. 183).\n**Piège** : 50 % = seuil de définition ; 50-55 mm = seuil d'intervention."},{"id":"225-qroc-413","type":"QROC","rank":"A","objective":"225-obj-10","tags":["pronostic"],"difficulty":2,"question":"Quel est le risque annuel de rupture d'un AAA de diamètre supérieur à 60 mm ?","answer":"Environ 15 % par an","accept":["15","15 %","15%","environ 15%","15 % par an"],"keywords":["15"],"explanation":"Le risque de rupture croît avec le diamètre : 0,4 %/an si < 40 mm, 3 %/an à 50-59 mm, 15 %/an au-delà de 60 mm.","src":"p. 183-185","deep":"**Pourquoi** : le risque de rupture augmente exponentiellement avec le diamètre : 0,4 %/an < 40 mm, 3 % à 50-59 mm, 15 % au-delà de 60 mm ; près de 4 fois plus chez la femme à diamètre égal (p. 184).\n**À relier** : intervention à froid dès 50-55 mm.\n**Astuce** : 0,4 – 3 – 15.\n**Piège** : 0,4 %/an = < 40 mm ; 3 %/an = 50-59 mm ; 15 %/an = > 60 mm (p. 184)."},{"id":"225-qroc-414","type":"QROC","rank":"A","objective":"225-obj-13","tags":["examens","surveillance"],"difficulty":1,"question":"Quel examen permet le dépistage et la surveillance du diamètre d'un AAA ?","answer":"L'échographie abdominale","accept":["echographie","echo abdominale","échographie","écho abdominale","échographie abdominale","échographie doppler abdominale"],"keywords":["echo"],"explanation":"L'échographie abdominale dépiste, mesure le diamètre maximal et assure le suivi de l'AAA ; le scanner injecté est l'examen préthérapeutique.","src":"p. 183-185","deep":"**Pourquoi** : l'échographie abdominale, non invasive, dépiste l'AAA, mesure son diamètre maximal et assure le suivi ; elle repère aussi les anévrismes poplités et iliaques associés (p. 184).\n**À relier** : bilan préthérapeutique = scanner injecté ; IRM si scanner contre-indiqué (p. 185).\n**Piège** : l'artériographie ne sert pas à mesurer l'AAA (thrombus mural) (p. 185)."},{"id":"225-qroc-415","type":"QROC","rank":"A","objective":"225-obj-12","tags":["diagnostic"],"difficulty":2,"question":"Quelle manifestation cardiaque révèle une fistule aorto-cave compliquant un AAA ?","answer":"Une insuffisance cardiaque à débit élevé","accept":["insuffisance cardiaque","haut debit","debit eleve","IC à haut débit","insuffisance cardiaque à haut débit","insuffisance cardiaque à débit élevé","insuffisance cardiaque haut débit"],"keywords":["debit"],"explanation":"Une fistule aorto-cave se révèle par une insuffisance cardiaque à débit élevé ; une fistule aorto-digestive par une hémorragie digestive.","src":"p. 183-185","deep":"**Pourquoi** : la fissuration d'un AAA dans un organe adjacent est beaucoup plus rare que la rupture ; dans la veine cave (fistule aorto-cave), elle se révèle par une insuffisance cardiaque à débit élevé (p. 184).\n**À relier** : fistule aorto-digestive = hémorragie digestive.\n**Piège** : ne pas inverser les deux fistules."},{"id":"225-qroc-416","type":"QROC","rank":"A","objective":"225-obj-11","tags":["épidémiologie","diagnostic"],"difficulty":1,"question":"Quelle population, définie par son sexe et son âge, doit être dépistée par échographie pour un AAA ?","answer":"Chez l'homme de plus de 65 ans","accept":["homme > 65","homme de plus de 65 ans","hommes de plus de 65 ans","hommes > 65 ans","homme > 65 ans","hommes de plus de 65"],"keywords":["homme","65"],"explanation":"Le dépistage échographique est recommandé chez l'homme > 65 ans, ou plus jeune en cas de facteurs de risque (tabac, athérome, antécédents familiaux).","src":"p. 183-185","deep":"**Pourquoi** : l'AAA est le plus souvent asymptomatique et découvert fortuitement : on le dépiste par échographie chez les sujets à risque, au premier rang l'homme de plus de 65 ans (p. 184), chez qui la prévalence est de 2 à 5 % (p. 183).\n**À relier** : plus jeune si tabagisme, maladie athéromateuse ou antécédents familiaux d'anévrisme (p. 184, rang B).\n**Piège** : cible = homme ET plus de 65 ans."},{"id":"225-qroc-417","type":"QROC","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie de l'AAA dans 80 à 90 % des cas ?","answer":"L'athérome","accept":["atherome","atherosclerose","atheromateux","athérosclérose","maladie athéromateuse","athéromateuse","athérome"],"keywords":["atherom"],"explanation":"Dans 80-90 % des cas, l'AAA survient sur un terrain athéromateux, souvent associé à une AOMI ou une atteinte coronarienne ou carotidienne.","src":"p. 183-185","deep":"**Pourquoi** : dans 80-90 % des cas, l'AAA survient chez un sujet athéromateux, notamment porteur d'AOMI, de coronaropathie ou d'atteinte carotidienne (p. 184).\n**À relier** : autres causes : maladies du tissu élastique (Marfan, Ehlers-Danlos, Loeys-Dietz), aortites (Takayasu, Behçet, Horton ; syphilis autrefois) (p. 184).\n**Piège** : le diabète, FdR majeur d'AOMI, est associé à MOINS d'AAA (p. 183)."},{"id":"225-qroc-418","type":"QROC","rank":"B","objective":"225-obj-14","tags":["surveillance"],"difficulty":3,"question":"Au-delà de quel diamètre la surveillance échographique d'un AAA asymptomatique est-elle renforcée tous les 6 mois ?","answer":"Au-delà de 45 mm","accept":["45","45 mm","> 45 mm","plus de 45 mm"],"keywords":["45"],"explanation":"La surveillance échographique est renforcée (tous les 6 mois) si le diamètre dépasse 45 mm, l'intervention étant programmée au-delà de 50-55 mm.","src":"p. 185-187","deep":"**Pourquoi** : plus l'anévrisme est gros et proche du seuil d'intervention, plus il faut le surveiller souvent (p. 185).\n**À relier** : seuil d'intervention : 50-55 mm ; progression 3 fois plus rapide si tabagisme actif.\n**Piège** : 45 mm = surveillance renforcée ; 50-55 mm = chirurgie."},{"id":"225-qroc-420","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":1,"question":"Quels sont les deux principaux facteurs de risque de l'AOMI ?","answer":"Le tabagisme et le diabète","accept":["tabac et diabete","tabagisme et diabete","tabac et diabète","tabagisme et diabète","diabète et tabac","diabète et tabagisme","tabac, diabète"],"keywords":["taba","diabet"],"explanation":"Le tabagisme (plus fréquent chez le sujet jeune) et le diabète (formes distales plus graves) sont les deux principaux facteurs de risque de l'AOMI.","src":"p. 167-168","deep":"**Pourquoi** : le tabagisme est plus fréquent chez le sujet jeune ; le diabète donne des formes graves d'emblée, plus distales (p. 168).\n**À relier** : HTA et hypercholestérolémie : FDR fréquemment associés.\n**Astuce** : T + D.\n**Piège** : HTA et hypercholestérolémie sont « fréquemment associées », pas les deux principaux FdR (p. 168)."},{"id":"225-qcm-503","type":"QRM","rank":"A","objective":"225-obj-01","tags":["épidémiologie","AOMI"],"difficulty":2,"stem":"Concernant l'épidémiologie de l'AOMI, quelles propositions sont exactes ?","options":[{"t":"Le pic de présentation est plus précoce chez la femme que chez l'homme.","ok":false,"why":"Le pic se situe à 60-75 ans chez l'homme et à 70-80 ans chez la femme : il est plus TARDIF chez la femme (p. 167)."},{"t":"Sa prévalence clinique atteint 10 à 15 % après 60 ans.","ok":false,"why":"Formes cliniques : 1 à 5 % après 60 ans ; 10-15 % seulement si l'on inclut les formes asymptomatiques (p. 168)."},{"t":"Pour un cas clinique, on compte 2 à 4 formes infracliniques, ce qui justifie un dépistage ciblé.","ok":true,"why":"Les formes infracliniques sont 2 à 4 fois plus nombreuses que les formes cliniques, ce qui justifie de les dépister pour mieux prévenir (p. 168)."},{"t":"C'est la première localisation de l'athérosclérose.","ok":false,"why":"Elle n'est que la 3e localisation, après les atteintes coronarienne et cérébrale (p. 167)."},{"t":"Elle touche plus souvent l'homme.","ok":true,"why":"Dans sa forme symptomatique, l'AOMI est plus fréquente chez l'homme que chez la femme (p. 167)."}],"explanation":"L'AOMI, 3e localisation de l'athérosclérose, prédomine chez l'homme dans sa forme symptomatique ; pic de présentation entre 60 et 75 ans chez l'homme et entre 70 et 80 ans chez la femme ; prévalence clinique 1–5 % après 60 ans, 10–15 % en incluant les formes asymptomatiques (2 à 4 formes infracliniques pour un cas clinique).","src":"p. 167-168","deep":"**Pourquoi** : l'AOMI clinique est la partie visible : 2 à 4 formes infracliniques pour 1 clinique, d'où le dépistage ciblé ; elle prédomine chez l'homme dans sa forme symptomatique (p. 167-168).\n**À relier** : pic à 60-75 ans chez l'homme, 70-80 ans chez la femme ; prévalence 1-5 % après 60 ans, 10-15 % avec les formes asymptomatiques.\n**Piège** : 3e localisation de l'athérosclérose (pas la 1re)."},{"id":"225-qcm-504","type":"QRM","rank":"A","objective":"225-obj-03","tags":["classification","Leriche-Fontaine","Rutherford"],"difficulty":3,"stem":"Quelles correspondances entre les classifications de Leriche-Fontaine et de Rutherford de l'AOMI sont exactes ?","options":[{"t":"Stade III de Leriche-Fontaine ↔ grade II (catégorie 4) de Rutherford","ok":true,"why":"Douleur ischémique de repos = stade III de Leriche-Fontaine = grade II, catégorie 4 de Rutherford (tableau 7.1, p. 168)."},{"t":"Stade II de Leriche-Fontaine ↔ grade I (catégories 1 à 3) de Rutherford","ok":true,"why":"Claudication intermittente (stade II) = grade I de Rutherford, découpé en catégories 1, 2, 3 (légère, modérée, sévère) (tableau 7.1, p. 168)."},{"t":"La catégorie 4 de Rutherford correspond à une perte de substance majeure.","ok":false,"why":"Catégorie 4 = douleur ischémique de repos ; la perte de substance faible ou majeure relève du grade III (tableau 7.1, p. 168)."},{"t":"Le stade I de Leriche-Fontaine correspond à la claudication intermittente.","ok":false,"why":"Stade I = asymptomatique (grade 0 de Rutherford) ; la claudication est le stade II (p. 168)."},{"t":"Stade IV de Leriche-Fontaine ↔ grade III de Rutherford","ok":true,"why":"Ulcération ou gangrène (stade IV) = grade III de Rutherford (perte de substance faible ou majeure) (p. 168) ; stades III + IV = ischémie permanente (p. 169)."}],"explanation":"Leriche-Fontaine I/II/III/IV (asymptomatique, claudication, douleur de repos, ulcération ou gangrène) correspond à Rutherford grade 0 / I (catégories 1-3) / II (catégorie 4) / III (perte de substance faible ou majeure).","src":"p. 168-170","deep":"**Pourquoi** : Leriche-Fontaine I (asymptomatique), II (claudication), III (douleur de repos), IV (ulcération/gangrène) correspondent à Rutherford grade 0, I (cat. 1-3 : claudication légère à sévère), II (cat. 4 : douleur de repos), III (perte de substance faible ou majeure) (tableau 7.1, p. 168).\n**À relier** : Rutherford est le plus souvent utilisé de nos jours.\n**Piège** : le stade I n'est pas la claudication ; la catégorie 4 est la douleur de repos."},{"id":"225-qcm-505","type":"QRM","rank":"A","objective":"225-obj-04","tags":["examen clinique","AOMI"],"difficulty":1,"stem":"Concernant l'examen physique d'un patient suspect d'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'absence isolée d'un pouls pédieux suffit à affirmer l'AOMI.","ok":false,"why":"Le pouls pédieux peut manquer de façon congénitale chez 5 % de la population (p. 170) : l'IPS est indispensable pour conclure."},{"t":"Il comprend une palpation abdominale et poplitée à la recherche d'un anévrisme.","ok":true,"why":"La recherche d'anévrisme est systématique à l'abdomen et au creux poplité (p. 170) ; un anévrisme poplité est associé à un AAA dans 30 % des cas (p. 186)."},{"t":"Il est toujours bilatéral et comparatif.","ok":true,"why":"L'examen est systématiquement bilatéral et comparatif (p. 170), puis complété par l'IPS et un examen cardiovasculaire général (p. 170)."},{"t":"Le temps de recoloration cutanée est raccourci au niveau du pied en cas d'AOMI.","ok":false,"why":"Il est ALLONGÉ au pied et aux orteils ; la normale est < 3 secondes (p. 170)."},{"t":"La palpation des pouls se limite au pouls pédieux.","ok":false,"why":"On palpe fémoral, poplité, tibial postérieur et pédieux à la recherche d'un amortissement ou d'une abolition (p. 170)."}],"explanation":"Examen bilatéral et comparatif : inspection, palpation (froideur, pouls fémoral, poplité, tibial postérieur, pédieux, recoloration < 3 s), auscultation des trajets vasculaires, recherche d'anévrisme abdominal et poplité.","src":"p. 170-173","deep":"**Pourquoi** : l'examen est toujours bilatéral et comparatif ; un seul pouls absent ne suffit pas (pédieux absent de naissance chez 5 %) (p. 170).\n**À relier** : recoloration cutanée allongée (> 3 s), souffle, recherche d'anévrisme abdominal et poplité, puis IPS.\n**Piège** : « recoloration raccourcie » : c'est l'inverse."},{"id":"225-qcm-506","type":"QRM","rank":"A","objective":"225-obj-04","tags":["TcPO2","ischémie critique"],"difficulty":3,"stem":"Concernant la mesure de la pression transcutanée en oxygène (TcPO2), quelles propositions sont exactes ?","options":[{"t":"Une valeur > 35 mmHg traduit une hypoxie critique.","ok":false,"why":"> 35 mmHg = bonne compensation métabolique ; l'hypoxie critique est < 10 mmHg (p. 171)."},{"t":"Une valeur entre 10 et 35 mmHg témoigne d'une bonne compensation métabolique.","ok":false,"why":"Entre 10 et 35 mmHg, la TcPO2 traduit une hypoxie continue ; c'est une valeur supérieure à 35 mmHg qui témoigne d'une bonne compensation (p. 171)."},{"t":"Une valeur < 10 mmHg traduit une hypoxie critique.","ok":true,"why":"TcPO2 < 10 mmHg = preuve d'une hypoxie critique (p. 171) ; la normale au dos du pied dépasse 50 mmHg."},{"t":"À l'état basal, sans hyperémie, elle distingue une peau saine d'une peau ischémique.","ok":false,"why":"À l'état basal, la PO2 cutanée est très basse (3 à 4 mmHg), sans différence entre peau saine et ischémique : une hyperémie par la chaleur est nécessaire pour que l'examen soit discriminant (p. 171)."},{"t":"Elle guide le niveau d'une amputation.","ok":true,"why":"L'amputation doit passer en zone saine et bien oxygénée, d'où l'intérêt de la TcPO2 (p. 177)."}],"explanation":"TcPO2 mesurée après hyperémie (à l'état basal, 3 à 4 mmHg sans différence entre peau saine et ischémique) : normale > 50 mmHg au dos du pied, > 35 mmHg bonne compensation, 10–35 mmHg hypoxie continue, < 10 mmHg hypoxie critique ; utile dans l'ischémie critique et pour guider le niveau d'une amputation.","src":"p. 170-173, 175-178","deep":"**Pourquoi** : la TcPO2 de base est très basse (3-4 mmHg) sans différence entre peau saine et ischémique : on provoque une hyperémie par chaleur pour la rendre discriminante (p. 171).\n**À relier** : normale > 50 mmHg au dos du pied ; > 35 bonne compensation ; 10-35 hypoxie continue ; < 10 hypoxie critique ; guide aussi le niveau d'amputation.\n**Piège** : ne pas inverser > 35 et 10-35."},{"id":"225-qcm-507","type":"QRM","rank":"A","objective":"225-obj-03","tags":["diagnostic différentiel","ulcère"],"difficulty":2,"stem":"Devant un ulcère du membre inférieur, quels diagnostics différentiels de l'ulcère artériel sont cités ?","options":[{"t":"Ulcère « suspendu » de la face antérieure de la jambe","ok":false,"why":"L'ulcère artériel siège aux zones d'appui ou de frottement, parfois à la face antérieure de jambe (« suspendu ») (p. 169) : c'est l'AOMI elle-même."},{"t":"Syndrome régional douloureux complexe","ok":false,"why":"Il figure dans les différentiels de la douleur de DÉCUBITUS (avec neuropathie sensorielle, compression radiculaire) (p. 174)."},{"t":"Ulcère veineux","ok":true,"why":"Liste du Collège des ulcères non artériels : veineux, microcirculatoire, neuropathique, traumatique (p. 174)."},{"t":"Canal lombaire étroit","ok":false,"why":"Différentiel des douleurs à la MARCHE (douleur ou paresthésies d'effort cédant au repos) (p. 174)."},{"t":"Ulcère neuropathique","ok":true,"why":"Cité parmi les ulcères non artériels (p. 174) ; piège : la neuropathie peut aussi masquer une AOMI sévère (p. 169)."}],"explanation":"Diagnostics différentiels de l'ulcère artériel cités : ulcères veineux, microcirculatoire, neuropathique et traumatique. L'ulcère « suspendu » de face antérieure de jambe est une localisation de l'ulcère artériel ; le canal lombaire étroit (douleurs à la marche) et le syndrome régional douloureux complexe (douleurs de décubitus) relèvent d'autres listes de différentiels.","src":"p. 174","deep":"**Pourquoi** : devant un ulcère de jambe, on distingue l'ulcère artériel des ulcères veineux, microcirculatoires, neuropathiques et traumatiques (p. 174).\n**À relier** : ulcère artériel : zones d'appui/frottement, parfois face antérieure de jambe (« suspendu »), souvent très algique.\n**Piège** : ne pas piocher dans les listes des douleurs à la marche ou de décubitus (canal lombaire, algodystrophie)."},{"id":"225-qcm-508","type":"QRM","rank":"B","objective":"225-obj-05","tags":["traitement local","réadaptation"],"difficulty":2,"stem":"Concernant le traitement à visée locale de l'AOMI, quelles propositions sont exactes ?","options":[{"t":"La réadaptation est idéalement supervisée et associée à une éducation thérapeutique.","ok":true,"why":"La réadaptation supervisée donne de meilleurs résultats que le programme seul et est toujours complétée par l'éducation thérapeutique (p. 175)."},{"t":"Les prostaglandines sont possibles en ischémie critique non revascularisable.","ok":true,"why":"Perfusions quotidiennes pendant plusieurs semaines en milieu spécialisé, si ischémie critique non revascularisable (p. 176, rang B)."},{"t":"Une marche régulière de 30 à 45 minutes, au moins 3 fois par semaine, est recommandée.","ok":true,"why":"Au minimum 30-45 min, au moins 3 fois/semaine, en ralentissant ou s'arrêtant au seuil de la douleur (p. 175) : elle développe la collatéralité et le pool mitochondrial."},{"t":"Les traitements vasoactifs améliorent le pronostic vital.","ok":false,"why":"Ils n'ont aucun bénéfice pronostique à long terme ; plusieurs ont été retirés pour futilité ou déremboursés (p. 176, rang B)."},{"t":"Les traitements vasoactifs (ex. pentoxifylline) ont un bénéfice modeste sur le périmètre de marche.","ok":true,"why":"Ils améliorent modestement le périmètre de marche, sans effet sur l'évolution de la maladie (p. 176, rang B) ; la statine peut aussi allonger la marche."}],"explanation":"Traitement local : arrêt du tabac, marche régulière (idéalement réadaptation supervisée + ETP), vasoactifs à bénéfice modeste sans effet pronostique, prostaglandines en ischémie critique non revascularisable, revascularisation selon le stade.","src":"p. 175-178","deep":"**Pourquoi** : la marche régulière et l'arrêt du tabac favorisent les collatérales et le métabolisme musculaire : allongement de la distance de marche (p. 175).\n**À relier** : au minimum 30-45 min, ≥ 3 fois/semaine, au seuil de la douleur ; réadaptation supervisée + ETP ; prostaglandines si ischémie critique non revascularisable.\n**Piège** : les vasoactifs n'améliorent pas le pronostic."},{"id":"225-qcm-509","type":"QRM","rank":"B","objective":"225-obj-05","tags":["revascularisation","AOMI"],"difficulty":2,"stem":"Concernant la revascularisation dans l'AOMI, quelles propositions sont exactes ?","options":[{"t":"Les résultats de l'angioplastie sont d'autant plus favorables que les lésions sont courtes et proximales","ok":true,"why":"Résultats d'autant meilleurs que les lésions sont courtes et proximales ; occlusions longues : angioplastie sous-adventicielle possible (p. 176, rang B)."},{"t":"Elle est proposée à tout claudicant, quel que soit son périmètre de marche.","ok":false,"why":"Chez le claudicant, elle se discute si la claudication sévère altère la qualité de vie après traitement médical bien mené, ou d'emblée si PM < 100 m avec handicap et/ou atteinte aorto-iliaque sévère (p. 176)."},{"t":"Une bithérapie antiplaquettaire de 1 à 6 mois suit une angioplastie.","ok":true,"why":"Après angioplastie avec ou sans stent, 1 à 6 mois selon le geste et sa localisation (p. 176, rang B)."},{"t":"La revascularisation est proposée autant que possible en cas d'ischémie permanente","ok":true,"why":"En ischémie permanente, le pronostic du membre est engagé : revasculariser autant que possible, l'amputation n'intervenant qu'à défaut (p. 176-177)."},{"t":"Le pontage, de préférence avec du matériel veineux, est une option chirurgicale de revascularisation","ok":true,"why":"Pontage aorto-bi-iliaque (ou bifémoral), fémoropoplité ou fémorojambier ; une endartériectomie est parfois proposée, le plus souvent en association avec un pontage (p. 176)."}],"explanation":"Revascularisation proposée autant que possible en ischémie permanente, discutée si claudication invalidante (< 100 m) ; angioplastie (lésions courtes et proximales ; bithérapie antiplaquettaire 1-6 mois) ou pontage chirurgical selon l'étendue et la sévérité des lésions et l'état du patient ; surveillance clinique et écho-Doppler.","src":"p. 175-178","deep":"**Pourquoi** : la revascularisation est proposée autant que possible en ischémie permanente ; chez le claudicant, elle est discutée si handicap important (< 100 m), après traitement médical, ou atteinte aorto-iliaque sévère (p. 176).\n**À relier** : angioplastie ± stent (puis bithérapie antiplaquettaire 1-6 mois) ; pontage (veine de préférence) ; endartériectomie ; techniques hybrides.\n**Piège** : l'angioplastie réussit mieux sur lésions courtes et proximales."},{"id":"225-qcm-510","type":"QRM","rank":"A","objective":"225-obj-07","tags":["ischémie aiguë","physiopathologie"],"difficulty":2,"stem":"Concernant la physiopathologie de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Sa gravité dépend de la pression artérielle systémique.","ok":true,"why":"Premier des trois facteurs de gravité, d'où le maintien d'une PA correcte (remplissage si besoin) (p. 178, 182)."},{"t":"La nécrose cutanée apparaît vers la 24e heure.","ok":true,"why":"La nécrose cutanée débute à partir de la 24e heure, après les nerfs (2 h) et les muscles (6-8 h) (p. 178)."},{"t":"Sa gravité est d'autant plus grande que la collatéralité est abondante.","ok":false,"why":"Une collatéralité abondante limite au contraire la baisse de débit ; c'est son absence qui explique la sévérité de l'embolie sur artère saine (p. 178, 181)."},{"t":"Sa gravité dépend de la qualité du lit d'aval.","ok":true,"why":"Troisième facteur : qualité du réseau d'aval ; un lit jambier mauvais oriente vers la thrombolyse in situ si ischémie peu sévère (p. 178, 182)."},{"t":"L'occlusion de la bifurcation aortique donne typiquement une ischémie unilatérale modérée.","ok":false,"why":"Cas le plus grave : ischémie bilatérale sévère avec paralysie sensitivomotrice, signes généraux jusqu'au collapsus (p. 179)."}],"explanation":"La gravité dépend de la PA systémique, de la collatéralité et du lit d'aval ; nerfs souffrant dès 2 h, muscles dès 6–8 h, peau vers 24 h ; l'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère.","src":"p. 178-180","deep":"**Pourquoi** : la gravité de la baisse de débit dépend de la PA systémique, de l'abondance des collatérales et de la qualité du lit d'aval (p. 178).\n**À relier** : embolie sur artère saine = pas de collatérales = douleur brutale et sévère ; occlusion de la bifurcation aortique = ischémie bilatérale sévère, jusqu'au collapsus.\n**Piège** : plus de collatérales = moins grave, pas l'inverse."},{"id":"225-qcm-511","type":"QRM","rank":"B","objective":"225-obj-08","tags":["ischémie aiguë","thrombose in situ","étiologies"],"difficulty":3,"stem":"Parmi les causes suivantes, lesquelles sont citées comme causes de thrombose artérielle in situ ?","options":[{"t":"Tumeur de l'aorte","ok":false,"why":"Tumeurs, athérome, anévrisme et aortites de l'aorte sont des sources d'EMBOLIE (p. 181)."},{"t":"Endocardite infectieuse","ok":false,"why":"Source cardiaque d'embolie sur artère saine (p. 181)."},{"t":"Fibrillation atriale","ok":false,"why":"Première cause cardiaque d'embolie, parfois annoncée par des palpitations (p. 181)."},{"t":"Anévrisme poplité thrombosé","ok":true,"why":"Thrombose in situ sur artère malade, comme l'AOMI, les artériopathies non athéromateuses, la déshydratation du sujet âgé, le kyste adventiciel ou une cause iatrogène (TIH, cathétérisme) (p. 181)."},{"t":"Myxome de l'atrium","ok":false,"why":"Tumeur cardiaque emboligène (p. 181), donc embolie et non thrombose in situ."}],"explanation":"Thrombose in situ : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation du sujet âgé, kyste adventiciel, dissection, coagulopathies, causes iatrogènes (cathétérisme, TIH, ergotisme). Embolie : causes cardiaques (fibrillation atriale, endocardite, myxome…) et aortiques (athérome, anévrisme, aortites, tumeurs).","src":"p. 181-182","deep":"**Pourquoi** : thrombose in situ = artère déjà malade (AOMI, non athéromateuse, anévrisme poplité thrombosé), hémoconcentration/déshydratation du sujet âgé, kyste adventiciel, dissection, coagulopathie, iatrogène (cathétérisme, TIH, ergotisme) (p. 181).\n**À relier** : embolie = cœur (FA, endocardite, myxome...) ou aorte (athérome, anévrisme, tumeur).\n**Piège** : tout ce qui est cardiaque emboligène est une embolie."},{"id":"225-qcm-512","type":"QRM","rank":"B","objective":"225-obj-08","tags":["ischémie aiguë","embolie"],"difficulty":2,"stem":"Concernant l'ischémie aiguë par embolie sur artères saines, quelles propositions sont exactes ?","options":[{"t":"La source peut être aortique (athérome, anévrisme, aortite, tumeur).","ok":true,"why":"Sources aortiques d'embolie : athérome, anévrisme, aortites, tumeurs ; les autres sont cardiaques (FA en tête) (p. 181)."},{"t":"La douleur est brutale, aiguë et sévère du fait de l'absence de collatérales.","ok":true,"why":"Sur artère saine, aucune collatérale ne compense : douleur brutale, aiguë et sévère (p. 181)."},{"t":"Elle touche plutôt un sujet âgé ayant une AOMI connue.","ok":false,"why":"C'est le terrain de la thrombose in situ ; l'embolie survient classiquement chez un sujet plus jeune sans antécédent vasculaire connu (mais pouvant avoir une cardiopathie) (p. 181)."},{"t":"Elle est typiquement favorisée par une déshydratation ou une hémoconcentration.","ok":false,"why":"La déshydratation et l'hémoconcentration du sujet âgé sont des causes de thrombose in situ ; l'embolie peut être précédée de palpitations (arythmie) (p. 181)."},{"t":"L'installation est progressive grâce à une collatéralité préalable.","ok":false,"why":"Installation progressive avec douleur moyenne = thrombose in situ, grâce à une collatéralité préexistante (p. 181)."}],"explanation":"L'embolie sur artère saine survient classiquement chez un sujet plus jeune sans antécédent vasculaire (mais parfois cardiopathe), avec une douleur brutale et sévère faute de collatérales, parfois précédée de palpitations ; ses sources sont cardiaques (fibrillation atriale…) ou aortiques. Un terrain âgé artériopathe ou une déshydratation orientent vers une thrombose in situ.","src":"p. 181-182","deep":"**Pourquoi** : l'embole migre vers une artère saine sans collatérales : douleur brutale, aiguë et sévère, sujet plutôt jeune, parfois précédée de palpitations (p. 181).\n**À relier** : sources cardiaques ou aortiques ; recherche d'emboles multiples (autres localisations) ; anticoagulation au long cours si FA.\n**Piège** : sujet âgé artéritique avec déshydratation = thrombose in situ."},{"id":"225-qcm-513","type":"QRM","rank":"A","objective":"225-obj-09","tags":["ischémie aiguë","syndrome de revascularisation"],"difficulty":2,"stem":"Concernant la prise en charge des conséquences métaboliques et générales d'une ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Le membre est maintenu surélevé.","ok":false,"why":"Position légèrement déclive, protection mousse ou coton, sans frottement (p. 182)."},{"t":"Les CPK sont surveillées.","ok":true,"why":"Acidose hyperkaliémique et insuffisance rénale aiguë se dépistent par diurèse horaire, ionogramme, urée, créatininémie et CPK (p. 183)."},{"t":"La diurèse est surveillée par sonde urinaire.","ok":true,"why":"Sonde urinaire et diurèse horaire : la myoglobine et l'acidose exposent à la nécrose tubulaire aiguë (p. 178-179, 183)."},{"t":"L'acidose est corrigée par bicarbonates IV.","ok":true,"why":"Alcalinisation progressive par bicarbonates IV ; hyperkaliémie : chélateur (polystyrène sulfonate), voire dialyse, et lavage du membre (p. 183)."},{"t":"Le remplissage vasculaire est contre-indiqué.","ok":false,"why":"Au contraire, l'équilibration hémodynamique par remplissage macromoléculaire fait partie du traitement médical (p. 182)."}],"explanation":"Surveillance diurèse (sonde), ionogramme, urée, créatininémie, CPK ; bicarbonates IV, traitement de l'hyperkaliémie (chélateur, voire dialyse), lavage de membre ; position légèrement déclive ; correction hémodynamique.","src":"p. 182-183","deep":"**Pourquoi** : la reperfusion peut provoquer acidose hyperkaliémique et insuffisance rénale aiguë : on surveille diurèse (sonde), ionogramme, urée, créatinine, CPK (p. 183).\n**À relier** : bicarbonates IV, chélateur du potassium voire dialyse, lavage du membre ; remplissage si besoin.\n**Piège** : position légèrement déclive (pas surélevée) ; le remplissage n'est pas contre-indiqué."},{"id":"225-qcm-514","type":"QRM","rank":"B","objective":"225-obj-10","tags":["AAA","histoire naturelle"],"difficulty":3,"stem":"Concernant l'épidémiologie et l'histoire naturelle de l'anévrisme de l'aorte abdominale (AAA), quelles propositions sont exactes ?","options":[{"t":"Le tabagisme actif accélère la croissance d'environ 3 fois.","ok":true,"why":"Progression 3 fois plus rapide si le tabac est poursuivi pendant le suivi (p. 186)."},{"t":"La croissance moyenne est de 2 à 4 mm par an.","ok":true,"why":"En moyenne 2-4 mm/an, non linéaire, plus rapide chez l'homme fumeur et quand le diamètre est grand (p. 185)."},{"t":"Entre 75 et 84 ans, la prévalence de l'AAA est de 5 % chez l'homme et de 3 % chez la femme","ok":true,"why":"Environ 5 % chez l'homme et 3 % chez la femme dans cette tranche d'âge (p. 183)."},{"t":"Le risque de rupture est d'environ 0,4 %/an pour un diamètre de 50 à 59 mm.","ok":false,"why":"0,4 %/an concerne les AAA < 40 mm ; à 50-59 mm c'est 3 %/an, au-delà de 60 mm 15 %/an (p. 184)."},{"t":"Sa prévalence est en baisse dans les pays occidentaux.","ok":true,"why":"En baisse dans les populations occidentales : 2 à 5 % des hommes de plus de 65 ans (p. 183)."}],"explanation":"AAA : prévalence 2–5 % chez l'homme > 65 ans ; croissance 2–4 mm/an (× 3 si tabagisme actif) ; rupture ≈ 0,4 %/an si < 40 mm, 3 %/an à 50–59 mm, 15 %/an au-delà de 60 mm.","src":"p. 183-187","deep":"**Pourquoi** : AAA = prévalence en baisse (2-5 % chez l'homme > 65 ans ; 5 % chez l'homme et 3 % chez la femme à 75-84 ans), croissance moyenne 2-4 mm/an, ×3 si tabagisme (p. 183, 185-186).\n**À relier** : rupture : 0,4 %/an < 40 mm, 3 % à 50-59 mm, 15 % > 60 mm ; ×4 chez la femme.\n**Piège** : 0,4 %/an concerne les petits AAA (< 40 mm)."},{"id":"225-qru-501","type":"QRU","rank":"A","objective":"225-obj-10","tags":["anévrisme","physiopathologie"],"difficulty":2,"stem":"Quel mécanisme explique la perte de résistance de la paroi artérielle à la distension au cours d'un anévrisme ?","options":[{"t":"Occlusion embolique de la lumière artérielle","ok":false,"why":"Mécanisme de l'ischémie aiguë sur artère saine (p. 181), qui ne dilate pas la paroi."},{"t":"Destruction des fibres élastiques et fragmentation du collagène de la média sous l'effet d'enzymes comme les métalloprotéases","ok":true,"why":"La média perd sa résistance à la distension par destruction des fibres élastiques et fragmentation du collagène, favorisée par des enzymes (métalloprotéases) (p. 183)."},{"t":"Hyperplasie intimale sténosante","ok":false,"why":"Une lésion sténosante rétrécit la lumière (logique de l'AOMI), alors que l'anévrisme est une dilatation de plus de 50 % par atteinte de la média (p. 183)."},{"t":"Calcification isolée de la média (médiacalcose)","ok":false,"why":"La médiacalcose est une calcification de la média sans rétrécissement intraluminal, responsable d'une rigidité artérielle (IPS > 1,40) : ce n'est pas le mécanisme décrit de l'anévrisme (p. 171)."},{"t":"Spasme artériel prolongé","ok":false,"why":"Phénomène transitoire et rétrécissant, à l'opposé d'une dilatation focale et PERMANENTE (p. 183)."}],"explanation":"La média perd sa résistance à la distension par destruction des fibres élastiques et fragmentation du collagène, sous l'effet d'enzymes comme les métalloprotéases.","src":"p. 183-185","deep":"**Pourquoi** : la média perd sa capacité à résister à la distension quand les fibres élastiques sont détruites et le collagène fragmenté, sous l'effet d'enzymes (métalloprotéases) (p. 183).\n**À relier** : formes génétiques : maladies du tissu élastique (Marfan, Ehlers-Danlos) (p. 184, rang B).\n**Piège** : la médiacalcose rigidifie l'artère (IPS > 1,40), elle ne la dilate pas."},{"id":"225-qru-502","type":"QRU","rank":"B","objective":"225-obj-14","tags":["AAA","traitement endovasculaire"],"difficulty":3,"stem":"Un homme de 78 ans, à haut risque chirurgical (BPCO sévère, insuffisance cardiaque), a un AAA sous-rénal asymptomatique de 58 mm avec une anatomie favorable. Quelle prise en charge est la plus adaptée ?","options":[{"t":"Chirurgie à ciel ouvert, préférable chez le sujet à haut risque","ok":false,"why":"L'endoprothèse, moins invasive, est proposée aux sujets à haut risque chirurgical si l'anatomie est favorable (p. 186)."},{"t":"Artériographie pour mesurer le diamètre avant toute décision","ok":false,"why":"L'artériographie ne montre que la lumière artérielle : pas de mesure fiable du diamètre (thrombus mural) (p. 185)."},{"t":"Traitement médical seul, l'intervention étant réservée à la rupture","ok":false,"why":"Au-delà de 50-55 mm, le risque de rupture devient important : intervention « à froid » programmée, sans attendre la rupture (p. 186)."},{"t":"Surveillance échographique tous les 6 mois","ok":false,"why":"Ce rythme concerne les AAA de 45 mm jusqu'au seuil d'intervention (p. 185) ; à 58 mm le seuil est dépassé (p. 186)."},{"t":"Traitement endovasculaire par endoprothèse introduite par voie fémorale","ok":true,"why":"Endoprothèse introduite par voie fémorale, moins invasive, proposée au haut risque chirurgical si l'anatomie le permet ; surveillance des endofuites ensuite (p. 186)."}],"explanation":"Au-delà de 50-55 mm : intervention à froid, chirurgie ouverte ou endoprothèse ; l'endoprothèse, moins invasive, est proposée aux sujets à haut risque chirurgical si l'anatomie est favorable, avec surveillance des endofuites.","src":"p. 185-187","deep":"**Pourquoi** : 58 mm dépasse le seuil de 50-55 mm : intervention « à froid ». Haut risque chirurgical + anatomie favorable = endoprothèse par voie fémorale, moins invasive (p. 186).\n**À relier** : surveillance au long cours par scanner ou échographie de contraste (endofuites).\n**Piège** : l'artériographie ne mesure pas le diamètre ; surveillance seule n'est plus adaptée à 58 mm."},{"id":"225-qru-503","type":"QRU","rank":"B","objective":"225-obj-15","tags":["AAA","embolie","urgence"],"difficulty":2,"stem":"Un porteur d'AAA de 52 mm présente une ischémie aiguë du membre inférieur par embolie à partir du thrombus intra-anévrismal. Quelle est la priorité ?","options":[{"t":"Un antiplaquettaire seul avec réévaluation à 1 mois","ok":false,"why":"L'ischémie aiguë est une urgence vasculaire, pronostic du membre engagé (p. 178) : la revascularisation est la priorité."},{"t":"Une amputation d'emblée","ok":false,"why":"Elle se discute seulement si l'ischémie est dépassée (p. 183)."},{"t":"La revascularisation urgente du membre, la cure de l'AAA étant secondaire","ok":true,"why":"En cas d'embolie à partir d'un AAA, on revascularise d'abord le membre en urgence, la cure de l'AAA venant secondairement (p. 186, rang B)."},{"t":"Une surveillance échographique rapprochée de l'AAA","ok":false,"why":"La surveillance échographique concerne l'AAA asymptomatique (p. 185) ; ici l'ischémie aiguë impose une revascularisation urgente."},{"t":"La cure de l'AAA en urgence avant toute revascularisation du membre","ok":false,"why":"L'ordre est inverse : membre d'abord, cure de l'AAA secondairement (p. 186, rang B)."}],"explanation":"En cas d'ischémie aiguë de membre par embolie à partir d'un AAA, la revascularisation du membre est urgente, la cure de l'AAA étant secondaire.","src":"p. 185-187","deep":"**Pourquoi** : une embolie à partir d'un AAA donne une ischémie aiguë, urgence vasculaire : le membre prime (p. 186, rang B).\n**À relier** : puis cure de l'AAA de façon différée ; mêmes principes que l'ischémie aiguë (héparine, antalgiques, revascularisation).\n**Piège** : ne pas amputer d'emblée, sauf ischémie dépassée."},{"id":"225-qru-504","type":"QRU","rank":"A","objective":"225-obj-10","tags":["anévrisme poplité"],"difficulty":2,"stem":"Concernant l'anévrisme de l'artère poplitée, quelle proposition est exacte ?","options":[{"t":"Il ne se découvre jamais à la palpation.","ok":false,"why":"En phase asymptomatique, il se découvre souvent par une masse battante au creux poplité (pouls « trop bien perçu ») (p. 186)."},{"t":"Un anévrisme poplité controlatéral ne justifie aucun dépistage.","ok":false,"why":"Un AAA ou un AP controlatéral définissent un risque élevé justifiant un échodoppler (p. 186)."},{"t":"Il est associé à un AAA dans environ 30 % des cas et bilatéral dans près de la moitié des cas.","ok":true,"why":"AP associé à un AAA dans ≈ 30 % des cas et bilatéral dans près de la moitié (p. 186), d'où la palpation poplitée systématique (p. 170)."},{"t":"Son dépistage repose sur l'artériographie.","ok":false,"why":"Il repose sur la palpation et l'échodoppler (p. 186) ; l'artériographie est réservée aux revascularisations (p. 173)."},{"t":"Son diagnostic repose sur la mesure de l'index de pression systolique.","ok":false,"why":"L'IPS sert au diagnostic de l'AOMI ; l'anévrisme poplité est découvert par la palpation d'une masse battante au creux poplité ou par un écho-Doppler (p. 171, 186)."}],"explanation":"L'anévrisme poplité est associé à un AAA dans ≈ 30 % des cas, bilatéral une fois sur deux ; il est découvert par la palpation, par un écho-Doppler (dépistage si AAA ou AP controlatéral) ou devant une artériopathie ou une ischémie aiguë.","src":"p. 170, 186","deep":"**Pourquoi** : l'anévrisme poplité s'associe à l'AAA dans environ 30 % des cas et est bilatéral dans près de la moitié ; masse battante au creux poplité (pouls trop bien perçu) (p. 170, 186).\n**À relier** : échodoppler si AAA ou anévrisme poplité controlatéral ; peut se révéler par une artériopathie progressive ou une ischémie aiguë.\n**Piège** : le diagnostic ne passe pas par l'IPS ni l'artériographie."},{"id":"225-qru-505","type":"QRU","rank":"A","objective":"225-obj-16","tags":["athérome aortique","facteurs de risque"],"difficulty":1,"stem":"Quel facteur de risque est le plus associé à l'athérome aortique ?","options":[{"t":"L'hypertension artérielle","ok":false,"why":"Le Collège désigne le tabagisme comme le FdR le plus fortement associé aux plaques aortiques (p. 166) ; à l'inverse, l'athérome des artères rénales peut causer une HTA rénovasculaire."},{"t":"La sédentarité","ok":false,"why":"Parmi tous les FdR, c'est le tabagisme qui est le plus fortement associé à l'athérome aortique (p. 166)."},{"t":"Le tabagisme","ok":true,"why":"FdR le plus fortement associé aux plaques aortiques, présentes chez 25 % des hommes et 20 % des femmes de 40-55 ans (p. 166)."},{"t":"L'hypercholestérolémie","ok":false,"why":"Le FdR le plus associé à l'athérome aortique est le tabagisme (p. 166)."},{"t":"Le diabète","ok":false,"why":"Le Collège désigne le tabagisme, et non le diabète, comme le FdR le plus fortement associé aux plaques d'athérome aortiques (p. 166)."}],"explanation":"L'athérome aortique prédomine à la bifurcation et à l'origine des branches ; le tabagisme en est le facteur le plus associé ; il peut se compliquer d'embolies et marque un surrisque CV global.","src":"p. 166-167","deep":"**Pourquoi** : de tous les facteurs de risque, le tabagisme est le plus fortement associé aux plaques d'athérome aortiques (p. 166).\n**À relier** : sièges : bifurcation aortique et origine des branches ; embolies possibles ; marqueur de risque CV global.\n**Astuce** : tabac = FDR n°1 de l'athérome aortique.\n**Piège** : ces plaques sont le plus souvent asymptomatiques et découvertes fortuitement (calcifications en imagerie), mais leur présence et leur extension marquent un risque CV accru (p. 166)."},{"id":"225-qroc-501","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":2,"question":"Quelle est la prévalence de l'AOMI après 60 ans si l'on intègre les formes infracliniques ?","answer":"10 à 15 %","accept":["10-15 %","10 à 15 pour cent","10 à 15%","10-15%","entre 10 et 15 %"],"keywords":["10","15"],"explanation":"La prévalence clinique est de 1–5 % après 60 ans et atteint 10–15 % avec les formes infracliniques.","src":"p. 167-168","deep":"**Pourquoi** : pour chaque cas d'AOMI clinique, 2 à 4 patients ont une forme infraclinique : la forme clinique n'est que la partie visible (p. 168).\n**À relier** : forme clinique : 1-5 % après 60 ans ; dépistage ciblé des populations à risque.\n**Piège** : 1-5 % = clinique ; 10-15 % = avec les formes asymptomatiques."},{"id":"225-qroc-502","type":"QROC","rank":"A","objective":"225-obj-03","tags":["claudication"],"difficulty":1,"question":"En combien de temps la douleur de claudication intermittente cède-t-elle à l'arrêt de la marche ?","answer":"En moins de 5 minutes","accept":["< 5 minutes","moins de 5 min","< 5 min","5 minutes","en moins de 5 minutes"],"keywords":["minute"],"explanation":"La claudication est une crampe du mollet à la marche cédant en moins de 5 minutes à l'arrêt.","src":"p. 168-170","deep":"**Pourquoi** : la claudication traduit une hypoxie musculaire d'effort réversible : dès l'arrêt, le débit redevient suffisant et la douleur cède habituellement en moins de 5 minutes (p. 168).\n**À relier** : sévère si distance de marche < 100 m (p. 169) ; une douleur de repos signe l'ischémie permanente (p. 169).\n**Piège** : formes atypiques fréquentes (distances variables, cuisse, fesse, simple ralentissement du pas) (p. 169)."},{"id":"225-qroc-503","type":"QROC","rank":"A","objective":"225-obj-03","tags":["ischémie critique"],"difficulty":2,"question":"Quelle pression d'hallux définit l'ischémie critique ?","answer":"Moins de 30 mmHg","accept":["< 30 mmHg","inférieure à 30 mmHg","30 mmHg","moins de 30","<30"],"keywords":["30"],"explanation":"L'ischémie critique est définie par une pression de cheville < 50 mmHg ou une pression d'hallux < 30 mmHg.","src":"p. 168-170","deep":"**Pourquoi** : la pression d'hallux < 30 mmHg traduit l'effondrement de la perfusion distale (ischémie critique) (p. 169).\n**À relier** : cheville < 50 mmHg ; TcPO2 < 10 mmHg ; douleurs > 15 jours.\n**Astuce** : 50 cheville / 30 orteil.\n**Piège** : 30 mmHg = hallux/orteil ; 50 mmHg = cheville (p. 169)."},{"id":"225-qroc-504","type":"QROC","rank":"A","objective":"225-obj-04","tags":["index de pression d'orteil","médiacalcose"],"difficulty":3,"question":"En dessous de quelle valeur l'index de pression d'orteil est-il pathologique ?","answer":"Inférieur à 0,70","accept":["< 0,70","0,70","0,7","moins de 0,70","inférieur à 0,7","<0,7"],"keywords":["0,7"],"explanation":"En cas de médiacalcose (IPS > 1,40), l'IPS est remplacé par l'index de pression d'orteil, pathologique si < 0,70.","src":"p. 170-173","deep":"**Pourquoi** : en cas de médiacalcose (IPS > 1,40), la cheville est non interprétable ; on utilise la pression d'orteil, avec un manchon adapté (p. 171).\n**À relier** : pression d'orteil < 30 mmHg = ischémie critique ; surtout chez diabétique, insuffisant rénal, très âgé.\n**Piège** : seuil de l'index d'orteil (0,70) ≠ seuil de pression (30 mmHg)."},{"id":"225-qroc-505","type":"QROC","rank":"A","objective":"225-obj-04","tags":["TcPO2"],"difficulty":3,"question":"En dessous de quelle valeur de TcPO2 parle-t-on d'hypoxie critique ?","answer":"Moins de 10 mmHg","accept":["< 10 mmHg","10 mmHg","10","inférieure à 10 mmHg","moins de 10","<10"],"keywords":["10"],"explanation":"TcPO2 : > 50 mmHg normale, > 35 mmHg bonne compensation, 10–35 mmHg hypoxie continue, < 10 mmHg hypoxie critique.","src":"p. 170-173","deep":"**Pourquoi** : TcPO2 sous hyperémie : > 50 normale (dos du pied), > 35 bonne compensation, 10-35 hypoxie continue, < 10 hypoxie critique (p. 171).\n**À relier** : utile pour l'ischémie critique et pour choisir le niveau d'amputation.\n**Piège** : au repos sans hyperémie, 3-4 mmHg partout (non discriminant)."},{"id":"225-qroc-506","type":"QROC","rank":"A","objective":"225-obj-05","tags":["réentraînement","traitement"],"difficulty":2,"question":"Pendant combien de temps est proposé le réentraînement à raison de 3 séances par semaine dans l'AOMI ?","answer":"12 semaines","accept":["12 sem","douze semaines","3 mois","12"],"keywords":["12","semaine"],"explanation":"Le traitement à visée générale comprend un réentraînement 3 fois par semaine pendant 12 semaines.","src":"p. 175-178","deep":"**Pourquoi** : la marche régulière développe la circulation collatérale et le pool mitochondrial musculaire, d'où l'allongement de la distance de marche ; la cible est 3 séances/semaine pendant 12 semaines (p. 175).\n**À relier** : marche 30-45 min, ≥ 3 fois/semaine, au seuil de la douleur ; réadaptation supervisée préférée, avec éducation thérapeutique (p. 175).\n**Astuce** : 3 × / semaine × 12 semaines.\n**Piège** : 12 semaines (pas 4) ; chaque séance = marche d'au moins 30-45 min (p. 175)."},{"id":"225-qroc-507","type":"QROC","rank":"A","objective":"225-obj-07","tags":["ischémie aiguë","chronologie"],"difficulty":1,"question":"Vers quelle heure apparaît la nécrose cutanée au cours d'une ischémie aiguë de membre ?","answer":"Vers la 24e heure","accept":["24 heures","24 h","24e heure","24","à partir de la 24e heure"],"keywords":["24"],"explanation":"Souffrance nerveuse dès 2 h, musculaire dès 6–8 h, nécrose cutanée vers la 24e heure.","src":"p. 178-180","deep":"**Pourquoi** : la nécrose cutanée est tardive, vers la 24e heure ; nerf (2 h) puis muscle (6-8 h) souffrent avant (p. 178).\n**À relier** : au-delà de ce délai, revascularisation tardive : aponévrotomie de décompression, voire amputation si dépassée.\n**Astuce** : 2 – 6/8 – 24.\n**Piège** : la nécrose cutanée est le signe le plus tardif (24 h), après la souffrance nerveuse (2 h) et musculaire (6-8 h) (p. 178)."},{"id":"225-qroc-508","type":"QROC","rank":"A","objective":"225-obj-09","tags":["aponévrotomie","syndrome des loges"],"difficulty":3,"question":"Quelle loge est habituellement concernée par l'aponévrotomie de décompression après revascularisation tardive d'une ischémie aiguë ?","answer":"La loge antéro-externe de jambe","accept":["loge antéro-externe","loge antérolatérale de jambe","antéro-externe","loge antéro-externe de la jambe","loge antérieure et externe de la jambe"],"keywords":["antero","externe"],"explanation":"Après une revascularisation tardive, le geste est généralement complété par une aponévrotomie de décompression, le plus souvent de la loge antéro-externe de jambe.","src":"p. 182-183","deep":"**Pourquoi** : après revascularisation tardive, l'œdème comprime les muscles dans leurs loges inextensibles (syndrome des loges) ; la décompression préventive se fait en général sur la loge antéro-externe de jambe (p. 183).\n**À relier** : d'autres régions (pied) si besoin.\n**Piège** : l'aponévrotomie prévient le syndrome des loges mais ne revascularise pas ; elle complète « généralement » une revascularisation tardive (p. 183)."},{"id":"225-qroc-509","type":"QROC","rank":"B","objective":"225-obj-14","tags":["AAA","suivi"],"difficulty":3,"question":"Quelle complication l'écho-Doppler de surveillance recherche-t-il après chirurgie conventionnelle d'un AAA ?","answer":"Faux anévrisme anastomotique","accept":["faux anévrisme","faux anévrisme de l'anastomose","faux anévrismes","faux anévrisme des anastomoses","faux anévrisme anastomotique"],"keywords":["faux","anastomo"],"explanation":"Après chirurgie conventionnelle : surveillance écho-Doppler (faux anévrisme anastomotique, thrombose exceptionnelle) ; après endoprothèse : recherche d'endofuites.","src":"p. 185-187","deep":"**Pourquoi** : sur prothèse chirurgicale, les anastomoses peuvent se dégrader : faux anévrisme anastomotique ; la thrombose est exceptionnelle (p. 186).\n**À relier** : endoprothèse = endofuites (scanner ou échographie de contraste).\n**Piège** : ne pas confondre les deux surveillances."},{"id":"225-qroc-510","type":"QROC","rank":"A","objective":"225-obj-12","tags":["AAA","fistule"],"difficulty":2,"question":"Quelle manifestation révèle une fistule aorto-digestive compliquant un AAA ?","answer":"Une hémorragie digestive","accept":["hémorragie digestive","saignement digestif","hémorragie digestive massive","hématémèse"],"keywords":["hemorragie","digestive"],"explanation":"Une fistule aorto-cave donne une insuffisance cardiaque à débit élevé ; une fistule aorto-digestive, une hémorragie digestive.","src":"p. 183-185","deep":"**Pourquoi** : la fissuration d'un AAA dans un organe voisin est beaucoup plus rare que la rupture ; dans le tube digestif (fistule aorto-digestive), elle se révèle par une hémorragie digestive (p. 184).\n**À relier** : fistule aorto-cave = insuffisance cardiaque à débit élevé (p. 184).\n**Piège** : ne pas inverser les deux fistules."},{"id":"225-qroc-601","type":"QROC","rank":"A","objective":"225-obj-16","tags":["définition","étiologie"],"difficulty":1,"question":"Quels sont les deux mécanismes possibles de l'occlusion artérielle responsable d'une ischémie mésentérique aiguë ?","answer":"Thrombose in situ ou embolie","accept":["thrombose et embolie","embolie et thrombose","thrombose in situ ou embolie","embolie ou thrombose","thrombose ou embolie","embolie ou thrombose in situ","thrombose in situ et embolie","thrombose, embolie"],"keywords":["thromb","embol"],"explanation":"L'ischémie mésentérique aiguë est une interruption brutale de la perfusion d'une partie de l'intestin par occlusion d'une ou plusieurs artères digestives, par thrombose in situ ou par embolie. L'infarctus reste rare grâce aux nombreuses collatérales, mais c'est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge.","src":"p. 167","deep":"**Pourquoi** : l'ischémie mésentérique aiguë est une coupure brutale de la perfusion d'une partie de l'intestin par occlusion d'une ou plusieurs artères digestives ; l'occlusion naît soit d'un thrombus formé sur place, soit d'un embole venu d'ailleurs (p. 167).\n**Piège** : l'infarctus digestif reste rare grâce aux nombreuses collatérales, mais c'est une urgence vitale : le pronostic dépend de la rapidité de la prise en charge (p. 167).\n**À relier** : une fibrillation atriale ou des embolies dans d'autres territoires orientent vers l'embolie (p. 167) ; même opposition thrombose in situ / embolie dans l'ischémie aiguë de membre (rang B, p. 181)."},{"id":"225-qroc-602","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","pièges"],"difficulty":2,"question":"Dans le tableau classique d'ischémie mésentérique aiguë, quelle caractéristique de l'examen physique abdominal accompagne la douleur abdominale aiguë ?","answer":"Une paucité de signes physiques","accept":["paucité","pauvre","pauvreté","peu de signes","paucité de signes physiques","peu de signes physiques","examen pauvre","abdomen pauvre","pauvreté de signes physiques"],"keywords":["pauc"],"explanation":"Le tableau classique associe une douleur abdominale aiguë avec peu de signes physiques, une vidange digestive accélérée (vomissements et/ou diarrhée) et des indices de cause embolique, notamment une fibrillation atriale.","src":"p. 167","deep":"**Pourquoi** : le tableau typique (occlusion de l'artère mésentérique) est une triade : douleur abdominale aiguë contrastant avec un examen physique pauvre, vidange digestive accélérée (vomissements et/ou diarrhée), indices d'embolie, surtout une FA (p. 167).\n**Piège** : un abdomen peu parlant ne rassure pas : ce décalage douleur/examen est justement le signe d'alerte ; les formes plus frustes expliquent des errances diagnostiques (p. 167).\n**À relier** : des signes d'embolie dans d'autres territoires renforcent l'hypothèse embolique ; urgence vitale, pronostic lié à la rapidité de la prise en charge (p. 167)."},{"id":"225-qroc-603","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans l'ischémie mésentérique chronique, quel signe physique éventuel évoque une sténose artérielle viscérale ?","answer":"Un souffle abdominal","accept":["souffle abdominal","souffle","souffle épigastrique","souffle sur le trajet vasculaire"],"keywords":["souffle"],"explanation":"L'ischémie mésentérique chronique se manifeste par un angor digestif : douleurs abdominales après les repas, et dans les formes graves amaigrissement parce que le patient limite ses repas. Le seul signe physique éventuel est un souffle abdominal, qui évoque une sténose d'artère viscérale.","src":"p. 166","deep":"**Pourquoi** : la sténose d'une artère digestive (tronc cœliaque, mésentériques) crée un flux turbulent audible : le souffle abdominal est le seul signe physique éventuel de l'ischémie mésentérique chronique (p. 166).\n**Piège** : l'amaigrissement des formes graves s'explique par la restriction des repas : le patient mange moins pour éviter l'angor digestif post-prandial, d'où l'altération de l'état général (p. 166).\n**À relier** : sténoses digestives souvent asymptomatiques, associées à d'autres atteintes athéromateuses (p. 166) ; diagnostic par échodoppler des artères digestives, angioscanner ou angio-IRM (rang B, p. 166)."},{"id":"225-qroc-604","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie","diagnostic"],"difficulty":2,"question":"Pour chaque cas d'AOMI clinique, combien de patients (fourchette) présentent une forme infraclinique ?","answer":"2 à 4","accept":["2 à 4","2-4","deux à quatre","2 et 4","entre 2 et 4","2 à 4 patients"],"keywords":["2","4"],"explanation":"L'AOMI clinique n'est que la partie visible : chaque cas clinique s'accompagne de deux à quatre formes infracliniques. Cela souligne l'intérêt du dépistage des formes infracliniques pour mieux prévenir la maladie.","src":"p. 168","deep":"**Pourquoi** : l'AOMI reste longtemps muette (retentissement hémodynamique modéré, collatérales qui se développent progressivement), d'où 2 à 4 formes infracliniques pour 1 forme clinique (p. 168).\n**Piège** : ne pas confondre les chiffres : prévalence des formes cliniques 1-5 % après 60 ans, jusqu'à 10-15 % en incluant les asymptomatiques ; incidence 2-5 ‰ (p. 168).\n**À relier** : d'où l'intérêt du dépistage des formes infracliniques (p. 168) ; distinguer l'AOMI « masquée » (sujet très âgé qui ne marche plus, neuropathie) de la forme vraiment asymptomatique (p. 169)."},{"id":"225-qroc-605","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie","épidémiologie"],"difficulty":2,"question":"Quelle proportion des atteintes artérielles oblitérantes des membres inférieurs est d'origine athéromateuse ?","answer":"Plus de 95 %","accept":["plus de 95 %","95 %","> 95 %","plus de 95%","95%"],"keywords":["95"],"explanation":"L'AOMI est synonyme d'atteinte athéromateuse des membres inférieurs et représente plus de 95 % des atteintes artérielles oblitérantes. Les artériopathies non athéromateuses (inflammatoires, postradiques, post-traumatiques, toxiques, dysplasie fibromusculaire, etc.) sont minoritaires.","src":"p. 174","deep":"**Pourquoi** : l'AOMI est par définition l'atteinte athéromateuse des artères des membres inférieurs et couvre plus de 95 % des artériopathies oblitérantes de ce territoire (p. 174).\n**Piège** : les causes non athéromateuses sont rares mais à évoquer : inflammatoires (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation (hypodébit d'aval), causes radiques, traumatiques, toxiques (ergot de seigle), gelures, compressions, artère poplitée piégée (p. 174).\n**À relier** : même logique pour l'AAA : athérome dans 80-90 % des cas, sinon maladies du tissu élastique ou aortite (rang B, p. 184)."},{"id":"225-qroc-606","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Dans quel type de zones siègent le plus souvent les ulcères artériels de l'ischémie permanente ?","answer":"Zones de frottement ou d'appui (orteils, bord externe du pied, talon)","accept":["frottement","appui","orteil","talon","bord externe du pied","zones d'appui","zones de frottement","orteils","zones d'appui ou de frottement"],"keywords":["appui","frottement"],"explanation":"Les ulcères siègent surtout aux zones de frottement ou d'appui (orteil, dos et bord externe du pied, talon), parfois à la face antérieure de la jambe (ulcère « suspendu »). Ils surviennent spontanément ou après un traumatisme minime et peuvent creuser jusqu'à l'aponévrose ou l'os.","src":"p. 169","deep":"**Pourquoi** : les ulcères artériels de l'ischémie permanente (stade IV) siègent surtout là où la peau ischémique subit frottement ou appui : orteil, dos et bord externe du pied, talon (p. 169).\n**Piège** : localisation atypique possible à la face antérieure de jambe (ulcère « suspendu ») ; un traumatisme minime (geste de pédicure agressif) suffit à les déclencher ; souvent petits mais creusants jusqu'à l'aponévrose ou l'os (p. 169).\n**À relier** : portes d'entrée d'infection (cellulite, arthrite, ostéite, voire septicémie) ; gangrène plus fréquente chez le diabétique (p. 169) ; diagnostics différentiels : ulcère veineux, microcirculatoire, neuropathique, traumatique (p. 174)."},{"id":"225-qroc-607","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Dans l'ischémie permanente, quelle position améliore les douleurs de décubitus ?","answer":"La position déclive (jambe pendante au bord du lit)","accept":["position déclive","déclive","jambe pendante","jambes pendantes","pendante","jambe au bord du lit","assis jambes pendantes","jambe pendante hors du lit","jambes pendantes au bord du lit"],"keywords":["declive"],"explanation":"Les douleurs de décubitus (brûlures des orteils et de l'avant-pied) apparaissent après quelques minutes à quelques heures de décubitus. Elles s'améliorent en position déclive, ce qui oblige le patient à laisser la jambe pendante au bord du lit, voire à se lever plusieurs fois la nuit.","src":"p. 169","deep":"**Pourquoi** : les douleurs de décubitus (stade III : brûlures des orteils et de l'avant-pied) apparaissent après minutes ou heures allongé et sont soulagées jambe pendante : le patient dort jambe hors du lit ou se lève la nuit (p. 169).\n**Piège** : cette position déclive prolongée entraîne un œdème de déclivité, lui-même source de complications trophiques (p. 169).\n**À relier** : ischémie permanente = stades III-IV, douleurs > 15 jours résistant aux antalgiques usuels ; avec pression de cheville < 50 mmHg ou d'orteil < 30 mmHg = ischémie critique, pronostic du membre engagé (p. 169)."},{"id":"225-qroc-608","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quel diagnostic différentiel neurologique donne des douleurs ou des paresthésies du mollet ou du pied à l'effort, cédant au repos ?","answer":"Un canal lombaire étroit","accept":["canal lombaire étroit","canal lombaire","sténose du canal lombaire","canal lombaire rétréci"],"keywords":["canal lombaire"],"explanation":"Chez le sujet âgé, plusieurs causes de douleur à la marche peuvent coexister avec l'AOMI : neurologiques (canal lombaire étroit, sciatalgie, atteinte médullaire), rhumatologiques, veineuses ou musculaires.","src":"p. 174","deep":"**Pourquoi** : le canal lombaire étroit donne douleurs ou paresthésies du mollet ou du pied à l'effort, cédant au repos : il imite la claudication artérielle (p. 174).\n**Piège** : chez le sujet âgé plusieurs causes coexistent souvent ; l'atteinte médullaire donne, elle, une parésie sans douleur avec dérobement des jambes (p. 174).\n**À relier** : pour trancher : une chute de la pression de cheville > 30 mmHg et/ou de l'IPS > 20 % juste après un test de marche sur tapis évoque l'AOMI (p. 171)."},{"id":"225-qroc-609","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle classe médicamenteuse peut provoquer des douleurs musculaires mimant un tableau d'AOMI ?","answer":"Les statines","accept":["statines","statine","les statines"],"keywords":["statine"],"explanation":"Les douleurs musculaires sous statines peuvent parfois mimer une AOMI, mais attention aux tableaux intriqués : les deux diagnostics peuvent coexister.","src":"p. 174","deep":"**Pourquoi** : les myalgies sous statine peuvent simuler une douleur de jambe à l'effort et faire suspecter une AOMI (p. 174).\n**Piège** : les tableaux peuvent être intriqués : l'AOMI et les myalgies coexistent chez un même patient, l'un n'exclut pas l'autre (p. 174).\n**À relier** : la statine reste systématique dans l'AOMI (LDL < 0,55 g/L et baisse d'au moins 50 %, p. 175) et peut même allonger le périmètre de marche (p. 176)."},{"id":"225-qroc-610","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Comment calcule-t-on l'index de pression systolique (IPS) d'un membre ?","answer":"PAS de cheville / PAS du bras (valeurs les plus élevées)","accept":["pression systolique de cheville sur pression systolique du bras","pas cheville sur pas bras","pas cheville pas bras","cheville sur bras","cheville bras","pression cheville pression bras","PAS cheville / PAS bras","rapport cheville bras","pression cheville divisée par pression bras","pression de cheville sur pression brachiale","cheville/bras"],"keywords":["cheville","bras"],"explanation":"L'IPS est le rapport de la pression systolique de cheville (la plus élevée des deux artères, tibiale postérieure et pédieuse) sur la pression systolique la plus élevée des deux bras, mesurées au brassard et au doppler de poche. La cheville est au numérateur.","src":"p. 170-171","deep":"**Pourquoi** : pour chaque membre : pression systolique de cheville la plus haute (tibiale postérieure ou pédieuse, mesurées au doppler de poche) divisée par la pression systolique la plus haute des deux bras (p. 170-171).\n**Piège** : l'artère fibulaire n'est pas mesurée ; chez le diabétique, l'insuffisant rénal ou le très âgé l'IPS de repos peut être faussé (> 1,40 = médiacalcose) : on utilise la pression d'orteil (index d'orteil < 0,70 = AOMI) (p. 170-171).\n**À relier** : normal 1,00-1,40 ; AOMI si < 0,90 sur au moins une cheville ; sévère si < 0,70 ; si symptomatique avec IPS de repos normal : IPS après effort (p. 171)."},{"id":"225-qroc-611","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","pronostic"],"difficulty":2,"question":"En dehors du diagnostic d'AOMI, à quoi sert aussi l'IPS ?","answer":"Marqueur de risque cardiovasculaire","accept":["risque cardiovasculaire","marqueur de risque","risque cv","marqueur de risque cardiovasculaire","marqueur du risque CV","évaluer le risque cardiovasculaire","pronostic cardiovasculaire"],"keywords":["risque"],"explanation":"L'IPS est aussi un marqueur de risque cardiovasculaire : une valeur inférieure à 0,90 est associée à un risque élevé d'accident coronarien ou cérébral, fatal ou non.","src":"p. 171","deep":"**Pourquoi** : au-delà du diagnostic, un IPS < 0,90 s'associe à un risque élevé d'accident coronarien ou cérébral, fatal ou non : c'est un marqueur de risque cardiovasculaire (p. 171).\n**Piège** : en cas d'AOMI asymptomatique (IPS < 0,90 seul), l'antiplaquettaire est débattu, sauf autre atteinte athéromateuse associée (p. 175).\n**À relier** : à 5 ans, chez le claudicant : 20 % de complications cardiovasculaires et 20 % de décès, pour moitié cardiovasculaires (p. 177) ; d'où la recherche d'une atteinte coronarienne et carotidienne (p. 188)."},{"id":"225-qroc-612","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie","pièges"],"difficulty":1,"question":"Quelles deux vérifications préalables impose l'injection de produit de contraste iodé d'un angioscanner des artères des membres inférieurs ?","answer":"Les allergies et la fonction rénale","accept":["allergies et fonction rénale","allergie et fonction rénale","fonction rénale et allergies","fonction rénale et allergie","allergie et insuffisance rénale","allergie, fonction rénale","fonction rénale, allergies","créatinine et allergies"],"keywords":["allerg","renal"],"explanation":"L'angioscanner étudie le chenal circulant et la paroi, mais nécessite du produit de contraste iodé : on vérifie au préalable les allergies et la fonction rénale. L'angio-IRM évite l'irradiation, mais le gadolinium est contre-indiqué en cas d'insuffisance rénale sévère.","src":"p. 172-173","deep":"**Pourquoi** : l'angioscanner repose sur l'injection d'iode : on recherche au préalable une allergie et on contrôle la fonction rénale (p. 172).\n**Piège** : l'angio-IRM évite l'irradiation, mais le gadolinium est contre-indiqué si clairance < 30 mL/min/1,73 m² et elle ne montre pas les calcifications utiles au chirurgien avant pontage (p. 173).\n**À relier** : ces imageries ne sont demandées que s'il existe une indication de revascularisation ; en première intention, l'échodoppler suffit à localiser et quantifier les lésions (p. 172)."},{"id":"225-qroc-613","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quel est l'objectif du traitement à visée générale d'un patient atteint d'AOMI ?","answer":"Améliorer le pronostic cardiovasculaire et vital","accept":["pronostic cardiovasculaire","pronostic vital","risque cardiovasculaire","pronostic cardiovasculaire et vital","améliorer le pronostic","réduire le risque cardiovasculaire"],"keywords":["pronostic"],"explanation":"Le traitement à visée générale (contrôle des facteurs de risque, antiplaquettaire, statine, IEC) s'applique à tout stade et vise le pronostic cardiovasculaire et vital. Le traitement à visée locale vise, lui, les symptômes et le pronostic du membre.","src":"p. 175","deep":"**Pourquoi** : l'AOMI est un marqueur d'athérome diffus : le traitement général (contrôle des FDR, antiplaquettaire si symptomatique, statine, IEC) s'applique à tout stade pour réduire infarctus, AVC et décès (p. 175).\n**Piège** : il ne remplace pas le traitement local (symptômes, membre) : les deux sont complémentaires ; même revascularisé et asymptomatique, le patient garde ces mesures (p. 175, 178).\n**À relier** : cibles : PAS ≤ 120-129 et PAD ≤ 70-79 mmHg, HbA1c < 7 %, LDL < 0,55 g/L, arrêt du tabac, IMC 20-25 kg/m² (p. 175)."},{"id":"225-qroc-614","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quel est l'objectif du traitement à visée locale de l'AOMI ?","answer":"Traiter l'ischémie (symptômes) et améliorer le pronostic du membre","accept":["pronostic du membre","traiter l'ischémie","résoudre les symptômes","sauvetage du membre","améliorer le pronostic du membre"],"keywords":["membre"],"explanation":"Le traitement à visée locale cherche à résoudre les symptômes en traitant l'ischémie et à améliorer le pronostic du membre : arrêt du tabac et marche régulière, revascularisation (angioplastie, pontage), soins de plaies, amputation en dernier recours ; les vasoactifs n'apportent qu'un gain modeste du périmètre de marche sans bénéfice pronostique (rang B, p. 176). Le traitement à visée générale vise, lui, le pronostic cardiovasculaire et vital.","src":"p. 175-177","deep":"**Pourquoi** : le traitement local cherche à faire disparaître les symptômes en traitant l'ischémie et à préserver le membre : marche régulière et arrêt du tabac, revascularisation, soins de plaies, amputation en dernier recours (p. 175-177).\n**Piège** : la revascularisation se discute surtout en ischémie permanente ou en claudication sévère invalidante malgré un traitement médical bien mené (p. 176).\n**À relier** : l'amputation se fait en zone saine bien oxygénée (TcPO2), en préservant l'appui ou le genou pour l'appareillage (p. 177)."},{"id":"225-qroc-615","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle classe d'antihypertenseurs peut être considérée chez tout patient atteint d'AOMI, quel que soit son niveau de pression artérielle, en l'absence de contre-indication ?","answer":"Un IEC ou un sartan","accept":["iec","sartan","enzyme de conversion","ara2","ara ii","IEC ou sartan","inhibiteur de l'enzyme de conversion","ARA2","ARA II","IEC"],"keywords":["iec"],"explanation":"Un traitement par inhibiteur de l'enzyme de conversion (ou sartan) peut être considéré chez tous les patients avec AOMI, quel que soit leur niveau de pression artérielle, en l'absence de contre-indication ; les IEC ont un intérêt pronostique.","src":"p. 175","deep":"**Pourquoi** : les IEC ont un intérêt pronostique dans l'AOMI : un IEC ou un sartan peut être considéré chez tout artéritique, quel que soit son niveau tensionnel, sauf contre-indication (p. 175).\n**Piège** : deux chiffres coexistent dans le même chapitre : cible PAS ≤ 120-129 / PAD ≤ 70-79 mmHg et IEC maintenant la PA < 140/90 mmHg (p. 175).\n**À relier** : l'algorithme de la claudication associe statine + antiplaquettaire, avec IEC si HTA ou insuffisance cardiaque (fig. 7.6, p. 177)."},{"id":"225-qroc-616","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":3,"question":"Dans quelle situation de l'AOMI les bêtabloquants doivent-ils être utilisés avec prudence, même en cas d'indication formelle ?","answer":"En cas d'ischémie critique sans revascularisation possible","accept":["ischémie critique","ischémie critique non revascularisable","ischémie critique sans revascularisation possible"],"keywords":["critique"],"explanation":"Les bêtabloquants ne sont proposés qu'en cas d'indication formelle (cardiopathie ischémique, insuffisance cardiaque à fraction d'éjection altérée, certaines arythmies), avec prudence en cas d'ischémie critique sans revascularisation possible.","src":"p. 175","deep":"**Pourquoi** : les bêtabloquants ne sont pas contre-indiqués dans l'AOMI : on les donne s'il existe une indication formelle (cardiopathie ischémique, IC à FE altérée, certaines arythmies) (p. 175).\n**Piège** : la prudence porte sur une situation précise : l'ischémie critique sans revascularisation possible (p. 175).\n**À relier** : devant une ischémie critique non revascularisable, des prostaglandines IV peuvent être proposées en milieu spécialisé (rang B, p. 176) ; sinon l'amputation est à envisager (p. 177)."},{"id":"225-qroc-617","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","prévention"],"difficulty":1,"question":"Lors d'une séance de marche d'entraînement, à quel moment le patient claudicant doit-il ralentir le pas ou s'arrêter quelques minutes ?","answer":"Au seuil de la douleur","accept":["seuil de la douleur","au seuil de la douleur","seuil douloureux","dès que la douleur","au seuil douloureux","dès l'apparition de la douleur","quand la douleur apparaît"],"keywords":["seuil","douleur"],"explanation":"La marche régulière (au minimum 30-45 minutes, au moins 3 fois par semaine, de préférence supervisée) se fait en ralentissant le pas ou en s'arrêtant quelques minutes au seuil de la douleur.","src":"p. 175","deep":"**Pourquoi** : on marche jusqu'au seuil douloureux puis on ralentit ou s'arrête quelques minutes : cet effort répété stimule les collatérales et le métabolisme musculaire (p. 175).\n**Piège** : la réadaptation supervisée (centre ou ambulatoire) donne de meilleurs résultats que le programme fait seul, et elle s'accompagne d'une éducation thérapeutique (p. 175).\n**À relier** : au minimum 30-45 min, au moins 3 fois par semaine ; cible 3 fois/semaine pendant 12 semaines (p. 175) ; si périmètre < 100 m ou atteinte aorto-iliaque sévère, envisager la revascularisation (fig. 7.6, p. 177)."},{"id":"225-qroc-618","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","physiopathologie"],"difficulty":2,"question":"Quel mécanisme vasculaire l'arrêt du tabac et la marche régulière favorisent-ils dans l'AOMI ?","answer":"Le développement de la circulation collatérale","accept":["circulation collatérale","collatérale","collatéralité","collatérales","développement de collatérales","développement des collatérales"],"keywords":["collat"],"explanation":"L'arrêt du tabac et la marche régulière favorisent la circulation collatérale et l'état métabolique musculaire (augmentation du pool mitochondrial), ce qui allonge la distance de marche, voire fait disparaître la claudication.","src":"p. 175","deep":"**Pourquoi** : arrêt du tabac et marche régulière développent la circulation collatérale et améliorent le métabolisme musculaire (plus de mitochondries), d'où un allongement de la distance de marche, voire la disparition de la claudication (p. 175).\n**Piège** : si l'atteinte aorto-iliaque est sévère, le développement de collatérales est illusoire : la revascularisation peut alors se discuter d'emblée (p. 176).\n**À relier** : la collatéralité explique aussi qu'une AOMI reste longtemps asymptomatique et qu'une thrombose in situ soit moins brutale qu'une embolie (p. 168 ; rang B, p. 181)."},{"id":"225-qroc-619","type":"QROC","rank":"A","objective":"225-obj-06","tags":["complications","prévention"],"difficulty":1,"question":"Chez un patient porteur d'une AOMI ou d'un AAA, quelles deux autres localisations de l'athérome faut-il rechercher ?","answer":"Une maladie coronarienne et une sténose carotidienne","accept":["coronarienne et carotidienne","coronaire et carotide","coronaire, carotide","maladie coronarienne et sténose carotidienne","atteinte coronaire et cérébrovasculaire","coronarienne et cérébrovasculaire","coronaire et carotidienne","carotide et coronaire"],"keywords":["coron","carot"],"explanation":"Les autres atteintes athéromateuses sont très fréquentes chez l'artéritique et le porteur d'AAA : il faut rechercher une maladie coronarienne sous-jacente et une sténose carotidienne (atteinte cérébrovasculaire), dès l'interrogatoire et l'examen cardiovasculaire général.","src":"p. 170, 188","deep":"**Pourquoi** : l'athérome est une maladie diffuse : AOMI et AAA s'accompagnent souvent d'atteintes coronariennes et carotidiennes ; c'est une notion indispensable du chapitre (p. 170, 188).\n**Piège** : le porteur d'AAA risque 10 fois plus de mourir d'une autre cause cardiovasculaire (coronarienne, AVC) que de la rupture (p. 184).\n**À relier** : l'interrogatoire cherche angor et déficits neurologiques, et l'examen cardiovasculaire général est systématique (p. 169-170) ; même réflexe dans l'item 221 (polyathéromateux)."},{"id":"225-qroc-620","type":"QROC","rank":"A","objective":"225-obj-07","tags":["définition","urgence"],"difficulty":1,"question":"Comment définit-on l'ischémie aiguë d'un membre inférieur ?","answer":"Interruption brutale du flux artériel (hypoxie tissulaire abrupte)","accept":["interruption brutale","arrêt brutal du flux","interruption brutale du flux artériel","arrêt brutal du flux artériel","obstruction artérielle brutale","interruption brutale du flux sanguin","hypoxie tissulaire abrupte"],"keywords":["brutal"],"explanation":"C'est une interruption brutale du flux artériel responsable d'une hypoxie tissulaire abrupte pouvant aboutir à la nécrose. C'est une urgence vasculaire : le pronostic du membre, voire du patient, est engagé.","src":"p. 178","deep":"**Pourquoi** : un arrêt brutal du flux artériel prive les tissus d'oxygène sans temps d'adaptation : nerfs atteints en premier (≈ 2 h), muscles vers 6-8 h (rhabdomyolyse), nécrose cutanée à partir de la 24e heure (p. 178).\n**Piège** : la gravité dépend de trois facteurs : pression artérielle systémique (à maintenir), abondance des collatérales et qualité du réseau d'aval (p. 178).\n**À relier** : urgence vasculaire, pronostic du membre voire vital : diagnostic clinique, équipe chirurgicale alertée tôt, aucune exploration ne doit retarder l'intervention (p. 178, 180)."},{"id":"225-qroc-621","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","urgence"],"difficulty":2,"question":"Quel tableau réalise l'occlusion aiguë de la bifurcation aortique ?","answer":"Une ischémie bilatérale sévère avec paralysie sensitivomotrice","accept":["ischémie bilatérale sévère","ischémie bilatérale","ischémie des deux membres","ischémie des deux membres inférieurs","paralysie sensitivomotrice bilatérale"],"keywords":["bilat"],"explanation":"Dans le cas le plus grave, l'occlusion de la bifurcation aortique provoque une ischémie bilatérale sévère avec paralysie sensitivomotrice. Les signes généraux sont alors souvent au premier plan, jusqu'au collapsus cardiovasculaire.","src":"p. 179","deep":"**Pourquoi** : la bifurcation aortique alimente les deux membres : son occlusion donne une ischémie bilatérale sévère avec paralysie sensitivomotrice ; c'est la forme la plus grave (p. 179).\n**Piège** : les signes généraux dominent alors, jusqu'au collapsus cardiovasculaire : ne pas s'arrêter au choc sans examiner les membres (p. 179).\n**À relier** : le niveau d'occlusion s'estime par la limite de la froideur et l'abolition des pouls en aval ; un déficit moteur classe au moins en grade IIb, une paralysie avec anesthésie en grade III (p. 179)."},{"id":"225-qroc-622","type":"QROC","rank":"A","objective":"225-obj-09","tags":["imagerie","diagnostic"],"difficulty":2,"question":"En cas d'embolie, que peut révéler l'artériographie en plus de localiser l'oblitération ?","answer":"D'autres emboles asymptomatiques (homo- ou controlatéraux)","accept":["autres emboles","emboles asymptomatiques","emboles","emboles controlatéraux","emboles multiples","d'autres emboles"],"keywords":["embol"],"explanation":"L'artériographie, le plus souvent réalisée au bloc opératoire, localise l'oblitération, précise son aspect (athérome, anévrisme, dissection) et apprécie le réseau d'aval. En cas d'embolie, elle peut aussi révéler d'autres emboles asymptomatiques.","src":"p. 180","deep":"**Pourquoi** : l'artériographie, en général faite au bloc, localise l'oblitération, en précise l'aspect (athérome, anévrisme, dissection) et évalue le réseau d'aval ; dans l'embolie elle peut montrer d'autres emboles muets, du même côté ou controlatéraux (p. 180).\n**Piège** : elle sert à guider le geste, pas à poser le diagnostic : en atteinte neurologique (grade II), aucune exploration ne doit retarder l'intervention (p. 180).\n**À relier** : l'échodoppler n'est fait que s'il ne fait pas perdre de temps (grade I sans atteinte neurologique) ; la recherche d'autres localisations ischémiques (embolies multiples) fait partie du bilan (p. 180, 182)."},{"id":"225-qroc-623","type":"QROC","rank":"A","objective":"225-obj-09","tags":["diagnostic","pièges"],"difficulty":2,"question":"À quel moment réalise-t-on le bilan cardiaque étiologique (Holter ECG, ETT, voire ETO) d'une ischémie aiguë de membre ?","answer":"Après la revascularisation","accept":["après la revascularisation","après revascularisation","une fois revascularisé","une fois le membre revascularisé","après le geste","en différé"],"keywords":["apres","revascular"],"explanation":"Avant l'intervention, on se limite à l'examen clinique complété par l'auscultation cardiaque, l'ECG, la palpation abdominale et un bilan de coagulation. Holter ECG, ETT (voire ETO ou IRM) et bilan artériel complémentaire ne sont faits qu'après la revascularisation.","src":"p. 182","deep":"**Pourquoi** : la priorité est la revascularisation : avant le geste on se contente de l'examen, de l'auscultation cardiaque, de l'ECG (arythmie), de la palpation abdominale (anévrisme) et d'un bilan de coagulation (p. 182).\n**Piège** : Holter, ETT, voire ETO ou IRM, et bilan artériel (échodoppler, angioscanner, artériographie) viennent après : les faire avant retarderait le traitement (p. 182).\n**À relier** : le traitement étiologique suit : anticoagulation au long cours si FA ; si thrombose, antiplaquettaire et contrôle des FDR (p. 183)."},{"id":"225-qroc-624","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","complications"],"difficulty":2,"question":"Quel traitement compense progressivement l'acidose métabolique du syndrome de revascularisation ?","answer":"L'alcalinisation par bicarbonates IV","accept":["bicarbonate","alcalinisation","bicarbonates","bicarbonate de sodium","bicarbonates IV","perfusion de bicarbonates"],"keywords":["bicarbon"],"explanation":"Après revascularisation, on recherche systématiquement une acidose métabolique hyperkaliémique et une insuffisance rénale aiguë (diurèse horaire, ionogramme, urée, créatinine, CPK). L'acidose est compensée progressivement par des bicarbonates IV ; la kaliémie nécessite un chélateur du potassium, voire une dialyse.","src":"p. 183","deep":"**Pourquoi** : la reperfusion relargue acides et contenu des cellules lysées : acidose métabolique, hyperkaliémie, myoglobinurie ; l'acidose se corrige progressivement par bicarbonates IV (p. 178, 183).\n**Piège** : l'hyperkaliémie est traitée à part : chélateur du potassium (polystyrène sulfonate de sodium), voire dialyse, et lavage du membre au sérum physiologique (p. 183).\n**À relier** : surveillance systématique : diurèse horaire (sonde), ionogramme, urée, créatinine, CPK ; l'insuffisance rénale vient du choc, de la myoglobine et des produits de contraste (p. 178-179, 183)."},{"id":"225-qroc-625","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","pièges"],"difficulty":1,"question":"Quelle prise en charge peut être la seule solution chez un malade très âgé et moribond présentant une ischémie aiguë de membre ?","answer":"Une prise en charge palliative","accept":["palliative","soins palliatifs","prise en charge palliative"],"keywords":["palliat"],"explanation":"Il faut évaluer rapidement la fonction cardiaque, les comorbidités et l'état général (pathologie incurable ou fortement handicapante). Une prise en charge palliative est parfois la seule solution chez un malade très âgé et moribond.","src":"p. 182","deep":"**Pourquoi** : le terrain pèse dans la décision : on évalue vite la fonction cardiaque, les comorbidités et l'état général (pathologie incurable ou très handicapante) (p. 182).\n**Piège** : le palliatif n'est pas la règle chez le sujet âgé : il n'est parfois la seule option que chez le malade très âgé et moribond (p. 182).\n**À relier** : si l'ischémie est dépassée (grade III), une amputation d'emblée peut être envisagée, aussi pour limiter les désordres métaboliques de la revascularisation (p. 180, 183)."},{"id":"225-qroc-626","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","pièges"],"difficulty":2,"question":"Quelle erreur de prise en charge est qualifiée d'inacceptable devant une ischémie aiguë de membre ?","answer":"Retarder la prise en charge par des examens d'imagerie inutiles","accept":["retarder la prise en charge","retard de prise en charge","retarder l'intervention","examens inutiles","examens d'imagerie inutiles","retard de prise en charge par des examens inutiles","imagerie inutile retardant la prise en charge"],"keywords":["retard"],"explanation":"Le diagnostic d'ischémie aiguë est clinique : aucune exploration ne doit retarder l'intervention, notamment en cas d'atteinte neurologique (grade II), et l'équipe chirurgicale doit être alertée au plus tôt.","src":"p. 180, 188","deep":"**Pourquoi** : le diagnostic est clinique et chaque heure aggrave les lésions (nerfs, puis muscles) : l'équipe chirurgicale est alertée tôt et aucune exploration ne doit retarder l'intervention (p. 178, 180).\n**Piège** : l'échodoppler n'est acceptable que sans perte de temps (grade I, sans atteinte neurologique) ; l'artériographie se fait au bloc (p. 180).\n**À relier** : règle voisine pour l'AAA rompu : urgence absolue, diagnostic confirmé par le scanner avant la prise en charge (p. 188) ; héparine et antalgiques dès que possible (p. 180)."},{"id":"225-qroc-627","type":"QROC","rank":"A","objective":"225-obj-10","tags":["diagnostic","imagerie"],"difficulty":2,"question":"Quelles deux autres localisations anévrismales recherche-t-on, notamment à l'échographie, chez un patient porteur d'un AAA ?","answer":"Les artères poplitées et iliaques","accept":["poplitées et iliaques","iliaques et poplitées","poplitée et iliaque","iliaque et poplitée","artères poplitées et iliaques","poplité et iliaque"],"keywords":["poplit","iliaq"],"explanation":"L'échographie abdominale dépiste l'AAA, mesure son diamètre maximal et assure son suivi ; elle recherche aussi les localisations associées les plus fréquentes, poplitées et iliaques. Un anévrisme poplité est lui-même associé à un AAA dans environ 30 % des cas.","src":"p. 184, 186","deep":"**Pourquoi** : l'échographie abdominale dépiste l'AAA, mesure son diamètre maximal, assure le suivi et recherche les localisations associées les plus fréquentes, poplitées et iliaques (p. 184).\n**Piège** : à l'inverse, devant un anévrisme poplité, chercher un AAA (associé dans 30 % des cas) et un anévrisme poplité controlatéral (bilatéral près d'une fois sur deux) (p. 186).\n**À relier** : à l'examen de toute AOMI, la recherche d'un anévrisme abdominal et poplité est systématique (p. 170)."},{"id":"225-qroc-628","type":"QROC","rank":"A","objective":"225-obj-10","tags":["pronostic","épidémiologie"],"difficulty":2,"question":"Quel est le risque annuel de rupture d'un anévrisme de l'aorte sous-rénale de 50 à 59 mm de diamètre ?","answer":"Environ 3 % par an","accept":["3 %","3 % par an","3 pour cent","3%","environ 3 %","3 pour cent par an"],"keywords":["3"],"explanation":"Le risque de rupture augmente de façon exponentielle avec le diamètre : très faible (0,4 %/an) en dessous de 40 mm, 3 % entre 50 et 59 mm, 15 % au-delà de 60 mm. À diamètre égal, il est près de 4 fois plus élevé chez la femme.","src":"p. 184","deep":"**Pourquoi** : le risque de rupture croît de façon exponentielle avec le diamètre : 0,4 %/an sous 40 mm, 3 %/an à 50-59 mm, 15 %/an au-delà de 60 mm (p. 184).\n**Piège** : à diamètre égal, le risque est près de 4 fois plus élevé chez la femme (p. 184).\n**À relier** : seuil d'intervention : 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an selon l'item 221 (p. 42) ; « au-delà de 50-55 mm » selon l'item 225 (rang B, p. 186)."},{"id":"225-qroc-629","type":"QROC","rank":"A","objective":"225-obj-10","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel signe palpatoire fait évoquer un anévrisme de l'artère poplitée ?","answer":"Une masse battante au creux poplité (pouls « trop bien perçu »)","accept":["masse battante","battante","pouls trop bien perçu","trop bien perçu","masse pulsatile","masse battante au creux poplité"],"keywords":["battante"],"explanation":"L'anévrisme poplité asymptomatique est découvert à la palpation d'une masse battante au creux poplité (pouls « trop bien perçu »), à l'échodoppler (surtout si AAA ou anévrisme poplité controlatéral), ou au stade d'artériopathie progressive, voire d'ischémie aiguë.","src":"p. 186","deep":"**Pourquoi** : l'anévrisme poplité dilate l'artère au creux poplité : on palpe une masse battante, le pouls semble « trop bien perçu » (p. 186).\n**Piège** : il peut aussi se révéler par une artériopathie progressive ou une ischémie aiguë plutôt que par une masse (p. 186) ; l'anévrisme poplité thrombosé figure parmi les causes de thrombose in situ (rang B, p. 181).\n**À relier** : écho-doppler surtout si risque élevé (AAA, anévrisme poplité controlatéral) ; associé à un AAA dans 30 % des cas, bilatéral près d'une fois sur deux (p. 186)."},{"id":"225-qroc-630","type":"QROC","rank":"A","objective":"225-obj-10","tags":["épidémiologie","étiologie"],"difficulty":1,"question":"Quels sont les deux principaux facteurs de risque d'AAA, en dehors de l'âge ?","answer":"Le tabagisme et les antécédents familiaux d'anévrisme","accept":["tabagisme et antécédents familiaux","tabac et antécédents familiaux","antécédents familiaux et tabagisme","antécédents familiaux et tabac","tabagisme, antécédents familiaux","tabac et antécédents familiaux d'anévrisme","tabagisme et antécédents familiaux d'anévrisme"],"keywords":["taba","famil"],"explanation":"En dehors de l'âge, les principaux facteurs de risque d'AAA sont le tabagisme et les antécédents familiaux d'anévrisme. Les sujets ayant une autre localisation aortique (thoracique) ou artérielle périphérique sont à plus haut risque d'AAA, alors que les diabétiques sont moins souvent atteints.","src":"p. 183","deep":"**Pourquoi** : en dehors de l'âge, le tabagisme et les antécédents familiaux d'anévrisme sont les deux principaux facteurs de risque d'AAA (p. 183).\n**Piège** : le diabète, majeur dans l'AOMI, n'en fait pas partie : les diabétiques ont moins souvent un AAA (p. 183).\n**À relier** : une autre localisation aortique (thoracique) ou artérielle périphérique augmente le risque (p. 183) ; dépistage échographique chez l'homme > 65 ans (p. 184) ; poursuite du tabac = croissance 3 fois plus rapide (rang B, p. 186)."},{"id":"225-qroc-631","type":"QROC","rank":"A","objective":"225-obj-10","tags":["étiologie","pièges"],"difficulty":2,"question":"Quelle maladie métabolique est moins souvent retrouvée chez les patients porteurs d'un AAA, contrairement à l'AOMI ?","answer":"Le diabète","accept":["diabète","diabétique","diabétiques","le diabète","diabète de type 2"],"keywords":["diab"],"explanation":"En dehors de l'âge, les principaux facteurs de risque d'AAA sont le tabagisme et les antécédents familiaux d'anévrisme ; les diabétiques sont moins souvent atteints, à l'inverse de l'AOMI où le diabète est un facteur de risque majeur.","src":"p. 183","deep":"**Pourquoi** : les deux maladies sont athéromateuses mais leurs FDR diffèrent : diabète moins fréquent chez les porteurs d'AAA, alors que tabac et diabète sont les principaux FDR de l'AOMI (p. 183 ; rang B, p. 168).\n**Piège** : ne pas plaquer les FDR de l'AOMI sur l'AAA : pour l'AAA, retenir tabagisme et antécédents familiaux d'anévrisme (p. 183).\n**À relier** : dans l'AOMI, le diabète donne des formes graves d'emblée, plus distales, et masque les symptômes par la neuropathie (rang B, p. 168 ; p. 169)."},{"id":"225-qroc-632","type":"QROC","rank":"A","objective":"225-obj-10","tags":["épidémiologie","pronostic"],"difficulty":2,"question":"À diamètre égal, chez quel sexe le risque de rupture d'un AAA est-il le plus élevé ?","answer":"Chez la femme (près de 4 fois plus)","accept":["femme","sexe féminin","féminin","la femme","chez la femme"],"keywords":["femme"],"explanation":"L'AAA est plus fréquent chez l'homme, mais à diamètre égal le risque de rupture est près de 4 fois plus important chez la femme.","src":"p. 184","deep":"**Pourquoi** : à diamètre égal, la paroi aortique féminine se rompt plus souvent : risque près de 4 fois supérieur à celui de l'homme (p. 184).\n**Piège** : fréquence ≠ risque : l'AAA est plus fréquent chez l'homme (75-84 ans : ≈ 5 % contre 3 % chez la femme) (p. 183).\n**À relier** : l'item 221 retient d'ailleurs un seuil opératoire plus bas chez la femme : 50 mm contre 55 mm chez l'homme (221 p. 42)."},{"id":"225-qroc-633","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel signe retrouvé à la palpation abdominale évoque un anévrisme de l'aorte abdominale ?","answer":"Une masse battante et expansive en région para-ombilicale","accept":["masse battante","battante","masse battante et expansive","masse pulsatile","masse pulsatile para-ombilicale","masse battante para-ombilicale"],"keywords":["battante"],"explanation":"Un AAA asymptomatique est le plus souvent découvert fortuitement : à la palpation abdominale (masse battante et expansive en région para-ombilicale, avec ou sans souffle) ou, plus souvent, lors d'une imagerie abdominale (échographie, scanner ou IRM).","src":"p. 184","deep":"**Pourquoi** : l'aorte dilatée se palpe en région para-ombilicale sous forme d'une masse battante et expansive, avec ou sans souffle (p. 184).\n**Piège** : la découverte est plus souvent fortuite à l'imagerie (échographie, scanner, IRM) qu'à la palpation : un examen normal ne l'exclut pas (p. 184).\n**À relier** : dépistage échographique des sujets à risque : hommes > 65 ans (p. 184) ; aussi plus jeunes avec FDR (tabac, athérome, antécédents familiaux) (rang B, p. 184)."},{"id":"225-qroc-634","type":"QROC","rank":"A","objective":"225-obj-13","tags":["imagerie","pièges"],"difficulty":2,"question":"Pourquoi l'artériographie est-elle inadaptée pour mesurer la taille d'un AAA ?","answer":"Elle ne visualise que la lumière artérielle (thrombus mural fréquent)","accept":["lumière","thrombus mural","thrombus","elle ne voit que la lumière","lumière artérielle seule","ne visualise que la lumière","thrombus intra-anévrismal"],"keywords":["lumiere"],"explanation":"L'artériographie ne montre que la lumière artérielle et ne donne pas une mesure fiable du diamètre, à cause de la grande fréquence du thrombus mural intra-anévrismal. Le scanner avec injection est l'examen préthérapeutique de référence.","src":"p. 185","deep":"**Pourquoi** : l'artériographie n'opacifie que la lumière circulante ; or l'AAA contient très souvent un thrombus mural : la lumière sous-estime le vrai diamètre (p. 185).\n**Piège** : elle n'est donc pas utile dans le bilan de l'AAA, contrairement à l'AOMI où elle garde une place lors des revascularisations (p. 173, 185).\n**À relier** : échographie pour dépister, mesurer et suivre ; scanner abdominopelvien injecté = examen préthérapeutique de référence ; IRM si scanner contre-indiqué (p. 184-185)."},{"id":"225-qroc-635","type":"QROC","rank":"A","objective":"225-obj-15","tags":["clinique","urgence"],"difficulty":1,"question":"Que fait craindre le caractère douloureux d'un anévrisme de l'aorte abdominale ?","answer":"Une rupture imminente (fissuration)","accept":["rupture imminente","rupture","fissuration","rupture de l'anévrisme"],"keywords":["ruptur"],"explanation":"Un AAA douloureux (douleur abdominale ou lombaire, avec ou sans choc hémorragique) est une urgence vitale : la douleur fait craindre une rupture imminente et impose une orientation immédiate vers un centre spécialisé de chirurgie vasculaire, où un scanner abdominal confirme le diagnostic.","src":"p. 184","deep":"**Pourquoi** : la douleur abdominale ou lombaire d'un AAA traduit une fissuration ou une rupture imminente : c'est une urgence vitale, avec ou sans choc hémorragique (p. 184).\n**Piège** : pas de simple surveillance : orientation en urgence vers un centre de chirurgie vasculaire, où le scanner confirme le diagnostic et localise l'anévrisme (p. 184) ; la rupture intrapéritonéale est souvent cataclysmique (p. 184).\n**À relier** : fissuration plus rare dans un organe voisin : fistule aortocave (IC à haut débit) ou aortodigestive (hémorragie digestive) (p. 184)."},{"id":"225-qroc-636","type":"QROC","rank":"B","objective":"225-obj-15","tags":["traitement","urgence"],"difficulty":3,"question":"Quelle technique, alternative à la chirurgie ouverte, peut aussi traiter un AAA rompu chez un patient à très haut risque périopératoire ?","answer":"L'endoprothèse (traitement endovasculaire)","accept":["endoprothèse","endovasculaire","traitement endovasculaire","endoprothèse aortique"],"keywords":["endo"],"explanation":"L'AAA rompu est une urgence absolue : aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention chez un patient en choc hémorragique. L'endoprothèse est aussi proposée dans l'anévrisme rompu, d'autant plus souvent que le risque périopératoire est très élevé et que l'équipe est expérimentée.","src":"p. 186","deep":"**Pourquoi** : l'endoprothèse, posée par voie fémorale, est moins invasive que la mise à plat-greffe : elle est aussi proposée dans l'AAA rompu, d'autant plus que le risque périopératoire est très élevé, avec de bons résultats dans les équipes entraînées (p. 186).\n**Piège** : elle exige des conditions anatomiques particulières, et le temps compte : en choc, aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention (p. 186).\n**À relier** : après endoprothèse, surveillance au long cours par imagerie à la recherche d'endofuites (p. 186)."},{"id":"225-qroc-637","type":"QROC","rank":"B","objective":"225-obj-14","tags":["suivi","imagerie"],"difficulty":3,"question":"Quels examens assurent la surveillance au long cours d'une endoprothèse aortique ?","answer":"Scanner ou échographie (de contraste)","accept":["scanner","échographie de contraste","échographie","scanner ou échographie de contraste","angioscanner","écho de contraste"],"keywords":["scanner"],"explanation":"Les endoprothèses nécessitent une surveillance régulière par scanner ou échographie de contraste, pour suivre le sac anévrismal et la position de la prothèse et détecter les endofuites, qui entretiennent l'évolutivité de l'anévrisme et un risque de rupture.","src":"p. 186","deep":"**Pourquoi** : après endoprothèse, il faut suivre le sac anévrismal et la position de la prothèse : scanner ou échographie (de contraste) répétés au long cours, pour dépister les endofuites qui entretiennent l'évolutivité et le risque de rupture (p. 186).\n**Piège** : ne pas confondre avec la chirurgie ouverte : la prothèse se suit à l'échodoppler, surtout pour les faux anévrismes anastomotiques, la thrombose étant exceptionnelle (p. 186).\n**À relier** : endofuites = flux qui maintient une pression dans le sac : défaut d'étanchéité aux extrémités ou entre deux modules, porosité, ou reflux par une branche (artères lombaires) (p. 186)."},{"id":"225-qroc-638","type":"QROC","rank":"B","objective":"225-obj-14","tags":["prévention","complications"],"difficulty":2,"question":"Pourquoi une antibioprophylaxie peut-elle se justifier avant un acte à risque bactérien chez un porteur de prothèse artérielle ?","answer":"Risque d'infection de la prothèse lors d'une bactériémie","accept":["infection de la prothèse","infection de prothèse","risque d'infection de prothèse","infection de prothèse vasculaire","colonisation de la prothèse"],"keywords":["infect"],"explanation":"En présence d'une prothèse artérielle, une bactériémie expose à un risque d'infection de la prothèse, ce qui peut justifier une antibioprophylaxie lors de tout acte thérapeutique à risque bactérien.","src":"p. 186","deep":"**Pourquoi** : une prothèse artérielle peut s'infecter lors d'une bactériémie : une antibioprophylaxie peut donc se justifier avant tout acte thérapeutique à risque bactérien (p. 186).\n**Piège** : l'indication est conditionnelle (« peut se justifier »), pas systématique pour tout geste (p. 186).\n**À relier** : même après une cure réussie, le patient reste à haut risque cardiovasculaire : surveillance et contrôle des FDR (p. 186)."},{"id":"225-qroc-701","type":"QROC","rank":"A","objective":"225-obj-16","tags":["épidémiologie","étiologie"],"difficulty":1,"question":"Parmi les facteurs de risque cardiovasculaire, lequel est le plus fortement associé aux plaques d'athérome de l'aorte ?","answer":"Le tabagisme","accept":["tabagisme","tabac"],"keywords":["taba"],"explanation":"Des plaques aortiques existent chez 25 % des hommes et 20 % des femmes de 40-55 ans ; de tous les facteurs de risque, le tabagisme est le plus fortement associé à ces lésions, le plus souvent asymptomatiques.","src":"p. 166","deep":"**Pourquoi** : de tous les facteurs de risque, le tabagisme est le plus fortement lié aux plaques aortiques ; ces lésions débutent dès le jeune âge (stries lipidiques) et l'imagerie en montre chez 25 % des hommes et 20 % des femmes de 40-55 ans (p. 166).\n**Piège** : ne pas répondre diabète : dans l'AOMI il donne surtout les formes graves d'emblée (rang B, p. 168), et pour l'AAA les diabétiques sont même moins souvent atteints (p. 183).\n**À relier** : le tabagisme est aussi, avec les antécédents familiaux, l'un des deux principaux facteurs de risque de l'AAA (p. 183) ; un AAA progresse 3 fois plus vite si le tabac continue (rang B, p. 186)."},{"id":"225-qroc-702","type":"QROC","rank":"A","objective":"225-obj-16","tags":["physiopathologie"],"difficulty":2,"question":"En dehors de l'origine des branches qui en naissent, quel autre siège de l'aorte est préférentiellement touché par l'athérome ?","answer":"La bifurcation aortique (naissance des artères iliaques)","accept":["bifurcation aortique","bifurcation de l'aorte","bifurcation","naissance des artères iliaques"],"keywords":["bifurc"],"explanation":"Tous les segments de l'aorte peuvent être atteints, mais les sièges préférentiels sont la bifurcation aortique, d'où naissent les artères iliaques, et l'origine de toute branche naissant de l'aorte.","src":"p. 166","deep":"**Pourquoi** : tous les segments de l'aorte peuvent être touchés, mais l'athérome se concentre aux points de division : bifurcation aortique (origine des iliaques) et origine de chaque branche née de l'aorte (p. 166).\n**Piège** : préférentiel ne veut pas dire exclusif ; et une plaque aortique s'accompagne souvent d'une atteinte des artères qui en naissent (coronaires, digestives, rénales) (p. 166).\n**À relier** : l'atteinte de l'origine des branches explique la sténose rénale (HTA rénovasculaire) et les sténoses digestives (ischémie mésentérique) (p. 166) ; une occlusion aiguë de la bifurcation donne une ischémie bilatérale sévère avec paralysie sensitivomotrice (p. 179)."},{"id":"225-qroc-703","type":"QROC","rank":"A","objective":"225-obj-16","tags":["complications","physiopathologie"],"difficulty":2,"question":"Par quel mécanisme une plaque d'athérome aortique peut-elle atteindre à distance le cerveau, les membres ou les viscères abdominales ?","answer":"Des emboles de matériel fibrinocruorique","accept":["embolie","emboles","embolique","embolisation"],"keywords":["embol"],"explanation":"Le plus souvent silencieuse, la plaque aortique n'a de traduction clinique qu'en cas d'ulcération de la paroi ou de phénomènes emboliques de matériel fibrinocruorique.","src":"p. 166","deep":"**Pourquoi** : la plaque aortique, le plus souvent muette, ne devient symptomatique qu'en cas d'ulcération de la paroi ou d'embolie de matériel fibrinocruorique, qui part dans le courant artériel (p. 166).\n**Piège** : le territoire dépend du siège de la plaque : aorte ascendante ou horizontale → cerveau ; sinon membres ou viscères abdominaux (p. 166).\n**À relier** : l'athérome aortique figure parmi les causes aortiques d'embolie sur artères saines de l'ischémie aiguë de membre, avec l'anévrisme, les aortites et les tumeurs aortiques (rang B, p. 181)."},{"id":"225-qroc-704","type":"QROC","rank":"A","objective":"225-obj-16","tags":["épidémiologie","pronostic"],"difficulty":1,"question":"Que représente la présence de calcifications ou de plaques aortiques, même asymptomatiques, pour le risque du patient ?","answer":"Un marqueur de risque cardiovasculaire","accept":["marqueur de risque cardiovasculaire","marqueur de risque","marqueur du risque cardiovasculaire"],"keywords":["marqueur","risque"],"explanation":"Le risque cardiovasculaire général augmente avec la présence et l'extension des calcifications aortiques, même asymptomatiques. Ces plaques sont souvent associées à d'autres atteintes (coronaires, digestives, rénales).","src":"p. 166","deep":"**Pourquoi** : le risque cardiovasculaire global augmente avec la présence et l'étendue des calcifications aortiques, même sans symptôme ; elles sont surtout découvertes par hasard sur une imagerie thoracique ou abdominale (p. 166).\n**Piège** : une trouvaille radiologique n'est pas anodine : ces plaques s'associent souvent à une atteinte coronaire, digestive ou rénale, à rechercher (p. 166).\n**À relier** : même logique de marqueur pour l'IPS < 0,90, associé à un risque élevé d'accident coronarien ou cérébral (p. 171), et pour l'AAA : 10 fois plus de risque de mourir d'une autre cause cardiovasculaire que de la rupture (p. 184)."},{"id":"225-qroc-705","type":"QROC","rank":"A","objective":"225-obj-16","tags":["étiologie","physiopathologie"],"difficulty":2,"question":"Quelle forme d'hypertension artérielle secondaire peut résulter d'une sténose athéromateuse d'une artère rénale ?","answer":"L'HTA rénovasculaire","accept":["hta rénovasculaire","hypertension rénovasculaire","rénovasculaire","renovasculaire"],"keywords":["renovasc"],"explanation":"L'athérome des artères rénales provoque une ischémie rénale ; la réponse est une activation de la cascade rénine-angiotensine-aldostérone, responsable d'une HTA rénovasculaire, étiologie d'HTA secondaire.","src":"p. 166","deep":"**Pourquoi** : la sténose athéromateuse rend le rein ischémique ; il répond en activant la cascade rénine-angiotensine-aldostérone, ce qui élève la pression artérielle : c'est l'HTA rénovasculaire, une cause d'HTA secondaire (p. 166).\n**Piège** : chez un patient polyathéromateux, une HTA n'est pas forcément essentielle : l'athérome touche volontiers l'origine des branches de l'aorte, dont les artères rénales (p. 166).\n**À relier** : même mécanisme sténosant sur les autres artères viscérales (tronc cœliaque, mésentériques) : souvent muettes, elles peuvent donner une ischémie mésentérique chronique ou aiguë (p. 166)."},{"id":"225-qroc-706","type":"QROC","rank":"A","objective":"225-obj-16","tags":["étiologie","clinique"],"difficulty":1,"question":"Citez une artère viscérale dont la sténose peut être responsable d'une ischémie mésentérique chronique ou aiguë.","answer":"Tronc cœliaque ou artère mésentérique supérieure ou inférieure","accept":["tronc cœliaque","tronc coeliaque","mésentérique supérieure","mésentérique inférieure","artères mésentériques","artère mésentérique supérieure","artère mésentérique inférieure","mésentérique","coeliaque","tronc cœliaque ou mésentérique","AMS"],"keywords":["coeliaque","mesenter"],"explanation":"Les sténoses du tronc cœliaque et/ou des artères mésentériques supérieure et/ou inférieure peuvent entraîner une ischémie digestive (ischémie mésentérique), chronique ou aiguë ; elles sont le plus souvent asymptomatiques.","src":"p. 166","deep":"**Pourquoi** : trois artères destinées au tube digestif peuvent être sténosées : tronc cœliaque, mésentérique supérieure, mésentérique inférieure ; leur atteinte peut causer une ischémie digestive (mésentérique), chronique ou aiguë (p. 166).\n**Piège** : ces sténoses sont le plus souvent asymptomatiques : c'est le tableau clinique (angor digestif ou douleur abdominale aiguë) qui fait parler d'ischémie mésentérique (p. 166).\n**À relier** : chronique : douleurs abdominales après les repas ± amaigrissement, souffle abdominal éventuel (p. 166) ; aiguë : urgence vitale par thrombose in situ ou embolie (p. 167)."},{"id":"225-qroc-707","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","physiopathologie"],"difficulty":2,"question":"Pourquoi une ischémie mésentérique chronique grave peut-elle entraîner un amaigrissement ?","answer":"Le patient limite ses repas pour éviter la douleur","accept":["limite ses repas","limite son alimentation","évite les repas","évite de manger","éviter les douleurs"],"keywords":["repas"],"explanation":"L'angor digestif survient après le repas : dans les cas graves, le patient limite ses repas pour éviter les douleurs, d'où une altération de l'état général et un amaigrissement.","src":"p. 166","deep":"**Pourquoi** : l'angor digestif survient après le repas ; dans les formes graves, le patient mange moins pour ne pas avoir mal, d'où altération de l'état général et amaigrissement (p. 166).\n**Piège** : le Collège n'invoque pas une malabsorption mais la restriction des repas ; l'examen est pauvre, limité à un éventuel souffle abdominal (p. 166).\n**À relier** : la sténose se confirme par échodoppler des artères digestives, angioscanner ou angio-IRM (rang B, p. 166) ; « dénutrition/malnutrition » est d'ailleurs une situation de départ de l'item (p. 164)."},{"id":"225-qroc-708","type":"QROC","rank":"B","objective":"225-obj-17","tags":["paraclinique","imagerie"],"difficulty":2,"question":"Citez un examen non invasif permettant de diagnostiquer une sténose artérielle responsable d'une ischémie mésentérique chronique.","answer":"Échodoppler des artères digestives, angioscanner ou angio-IRM","accept":["échodoppler des artères digestives","échodoppler","angioscanner","angio-irm","angio irm","angioscan","angio scanner","angio-scanner","ARM","echodoppler","écho-doppler"],"keywords":[],"explanation":"La sténose artérielle peut être diagnostiquée par l'échodoppler des artères digestives, un angioscanner ou une angio-IRM.","src":"p. 166","deep":"**Pourquoi** : la sténose d'une artère digestive se voit à l'échodoppler des artères digestives (non invasif) ou en imagerie en coupe : angioscanner ou angio-IRM (p. 166).\n**Piège** : l'artériographie n'est pas un examen diagnostique ici : on ne la réalise que pendant une revascularisation par voie endovasculaire (p. 166).\n**À relier** : même hiérarchie dans l'AOMI : échodoppler d'abord, angioscanner ou angio-IRM seulement si une revascularisation est envisagée, artériographie limitée aux procédures (p. 172-173)."},{"id":"225-qroc-709","type":"QROC","rank":"B","objective":"225-obj-17","tags":["paraclinique","pièges"],"difficulty":2,"question":"Dans l'ischémie mésentérique chronique, dans quelle situation l'artériographie est-elle réalisée ?","answer":"Lors d'une procédure de revascularisation endovasculaire","accept":["revascularisation endovasculaire","revascularisation par voie endovasculaire","geste endovasculaire","revascularisation"],"keywords":["revascul"],"explanation":"L'artériographie n'est pas l'examen diagnostique : elle n'est réalisée que lors d'une procédure de revascularisation par voie endovasculaire.","src":"p. 166","deep":"**Pourquoi** : le diagnostic de la sténose repose sur l'échodoppler, l'angioscanner ou l'angio-IRM ; l'artériographie n'est faite qu'au cours d'une revascularisation par voie endovasculaire (p. 166).\n**Piège** : ne pas la proposer au diagnostic initial : c'est un examen par ponction artérielle directe avec injection de contraste (p. 173).\n**À relier** : même règle dans l'AOMI, où l'artériographie, longtemps examen de référence, est désormais surtout limitée aux revascularisations (p. 173) ; dans l'AAA elle n'est pas utile car elle ne montre que la lumière (p. 185)."},{"id":"225-qroc-710","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","urgence"],"difficulty":1,"question":"Dans le tableau d'ischémie mésentérique aiguë, quel signe digestif accompagne la douleur abdominale aiguë pauvre en signes physiques ?","answer":"Une vidange digestive accélérée (vomissements et/ou diarrhée)","accept":["vidange digestive accélérée","vidange digestive","vomissements","diarrhée"],"keywords":["vidange"],"explanation":"Le tableau associe une douleur abdominale aiguë avec peu de signes physiques, une vidange digestive accélérée (vomissements et/ou diarrhée) et des indices d'une cause embolique.","src":"p. 167","deep":"**Pourquoi** : le tableau typique est une triade : douleur abdominale aiguë contrastant avec peu de signes physiques, vidange digestive accélérée (vomissements et/ou diarrhée), indices d'une cause embolique, surtout une fibrillation atriale (p. 167).\n**Piège** : ne pas attendre une défense : la pauvreté de l'examen fait partie du tableau ; les formes plus frustes expliquent des errances diagnostiques (p. 167).\n**À relier** : urgence vitale dont le pronostic dépend de la rapidité de la prise en charge ; l'infarctus digestif reste rare grâce aux nombreuses collatérales (p. 167)."},{"id":"225-qroc-711","type":"QROC","rank":"A","objective":"225-obj-17","tags":["clinique","étiologie"],"difficulty":2,"question":"Quel élément du contexte évoque une origine embolique devant une ischémie mésentérique aiguë ?","answer":"Une fibrillation atriale","accept":["fibrillation atriale","fibrillation auriculaire","acfa","fa"],"keywords":["fibrillation"],"explanation":"La présence d'une fibrillation atriale oriente vers une cause embolique ; des signes d'embolie dans d'autres territoires renforcent cette présomption.","src":"p. 167","deep":"**Pourquoi** : une fibrillation atriale est un trouble du rythme emboligène : elle oriente vers une embolie plutôt que vers une thrombose in situ (p. 167).\n**Piège** : des signes d'embolie dans d'autres territoires renforcent la présomption embolique ; à l'inverse, le patient est le plus souvent polyathéromateux (p. 167, 187).\n**À relier** : même raisonnement dans l'ischémie aiguë de membre : embolie parfois précédée de palpitations, FA en tête des causes cardiaques (rang B, p. 181) ; d'où l'ECG systématique (p. 182)."},{"id":"225-qroc-712","type":"QROC","rank":"A","objective":"225-obj-16","tags":["physiopathologie"],"difficulty":1,"question":"Pourquoi l'infarctus digestif reste-t-il rare au cours des occlusions artérielles mésentériques ?","answer":"Grâce aux nombreuses collatéralités","accept":["collatéralités","collatérales","collatéralité","nombreuses collatérales"],"keywords":["collat"],"explanation":"Compte tenu des nombreuses collatéralités, l'infarctus digestif est rare. L'ischémie mésentérique aiguë reste néanmoins une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge.","src":"p. 167","deep":"**Pourquoi** : les artères digestives ont de nombreuses collatéralités, qui permettent le plus souvent de compenser l'occlusion : l'infarctus digestif est donc rare (p. 167).\n**Piège** : rare ne veut pas dire bénin : l'ischémie mésentérique aiguë reste une urgence vitale, et le pronostic dépend de la rapidité de la prise en charge (p. 167).\n**À relier** : la collatéralité explique aussi la longue phase muette de l'AOMI (p. 168) et la douleur moins brutale de la thrombose in situ que de l'embolie sur artères saines (rang B, p. 181)."},{"id":"225-qroc-713","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"À quel âge se situe le pic de présentation de l'AOMI symptomatique chez l'homme ?","answer":"Entre 60 et 75 ans","accept":["60-75 ans","60 à 75 ans","60 et 75 ans","60-75"],"keywords":["60","75"],"explanation":"La forme symptomatique est plus fréquente chez l'homme, avec un pic entre 60 et 75 ans (entre 70 et 80 ans chez la femme).","src":"p. 167","deep":"**Pourquoi** : dans sa forme symptomatique, l'AOMI est plus fréquente chez l'homme, avec un pic de présentation entre 60 et 75 ans (p. 167).\n**Piège** : chez la femme le pic est plus tardif, entre 70 et 80 ans : ne pas inverser les fourchettes (p. 167).\n**À relier** : prévalence des formes cliniques 1-5 % après 60 ans, 10-15 % en incluant les formes asymptomatiques (p. 168) ; AOMI = 3e localisation de l'athérosclérose après coronaires et cerveau (p. 167)."},{"id":"225-qroc-714","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":2,"question":"Chez la femme, entre quels âges se situe le pic de présentation de l'AOMI symptomatique ?","answer":"Entre 70 et 80 ans","accept":["70-80 ans","70 à 80 ans","70 et 80 ans","70-80"],"keywords":["70","80"],"explanation":"Chez la femme le pic de présentation se situe entre 70 et 80 ans, soit plus tard que chez l'homme (60-75 ans), et la forme symptomatique est moins fréquente.","src":"p. 167","deep":"**Pourquoi** : chez la femme, la forme symptomatique est moins fréquente et se présente plus tard, avec un pic entre 70 et 80 ans (p. 167).\n**Piège** : ne pas reprendre la fourchette masculine, 60-75 ans (p. 167).\n**À relier** : pour l'AAA aussi la femme est moins touchée (entre 75 et 84 ans : 3 % contre 5 % chez l'homme), mais à diamètre égal son risque de rupture est près de 4 fois plus élevé (p. 183-184)."},{"id":"225-qroc-715","type":"QROC","rank":"A","objective":"225-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"Quelle est la prévalence des formes cliniques d'AOMI après 60 ans ?","answer":"De 1 à 5 %","accept":["1 à 5 %","1-5 %","entre 1 et 5 %","1 à 5"],"keywords":["1","5"],"explanation":"La prévalence des formes cliniques varie de 1 à 5 % après 60 ans, et atteint 10-15 % dans cette tranche d'âge si l'on inclut la forme asymptomatique.","src":"p. 168","deep":"**Pourquoi** : 1 à 5 % des plus de 60 ans ont une AOMI clinique ; la maladie est surtout infraclinique, avec 2 à 4 formes infracliniques pour une forme clinique (p. 168).\n**Piège** : 10-15 % est la prévalence en incluant les formes asymptomatiques ; 2-5 ‰ est l'incidence : ne pas mélanger les trois chiffres (p. 168).\n**À relier** : d'où l'intérêt du dépistage des formes infracliniques, par la mesure de l'IPS (p. 168, 170)."},{"id":"225-qroc-716","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":1,"question":"Dans l'AOMI, quel facteur de risque est plus fréquent chez le sujet jeune ?","answer":"Le tabagisme","accept":["tabagisme","tabac"],"keywords":["taba"],"explanation":"Le tabagisme est le facteur de risque le plus fréquent chez le sujet plus jeune ; le diabète est plus souvent responsable de formes graves d'emblée.","src":"p. 168","deep":"**Pourquoi** : le tabagisme et le diabète sont les deux principaux facteurs de risque de l'AOMI ; le tabagisme est le plus fréquent chez le sujet plus jeune (p. 168).\n**Piège** : ne pas répondre diabète : il est surtout responsable des formes graves d'emblée, plus distales et de pronostic plus sévère (p. 168).\n**À relier** : l'arrêt du tabac est au premier plan du traitement : il favorise la circulation collatérale et allonge la distance de marche (p. 175) ; risque d'amputation à 5 ans ~5 %, surtout si le tabagisme persiste (p. 177)."},{"id":"225-qroc-717","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie","pronostic"],"difficulty":2,"question":"Quel facteur de risque est le plus souvent responsable d'une AOMI grave d'emblée, d'atteinte plus distale et de pronostic plus sévère ?","answer":"Le diabète","accept":["diabète","diabétique"],"keywords":["diab"],"explanation":"Le diabète est plus souvent responsable de formes graves d'emblée, avec une atteinte plus distale et un pronostic plus sévère ; le tabagisme est plus fréquent chez le sujet plus jeune.","src":"p. 168","deep":"**Pourquoi** : chez le diabétique, l'AOMI est plus souvent grave d'emblée, plus distale et de pronostic plus sévère (p. 168).\n**Piège** : la neuropathie diabétique peut masquer la douleur, avec une ischémie permanente d'emblée chez un patient qui semblait asymptomatique (p. 169) ; la médiacalcose donne un IPS > 1,40 non interprétable → pression d'orteil (p. 171).\n**À relier** : la gangrène est plus fréquente chez le diabétique, souvent infectée (p. 169) ; cible du traitement général : HbA1c < 7 % (p. 175)."},{"id":"225-qroc-718","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":1,"question":"Outre le tabagisme et le diabète, quels sont les deux autres facteurs de risque fréquemment associés à l'AOMI ?","answer":"L'hypercholestérolémie et l'hypertension artérielle","accept":["hypercholestérolémie et hta","hypercholestérolémie et hypertension artérielle","hypertension artérielle et hypercholestérolémie","hta et hypercholestérolémie","hta et cholestérol"],"keywords":["cholest","hta"],"explanation":"Les principaux facteurs de risque sont le tabagisme et le diabète ; l'hypercholestérolémie et l'hypertension artérielle sont les autres facteurs fréquemment associés.","src":"p. 168","deep":"**Pourquoi** : après les deux principaux (tabac, diabète), l'hypercholestérolémie et l'HTA sont les autres facteurs fréquemment associés à l'AOMI (p. 168).\n**Piège** : deux réponses attendues ; ne pas citer les antécédents familiaux d'anévrisme : c'est l'un des deux principaux facteurs de risque de l'AAA (p. 183), absent de la liste des facteurs de l'AOMI (p. 168).\n**À relier** : cibles du traitement général : PAS ≤ 120-129 et PAD ≤ 70-79 mmHg, LDL < 0,55 g/L, HbA1c < 7 % (p. 175)."},{"id":"225-qroc-719","type":"QROC","rank":"A","objective":"225-obj-03","tags":["physiopathologie","clinique"],"difficulty":1,"question":"Pourquoi l'AOMI reste-t-elle longtemps asymptomatique au début de la maladie ?","answer":"Retentissement hémodynamique modéré et artères collatérales compensatrices","accept":["circulation collatérale","artères collatérales","collatérales","collatéralité"],"keywords":["collat"],"explanation":"Au début, le retentissement hémodynamique est modéré et des artères collatérales se développent progressivement pour compenser ; les premiers symptômes surviennent à l'effort, quand l'hypoxie musculaire apparaît.","src":"p. 168","deep":"**Pourquoi** : au début, le retentissement hémodynamique est modéré et des artères collatérales se développent progressivement pour compenser (p. 168).\n**Piège** : asymptomatique ne veut pas dire peu grave : une atteinte sévère peut rester muette (collatérales importantes, patient qui ne marche pas assez, neuropathie) (p. 169).\n**À relier** : les premiers symptômes apparaissent à l'effort, quand le débit ne suffit plus à oxygéner le muscle (ischémie d'effort), puis au repos (ischémie permanente) (p. 168)."},{"id":"225-qroc-720","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Comment appelle-t-on la distance de marche à laquelle apparaît la douleur de claudication ?","answer":"La distance de gêne","accept":["distance de gêne","périmètre de gêne","distance de gene"],"keywords":["gene"],"explanation":"La douleur de type crampe du mollet se déclenche après la distance de gêne ; elle oblige finalement le patient à s'arrêter au bout de la distance de marche.","src":"p. 168","deep":"**Pourquoi** : la distance de gêne marque l'apparition de la crampe du mollet ; la distance de marche est celle au bout de laquelle le patient doit s'arrêter (p. 168).\n**Piège** : ne pas les confondre ; la douleur cède habituellement en moins de 5 minutes, et la claudication est dite sévère si la distance de marche est < 100 m (p. 168-169).\n**À relier** : le test sur tapis roulant (3,2 km/h, pente 10 %) mesure ces deux distances de façon standardisée et suit leur évolution (p. 171)."},{"id":"225-qroc-721","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Quel niveau d'atteinte artérielle explique une claudication fessière ?","answer":"Une atteinte aorto-iliaque","accept":["aorto-iliaque","aorto iliaque","atteinte aorto-iliaque","aorto-iliaques"],"keywords":["aorto"],"explanation":"Dans les formes atypiques, la claudication peut siéger au pied, à la cuisse ou à la fesse ; la claudication fessière traduit une atteinte aorto-iliaque.","src":"p. 169","deep":"**Pourquoi** : parmi les formes atypiques, le Collège rattache la claudication fessière aux atteintes aorto-iliaques (p. 169).\n**Piège** : la claudication n'est pas toujours au mollet : pied, cuisse, fesse, paresthésies d'effort, ou simple ralentissement du pas sans arrêt (p. 169).\n**À relier** : claudication fessière et/ou fatigabilité à la marche + impuissance = syndrome de Leriche (aorto-iliaque) (p. 169) ; une atteinte aorto-iliaque sévère peut faire envisager d'emblée la revascularisation (p. 176)."},{"id":"225-qroc-722","type":"QROC","rank":"A","objective":"225-obj-03","tags":["pièges","clinique"],"difficulty":2,"question":"Comment appelle-t-on la forme d'AOMI sévère restée silencieuse (collatérales, marche limitée, neuropathie) qui se révèle d'emblée par une ischémie permanente ?","answer":"AOMI masquée","accept":["aomi masquée","forme masquée","masquée"],"keywords":["masqu"],"explanation":"Une atteinte sévère peut rester asymptomatique (collatéralité importante, comorbidités limitant la marche, neuropathie altérant la sensibilité) : cette AOMI masquée se distingue de la forme purement asymptomatique et justifie le dépistage chez les sujets à risque.","src":"p. 169","deep":"**Pourquoi** : une atteinte sévère peut rester muette par collatéralité importante, par comorbidités empêchant de marcher assez (insuffisance cardiaque ou respiratoire, atteintes articulaires) ou par neuropathie (diabète, insuffisance rénale, âge) ; dans ces deux derniers cas, elle peut se révéler d'emblée par une ischémie permanente (p. 169).\n**Piège** : la distinguer de la forme purement asymptomatique (p. 169).\n**À relier** : elle justifie le dépistage chez les sujets à risque par l'IPS, complété par une pression d'orteil chez le diabétique, l'insuffisant rénal et le sujet très âgé (p. 169-170)."},{"id":"225-qroc-723","type":"QROC","rank":"A","objective":"225-obj-03","tags":["pièges","clinique"],"difficulty":2,"question":"Avant même de chercher des douleurs à la marche, que faut-il vérifier chez un patient suspect d'AOMI ?","answer":"Qu'il marche réellement, sans se limiter pour éviter la douleur","accept":["qu'il marche","qu'il marche suffisamment","qu'il marche réellement","il marche"],"keywords":[],"explanation":"Il faut s'assurer que le patient marche et qu'il n'est pas limité ou ne se limite pas justement pour éviter la douleur ; sinon une AOMI sévère peut passer inaperçue.","src":"p. 169","deep":"**Pourquoi** : sans marche suffisante, pas de claudication : un patient limité par ses comorbidités, ou qui se limite pour éviter la douleur, peut cacher une AOMI sévère (p. 169).\n**Piège** : demander « avez-vous mal en marchant ? » ne suffit pas : il faut d'abord vérifier qu'il marche (p. 169).\n**À relier** : c'est l'AOMI masquée (sujet très âgé, comorbide, neuropathe), qui peut se révéler d'emblée par une ischémie permanente (p. 169)."},{"id":"225-qroc-724","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Quels sont le caractère et le siège des douleurs de décubitus de l'ischémie permanente ?","answer":"Brûlures des orteils et de l'avant-pied","accept":["brûlures des orteils","brûlures de l'avant-pied","brûlures"],"keywords":["brul"],"explanation":"Les douleurs de décubitus, type brûlures des orteils et de l'avant-pied, traduisent une ischémie permanente (stade III) ; elles s'améliorent en position déclive.","src":"p. 169","deep":"**Pourquoi** : au stade III, l'ischémie est permanente : brûlures des orteils et de l'avant-pied, apparaissant après quelques minutes à quelques heures de décubitus et soulagées jambe pendante (p. 169).\n**Piège** : ne pas répondre crampe du mollet à la marche, qui est la claudication intermittente (stade II) (p. 168).\n**À relier** : douleurs intenses → insomnie, altération de l'état général, antalgiques d'intensité croissante ; ischémie permanente = haut risque d'amputation sans revascularisation (p. 169)."},{"id":"225-qroc-725","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect du pied à l'examen d'un patient ayant des douleurs de décubitus d'ischémie permanente ?","answer":"Froid, pâle ou cyanosé","accept":["froid","pâle","cyanosé","froid et pâle"],"keywords":[],"explanation":"À l'examen, le pied est froid, pâle ou cyanosé ; un œdème de déclivité peut apparaître et favorise les complications trophiques.","src":"p. 169","deep":"**Pourquoi** : au repos, la perfusion ne suffit plus : le pied est froid, pâle ou cyanosé (p. 169).\n**Piège** : la position jambe pendante, adoptée pour soulager, favorise un œdème de déclivité, lui-même source de complications trophiques (p. 169).\n**À relier** : stade IV ensuite : peau mince, perte de pilosité, ulcères, gangrène (p. 169) ; à l'examen, temps de recoloration allongé (normal < 3 s) (p. 170)."},{"id":"225-qroc-726","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans la classification de Leriche et Fontaine, à quel stade correspond la claudication intermittente ?","answer":"Stade II","accept":["stade ii","stade 2","ii","stade II de Leriche et Fontaine"],"keywords":[],"explanation":"Leriche et Fontaine : stade I asymptomatique, stade II claudication intermittente, stade III douleur ischémique de repos, stade IV ulcération ou gangrène.","src":"p. 168","deep":"**Pourquoi** : Leriche et Fontaine : I asymptomatique, II claudication intermittente, III douleur ischémique de repos, IV ulcération ou gangrène (p. 168).\n**Piège** : stade II de Fontaine ≠ grade II de Rutherford (douleur de repos) : la claudication correspond au grade I (catégories 1 à 3) de Rutherford (p. 168).\n**À relier** : claudication sévère si distance de marche < 100 m (p. 169) ; prise en charge : facteurs de risque, statine, antiplaquettaire, réadaptation à la marche (p. 177)."},{"id":"225-qroc-727","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans la classification de Leriche et Fontaine, à quel stade correspond la douleur ischémique de repos ?","answer":"Stade III","accept":["stade iii","stade 3","iii","stade III de Leriche et Fontaine"],"keywords":[],"explanation":"Stade III de Leriche et Fontaine : douleur ischémique de repos (douleurs de décubitus) ; correspond au grade II (catégorie 4) de Rutherford.","src":"p. 168-169","deep":"**Pourquoi** : stade III = douleur ischémique de repos (décubitus), premier stade de l'ischémie permanente (p. 168-169).\n**Piège** : ne pas confondre avec le grade III de Rutherford (pertes de substance) : la douleur de repos y est le grade II, catégorie 4 (p. 168).\n**À relier** : ischémie permanente (III + IV) = douleurs > 15 jours résistant aux antalgiques ; avec pression de cheville < 50 mmHg ou d'orteil < 30 mmHg → ischémie critique (p. 169)."},{"id":"225-qroc-728","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans la classification de Leriche et Fontaine, à quel stade correspondent les troubles trophiques (ulcération ou gangrène) ?","answer":"Stade IV","accept":["stade iv","stade 4","iv","stade IV de Leriche et Fontaine"],"keywords":[],"explanation":"Stade IV de Leriche et Fontaine : ulcération ou gangrène, correspondant au grade III de Rutherford ; l'ischémie permanente englobe les stades III et IV.","src":"p. 168-169","deep":"**Pourquoi** : stade IV = troubles trophiques : ulcération ou gangrène (p. 168-169).\n**Piège** : en Rutherford, la même situation est le grade III, qui distingue perte de substance faible et majeure : même tableau, chiffre différent (p. 168).\n**À relier** : stades III et IV forment l'ischémie permanente : revasculariser autant que possible, l'amputation n'étant envisagée qu'en cas d'impossibilité ou d'échec (p. 169, 177)."},{"id":"225-qroc-729","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quelle classification internationale a le plus souvent supplanté celle de Leriche et Fontaine ?","answer":"La classification de Rutherford","accept":["rutherford","classification de rutherford"],"keywords":["rutherford"],"explanation":"La classification de Leriche et Fontaine est le plus souvent supplantée de nos jours par la classification internationale de Rutherford.","src":"p. 168","deep":"**Pourquoi** : la classification de Leriche et Fontaine est le plus souvent supplantée aujourd'hui par la classification internationale de Rutherford (p. 168).\n**Piège** : les deux décrivent les mêmes tableaux avec un décalage d'un cran : claudication = stade II / grade I ; douleur de repos = III / II ; troubles trophiques = IV / III (p. 168).\n**À relier** : une autre échelle de Rutherford grade l'ischémie aiguë (I, IIa, IIb, III) selon les déficits sensitif et moteur : ne pas les mélanger (p. 179)."},{"id":"225-qroc-730","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"question":"Dans la classification de Rutherford, quel grade regroupe les claudications légère, modérée et sévère ?","answer":"Le grade I","accept":["grade i","grade 1","i"],"keywords":[],"explanation":"Rutherford : grade 0 asymptomatique, grade I (catégories 1 à 3) claudication légère, modérée ou sévère, grade II (catégorie 4) douleur de repos, grade III ulcération ou gangrène.","src":"p. 168","deep":"**Pourquoi** : le grade I de Rutherford correspond à la claudication, déclinée en catégories 1 (légère), 2 (modérée) et 3 (sévère) (p. 168).\n**Piège** : grade II = douleur de repos (catégorie 4) ; ne pas confondre grade et catégorie (p. 168).\n**À relier** : équivaut au stade II de Leriche et Fontaine (p. 168) ; la revascularisation n'est envisagée d'emblée que si claudication très invalidante (< 100 m) ou atteinte aorto-iliaque sévère (p. 176-177)."},{"id":"225-qroc-731","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"question":"Dans la classification de Rutherford, à quel grade correspond la douleur ischémique de repos ?","answer":"Grade II (catégorie 4)","accept":["grade ii","grade 2","catégorie 4","ii","catégorie 4 de Rutherford"],"keywords":[],"explanation":"La douleur ischémique de repos (stade III de Leriche et Fontaine) correspond au grade II, catégorie 4, de Rutherford.","src":"p. 168","deep":"**Pourquoi** : la douleur ischémique de repos constitue à elle seule le grade II de Rutherford, catégorie 4 (p. 168).\n**Piège** : grade III de Rutherford = perte de substance (faible ou majeure) ; le stade III de Fontaine, lui, est la douleur de repos : même chiffre, tableaux différents (p. 168).\n**À relier** : ces douleurs de décubitus (brûlures des orteils, soulagées jambe pendante) signent l'ischémie permanente (p. 169)."},{"id":"225-qroc-732","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Comment nomme-t-on un ulcère artériel siégeant à la face antérieure de la jambe ?","answer":"Un ulcère « suspendu »","accept":["ulcère suspendu","suspendu","ulcere suspendu"],"keywords":["suspendu"],"explanation":"Les ulcères artériels siègent surtout aux zones de frottement ou d'appui (orteil, bord externe du pied, talon) et parfois à la face antérieure de la jambe : ulcère « suspendu ».","src":"p. 169","deep":"**Pourquoi** : les ulcères artériels siègent surtout aux zones de frottement ou d'appui (orteil, dos et bord externe du pied, talon), mais parfois à la face antérieure de la jambe : ulcère « suspendu » (p. 169).\n**Piège** : un ulcère de jambe n'est pas forcément artériel : ulcères veineux, microcirculatoires, neuropathiques et traumatiques sont des diagnostics différentiels (p. 174).\n**À relier** : souvent petits mais creusants, très algiques, porte d'entrée d'une infection locorégionale (cellulite, arthrite, ostéite) voire générale (p. 169)."},{"id":"225-qroc-733","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Quelles sont les caractéristiques habituelles de taille et de profondeur d'un ulcère de l'AOMI ?","answer":"Faible surface mais pouvant être creusant jusqu'à l'aponévrose ou l'os","accept":["faible surface","petite surface","creusant","généralement de faible surface"],"keywords":["surface","creus"],"explanation":"Les ulcères artériels sont généralement de faible surface mais peuvent être creusants, jusqu'à l'aponévrose ou l'os ; très algiques, ils sont une porte d'entrée à l'infection.","src":"p. 169","deep":"**Pourquoi** : l'ulcère de l'AOMI est généralement de faible surface, mais peut creuser jusqu'à l'aponévrose ou l'os (p. 169).\n**Piège** : petit ≠ bénin : il est très algique et peut être la porte d'entrée d'une infection locorégionale (cellulite, arthrite, ostéite), voire d'une septicémie (p. 169).\n**À relier** : soins de plaies sous supervision d'une équipe multidisciplinaire spécialisée ; revascularisation proposée autant que possible en ischémie permanente (p. 176)."},{"id":"225-qroc-734","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","pièges"],"difficulty":2,"question":"Quel geste banal peut déclencher un ulcère chez un patient atteint d'AOMI ?","answer":"Un traumatisme minime (ex : geste agressif de pédicure)","accept":["geste de pédicure","pédicure","traumatisme minime","traumatisme"],"keywords":[],"explanation":"Les ulcères peuvent apparaître spontanément ou après un traumatisme parfois minime, comme un geste de pédicure agressif.","src":"p. 169","deep":"**Pourquoi** : au stade des troubles trophiques la peau est mince et fragile : l'ulcère apparaît spontanément ou après un traumatisme parfois minime, comme un geste de pédicure agressif (p. 169).\n**Piège** : ne pas attendre une plaie importante : un petit traumatisme suffit (p. 169).\n**À relier** : les ulcères siègent aux zones de frottement ou d'appui (p. 169) ; l'éducation thérapeutique, qui accompagne la réadaptation, vise notamment le respect des règles de prévention (p. 175)."},{"id":"225-qroc-735","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Où apparaît surtout la gangrène de l'ischémie permanente ?","answer":"Au niveau des orteils ou du talon","accept":["orteils","orteil","talon","orteils ou talon","les orteils","le talon"],"keywords":[],"explanation":"La gangrène apparaît surtout aux orteils ou au talon et peut s'étendre à l'avant-pied, voire à la jambe ; elle est plus fréquente chez le diabétique, avec souvent des lésions infectées.","src":"p. 169","deep":"**Pourquoi** : la gangrène apparaît surtout aux orteils ou au talon, et peut s'étendre à l'avant-pied, voire à la jambe (p. 169).\n**Piège** : elle est plus fréquente chez le diabétique, avec des lésions souvent infectées (p. 169).\n**À relier** : l'amputation, geste ultime faute de revascularisation possible, se fait en zone saine bien oxygénée (intérêt de la TcPO2) en préservant l'appui ou le genou pour l'appareillage (p. 176-177)."},{"id":"225-qroc-736","type":"QROC","rank":"A","objective":"225-obj-06","tags":["définition","clinique"],"difficulty":2,"question":"Quelle durée minimale de douleurs résistant aux antalgiques usuels caractérise l'ischémie permanente ?","answer":"Plus de 15 jours","accept":["plus de 15 jours","15 jours","> 15 jours"],"keywords":["15"],"explanation":"L'ischémie permanente englobe les stades III et IV, avec des douleurs durant plus de 15 jours et résistant aux antalgiques usuels ; avec une pression de perfusion effondrée, elle définit l'ischémie critique.","src":"p. 169","deep":"**Pourquoi** : l'ischémie permanente (stades III et IV) se définit par des douleurs de plus de 15 jours résistant aux antalgiques usuels (p. 169).\n**Piège** : ischémie critique = ce tableau + effondrement des pressions de perfusion (cheville < 50 mmHg ou hallux < 30 mmHg) (p. 169) ; ne pas confondre avec l'index de pression d'orteil < 0,70, seuil diagnostique de l'AOMI (p. 171).\n**À relier** : en ischémie critique, le pronostic du membre est engagé (p. 169) et la mortalité à 5 ans est proche de 70 % (p. 178)."},{"id":"225-qroc-737","type":"QROC","rank":"A","objective":"225-obj-06","tags":["complications","urgence"],"difficulty":2,"question":"Quel risque pèse sur le membre d'un patient en ischémie permanente en l'absence de revascularisation ?","answer":"Un haut risque d'amputation","accept":["amputation","risque d'amputation","haut risque d'amputation"],"keywords":["amput"],"explanation":"L'ischémie permanente expose à un haut risque d'amputation en l'absence de revascularisation ; en ischémie critique, le pronostic vital du membre est engagé.","src":"p. 169","deep":"**Pourquoi** : à ce stade l'hypoxie tissulaire est permanente : sans revascularisation, le risque d'amputation est élevé (p. 169).\n**Piège** : le pronostic n'est pas seulement local : en ischémie critique, la mortalité à 5 ans est proche de 70 % (p. 178).\n**À relier** : revascularisation proposée autant que possible en ischémie permanente ; amputation seulement si elle est impossible ou en échec (p. 176-177)."},{"id":"225-qroc-738","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelle règle générale s'applique à l'examen clinique des membres inférieurs d'un patient suspect d'AOMI ?","answer":"Il est bilatéral et comparatif","accept":["bilatéral et comparatif","bilatéral","comparatif","bilatéral comparatif"],"keywords":["bilat"],"explanation":"L'examen clinique doit être systématiquement bilatéral et comparatif ; il est complété par la mesure de l'IPS et par un examen cardiovasculaire général.","src":"p. 170","deep":"**Pourquoi** : comparer les deux membres fait ressortir les différences de couleur, de chaleur, de pouls et de recoloration (p. 170).\n**Piège** : l'examen ne s'arrête pas aux membres : IPS systématique en cas de suspicion ou de dépistage, et examen cardiovasculaire général (coronaires, cérébrovasculaire) (p. 170).\n**À relier** : même règle dans l'ischémie aiguë, où les signes physiques s'apprécient par comparaison avec le membre controlatéral (p. 179)."},{"id":"225-qroc-739","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":2,"question":"Où recherche-t-on systématiquement des troubles trophiques à l'inspection du pied ?","answer":"Dans les espaces interdigitaux","accept":["espaces interdigitaux","interdigitaux","entre les orteils"],"keywords":["interdigit"],"explanation":"À l'inspection, le pied peut être de couleur normale, pâle ou cyanosé, et les troubles trophiques sont systématiquement recherchés, notamment dans les espaces interdigitaux.","src":"p. 170","deep":"**Pourquoi** : les troubles trophiques peuvent se cacher entre les orteils : on les recherche systématiquement dans les espaces interdigitaux (p. 170).\n**Piège** : un pied de couleur normale n'exclut rien : il peut être normal, pâle ou cyanosé (p. 170).\n**À relier** : les ulcères siègent surtout aux zones d'appui ou de frottement, parfois après un geste de pédicure agressif (p. 169)."},{"id":"225-qroc-740","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique","gravité"],"difficulty":2,"question":"Que témoigne une douleur à la pression des masses musculaires du mollet chez un patient atteint d'AOMI ?","answer":"Une ischémie sévère","accept":["ischémie sévère","sévère","ischémie importante"],"keywords":["sever"],"explanation":"À la palpation, le pied peut être froid, et une douleur à la pression des masses musculaires du mollet témoigne d'une ischémie sévère.","src":"p. 170","deep":"**Pourquoi** : à la palpation, une douleur provoquée par la pression des masses musculaires du mollet témoigne d'une ischémie sévère (p. 170).\n**Piège** : ne pas la prendre pour une simple douleur musculaire : les douleurs sous statines peuvent mimer une AOMI, mais les tableaux peuvent être intriqués (p. 174).\n**À relier** : on la retrouve dans l'ischémie aiguë, avec membre froid et livide, pouls abolis en aval, anesthésie et paralysie (p. 179)."},{"id":"225-qroc-741","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Quels sont les quatre pouls recherchés systématiquement à l'examen d'un patient suspect d'AOMI ?","answer":"Fémoral, poplité, tibial postérieur et pédieux","accept":["fémoral poplité tibial postérieur pédieux","fémoral, poplité, tibial postérieur, pédieux","fémoral, poplité, tibial postérieur et pédieux"],"keywords":["femor","poplit","pedieu"],"explanation":"Les pouls fémoral, poplité, tibial postérieur et pédieux sont recherchés à la recherche d'un amortissement ou d'une abolition ; le pouls pédieux peut être absent de façon congénitale chez environ 5 % de la population.","src":"p. 170","deep":"**Pourquoi** : on recherche, des deux côtés, un amortissement ou une abolition des pouls fémoral, poplité, tibial postérieur et pédieux (p. 170).\n**Piège** : le pédieux peut manquer de façon congénitale chez 5 % de la population : son absence isolée ne suffit pas (p. 170).\n**À relier** : l'IPS se mesure justement sur la tibiale postérieure et la pédieuse (p. 170) ; dans l'ischémie aiguë, l'abolition des pouls en aval aide à situer l'occlusion (p. 179)."},{"id":"225-qroc-742","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Quelle est la valeur normale du temps de recoloration cutanée au niveau du pied et des orteils ?","answer":"Moins de 3 secondes","accept":["< 3 secondes","moins de 3 secondes","inférieur à 3 secondes","3 secondes","moins de 3 s"],"keywords":["3"],"explanation":"Dans l'AOMI, le temps de recoloration cutanée est allongé ; il est normalement inférieur à 3 secondes.","src":"p. 170","deep":"**Pourquoi** : le temps de recoloration cutanée est normalement < 3 secondes ; il s'allonge au pied et aux orteils en cas d'AOMI (p. 170).\n**Piège** : c'est un signe parmi d'autres de la palpation (pied froid, douleur du mollet, pouls) : il ne remplace pas l'IPS (p. 170).\n**À relier** : toute suspicion d'AOMI est complétée par l'IPS : AOMI si < 0,90 (p. 170-171)."},{"id":"225-qroc-743","type":"QROC","rank":"A","objective":"225-obj-03","tags":["clinique"],"difficulty":1,"question":"Que recherche-t-on systématiquement à la palpation de l'abdomen et du creux poplité chez un patient suspect d'AOMI ?","answer":"Un anévrisme","accept":["anévrisme","un anévrisme","anevrisme"],"keywords":["anevrism"],"explanation":"Au niveau abdominal et au creux poplité, la recherche d'un anévrisme est systématique chez le patient suspect d'AOMI.","src":"p. 170","deep":"**Pourquoi** : la recherche d'un anévrisme est systématique à l'abdomen et au creux poplité (p. 170) : 80-90 % des AAA surviennent chez des athéromateux, notamment porteurs d'AOMI (rang B, p. 184).\n**Piège** : l'anévrisme poplité se palpe comme une masse battante (pouls trop bien perçu) ; il est associé à un AAA dans 30 % des cas et bilatéral près d'une fois sur deux (p. 186).\n**À relier** : dépistage échographique de l'AAA chez l'homme de plus de 65 ans (p. 184) ; l'échographie recherche aussi les localisations poplitées et iliaques (p. 184)."},{"id":"225-qroc-744","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Avec quel matériel mesure-t-on classiquement l'index de pression systolique ?","answer":"Un brassard tensionnel et un doppler de poche","accept":["brassard tensionnel et doppler de poche","brassard et doppler de poche","brassard et doppler","doppler de poche"],"keywords":["brassard","doppler"],"explanation":"L'IPS est classiquement évalué à l'aide d'un brassard tensionnel et d'un doppler de poche.","src":"p. 170","deep":"**Pourquoi** : le doppler de poche repère le flux ; le brassard est gonflé jusqu'à disparition du signal puis dégonflé, la pression systolique étant lue à sa réapparition (p. 170).\n**Piège** : la pression brachiale se mesure aussi au doppler, aux deux bras (p. 170).\n**À relier** : IPS = pression de cheville la plus élevée / pression brachiale la plus élevée ; AOMI si < 0,90 (p. 171)."},{"id":"225-qroc-745","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"À la cheville, sur quelles deux artères mesure-t-on la pression systolique pour calculer l'IPS ?","answer":"Tibiale postérieure et pédieuse","accept":["tibiale postérieure et pédieuse","pédieuse et tibiale postérieure","pédieux et tibial postérieur"],"keywords":["tibial","pedieu"],"explanation":"La pression systolique est mesurée aux niveaux tibial postérieur et pédieux, au niveau des deux chevilles.","src":"p. 170","deep":"**Pourquoi** : à chaque cheville, on mesure les pressions tibiale postérieure et pédieuse, et on retient la plus élevée (p. 170-171).\n**Piège** : pas la plus basse ; et l'artère fibulaire, de repérage plus difficile, n'est pas mesurée (p. 170).\n**À relier** : le dénominateur est la pression systolique la plus élevée des deux bras (p. 171)."},{"id":"225-qroc-746","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","pièges"],"difficulty":2,"question":"Quelle artère de la cheville n'est pas mesurée pour l'IPS car son repérage est plus difficile ?","answer":"L'artère fibulaire","accept":["fibulaire","artère fibulaire"],"keywords":["fibul"],"explanation":"Pour l'IPS, seules les pressions tibiale postérieure et pédieuse sont mesurées ; la pression de l'artère fibulaire, de repérage plus difficile, n'est pas mesurée.","src":"p. 170","deep":"**Pourquoi** : seules les pressions tibiale postérieure et pédieuse servent à l'IPS ; la fibulaire, plus difficile à repérer, n'est pas mesurée (p. 170).\n**Piège** : ne pas confondre fibulaire (non mesurée) et pédieuse (mesurée, mais congénitalement absente chez 5 %) (p. 170).\n**À relier** : pour chaque membre, on retient la plus haute des deux pressions de cheville (p. 170-171)."},{"id":"225-qroc-747","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Lors de la mesure de l'IPS, à quel moment du dégonflage du brassard lit-on la pression systolique de cheville ?","answer":"À la réapparition du signal doppler","accept":["réapparition du signal","réapparition du signal doppler","réapparition"],"keywords":["reapparition"],"explanation":"Le brassard est gonflé jusqu'à disparition du signal doppler puis dégonflé progressivement ; la pression systolique correspond au moment de la réapparition du signal.","src":"p. 170","deep":"**Pourquoi** : le brassard est gonflé jusqu'à disparition du signal doppler, puis dégonflé progressivement : la pression systolique correspond à la réapparition du signal (p. 170).\n**Piège** : ne pas lire la pression à la disparition du signal (p. 170).\n**À relier** : pression de cheville = la plus élevée des deux artères ; IPS normal entre 1,00 et 1,40 (p. 170-171)."},{"id":"225-qroc-748","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","pièges"],"difficulty":2,"question":"Chez quelles trois catégories de patients est-il conseillé de mesurer la pression d'orteil, l'IPS de repos pouvant être pris en défaut ?","answer":"Les diabétiques, insuffisants rénaux et sujets très âgés","accept":["diabétiques, insuffisants rénaux et très âgés","diabétiques, insuffisants rénaux, sujets très âgés","diabétique, insuffisant rénal, très âgé","diabète, insuffisance rénale, sujet âgé","diabétiques insuffisants rénaux et sujets âgés"],"keywords":["diab","ren","age"],"explanation":"Chez les patients diabétiques, insuffisants rénaux ou très âgés, l'IPS de repos peut être pris en défaut : il est conseillé de mesurer la pression d'orteil.","src":"p. 170","deep":"**Pourquoi** : chez le diabétique, l'insuffisant rénal et le sujet très âgé, l'IPS de repos peut être pris en défaut (p. 170) ; la médiacalcose, fréquente chez le diabétique âgé et le dialysé, rigidifie l'artère et fausse la pression de cheville (p. 171).\n**Piège** : un IPS > 1,40 n'est pas rassurant (médiacalcose) : on utilise l'index de pression d'orteil, pathologique si < 0,70 (p. 171).\n**À relier** : chez un symptomatique à IPS de repos normal, tests d'effort : IPS post-effort et TcPO2 d'effort (p. 170-171)."},{"id":"225-qroc-749","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":3,"question":"Quels sont les deux tests d'effort cités pour sensibiliser le diagnostic chez un patient symptomatique dont l'IPS de repos est normal ?","answer":"IPS post-effort et mesure transcutanée d'oxygène (TcPO2) à l'effort","accept":["ips post-effort et tcpo2","ips après effort et tcpo2","tcpo2 et ips post-effort","ips posteffort et tcpo2"],"keywords":["ips","tcpo2"],"explanation":"Chez les patients symptomatiques à IPS de repos normal, on recourt aux tests d'effort : IPS posteffort et mesure transcutanée d'oxygène (TcPO2) à l'effort.","src":"p. 170-171","deep":"**Pourquoi** : chez un claudicant, l'IPS de repos peut être > 0,90 ; l'effort démasque l'atteinte, d'où l'IPS post-effort et la TcPO2 à l'effort (p. 170-171).\n**Piège** : au tapis roulant, une baisse de la pression de cheville > 30 mmHg et/ou de l'IPS > 20 % juste après la marche évoque l'AOMI (p. 171).\n**À relier** : cette épreuve aide aussi au diagnostic différentiel des douleurs à la marche (canal lombaire étroit, claudication veineuse…) (p. 171, 174)."},{"id":"225-qroc-750","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":1,"question":"Entre quelles valeurs se situe habituellement l'IPS chez le sujet sain ?","answer":"Entre 1,00 et 1,40","accept":["1,00 et 1,40","1 et 1,4","1 à 1,4","1,00 à 1,40","1,0 à 1,4","1 à 1,40","1,0-1,4","de 1 à 1,4"],"keywords":[],"explanation":"Chez le sujet sain, l'IPS est habituellement compris entre 1,00 et 1,40 ; l'AOMI est retenue si au moins une cheville a un IPS inférieur à 0,90.","src":"p. 171","deep":"**Pourquoi** : chez le sujet sain, l'IPS se situe habituellement entre 1,00 et 1,40 (p. 171).\n**Piège** : un IPS > 1,40 n'est pas « excellent » : il traduit une rigidité artérielle par médiacalcose, qui impose la pression d'orteil ; AOMI si < 0,90 sur au moins une cheville, sévère si < 0,70 (p. 171).\n**À relier** : un IPS < 0,90 est aussi un marqueur de risque cardiovasculaire élevé (accident coronarien ou cérébral) (p. 171)."},{"id":"225-qroc-751","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","étiologie"],"difficulty":2,"question":"Chez quels patients la médiacalcose est-elle fréquente ?","answer":"Le diabétique âgé et/ou le patient dialysé","accept":["diabétique âgé","diabétique","dialysé","patient dialysé"],"keywords":[],"explanation":"La médiacalcose (calcification de la média sans rétrécissement intraluminal, différente de l'athérosclérose) est fréquente chez le diabétique âgé et/ou le patient dialysé rénal ; elle donne un IPS > 1,40.","src":"p. 171","deep":"**Pourquoi** : la médiacalcose calcifie la média sans rétrécir la lumière (lésion distincte de l'athérosclérose) ; l'artère devient rigide, typiquement chez le diabétique âgé et/ou le dialysé (p. 171).\n**Piège** : l'artère incompressible donne un IPS anormalement élevé (> 1,40) : un IPS « haut » n'élimine pas une AOMI associée (p. 171).\n**À relier** : on remplace alors la pression de cheville par la pression d'orteil (index < 0,70 = AOMI) ; chez le diabétique, l'insuffisant rénal ou le très âgé, la pression d'orteil est conseillée d'emblée (p. 170-171)."},{"id":"225-qroc-752","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","pièges"],"difficulty":3,"question":"Quelle mesure remplace la pression de cheville lorsque l'IPS est supérieur à 1,40 ?","answer":"La pression d'orteil (avec un manchon adapté)","accept":["pression d'orteil","index de pression d'orteil","pression d'hallux","pression digitale"],"keywords":["orteil"],"explanation":"Un IPS > 1,40 traduit une rigidité artérielle (médiacalcose) : la pression de cheville ne peut plus être estimée correctement et est remplacée par la pression d'orteil, mesurée avec un manchon adapté.","src":"p. 171","deep":"**Pourquoi** : si l'IPS dépasse 1,40, la rigidité artérielle (médiacalcose) empêche d'estimer correctement la pression de cheville ; on mesure la pression d'orteil avec un manchon adapté (p. 171).\n**Piège** : conclure à l'absence d'AOMI devant un IPS > 1,40, alors qu'il est simplement ininterprétable (p. 171).\n**À relier** : index de pression d'orteil < 0,70 = AOMI ; pression d'orteil < 30 mmHg = ischémie critique (avec cheville < 50 mmHg) (p. 169, 171)."},{"id":"225-qroc-753","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quel test de marche, non spécifique de l'AOMI et utilisé aussi dans l'insuffisance cardiaque, évalue le handicap fonctionnel général ?","answer":"Le test de marche de 6 minutes","accept":["test de marche de 6 minutes","test de marche de 6 min","tm6","tm6m","6 minutes"],"keywords":["6","marche"],"explanation":"Le test de marche de 6 minutes n'est pas spécifique de l'AOMI : la distance parcourue en 6 minutes évalue le handicap fonctionnel en général.","src":"p. 171","deep":"**Pourquoi** : la distance parcourue en 6 minutes mesure le handicap fonctionnel global, quelle qu'en soit la cause : il sert aussi dans l'insuffisance cardiaque, donc n'est pas spécifique de l'AOMI (p. 171).\n**Piège** : le test spécifique de l'AOMI est le tapis roulant standardisé (Strandness : 3,2 km/h, pente 10 %) (p. 171).\n**À relier** : le tapis mesure distances de gêne et de marche et remesure les pressions de cheville après l'effort (p. 171)."},{"id":"225-qroc-754","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":3,"question":"Après un test de marche sur tapis roulant, quelle baisse de la pression systolique de cheville est évocatrice d'AOMI ?","answer":"Une baisse > 30 mmHg","accept":["baisse de plus de 30 mmhg","baisse > 30 mmhg","30 mmhg","30","> 30","plus de 30 mmHg","30 mmHg de baisse"],"keywords":["30"],"explanation":"Après la marche, une baisse de la pression systolique de cheville > 30 mmHg et/ou une baisse > 20 % de l'IPS est évocatrice d'AOMI (intérêt pour le diagnostic différentiel des douleurs à la marche).","src":"p. 171","deep":"**Pourquoi** : à l'effort, une sténose hémodynamique empêche le débit d'aval de suivre : juste après la marche, une chute de pression de cheville > 30 mmHg et/ou de l'IPS > 20 % est évocatrice d'AOMI (p. 171).\n**Piège** : un IPS de repos > 0,90 n'élimine pas l'AOMI chez un claudicant : c'est l'indication même du test (p. 171).\n**À relier** : intérêt pour le diagnostic différentiel des douleurs à la marche (canal lombaire étroit, causes veineuses…) (p. 171, 174)."},{"id":"225-qroc-755","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Que permet d'évaluer le test de marche sur tapis roulant en dehors de la réévaluation des pressions de cheville ?","answer":"La distance de gêne et la distance de marche","accept":["distance de gêne et distance de marche","distances de gêne et de marche","distance de gêne et la distance de marche"],"keywords":["gene","marche"],"explanation":"Le test standardisé sur tapis roulant évalue la distance de gêne et la distance de marche (utile pour suivre l'évolution lors d'examens répétés) et réévalue les pressions de cheville après la marche.","src":"p. 171","deep":"**Pourquoi** : le tapis roulant standardisé (Strandness : 3,2 km/h, pente 10 %) chiffre la distance de gêne (premiers symptômes) et la distance de marche (arrêt), comparables d'un examen à l'autre (p. 171).\n**Piège** : distance de gêne ≠ distance de marche : la première marque l'apparition de la douleur, la seconde l'arrêt obligé (p. 168).\n**À relier** : claudication sévère si distance de marche < 100 m, seuil qui peut faire discuter une revascularisation d'emblée (p. 169, 176)."},{"id":"225-qroc-756","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Chez le sujet sain, quelle est la valeur de la TcPO2 au dos du pied ?","answer":"Supérieure à 50 mmHg","accept":["supérieure à 50 mmhg","plus de 50 mmhg","> 50 mmhg","50 mmhg","> 50","plus de 50"],"keywords":["50"],"explanation":"Après hyperémie provoquée par la chaleur, la TcPO2 au dos du pied est supérieure à 50 mmHg chez le sujet sain.","src":"p. 171","deep":"**Pourquoi** : après hyperémie par la chaleur, qui artérialise le flux cutané, la TcPO2 au dos du pied dépasse 50 mmHg chez le sujet sain (p. 171).\n**Piège** : ne pas confondre avec la PO2 cutanée basale (3-4 mmHg), très basse même sur peau saine, donc non discriminante (p. 171).\n**À relier** : paliers : > 35 mmHg bonne compensation, 10-35 hypoxie continue, < 10 hypoxie critique (p. 171)."},{"id":"225-qroc-757","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":3,"question":"Que traduit une TcPO2 comprise entre 10 et 35 mmHg ?","answer":"Une hypoxie continue","accept":["hypoxie continue","une hypoxie continue"],"keywords":["hypoxie","continue"],"explanation":"Une TcPO2 > 35 mmHg témoigne d'une bonne compensation métabolique, entre 10 et 35 mmHg d'une hypoxie continue, et < 10 mmHg d'une hypoxie critique.","src":"p. 171","deep":"**Pourquoi** : entre 10 et 35 mmHg (après hyperémie), l'oxygénation cutanée est insuffisante de façon permanente : hypoxie continue (p. 171).\n**Piège** : ce n'est pas encore l'hypoxie critique, réservée aux valeurs < 10 mmHg (p. 171).\n**À relier** : la TcPO2 sert au diagnostic de l'ischémie critique et à choisir un niveau d'amputation en zone bien oxygénée (p. 171, 177)."},{"id":"225-qroc-758","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"question":"Quelle valeur de TcPO2 témoigne d'une bonne compensation métabolique de l'artériopathie ?","answer":"Supérieure à 35 mmHg","accept":["supérieure à 35 mmhg","plus de 35 mmhg","> 35 mmhg","35 mmhg","> 35","plus de 35"],"keywords":["35"],"explanation":"Une TcPO2 > 35 mmHg témoigne d'une bonne compensation métabolique de l'artériopathie ; entre 10 et 35 mmHg il existe une hypoxie continue.","src":"p. 171","deep":"**Pourquoi** : au-dessus de 35 mmHg, la peau reste correctement oxygénée malgré l'artériopathie : bonne compensation métabolique (p. 171).\n**Piège** : ne pas confondre ce seuil avec la normale du sujet sain (> 50 mmHg) (p. 171).\n**À relier** : 10-35 mmHg = hypoxie continue, < 10 = hypoxie critique (p. 171)."},{"id":"225-qroc-759","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","physiopathologie"],"difficulty":3,"question":"Pourquoi provoque-t-on une hyperémie par la chaleur lors de la mesure de la TcPO2 ?","answer":"Pour artérialiser le flux sanguin cutané","accept":["artérialiser","artérialiser le flux","artérialisation"],"keywords":["arterial"],"explanation":"À l'état basal, la PO2 cutanée est très basse (3 à 4 mmHg) et identique sur peau saine ou ischémique ; l'hyperémie par la chaleur artérialise le flux et rend l'examen discriminant.","src":"p. 171","deep":"**Pourquoi** : à l'état basal, la PO2 cutanée est très basse (3-4 mmHg) et identique sur peau saine ou ischémique ; l'hyperémie par la chaleur artérialise le flux et rend l'examen discriminant (p. 171).\n**Piège** : la chaleur n'est pas un traitement ni une épreuve d'effort : elle conditionne seulement la mesure (p. 171).\n**À relier** : TcPO2 utile au diagnostic et à l'évaluation de l'ischémie critique, et au choix du niveau d'amputation (p. 171, 177)."},{"id":"225-qroc-760","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie","paraclinique"],"difficulty":1,"question":"Pourquoi l'échodoppler artériel est-il l'exploration la plus fréquemment utilisée dans l'AOMI ?","answer":"Parce qu'il est non invasif","accept":["non invasif","caractère non invasif","pas invasif"],"keywords":["non invasif"],"explanation":"L'échodoppler est l'exploration la plus utilisée du fait de son caractère non invasif ; il identifie les lésions et quantifie leur sévérité dans l'immense majorité des cas.","src":"p. 172","deep":"**Pourquoi** : son caractère non invasif en fait l'exploration la plus utilisée : l'échographie localise et caractérise les lésions, le doppler renseigne sur les flux ; il identifie et quantifie les lésions dans l'immense majorité des cas (p. 172).\n**Piège** : angioscanner, angio-IRM et artériographie ne sont demandés que s'il existe une indication de revascularisation (p. 172) ; l'artériographie est réservée aux procédures de revascularisation (p. 173, 187).\n**À relier** : le diagnostic d'AOMI repose d'abord sur l'IPS (< 0,90), l'échodoppler localisant ensuite les lésions (p. 171, 187)."},{"id":"225-qroc-761","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quels deux types d'informations apporte la combinaison de l'échographie et du doppler artériel dans l'AOMI ?","answer":"Anatomiques (lésions) et hémodynamiques (flux)","accept":["anatomiques et hémodynamiques","anatomiques","hémodynamiques","anatomie et hémodynamique","anatomique et hémodynamique","morphologiques et hémodynamiques"],"keywords":["anatom","hemodynam"],"explanation":"L'échographie-doppler donne des informations anatomiques sur la localisation et le type des lésions, et des données hémodynamiques sur les flux.","src":"p. 172","deep":"**Pourquoi** : l'échographie donne l'anatomie (localisation, type des lésions) et le doppler l'hémodynamique (flux), d'où la quantification de la sévérité (p. 172).\n**Piège** : répondre « anatomiques » seulement : l'intérêt de l'examen est la combinaison des deux (p. 172).\n**À relier** : flux normal triphasique à la fémorale ; une sténose donne un flux turbulent en mosaïque à l'écho-doppler couleur (fig. 7.2, p. 172)."},{"id":"225-qroc-762","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quel est l'aspect normal du flux doppler d'une artère fémorale ?","answer":"Un flux triphasique","accept":["flux triphasique","triphasique"],"keywords":["triphasi"],"explanation":"Le doppler normal d'une artère fémorale montre un flux triphasique ; une sténose crée un flux laminaire puis turbulent (en mosaïque) à l'échodoppler couleur.","src":"p. 172","deep":"**Pourquoi** : le flux doppler normal d'une artère fémorale est triphasique (fig. 7.2, p. 172).\n**Piège** : un flux turbulent (en mosaïque) à l'écho-doppler couleur témoigne d'une sténose, pas d'un aspect normal (fig. 7.2, p. 172).\n**À relier** : l'échodoppler apporte à la fois l'anatomie et ces données hémodynamiques, d'où son rôle central (p. 172)."},{"id":"225-qroc-763","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Que cherche-t-on à étudier avec l'angioscanner, l'angio-IRM ou l'artériographie lorsqu'ils sont demandés dans l'AOMI ?","answer":"La faisabilité et les modalités de la revascularisation","accept":["faisabilité de la revascularisation","faisabilité et modalités","modalités de la revascularisation","stratégie de revascularisation"],"keywords":["faisabilit"],"explanation":"Ces examens, qui donnent une vision simultanée de tout l'arbre artériel (sténoses, occlusions, collatérales), ne sont demandés que s'il existe une indication de revascularisation, pour en étudier la faisabilité et les modalités.","src":"p. 172","deep":"**Pourquoi** : ils montrent tout l'arbre artériel d'un coup (sténoses, occlusions, collatérales) : c'est ce dont on a besoin pour décider de la faisabilité et de la stratégie d'une revascularisation (p. 172).\n**Piège** : ce ne sont pas des examens de diagnostic initial : ils ne sont demandés que s'il existe une indication de revascularisation (p. 172).\n**À relier** : angioscanner : vérifier allergies et fonction rénale (iode) ; angio-IRM : gadolinium contre-indiqué si clairance < 30 mL/min/1,73 m² (p. 172-173)."},{"id":"225-qroc-764","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quel avantage l'angio-IRM présente-t-elle sur l'angioscanner ?","answer":"Elle évite les rayonnements ionisants","accept":["pas de rayonnements ionisants","évite les radiations ionisantes","sans rayonnement ionisant","pas d'irradiation"],"keywords":["ionisant"],"explanation":"L'angio-IRM (ARM) est une alternative qui évite les radiations ionisantes ; le gadolinium reste contre-indiqué en cas d'insuffisance rénale sévère.","src":"p. 173","deep":"**Pourquoi** : l'angio-IRM visualise l'ensemble de l'arbre artériel sans radiations ionisantes (p. 173).\n**Piège** : elle a ses propres limites : gadolinium contre-indiqué si insuffisance rénale sévère, et elle ne voit pas les calcifications utiles au chirurgien avant un pontage (p. 173).\n**À relier** : performances diagnostiques équivalentes à l'angioscanner (sensibilité et spécificité ≈ 95 % par rapport à l'artériographie) (p. 173)."},{"id":"225-qroc-765","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"En dessous de quelle clairance de la créatinine l'injection de gadolinium pour une angio-IRM est-elle contre-indiquée ?","answer":"Clairance < 30 mL/min/1,73 m²","accept":["30 ml/min","moins de 30 ml/min","inférieure à 30","< 30 ml/min/1,73 m2"],"keywords":["30"],"explanation":"Le gadolinium reste contre-indiqué en cas d'insuffisance rénale sévère, définie par une clairance < 30 mL/min/1,73 m².","src":"p. 173","deep":"**Pourquoi** : l'insuffisance rénale sévère (clairance < 30 mL/min/1,73 m²) contre-indique l'injection de gadolinium (p. 173).\n**Piège** : ne pas confondre avec la précaution de l'angioscanner, dont l'iode impose de vérifier allergies et fonction rénale (p. 172).\n**À relier** : après revascularisation d'une ischémie aiguë, les produits de contraste participent aussi à la toxicité rénale (p. 179)."},{"id":"225-qroc-766","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie","pièges"],"difficulty":3,"question":"Quels éléments, importants à connaître pour le chirurgien avant un pontage, l'angio-IRM ne permet-elle pas de visualiser ?","answer":"Les calcifications artérielles","accept":["calcifications","calcification","calcifications artérielles"],"keywords":["calcif"],"explanation":"L'angio-IRM ne visualise pas les calcifications, importantes à connaître pour le chirurgien lorsqu'un pontage est envisagé ; l'angioscanner, lui, étudie le chenal circulant et la paroi.","src":"p. 173","deep":"**Pourquoi** : l'angio-IRM ne visualise pas les calcifications, alors que le chirurgien doit les connaître lorsqu'un pontage est envisagé (p. 173).\n**Piège** : à performances diagnostiques équivalentes (≈ 95 %), angio-IRM et angioscanner n'ont pas les mêmes limites ; l'angioscanner étudie le chenal circulant et la paroi (p. 172-173).\n**À relier** : angio-IRM : pas de radiation, mais gadolinium contre-indiqué si clairance < 30 mL/min/1,73 m² (p. 173)."},{"id":"225-qroc-767","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quelles sont les sensibilité et spécificité de l'angioscanner et de l'angio-IRM comparées à l'artériographie ?","answer":"Équivalentes, de l'ordre de 95 %","accept":["95 %","environ 95 %","95","équivalentes"],"keywords":["95"],"explanation":"Les performances diagnostiques de l'angioscanner et de l'ARM sont équivalentes, avec une sensibilité et une spécificité de l'ordre de 95 % par rapport à l'artériographie.","src":"p. 173","deep":"**Pourquoi** : comparés à l'artériographie, angioscanner et angio-IRM ont des performances équivalentes, avec sensibilité et spécificité d'environ 95 % (p. 173).\n**Piège** : croire l'angio-IRM moins performante : seules leurs limites diffèrent (irradiation et iode pour l'un, gadolinium et calcifications pour l'autre) (p. 172-173).\n**À relier** : l'artériographie, ancienne référence, est désormais limitée aux procédures de revascularisation (p. 173)."},{"id":"225-qroc-768","type":"QROC","rank":"A","objective":"225-obj-04","tags":["imagerie"],"difficulty":2,"question":"Quel réseau artériel l'artériographie reste-t-elle souvent nécessaire pour visualiser en cas de revascularisation distale ?","answer":"Le réseau jambier et pédieux","accept":["réseau jambier et pédieux","jambier et pédieux","jambier","artères jambières"],"keywords":["jambier"],"explanation":"L'artériographie, qui nécessite une ponction artérielle directe, est aujourd'hui limitée aux procédures de revascularisation ; elle reste souvent nécessaire pour bien visualiser le réseau jambier et pédieux en cas de revascularisation distale.","src":"p. 173","deep":"**Pourquoi** : pour une revascularisation distale, il faut bien voir les artères de jambe et du pied ; l'artériographie reste souvent nécessaire pour ce réseau jambier et pédieux (p. 173).\n**Piège** : elle nécessite une ponction artérielle directe et du contraste : elle n'est plus un examen diagnostique, mais un temps des procédures de revascularisation (p. 173).\n**À relier** : dans l'ischémie aiguë, l'artériographie est le plus souvent réalisée au bloc pour guider le geste et apprécier le réseau d'aval (p. 180)."},{"id":"225-qroc-769","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Quel tableau fait évoquer une atteinte médullaire plutôt qu'une AOMI devant une gêne à la marche ?","answer":"Parésie du membre sans douleur, avec dérobement des jambes","accept":["parésie sans douleur","dérobement des jambes","dérobement","parésie du membre sans douleur"],"keywords":["derobement"],"explanation":"Parmi les causes neurologiques de douleurs à la marche, le canal lombaire étroit donne des douleurs ou paresthésies à l'effort cédant au repos ; l'atteinte médullaire donne une parésie du membre sans douleur avec dérobement des jambes.","src":"p. 174","deep":"**Pourquoi** : une gêne à la marche sans douleur, avec parésie et dérobement des jambes, évoque une atteinte médullaire, cause neurologique du diagnostic différentiel (p. 174).\n**Piège** : le canal lombaire étroit, lui, donne des douleurs ou paresthésies d'effort cédant au repos, proches d'une claudication artérielle (p. 174).\n**À relier** : l'IPS (< 0,90), éventuellement après test de marche, tranche entre cause artérielle et autre cause (p. 171)."},{"id":"225-qroc-770","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":1,"question":"Quelle cause veineuse peut mimer une claudication artérielle ?","answer":"La claudication veineuse (post-thrombotique)","accept":["claudication veineuse","post-thrombotique","séquelle post-thrombotique"],"keywords":["veineuse"],"explanation":"Les diagnostics différentiels d'une douleur à la marche incluent causes neurologiques, rhumatologiques, veineuses (claudication veineuse post-thrombotique), vasculaires (piège poplité, kyste poplité, endofibrose iliaque, syndrome des loges) et musculaires (statines).","src":"p. 174","deep":"**Pourquoi** : la claudication veineuse post-thrombotique figure parmi les causes de douleur à la marche qui peuvent mimer une claudication artérielle (p. 174).\n**Piège** : conclure à une AOMI sur la seule douleur d'effort : examen comparatif des pouls et IPS sont systématiques (p. 170).\n**À relier** : autres mimes à la marche : canal lombaire étroit, causes rhumatologiques, piège ou kyste poplité, endofibrose iliaque, syndrome des loges, myalgies sous statines (p. 174)."},{"id":"225-qroc-771","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Citez un diagnostic différentiel d'une douleur de décubitus d'origine non artérielle.","answer":"Neuropathie sensorielle, SDRC ou compression radiculaire","accept":["neuropathie sensorielle","neuropathie","algodystrophie","causalgie","syndrome régional douloureux complexe","compression radiculaire","SDRC","syndrome douloureux régional complexe","neuropathie diabétique"],"keywords":[],"explanation":"En cas de douleur de décubitus, il faut évoquer une neuropathie sensorielle (diabétique, toxique, carencielle), un syndrome régional douloureux complexe (anciennes algodystrophies et causalgies) ou une compression radiculaire.","src":"p. 174","deep":"**Pourquoi** : une douleur de décubitus non artérielle relève d'une neuropathie sensorielle (diabétique, toxique, carentielle), d'un syndrome régional douloureux complexe ou d'une compression radiculaire (p. 174).\n**Piège** : l'ischémie permanente (stade III) donne des brûlures des orteils et de l'avant-pied après quelques minutes à heures de décubitus, soulagées jambe pendante, avec pied froid, pâle ou cyanosé (p. 169).\n**À relier** : chez le diabétique, la neuropathie peut aussi masquer l'AOMI, révélée d'emblée par une ischémie permanente (p. 169)."},{"id":"225-qroc-772","type":"QROC","rank":"A","objective":"225-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Citez un diagnostic différentiel de l'ulcère artériel.","answer":"Ulcère veineux, microcirculatoire, neuropathique ou traumatique","accept":["ulcère veineux","veineux","microcirculatoire","neuropathique","traumatique","ulcère neuropathique"],"keywords":[],"explanation":"Devant un ulcère de jambe, les diagnostics différentiels de l'ulcère artériel sont les ulcères veineux, microcirculatoires, neuropathiques et traumatiques.","src":"p. 174","deep":"**Pourquoi** : devant un ulcère, il faut discuter les autres mécanismes : veineux, microcirculatoire, neuropathique, traumatique (p. 174).\n**Piège** : un artéritique peut avoir un ulcère d'une autre cause : le siège (zones d'appui/frottement, face antérieure de jambe pour l'ulcère « suspendu »), la douleur et l'IPS orientent (p. 169-171).\n**À relier** : l'ulcère artériel est un trouble trophique de stade IV = ischémie permanente, à revasculariser autant que possible (p. 169, 176)."},{"id":"225-qroc-773","type":"QROC","rank":"A","objective":"225-obj-03","tags":["pièges","diagnostic"],"difficulty":2,"question":"Chez le sujet âgé, quel terme décrit le fait qu'une AOMI et une autre cause de douleur de membre puissent coexister ?","answer":"Des tableaux intriqués (causes qui peuvent coexister)","accept":["peuvent coexister","tableaux intriqués","intriquées","intriqués","coexistent","intriqué","intrication","causes associées"],"keywords":[],"explanation":"Certaines étiologies de douleurs de membres peuvent coexister, notamment chez les sujets âgés : ainsi les douleurs musculaires sous statines peuvent mimer une AOMI, mais il faut se méfier des tableaux intriqués.","src":"p. 174","deep":"**Pourquoi** : chez le sujet âgé, plusieurs causes de douleur de membre peuvent coexister avec l'AOMI ; les myalgies sous statines peuvent la mimer, mais les tableaux sont souvent intriqués (p. 174).\n**Piège** : s'arrêter à la cause la plus évidente : une autre cause identifiée n'élimine pas une AOMI associée (p. 174).\n**À relier** : l'IPS, examen de 1re ligne, documente la part artérielle (p. 170-171)."},{"id":"225-qroc-774","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Quelle artériopathie non athéromateuse touche les artères iliaques ou poplitées des membres inférieurs ?","answer":"La dysplasie fibromusculaire","accept":["dysplasie fibromusculaire","dysplasie fibro-musculaire"],"keywords":["dysplasie"],"explanation":"Parmi les artériopathies non athéromateuses, la dysplasie fibromusculaire touche le niveau iliaque ou poplité ; l'AOMI athéromateuse représente plus de 95 % des atteintes oblitérantes.","src":"p. 174","deep":"**Pourquoi** : la dysplasie fibromusculaire est une artériopathie non athéromateuse qui peut toucher l'étage iliaque ou poplité (p. 174).\n**Piège** : elle est rare : l'athérome représente plus de 95 % des atteintes artérielles oblitérantes des membres inférieurs (p. 174).\n**À relier** : autres causes non athéromateuses : inflammatoires (Buerger, Takayasu, Horton, collagénoses), coarctation, postradiques, post-traumatiques, toxiques, gelures, compressions (p. 174)."},{"id":"225-qroc-775","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Quelle malformation de l'aorte est une cause d'hypodébit en aval, dont les membres inférieurs ?","answer":"La coarctation de l'aorte","accept":["coarctation de l'aorte","coarctation","coarctation aortique"],"keywords":["coarctation"],"explanation":"La coarctation de l'aorte est une artériopathie non athéromateuse, cause d'hypodébit en aval, notamment aux membres inférieurs.","src":"p. 174","deep":"**Pourquoi** : la coarctation de l'aorte rétrécit l'aorte et réduit le débit en aval, notamment vers les membres inférieurs (p. 174).\n**Piège** : c'est une exception : plus de 95 % des atteintes oblitérantes des membres inférieurs sont athéromateuses (p. 174).\n**À relier** : l'AOMI athéromateuse est la 3ᵉ localisation de l'athérosclérose après coronaires et cerveau (p. 167)."},{"id":"225-qroc-776","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Quels dérivés toxiques peuvent provoquer une artériopathie non athéromateuse des membres inférieurs ?","answer":"Les dérivés de l'ergot de seigle","accept":["ergot de seigle","dérivés de l'ergot de seigle","ergot"],"keywords":["ergot"],"explanation":"Les atteintes toxiques (dérivés de l'ergot de seigle, etc.) font partie des artériopathies non athéromateuses, avec les atteintes postradiques, post-traumatiques, les gelures et les compressions extrinsèques.","src":"p. 174","deep":"**Pourquoi** : les dérivés de l'ergot de seigle sont la cause toxique d'artériopathie non athéromateuse citée par le Collège (p. 174).\n**Piège** : l'ergotisme apparaît aussi parmi les causes iatrogènes de thrombose artérielle in situ, avec le cathétérisme et la thrombopénie à l'héparine (p. 181).\n**À relier** : autres causes non athéromateuses : postradiques, post-traumatiques, gelures, compressions extrinsèques (p. 174)."},{"id":"225-qroc-777","type":"QROC","rank":"B","objective":"225-obj-02","tags":["étiologie"],"difficulty":2,"question":"Citez une atteinte artérielle non athéromateuse spécifique de l'artère poplitée.","answer":"Artère poplitée piégée ou kyste poplité sous-adventiciel","accept":["artère poplitée piégée","poplitée piégée","kyste poplité","kyste sous-adventiciel","kyste poplité sous-adventiciel"],"keywords":[],"explanation":"Les atteintes spécifiques de l'artère poplitée sont l'artère poplitée piégée et le kyste poplité sous-adventiciel.","src":"p. 174","deep":"**Pourquoi** : l'artère poplitée a deux atteintes spécifiques non athéromateuses : l'artère poplitée piégée et le kyste poplité sous-adventiciel (p. 174).\n**Piège** : ces mêmes entités figurent dans le diagnostic différentiel des douleurs à la marche, et le kyste adventiciel peut se compliquer de thrombose in situ (p. 174, 181).\n**À relier** : ne pas les confondre avec l'anévrisme poplité, souvent associé à un AAA (30 %) et bilatéral une fois sur deux (p. 186)."},{"id":"225-qroc-778","type":"QROC","rank":"A","objective":"225-obj-04","tags":["paraclinique","diagnostic"],"difficulty":1,"question":"Combien de chevilles doivent avoir un IPS inférieur à 0,90 pour retenir le diagnostic d'AOMI ?","answer":"Au moins une cheville","accept":["au moins une","une seule cheville","une cheville","au moins une cheville"],"keywords":["au moins"],"explanation":"Le patient est atteint d'AOMI si au moins l'une des deux chevilles présente un IPS inférieur à 0,90 ; l'AOMI est sévère si l'IPS est inférieur à 0,70.","src":"p. 171","deep":"**Pourquoi** : l'AOMI est retenue si au moins l'une des deux chevilles a un IPS < 0,90 ; chaque membre a son propre IPS (p. 171).\n**Piège** : une cheville normale ne rassure pas sur l'autre ; et un IPS > 1,40 (médiacalcose) n'est pas « normal » (p. 171).\n**À relier** : sévère si < 0,70 ; un IPS < 0,90 est aussi un marqueur de risque cardiovasculaire élevé (p. 171)."},{"id":"225-qroc-779","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","prévention"],"difficulty":1,"question":"Quelles sont les deux mesures prioritaires du contrôle des facteurs de risque dans l'AOMI ?","answer":"L'arrêt du tabac et le contrôle du diabète","accept":["arrêt du tabac et contrôle du diabète","tabac et diabète","arrêt du tabac et diabète","sevrage tabagique et diabète"],"keywords":["tabac","diab"],"explanation":"Le traitement à visée générale s'applique à tout stade ; le contrôle des facteurs de risque, aux premiers chefs l'arrêt du tabac et le contrôle du diabète, est essentiel.","src":"p. 175","deep":"**Pourquoi** : le Collège place « aux premiers chefs » l'arrêt du tabac et le contrôle du diabète dans le contrôle des facteurs de risque, essentiel à tout stade (p. 175).\n**Piège** : ces mesures ne se limitent pas aux symptomatiques : le traitement à visée générale s'applique à tout stade d'artériopathie (p. 175).\n**À relier** : (rang B) tabac et diabète sont les deux principaux facteurs de risque de l'AOMI (p. 168) ; cibles : HbA1c < 7 %, LDL < 0,55 g/L, PAS ≤ 120-129 mmHg (p. 175)."},{"id":"225-qroc-780","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle est la cible de pression artérielle systolique dans le traitement à visée générale d'un patient atteint d'AOMI ?","answer":"PAS ≤ 120-129 mmHg","accept":["120-129","120 à 129","entre 120 et 129","≤ 120-129 mmhg"],"keywords":["120","129"],"explanation":"Cibles du traitement général : PAS ≤ 120-129 mmHg, PAD ≤ 70-79 mmHg, HbA1c < 7 %, LDL-cholestérol < 0,55 g/L (< 1,4 mmol/L), IMC entre 20 et 25 kg/m².","src":"p. 175","deep":"**Pourquoi** : le traitement général de l'AOMI vise une PAS ≤ 120-129 mmHg (et PAD ≤ 70-79 mmHg) pour réduire le risque cardiovasculaire (p. 175).\n**Piège** : ne pas confondre avec le seuil de 140/90 mmHg mentionné pour l'intérêt pronostique des IEC (p. 175).\n**À relier** : IEC ou sartan envisageable chez tout patient avec AOMI, quel que soit le niveau de PA, sauf contre-indication (p. 175)."},{"id":"225-qroc-781","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quel objectif de PAD fixe-t-on chez l'artériopathe, parallèlement à la cible de PAS ?","answer":"PAD ≤ 70-79 mmHg","accept":["70-79","70 à 79","entre 70 et 79","≤ 70-79 mmhg"],"keywords":["70","79"],"explanation":"La cible tensionnelle du patient artériopathe est une PAS ≤ 120-129 mmHg et une PAD ≤ 70-79 mmHg ; un IEC ou un sartan peut être considéré chez tous, quel que soit le niveau de PA.","src":"p. 175","deep":"**Pourquoi** : la cible tensionnelle associe PAS ≤ 120-129 mmHg et PAD ≤ 70-79 mmHg (p. 175).\n**Piège** : ne pas inverser les deux plages, ni retenir 140/90, seuil cité pour l'intérêt pronostique des IEC (p. 175).\n**À relier** : autres cibles du traitement général : HbA1c < 7 %, LDL < 0,55 g/L (< 1,4 mmol/L), IMC 20-25 kg/m² (p. 175)."},{"id":"225-qroc-782","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle est la cible d'HbA1c chez un patient atteint d'AOMI ?","answer":"HbA1c < 7 %","accept":["< 7 %","inférieure à 7 %","moins de 7 %","7 %","< 7","7"],"keywords":["7"],"explanation":"Dans le traitement à visée générale de l'AOMI, la cible d'HbA1c est < 7 %, avec le contrôle des autres facteurs de risque et l'arrêt du tabac.","src":"p. 175","deep":"**Pourquoi** : HbA1c < 7 % est la cible glycémique du traitement à visée générale, le contrôle du diabète étant avec l'arrêt du tabac une mesure de premier plan (p. 175).\n**Piège** : la cible est la même quel que soit le stade : le traitement général s'applique à tout stade d'artériopathie (p. 175).\n**À relier** : le diabète donne des formes graves d'emblée et distales, et une médiacalcose qui fausse l'IPS (p. 168, 171)."},{"id":"225-qroc-783","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","prévention"],"difficulty":2,"question":"Quelle plage d'indice de masse corporelle est préconisée dans le traitement général de l'AOMI ?","answer":"Entre 20 et 25 kg/m²","accept":["20 et 25","20-25","20 à 25","entre 20 et 25 kg/m2"],"keywords":["20","25"],"explanation":"Sont préconisés l'arrêt du tabac, le régime méditerranéen, un IMC entre 20 et 25 kg/m² et un exercice modéré, avec un réentraînement à raison de 3 fois par semaine pendant 12 semaines.","src":"p. 175","deep":"**Pourquoi** : un IMC entre 20 et 25 kg/m² fait partie des mesures hygiénodiététiques préconisées, avec régime méditerranéen, exercice modéré et arrêt du tabac (p. 175).\n**Piège** : ne pas donner une cible « < 30 » : la plage visée est la normale, 20-25 kg/m² (p. 175).\n**À relier** : réentraînement visé : 3 fois/semaine pendant 12 semaines ; marche 30-45 min au moins 3 fois/semaine (p. 175)."},{"id":"225-qroc-784","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelles complications l'antiagrégant plaquettaire vise-t-il à réduire chez le patient atteint d'AOMI symptomatique ?","answer":"Les complications cardiovasculaires : infarctus et AVC","accept":["infarctus et avc","infarctus","avc","complications cardiovasculaires"],"keywords":[],"explanation":"Tout patient atteint d'AOMI symptomatique doit recevoir un antiagrégant plaquettaire (aspirine ou clopidogrel) afin de réduire le risque de complications cardiovasculaires (infarctus, AVC).","src":"p. 175","deep":"**Pourquoi** : l'AOMI témoigne d'un athérome diffus : l'antiagrégant (aspirine ou clopidogrel) réduit le risque de complications cardiovasculaires, infarctus et AVC (p. 175).\n**Piège** : il n'est pas prescrit pour allonger la distance de marche ; et en AOMI asymptomatique, son intérêt est débattu sauf autre territoire atteint (p. 175).\n**À relier** : à 5 ans, 20 % des claudicants ont une complication cardiovasculaire et 20 % décèdent, pour moitié de cause cardiovasculaire (p. 177)."},{"id":"225-qroc-785","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":3,"question":"Chez un patient ayant une AOMI asymptomatique (IPS < 0,90), dans quel cas le recours aux antiplaquettaires est-il plutôt retenu, malgré un bénéfice débattu ?","answer":"S'il existe d'autres atteintes athéromateuses (ex : cardiopathie ischémique)","accept":["autres atteintes athéromateuses","autre territoire athéromateux","cardiopathie ischémique","atteinte coronarienne"],"keywords":[],"explanation":"En cas d'AOMI asymptomatique (IPS < 0,90), le recours aux antiplaquettaires est débattu, à moins que le patient ait aussi une atteinte athéromateuse dans un autre territoire, par exemple une cardiopathie ischémique.","src":"p. 175","deep":"**Pourquoi** : en AOMI asymptomatique (IPS < 0,90), le bénéfice des antiplaquettaires est débattu ; on les retient plutôt si l'athérome touche un autre territoire, par exemple une cardiopathie ischémique (p. 175).\n**Piège** : en AOMI symptomatique, la règle est différente : tout patient doit recevoir aspirine ou clopidogrel (p. 175).\n**À relier** : devant toute AOMI, rechercher une maladie coronarienne ou une sténose carotidienne, orientée par la clinique (p. 177, 188)."},{"id":"225-qroc-786","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Le recours aux IEC a un intérêt pronostique chez l'artériopathe en maintenant la pression artérielle sous quelle valeur ?","answer":"Une PA inférieure à 140/90 mmHg","accept":["140/90","< 140/90 mmhg","inférieure à 140/90","moins de 140/90"],"keywords":["140","90"],"explanation":"Le recours aux IEC a un intérêt pronostique en maintenant la pression artérielle inférieure à 140/90 mmHg ; la cible du traitement général reste PAS ≤ 120-129 mmHg.","src":"p. 175","deep":"**Pourquoi** : le Collège attribue aux IEC un intérêt pronostique en maintenant la PA sous 140/90 mmHg (p. 175).\n**Piège** : deux chiffres coexistent : 140/90 pour l'intérêt des IEC, et la cible générale plus stricte PAS ≤ 120-129 / PAD ≤ 70-79 mmHg (p. 175).\n**À relier** : un IEC ou un sartan peut être envisagé chez tout patient avec AOMI, quel que soit son niveau de PA (p. 175)."},{"id":"225-qroc-787","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","pièges"],"difficulty":2,"question":"Citez une indication formelle justifiant un bêtabloquant chez un patient atteint d'AOMI.","answer":"Cardiopathie ischémique, IC à FEVG altérée ou certaines arythmies","accept":["cardiopathie ischémique","insuffisance cardiaque à fraction d'éjection altérée","insuffisance cardiaque","arythmie","arythmies"],"keywords":[],"explanation":"Les bêtabloquants peuvent être proposés en cas d'indication formelle (cardiopathie ischémique, insuffisance cardiaque à fraction d'éjection altérée, certaines arythmies), avec prudence en cas d'ischémie critique sans revascularisation possible.","src":"p. 175","deep":"**Pourquoi** : le bêtabloquant n'est pas un traitement de l'AOMI : il se prescrit s'il existe une indication formelle (cardiopathie ischémique, insuffisance cardiaque à FE altérée, certaines arythmies) (p. 175).\n**Piège** : il n'est pas contre-indiqué dans l'AOMI ; seule une prudence est demandée en ischémie critique sans revascularisation possible (p. 175).\n**À relier** : socle médicamenteux de l'AOMI symptomatique : antiagrégant + statine ± IEC (fig. 7.6, p. 177)."},{"id":"225-qroc-788","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quel effet de la statine peut s'observer sur la marche à l'instauration du traitement chez l'artériopathe ?","answer":"Une augmentation du périmètre de marche","accept":["augmentation du périmètre de marche","allongement du périmètre de marche","amélioration du périmètre de marche","augmente le périmètre de marche"],"keywords":["perimetre"],"explanation":"L'instauration d'un traitement par statine peut s'accompagner d'une augmentation du périmètre de marche, en plus de son effet pronostique cardiovasculaire (LDL < 0,55 g/L).","src":"p. 176","deep":"**Pourquoi** : au-delà de son effet sur le LDL et le risque cardiovasculaire, l'instauration d'une statine peut s'accompagner d'une augmentation du périmètre de marche (p. 176).\n**Piège** : cet effet ne remplace ni la réadaptation à la marche ni l'arrêt du tabac (p. 175).\n**À relier** : statine systématique : LDL < 0,55 g/L avec baisse ≥ 50 % de la valeur initiale (p. 175)."},{"id":"225-qroc-789","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelles durée et fréquence minimales de marche régulière sont recommandées dans l'AOMI (deux éléments attendus) ?","answer":"30-45 minutes, au moins 3 fois par semaine","accept":["30-45 minutes 3 fois par semaine","30 à 45 minutes","30-45 minutes","3 fois par semaine"],"keywords":["30","45","3"],"explanation":"La marche consiste au minimum en une marche régulière de 30-45 minutes, au moins 3 fois par semaine, en ralentissant le pas ou en s'arrêtant quelques minutes au seuil de la douleur.","src":"p. 175","deep":"**Pourquoi** : le minimum est une marche régulière de 30-45 minutes, au moins 3 fois/semaine, en ralentissant ou en s'arrêtant quelques minutes au seuil de la douleur : elle développe les collatérales et le métabolisme musculaire (p. 175).\n**Piège** : il ne s'agit pas de marcher en restant sans douleur : on va jusqu'au seuil de la douleur, puis on ralentit (p. 175).\n**À relier** : réadaptation de préférence supervisée, avec de meilleurs résultats que le programme fait seul, et complétée par l'éducation thérapeutique (p. 175)."},{"id":"225-qroc-790","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","physiopathologie"],"difficulty":2,"question":"Quel effet métabolique sur le muscle l'arrêt du tabac et la marche régulière favorisent-ils, en plus de la circulation collatérale ?","answer":"Une augmentation du pool mitochondrial","accept":["pool mitochondrial","augmentation du pool mitochondrial","mitochondries"],"keywords":["mitochond"],"explanation":"Arrêt du tabac et marche favorisent le développement de la circulation collatérale et l'état métabolique musculaire (augmentation du pool mitochondrial), allongeant la distance de marche voire faisant disparaître la claudication.","src":"p. 175","deep":"**Pourquoi** : arrêt du tabac et marche régulière améliorent l'état métabolique du muscle (augmentation du pool mitochondrial), en plus de la circulation collatérale (p. 175).\n**Piège** : répondre « circulation collatérale » ne suffit pas : la question vise l'effet musculaire (p. 175).\n**À relier** : résultat : allongement de la distance de marche, voire disparition de la claudication (p. 175)."},{"id":"225-qroc-791","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle modalité de réadaptation à la marche donne de meilleurs résultats que le programme réalisé seul par le patient ?","answer":"La réadaptation supervisée en milieu spécialisé","accept":["supervisée","réadaptation supervisée","marche supervisée","rééducation supervisée"],"keywords":["supervis"],"explanation":"La réadaptation supervisée (centre de réadaptation, de préférence en ambulatoire) est fortement conseillée, avec de meilleurs résultats que la marche non supervisée.","src":"p. 175","deep":"**Pourquoi** : la réadaptation supervisée en milieu spécialisé (centre ou, surtout, ambulatoire) donne de meilleurs résultats que le programme de marche fait seul (p. 175).\n**Piège** : une marche libre non encadrée reste utile mais moins efficace : le Collège conseille fortement la supervision (p. 175).\n**À relier** : fig. 7.6 : réadaptation à la marche de préférence supervisée pour toute claudication non très invalidante (p. 177)."},{"id":"225-qroc-792","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","prévention"],"difficulty":1,"question":"Par quoi la réadaptation supervisée est-elle toujours complétée ?","answer":"L'éducation thérapeutique du patient","accept":["éducation thérapeutique","éducation thérapeutique du patient","etp","éducation thérapeutique du patient (ETP)"],"keywords":["education therap"],"explanation":"L'éducation thérapeutique assure une bonne connaissance de la maladie, le respect des règles de prévention et une meilleure observance.","src":"p. 175","deep":"**Pourquoi** : la réadaptation supervisée est toujours complétée par l'éducation thérapeutique : connaissance de la maladie, respect des règles de prévention, meilleure observance (p. 175).\n**Piège** : la réadaptation ne se résume pas à un programme de marche : sans éducation, l'observance et la prévention en pâtissent (p. 175).\n**À relier** : même revascularisé et asymptomatique, le patient garde des mesures préventives, vu la mortalité de l'ischémie critique (≈ 70 % à 5 ans) (p. 178)."},{"id":"225-qroc-793","type":"QROC","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Que peut-on attendre des traitements vasoactifs comme la pentoxifylline dans l'AOMI ?","answer":"Une amélioration modeste du périmètre de marche, sans bénéfice pronostique","accept":["amélioration modeste du périmètre de marche","modeste","sans bénéfice pronostique","bénéfice modeste"],"keywords":["modest"],"explanation":"Certains traitements vasoactifs (ex : pentoxifylline) améliorent modestement le périmètre de marche, sans bénéfice pronostique à long terme ; plusieurs ont été retirés du marché pour futilité ou déremboursés.","src":"p. 176","deep":"**Pourquoi** : les vasoactifs (ex : pentoxifylline) améliorent modestement le périmètre de marche, sans bénéfice pronostique à long terme ; plusieurs ont été retirés du marché pour futilité ou déremboursés (p. 176).\n**Piège** : les présenter comme un traitement de fond : le pronostic est porté par l'arrêt du tabac, la statine, l'antiagrégant et la marche (p. 175).\n**À relier** : la statine, elle, peut aussi augmenter le périmètre de marche, tout en réduisant le risque cardiovasculaire (p. 175-176)."},{"id":"225-qroc-794","type":"QROC","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle classe médicamenteuse peut être proposée, en perfusions quotidiennes pendant plusieurs semaines en milieu spécialisé, dans l'ischémie critique non revascularisable ?","answer":"Les prostaglandines","accept":["prostaglandines","prostaglandine"],"keywords":["prostaglandin"],"explanation":"Les prostaglandines peuvent être proposées en cas d'ischémie critique non revascularisable : perfusions quotidiennes pendant plusieurs semaines, en milieu spécialisé.","src":"p. 176","deep":"**Pourquoi** : les prostaglandines sont l'option médicamenteuse de l'ischémie critique non revascularisable : perfusions quotidiennes pendant plusieurs semaines en milieu spécialisé (p. 176).\n**Piège** : elles ne s'adressent pas à la claudication et ne remplacent pas la revascularisation, à tenter autant que possible (p. 176).\n**À relier** : en cas d'impossibilité ou d'échec de la revascularisation sans autre option, l'amputation est à envisager (p. 177)."},{"id":"225-qroc-795","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Dans quelle situation la revascularisation est-elle proposée autant que possible ?","answer":"En cas d'ischémie permanente","accept":["ischémie permanente","ischémie critique","stades iii et iv"],"keywords":["permanente"],"explanation":"La revascularisation est proposée autant que possible lors d'une ischémie permanente ; en ischémie critique, on cherche à revasculariser le membre et l'amputation n'est envisagée qu'en dernier recours.","src":"p. 176-177","deep":"**Pourquoi** : en ischémie permanente (stades III-IV), le pronostic du membre est engagé : revascularisation proposée autant que possible (p. 169, 176).\n**Piège** : ce n'est pas l'indication de principe de la claudication, traitée d'abord par traitement médical et réadaptation (fig. 7.6, p. 177).\n**À relier** : si la revascularisation est impossible ou échoue : (rang B) prostaglandines possibles (p. 176), puis amputation à envisager (p. 177)."},{"id":"225-qroc-796","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quel préalable précède habituellement une revascularisation pour claudication intermittente sévère altérant la qualité de vie ?","answer":"Un traitement médical bien mené, réadaptation incluse","accept":["traitement médical bien mené","réadaptation","après réadaptation","traitement médical"],"keywords":[],"explanation":"Une revascularisation peut être proposée en cas de claudication sévère altérant la qualité de vie, notamment après un traitement médical bien mené incluant la réadaptation.","src":"p. 176","deep":"**Pourquoi** : la claudication n'engage pas le pronostic du membre comme l'ischémie permanente : la revascularisation se discute surtout après un traitement médical bien mené, réadaptation incluse (p. 176).\n**Piège** : revasculariser d'emblée une claudication modérée ; le Collège réserve le geste d'emblée aux situations particulières (p. 176).\n**À relier** : d'emblée possible si périmètre < 100 m avec handicap important ou atteinte aorto-iliaque sévère (p. 176)."},{"id":"225-qroc-797","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":3,"question":"Dans quelles situations revascularise-t-on d'emblée une claudication, sans attendre l'échec du traitement médical ?","answer":"PM < 100 m avec handicap important, ou atteinte aorto-iliaque sévère","accept":["périmètre de marche très faible","< 100 m","atteinte aorto-iliaque sévère","handicap fonctionnel important"],"keywords":[],"explanation":"D'emblée en cas de périmètre de marche très faible (< 100 m) avec handicap fonctionnel important (ex : professionnel), et/ou d'atteinte aorto-iliaque sévère rendant illusoire l'espoir d'un développement de collatérales.","src":"p. 176","deep":"**Pourquoi** : on n'attend pas l'échec du traitement médical si le périmètre est très faible (< 100 m) avec handicap important (ex : professionnel), et/ou si l'atteinte aorto-iliaque sévère rend illusoire le développement de collatérales (p. 176).\n**Piège** : sans ces critères, on commence par traitement médical et réadaptation (fig. 7.6, p. 177).\n**À relier** : < 100 m est aussi le seuil qui définit la claudication sévère (p. 169)."},{"id":"225-qroc-798","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle technique endovasculaire constitue l'essentiel de la revascularisation endovasculaire des artères des membres inférieurs ?","answer":"L'angioplastie intraluminale par ballonnet (± stent)","accept":["angioplastie intraluminale par ballonnet","angioplastie par ballonnet","angioplastie intraluminale","angioplastie"],"keywords":["angioplastie"],"explanation":"Le traitement endovasculaire est essentiellement une angioplastie intraluminale par ballonnet, pouvant être complétée par un stent.","src":"p. 176","deep":"**Pourquoi** : le traitement endovasculaire repose essentiellement sur l'angioplastie intraluminale par ballonnet, éventuellement complétée par un stent (p. 176).\n**Piège** : ne pas confondre avec l'endartériectomie, geste chirurgical (souvent à la bifurcation fémorale, associé à un pontage) (p. 176).\n**À relier** : (rang B) après angioplastie avec ou sans stent, bithérapie antiplaquettaire 1 à 6 mois selon le geste (p. 176) ; toute revascularisation impose une surveillance clinique et échodoppler (p. 176)."},{"id":"225-qroc-799","type":"QROC","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle technique d'angioplastie peut être proposée en cas d'occlusions longues ?","answer":"L'angioplastie sous-adventicielle","accept":["angioplastie sous-adventicielle","sous-adventicielle","sous adventicielle"],"keywords":["adventici"],"explanation":"D'autres techniques que l'angioplastie intraluminale, telle l'angioplastie sous-adventicielle, peuvent être proposées en cas d'occlusions longues.","src":"p. 176","deep":"**Pourquoi** : en cas d'occlusions longues, d'autres techniques que l'angioplastie intraluminale peuvent être proposées, comme l'angioplastie sous-adventicielle (p. 176).\n**Piège** : la réserver aux sténoses courtes : c'est l'inverse, les lésions courtes et proximales étant celles où l'angioplastie classique réussit le mieux (p. 176).\n**À relier** : l'angioplastie des artères distales (pied) s'est aussi développée ces dernières années (p. 176)."},{"id":"225-qroc-801","type":"QROC","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelles lésions artérielles donnent les résultats les plus favorables avec l'angioplastie ?","answer":"Les lésions courtes et proximales","accept":["courtes et proximales","lésions courtes et proximales","courtes proximales","lésions courtes"],"keywords":["court"],"explanation":"Plus une lésion est courte et proximale, meilleur est le résultat de l'angioplastie ; celle des artères distales du pied s'est toutefois développée récemment.","src":"p. 176","deep":"**Pourquoi** : les résultats de l'angioplastie sont d'autant plus favorables que les lésions sont courtes et proximales (p. 176).\n**Piège** : cela ne rend pas l'angioplastie distale impossible : celle des artères du pied s'est développée ces dernières années (p. 176).\n**À relier** : occlusions longues : angioplastie sous-adventicielle possible ; le choix de la technique dépend de l'étendue, de la sévérité des lésions et de l'état du patient (p. 176)."},{"id":"225-qroc-802","type":"QROC","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle durée de bithérapie antiplaquettaire est proposée après une angioplastie, avec ou sans stent ?","answer":"De 1 à 6 mois, selon le geste et sa localisation","accept":["1 à 6 mois","de 1 à 6 mois","1-6 mois","entre 1 et 6 mois"],"keywords":["1","6"],"explanation":"Après une angioplastie, stent ou non, on associe deux antiplaquettaires pendant 1 à 6 mois, la durée variant avec le geste et sa localisation.","src":"p. 176","deep":"**Pourquoi** : après une angioplastie, avec ou sans stent, une bithérapie antiplaquettaire est proposée pour une période de 1 à 6 mois, selon le geste et sa localisation (p. 176).\n**Piège** : ce n'est ni à vie ni dès le diagnostic : l'AOMI symptomatique relève en soi d'un seul antiagrégant, aspirine ou clopidogrel (p. 175).\n**À relier** : toute revascularisation impose une surveillance clinique et échodoppler (risque de thrombose de stent ou de pontage) (p. 176)."},{"id":"225-qroc-803","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quel matériel est préféré pour réaliser un pontage dans l'AOMI ?","answer":"Le matériel veineux (à défaut, une prothèse vasculaire)","accept":["matériel veineux","veine","veineux","greffon veineux"],"keywords":["veine"],"explanation":"Le pontage court-circuite les lésions sténosantes ou occlusives, de préférence avec du matériel veineux, ou à défaut avec une prothèse vasculaire.","src":"p. 176","deep":"**Pourquoi** : le pontage court-circuite les lésions sténosantes ou occlusives, de préférence avec du matériel veineux, ou à défaut avec une prothèse vasculaire (p. 176).\n**Piège** : prothèse = solution de second choix dans l'AOMI, alors que dans l'AAA la mise à plat-greffe interpose justement une prothèse (p. 176 ; rang B, p. 186).\n**À relier** : pontages les plus fréquents : aorto-bi-iliaque (ou bifémoral), fémoropoplité, fémorojambier (p. 176)."},{"id":"225-qroc-804","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Citez l'un des pontages les plus fréquents dans l'AOMI.","answer":"Aorto-bi-iliaque (ou bifémoral), fémoropoplité ou fémorojambier","accept":["aorto-bi-iliaque","aortobifémoral","fémoropoplité","fémorojambier","fémoro-poplité","fémoro-jambier"],"keywords":[],"explanation":"Les pontages les plus fréquents sont le pontage aorto-bi-iliaque (ou bifémoral), le pontage fémoropoplité et le pontage fémorojambier.","src":"p. 176","deep":"**Pourquoi** : les pontages les plus fréquents suivent l'axe artériel : aorto-bi-iliaque (ou bifémoral), fémoropoplité, fémorojambier (p. 176).\n**Piège** : ne pas citer un pontage extra-anatomique (croisé fémorofémoral, axillofémoral), qui peut être envisagé mais ne figure pas parmi les plus fréquents (p. 176).\n**À relier** : les gestes peuvent être associés (techniques hybrides : pontage aortobifémoral + angioplastie poplitée) (p. 176)."},{"id":"225-qroc-805","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Citez un pontage extra-anatomique envisageable dans l'AOMI.","answer":"Pontage croisé fémorofémoral ou axillofémoral","accept":["fémorofémoral croisé","pontage croisé","axillofémoral","fémoro-fémoral croisé","axillo-fémoral"],"keywords":[],"explanation":"Des pontages extra-anatomiques peuvent être envisagés, tels que le pontage croisé fémorofémoral, voire axillofémoral.","src":"p. 176","deep":"**Pourquoi** : un pontage extra-anatomique ne suit pas le trajet de l'artère native : pontage croisé fémorofémoral, voire axillofémoral (p. 176).\n**Piège** : fémoropoplité et fémorojambier sont des pontages anatomiques, parmi les plus fréquents (p. 176).\n**À relier** : matériel de préférence veineux, sinon prothétique ; surveillance clinique et échodoppler après tout pontage (p. 176)."},{"id":"225-qroc-806","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quel geste est parfois associé à un pontage, notamment au niveau de la bifurcation fémorale ?","answer":"Une endartériectomie","accept":["endartériectomie","endartériectomie fémorale","endarteriectomie"],"keywords":["endarteriectomie"],"explanation":"L'endartériectomie, le plus souvent associée à un pontage, améliore le réseau fémoral profond et favorise le développement de la circulation collatérale de la cuisse lors d'une occlusion fémorale superficielle.","src":"p. 176","deep":"**Pourquoi** : l'endartériectomie, le plus souvent associée à un pontage, améliore le réseau fémoral profond à la bifurcation fémorale et favorise les collatérales de la cuisse lors d'une occlusion fémorale superficielle (p. 176).\n**Piège** : ce n'est pas un geste endovasculaire : c'est un geste chirurgical, à distinguer de l'angioplastie (p. 176).\n**À relier** : chirurgie et endovasculaire peuvent être combinés : techniques hybrides (p. 176)."},{"id":"225-qroc-807","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Comment nomme-t-on l'association d'une chirurgie et d'un geste endovasculaire (ex : pontage aortobifémoral complété par une angioplastie poplitée) ?","answer":"Une technique hybride","accept":["technique hybride","techniques hybrides","hybride"],"keywords":["hybride"],"explanation":"Les gestes de revascularisation peuvent être associés : ce sont les techniques hybrides (chirurgie + endovasculaire).","src":"p. 176","deep":"**Pourquoi** : chirurgie et endovasculaire peuvent être associés au cours d'une même prise en charge : ce sont les techniques hybrides, par exemple un pontage aortobifémoral complété par une angioplastie poplitée (p. 176).\n**Piège** : hybride = un geste chirurgical + un geste endovasculaire, pas deux gestes de même nature (p. 176).\n**À relier** : le choix des techniques dépend de l'étendue et de la sévérité des lésions et de l'état du patient (p. 176)."},{"id":"225-qroc-808","type":"QROC","rank":"A","objective":"225-obj-05","tags":["suivi","complications"],"difficulty":2,"question":"Quel examen assure, avec la surveillance clinique, le suivi d'un patient après une revascularisation des membres inférieurs ?","answer":"L'échodoppler","accept":["échodoppler","écho-doppler","échodoppler artériel"],"keywords":["doppler"],"explanation":"Quelle que soit la méthode de revascularisation, une surveillance clinique et paraclinique (échodoppler) est nécessaire.","src":"p. 176","deep":"**Pourquoi** : quelle que soit la méthode de revascularisation, une surveillance clinique et paraclinique par échodoppler est nécessaire (p. 176).\n**Piège** : la surveillance s'impose même chez un patient devenu asymptomatique : la thrombose ou la dégradation d'un pontage peut survenir à distance (p. 176).\n**À relier** : (rang B) après cure d'AAA aussi, échodoppler au long cours pour les prothèses de chirurgie conventionnelle (p. 186)."},{"id":"225-qroc-809","type":"QROC","rank":"A","objective":"225-obj-05","tags":["suivi","complications"],"difficulty":2,"question":"Pourquoi une surveillance est-elle nécessaire après une revascularisation (stent ou pontage) ?","answer":"Risque de thrombose de stent ou de pontage et de dégradation des anastomoses","accept":["thrombose de stent","thrombose de pontage","thrombose","dégradation des pontages"],"keywords":["thrombose"],"explanation":"Le risque de thrombose de stent ou de pontage, ou de dégradation des pontages et des anastomoses, impose une surveillance clinique et échodoppler.","src":"p. 176","deep":"**Pourquoi** : après revascularisation, on craint la thrombose de stent ou de pontage, et la dégradation des pontages et des anastomoses : d'où une surveillance clinique et échodoppler (p. 176).\n**Piège** : une revascularisation réussie n'est pas définitive ; et les mesures préventives restent nécessaires même chez le revascularisé asymptomatique (p. 176, 178).\n**À relier** : après angioplastie, (rang B) bithérapie antiplaquettaire 1 à 6 mois (p. 176)."},{"id":"225-qroc-810","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Sous la supervision de quelle équipe les soins de plaies de l'AOMI doivent-ils être réalisés ?","answer":"Une équipe multidisciplinaire spécialisée en plaies et cicatrisation","accept":["équipe multidisciplinaire","équipe multidisciplinaire spécialisée","équipe spécialisée en plaies"],"keywords":["multidisciplinaire"],"explanation":"Les soins de plaies se font sous supervision d'une équipe multidisciplinaire spécialisée en plaies et cicatrisation.","src":"p. 176","deep":"**Pourquoi** : les plaies de l'AOMI doivent être soignées sous la supervision d'une équipe multidisciplinaire spécialisée en plaies et cicatrisation (p. 176).\n**Piège** : ces plaies ischémiques sont des portes d'entrée infectieuses (cellulite, arthrite, ostéite, septicémie) : ne pas les traiter comme des plaies banales (p. 169).\n**À relier** : un trouble trophique = stade IV = ischémie permanente, à revasculariser autant que possible (p. 169, 176)."},{"id":"225-qroc-811","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Quelle place occupe l'amputation dans la prise en charge de l'AOMI ?","answer":"Le geste ultime, à défaut de toute possibilité de revascularisation","accept":["geste ultime","ultime recours","dernier recours","à défaut de revascularisation"],"keywords":["ultime"],"explanation":"L'amputation est le geste ultime, à défaut de toute possibilité de revascularisation.","src":"p. 176","deep":"**Pourquoi** : l'amputation est le geste ultime, à défaut de toute possibilité de revascularisation : on revascularise autant que possible avant d'y penser (p. 176-177).\n**Piège** : elle n'est pas un premier choix dans l'ischémie permanente, sauf ischémie dépassée dans le contexte aigu (p. 177, 183).\n**À relier** : buts : traiter la douleur et/ou limiter l'infection ; niveau en zone saine et bien oxygénée (TcPO2) (p. 176-177)."},{"id":"225-qroc-812","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quels sont les buts de l'amputation dans l'AOMI ?","answer":"Traiter la douleur et éviter ou limiter les complications infectieuses","accept":["traiter la douleur","éviter les complications infectieuses","limiter les complications infectieuses"],"keywords":[],"explanation":"L'amputation vise à traiter la douleur et/ou à éviter ou limiter les complications infectieuses mettant en péril le patient.","src":"p. 176","deep":"**Pourquoi** : l'amputation vise à traiter la douleur et/ou à éviter ou limiter les complications infectieuses qui mettent le patient en péril (p. 176).\n**Piège** : ce n'est pas un geste de revascularisation : on ne la propose qu'à défaut de toute possibilité de revascularisation (p. 176).\n**À relier** : niveau choisi en zone saine et bien oxygénée (TcPO2), en préservant l'appui ou le genou pour l'appareillage (p. 177)."},{"id":"225-qroc-813","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement","paraclinique"],"difficulty":2,"question":"Quelle mesure aide à choisir une zone bien oxygénée pour pratiquer l'amputation ?","answer":"La TcPO2","accept":["tcpo2","pression transcutanée en oxygène","mesure de la tcpo2"],"keywords":["tcpo2"],"explanation":"L'amputation doit être faite en zone saine et bien oxygénée, d'où l'intérêt de la mesure de la TcPO2.","src":"p. 177","deep":"**Pourquoi** : la TcPO2 évalue l'oxygénation cutanée ; or l'amputation doit être faite en zone saine et bien oxygénée : c'est l'intérêt de cette mesure (p. 171, 177).\n**Piège** : ne pas répondre IPS : il renseigne sur la pression de cheville, pas sur l'oxygénation d'une zone précise, et peut être faussé par la médiacalcose (p. 171).\n**À relier** : TcPO2 après hyperémie : < 10 mmHg = hypoxie critique ; > 35 = bonne compensation (p. 171)."},{"id":"225-qroc-814","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Pourquoi cherche-t-on à sauvegarder l'appui du pied ou l'articulation du genou lors d'une amputation ?","answer":"Pour permettre l'appareillage par prothèse et retrouver la marche","accept":["appareillage","appareillage par prothèse","prothèse","retrouver la marche"],"keywords":["appareill"],"explanation":"Sauvegarder l'appui (amputation d'orteil, transmétatarsienne) ou le genou permet d'espérer un appareillage par prothèse, une marche retrouvée, une meilleure autonomie et une meilleure qualité de vie.","src":"p. 177","deep":"**Pourquoi** : préserver l'appui (amputation d'orteil, transmétatarsienne) ou le genou permet d'espérer un appareillage par prothèse, donc la reprise de la marche, l'autonomie et la qualité de vie (p. 177).\n**Piège** : « amputer haut pour être tranquille » prive le patient d'appareillage : on ampute aussi bas que le permet une zone saine et bien oxygénée (p. 177).\n**À relier** : la TcPO2 guide ce niveau (p. 177)."},{"id":"225-qroc-815","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quand envisage-t-on l'amputation chez un patient en ischémie critique ?","answer":"En cas d'impossibilité ou d'échec de la revascularisation","accept":["impossibilité de revascularisation","échec de la revascularisation","échec de revascularisation","revascularisation impossible"],"keywords":["revascul"],"explanation":"En ischémie critique, on cherche à revasculariser le membre autant que possible ; en cas d'impossibilité ou d'échec des tentatives sans autre option, l'amputation est à envisager.","src":"p. 177","deep":"**Pourquoi** : en ischémie critique, on cherche à revasculariser le membre autant que possible ; l'amputation n'est à envisager qu'en cas d'impossibilité ou d'échec des tentatives, sans autre option (p. 177).\n**Piège** : ne pas amputer avant d'avoir évalué la revascularisation ; (rang B) les prostaglandines sont une option de l'ischémie critique non revascularisable (p. 176).\n**À relier** : ischémie critique = ischémie permanente avec pression de cheville < 50 mmHg ou d'hallux < 30 mmHg ; mortalité à 5 ans proche de 70 % (p. 169, 178)."},{"id":"225-qroc-816","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"question":"Quelle est la prise en charge de première intention d'une claudication intermittente qui n'est ni très invalidante ni liée à une atteinte aorto-iliaque sévère ?","answer":"La réadaptation à la marche, de préférence supervisée","accept":["réadaptation à la marche","réadaptation supervisée","rééducation à la marche","marche supervisée"],"keywords":[],"explanation":"Algorithme de la claudication : en cas de périmètre de marche < 100 m ou d'atteinte aorto-iliaque sévère et extensive, on envisage la revascularisation ; sinon, réadaptation à la marche, de préférence supervisée.","src":"p. 177","deep":"**Pourquoi** : sans claudication très invalidante (< 100 m) ni atteinte aorto-iliaque sévère et extensive, l'algorithme propose la réadaptation à la marche, de préférence supervisée en centre (fig. 7.6, p. 177).\n**Piège** : ne pas revasculariser d'emblée un claudicant modéré ; la revascularisation est envisagée seulement si les critères sont présents (fig. 7.6, p. 177).\n**À relier** : dans tous les cas : prise en charge des FdR, statine + antiplaquettaire (+ IEC si HTA ou insuffisance cardiaque) (fig. 7.6, p. 177)."},{"id":"225-qroc-817","type":"QROC","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":1,"question":"Dans tous les cas de claudication intermittente, quel traitement médicamenteux est associé au contrôle des facteurs de risque ?","answer":"Statines + traitement antiplaquettaire (+ IEC si HTA ou insuffisance cardiaque)","accept":["statines et antiplaquettaire","statine et antiagrégant","statines + antiplaquettaire"],"keywords":["statine"],"explanation":"Dans tous les cas : prise en charge des facteurs de risque cardiovasculaire, statines et traitement antiplaquettaire (plus IEC si HTA ou insuffisance cardiaque).","src":"p. 177","deep":"**Pourquoi** : la figure 7.6 démarre « dans tous les cas » par la prise en charge des facteurs de risque, une statine et un antiplaquettaire, plus un IEC si HTA ou insuffisance cardiaque (p. 177).\n**Piège** : un anticoagulant oral n'est pas le traitement de la claudication : c'est un antiplaquettaire (aspirine ou clopidogrel) qui est indiqué (p. 175).\n**À relier** : statine : LDL < 0,55 g/L et baisse ≥ 50 % ; IEC ou sartan envisageable chez tous, quel que soit le niveau de PA (p. 175)."},{"id":"225-qroc-818","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"À quoi l'espérance de vie d'un sujet atteint d'ischémie permanente est-elle comparable ?","answer":"À celle de certains cancers","accept":["certains cancers","cancers","cancer"],"keywords":["cancer"],"explanation":"Le pronostic de l'AOMI est grave : l'espérance de vie d'un sujet en ischémie permanente est équivalente à celle de certains cancers.","src":"p. 177","deep":"**Pourquoi** : le pronostic de l'AOMI est grave : l'espérance de vie d'un sujet en ischémie permanente est équivalente à celle de certains cancers (p. 177).\n**Piège** : ne pas réduire l'AOMI à un problème de jambe : c'est un marqueur d'athérome diffus, avec risque coronarien et cérébral (p. 175, 177).\n**À relier** : ischémie critique : mortalité à 5 ans proche de 70 % ; claudication : espérance de vie réduite d'environ 10 ans (p. 177-178)."},{"id":"225-qroc-819","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"Chez les patients claudicants, quelle proportion décède dans les 5 ans (dont la moitié de cause cardiovasculaire) ?","answer":"20 %","accept":["20 %","20","20 % dont la moitié de cause cardiovasculaire","20%","un cinquième","1/5"],"keywords":["20"],"explanation":"Chez les claudicants, à 5 ans : 20 % ont des complications cardiovasculaires et 20 % décèdent, pour moitié de causes cardiovasculaires.","src":"p. 177","deep":"**Pourquoi** : chez les claudicants à 5 ans : 20 % ont des complications cardiovasculaires et 20 % décèdent, pour moitié de causes cardiovasculaires (p. 177).\n**Piège** : ne pas confondre ces deux « 20 % » (complications vs décès) ; et l'espérance de vie est réduite d'environ 10 ans (p. 177).\n**À relier** : c'est pourquoi antiagrégant, statine et contrôle des FdR sont indiqués dès la claudication (p. 175)."},{"id":"225-qroc-820","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"Chez les patients claudicants, quelle proportion voit son artériopathie s'aggraver localement à 5 ans ?","answer":"25 % (dont 1/5 avec une amputation majeure)","accept":["25 %","25","un quart"],"keywords":["25"],"explanation":"Sur le plan local, 25 % des claudicants voient leur artériopathie s'aggraver à 5 ans, dont un cinquième subit une amputation majeure.","src":"p. 177","deep":"**Pourquoi** : sur le plan local, 25 % des claudicants voient leur artériopathie s'aggraver à 5 ans, et un cinquième d'entre eux subit une amputation majeure (p. 177).\n**Piège** : ne pas confondre 25 % (aggravation locale) avec le risque d'amputation à 5 ans, de l'ordre de 5 % (p. 177).\n**À relier** : le risque local est surtout majoré par un mauvais contrôle des facteurs de risque, le tabac en tête (p. 177)."},{"id":"225-qroc-821","type":"QROC","rank":"A","objective":"225-obj-06","tags":["pronostic"],"difficulty":2,"question":"Quel est le risque d'amputation à 5 ans au niveau des membres inférieurs, notamment en cas de mauvais contrôle du tabagisme ?","answer":"Environ 5 %","accept":["5 %","environ 5 %","de l'ordre de 5 %","5"],"keywords":["5"],"explanation":"À 5 ans, le risque d'amputation est de l'ordre de 5 %, notamment en cas de mauvais contrôle des facteurs de risque (tabagisme).","src":"p. 177","deep":"**Pourquoi** : à 5 ans, le risque d'amputation des membres inférieurs est de l'ordre de 5 %, notamment en cas de mauvais contrôle des facteurs de risque (tabagisme) (p. 177).\n**Piège** : ne pas confondre avec les 25 % d'aggravation locale, dont un cinquième aboutit à une amputation majeure (p. 177).\n**À relier** : le risque vital est bien supérieur : 20 % de décès à 5 ans chez le claudicant (p. 177)."},{"id":"225-qroc-822","type":"QROC","rank":"A","objective":"225-obj-07","tags":["physiopathologie"],"difficulty":2,"question":"Citez l'un des trois facteurs dont dépend la gravité de la baisse du débit artériel dans l'ischémie aiguë.","answer":"PA systémique, abondance des collatérales ou qualité du réseau d'aval","accept":["pression artérielle systémique","circulation collatérale","collatérales","collatéralité","réseau d'aval","lit d'aval"],"keywords":[],"explanation":"La gravité dépend de la pression artérielle systémique (qui doit être maintenue à un niveau correct), de l'abondance de la circulation collatérale et de la qualité du réseau artériel d'aval.","src":"p. 178","deep":"**Pourquoi** : la gravité de la baisse de débit dépend de la pression artérielle systémique (à maintenir à un niveau correct), de l'abondance de la circulation collatérale et de la qualité du réseau d'aval (p. 178).\n**Piège** : ne pas oublier la PA systémique : une hypotension aggrave l'ischémie, d'où l'équilibration hémodynamique dans le traitement médical (p. 178, 182).\n**À relier** : (rang B) la collatéralité préalable explique qu'une thrombose in situ soit moins brutale qu'une embolie sur artère saine (p. 181)."},{"id":"225-qroc-823","type":"QROC","rank":"A","objective":"225-obj-09","tags":["physiopathologie","complications"],"difficulty":2,"question":"Pourquoi l'œdème musculaire peut-il aboutir à un arrêt total de la circulation (syndrome des loges) ?","answer":"Les loges aponévrotiques sont inextensibles","accept":["loges inextensibles","loges aponévrotiques inextensibles","aponévrose inextensible","inextensibles"],"keywords":["inextensible"],"explanation":"Les muscles des membres sont enfermés dans des loges aponévrotiques inextensibles : l'œdème comprime les tissus jusqu'à un arrêt total de la circulation, seule l'aponévrotomie de décharge pouvant alors libérer le muscle.","src":"p. 178","deep":"**Pourquoi** : les muscles sont enfermés dans des loges aponévrotiques inextensibles : l'œdème d'anoxie y fait monter la pression jusqu'à comprimer les tissus et arrêter la circulation (syndrome des loges) (p. 178).\n**Piège** : ce n'est pas une thrombose veineuse : c'est une compression, que seule l'aponévrotomie de décharge lève (p. 178).\n**À relier** : en cas de revascularisation tardive, le geste est généralement complété par une aponévrotomie (loge antéroexterne de jambe) (p. 183)."},{"id":"225-qroc-824","type":"QROC","rank":"A","objective":"225-obj-09","tags":["physiopathologie"],"difficulty":1,"question":"Comment nomme-t-on l'aggravation de l'atteinte cellulaire, par relargage d'acides et de radicaux libres, à la remise en circulation du membre ?","answer":"Le syndrome de revascularisation","accept":["syndrome de revascularisation","syndrome de reperfusion"],"keywords":["syndrome de revascularisation"],"explanation":"Au moment de la remise en circulation, le relargage d'acides et de radicaux libres aggrave localement l'atteinte cellulaire : c'est le syndrome de revascularisation, qui peut aussi avoir des conséquences générales sévères.","src":"p. 178","deep":"**Pourquoi** : à la remise en circulation, le relargage d'acides et de radicaux libres aggrave localement l'atteinte cellulaire : c'est le syndrome de revascularisation (p. 178).\n**Piège** : la reperfusion, bien qu'indispensable, peut paradoxalement entraîner des conséquences sévères, locales et générales (p. 178).\n**À relier** : conséquences générales : hyperkaliémie, acidose métabolique, myoglobinurie, nécrose tubulaire aiguë, CIVD possible (p. 178-179)."},{"id":"225-qroc-825","type":"QROC","rank":"A","objective":"225-obj-09","tags":["complications","biologie"],"difficulty":2,"question":"Quelles anomalies du calcium et du phosphore surviennent à la reperfusion d'un membre ischémique ?","answer":"Hypocalcémie et hyperphosphorémie","accept":["hypocalcémie et hyperphosphorémie","hypocalcémie","hyperphosphorémie"],"keywords":["hypocalc","hyperphosph"],"explanation":"Les troubles métaboliques de la reperfusion associent hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie et myoglobinurie, hausse de la créatinémie, hypocalcémie et hyperphosphorémie ; une CIVD est possible.","src":"p. 178","deep":"**Pourquoi** : la reperfusion relargue le contenu des cellules lysées et des métabolites : hypocalcémie et hyperphosphorémie, avec hyperkaliémie, acidose, hyperuricémie, myoglobinémie et créatinine élevée (p. 178).\n**Piège** : ne pas inverser : calcium bas, phosphore haut (p. 178).\n**À relier** : le danger immédiat est l'acidose hyperkaliémique : ionogramme surveillé, bicarbonates IV, chélateur du potassium voire dialyse (p. 183)."},{"id":"225-qroc-826","type":"QROC","rank":"A","objective":"225-obj-09","tags":["complications"],"difficulty":2,"question":"Quelle lésion rénale peut compliquer la reperfusion d'un membre ischémique ?","answer":"Une nécrose tubulaire aiguë","accept":["nécrose tubulaire aiguë","nta","nécrose tubulaire"],"keywords":["necrose tubulaire"],"explanation":"Une nécrose tubulaire aiguë peut survenir, secondaire au choc, à l'instabilité de la pression de perfusion rénale, à la précipitation intratubulaire de myoglobine et à sa toxicité en milieu acide, ainsi qu'à celle des produits de contraste.","src":"p. 178-179","deep":"**Pourquoi** : l'insuffisance rénale de la reperfusion est une nécrose tubulaire aiguë : choc et instabilité de la perfusion rénale, précipitation intratubulaire de myoglobine, toxicité de la myoglobine en milieu acide et des produits de contraste (p. 178-179).\n**Piège** : ce n'est pas une occlusion des artères rénales (p. 178-179).\n**À relier** : surveillance : diurèse horaire, ionogramme, urée, créatininémie, CPK (p. 183)."},{"id":"225-qroc-827","type":"QROC","rank":"A","objective":"225-obj-09","tags":["complications","physiopathologie"],"difficulty":2,"question":"Quelle protéine musculaire précipite dans les tubules rénaux lors de la reperfusion et y est toxique en milieu acide ?","answer":"La myoglobine","accept":["myoglobine","la myoglobine","myoglobinurie"],"keywords":["myoglobine"],"explanation":"La myoglobine libérée par les cellules lysées précipite dans les tubules et est directement toxique en milieu acide ; les produits de contraste d'une artériographie aggravent le risque d'insuffisance rénale.","src":"p. 178-179","deep":"**Pourquoi** : la myoglobine libérée par la rhabdomyolyse précipite dans les tubules et y est directement toxique en milieu acide (p. 178-179).\n**Piège** : les CPK sont le marqueur dosé en surveillance (p. 183), mais la protéine qui précipite dans les tubules est la myoglobine.\n**À relier** : les muscles souffrent dès 6-8 h d'ischémie (rhabdomyolyse), les nerfs dès 2 h (p. 178)."},{"id":"225-qroc-828","type":"QROC","rank":"A","objective":"225-obj-07","tags":["diagnostic"],"difficulty":1,"question":"Comment pose-t-on essentiellement le diagnostic d'une ischémie aiguë de membre inférieur ?","answer":"Il est essentiellement clinique","accept":["clinique","cliniquement","essentiellement clinique"],"keywords":["clinique"],"explanation":"Le diagnostic est essentiellement clinique et ne doit pas être inutilement prolongé par des explorations qui ne sont pas nécessaires à l'intervention urgente.","src":"p. 179","deep":"**Pourquoi** : douleur brutale, membre froid et livide, pouls abolis en aval, déficit sensitivomoteur : le diagnostic est essentiellement clinique (p. 179).\n**Piège** : ne pas prolonger le diagnostic par des explorations inutiles : réaliser des examens inutiles qui retardent la prise en charge est une notion inacceptable (p. 179, 188).\n**À relier** : l'équipe chirurgicale est alertée au plus tôt ; l'artériographie est le plus souvent faite au bloc (p. 180)."},{"id":"225-qroc-829","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique"],"difficulty":1,"question":"Quels sont les signes fonctionnels de l'ischémie aiguë d'un membre inférieur ?","answer":"Douleur brutale, intense (broiement), avec impotence fonctionnelle","accept":["douleur brutale","broiement","douleur intense à type de broiement","impotence fonctionnelle"],"keywords":["brutale","broiement"],"explanation":"Le tableau fonctionnel associe une douleur d'apparition brutale (quelques heures dans la forme subaiguë), intense, à type de broiement, avec impotence fonctionnelle du membre.","src":"p. 179","deep":"**Pourquoi** : signes fonctionnels : douleur d'apparition brutale (parfois en quelques heures dans la forme subaiguë), intense, à type de broiement, avec impotence fonctionnelle du membre (p. 179).\n**Piège** : la brutalité et l'intensité distinguent l'ischémie aiguë de la claudication, douleur d'effort qui cède à l'arrêt (p. 168, 179).\n**À relier** : signes physiques : membre froid, livide, douleur à la palpation des muscles, pouls abolis en aval, anesthésie et paralysie (nerf fibulaire commun : pied qui ne se relève pas) (p. 179)."},{"id":"225-qroc-830","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique"],"difficulty":2,"question":"Comment estime-t-on le niveau de l'occlusion artérielle en cas d'ischémie aiguë ?","answer":"Par le niveau de la froideur du membre et l'abolition des pouls en aval","accept":["niveau de la froideur","localisation de la froideur","froideur du membre et abolition des pouls","froideur et abolition des pouls"],"keywords":["froideur","pouls"],"explanation":"La topographie de l'occlusion est généralement estimée par la localisation de la froideur du membre et de l'abolition des pouls en aval.","src":"p. 179","deep":"**Pourquoi** : la topographie de l'occlusion s'estime par la limite de la froideur du membre et l'abolition des pouls en aval (p. 179).\n**Piège** : le niveau se déduit d'abord de la clinique : l'imagerie ne doit pas retarder le geste, l'artériographie étant le plus souvent faite au bloc (p. 180).\n**À relier** : cas le plus grave : occlusion de la bifurcation aortique, ischémie bilatérale sévère avec paralysie sensitivomotrice (p. 179)."},{"id":"225-qroc-831","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","urgence"],"difficulty":2,"question":"Quel signe général grave peut survenir lors d'une occlusion de la bifurcation aortique ?","answer":"Un collapsus cardiovasculaire","accept":["collapsus","collapsus cardiovasculaire","collapsus cardio-vasculaire"],"keywords":["collapsus"],"explanation":"L'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère avec paralysie sensitivomotrice ; les signes généraux sont souvent au premier plan, jusqu'au collapsus cardiovasculaire.","src":"p. 179","deep":"**Pourquoi** : l'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère avec paralysie sensitivomotrice ; les signes généraux passent au premier plan, jusqu'au collapsus cardiovasculaire (p. 179).\n**Piège** : devant une ischémie bilatérale, ne pas chercher deux causes : penser à la bifurcation aortique (p. 179).\n**À relier** : l'état hémodynamique doit être équilibré (remplissage) : la PA systémique conditionne la gravité de l'ischémie (p. 178, 182)."},{"id":"225-qroc-832","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","diagnostic"],"difficulty":1,"question":"Dans la classification de Rutherford de l'ischémie aiguë, quel grade correspond à un membre viable, sans déficit, avec urgence relative ?","answer":"Grade I","accept":["grade i","grade 1","i"],"keywords":[],"explanation":"Grade I : viable, aucun déficit sensitif ni moteur, pas de menace immédiate, urgence relative.","src":"p. 179","deep":"**Pourquoi** : grade I de Rutherford : membre viable, sans déficit sensitif ni moteur, pas de menace immédiate, urgence relative (tableau 7.2, p. 179).\n**Piège** : viable ne veut pas dire sans traitement : héparine et antalgiques dès que possible, puis imagerie en urgence et revascularisation dans les heures (fig. 7.7, p. 180).\n**À relier** : IIa : sensitif limité aux orteils ; IIb : au-delà des orteils + moteur modéré ; III : irréversible (p. 179)."},{"id":"225-qroc-833","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","diagnostic"],"difficulty":3,"question":"Quel grade de Rutherford correspond à une ischémie discrètement menaçante : déficit sensitif absent ou limité aux orteils, sans déficit moteur ?","answer":"Grade IIa","accept":["grade iia","iia","grade 2a","2a"],"keywords":[],"explanation":"Grade IIa : ischémie discrètement menaçante, déficit sensitif absent ou limité aux orteils, pas de déficit moteur ; elle est récupérable si prise en charge.","src":"p. 179","deep":"**Pourquoi** : grade IIa : ischémie discrètement menaçante, déficit sensitif absent ou limité aux orteils, pas de déficit moteur ; récupérable si prise en charge (tableau 7.2, p. 179).\n**Piège** : IIa et IIb se distinguent par l'étendue du déficit sensitif (orteils vs au-delà) et la présence d'un déficit moteur (IIb) (p. 179).\n**À relier** : dès le grade II, aucune exploration ne doit retarder l'intervention (p. 180)."},{"id":"225-qroc-834","type":"QROC","rank":"A","objective":"225-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel grade de Rutherford correspond à une ischémie irréversible, avec perte de tissus et déficit séquellaire inévitables ?","answer":"Grade III","accept":["grade iii","iii","grade 3"],"keywords":[],"explanation":"Grade III : ischémie irréversible, avec anesthésie importante et déficit moteur important (paralysie) ; la perte de tissus et le déficit séquellaire sont inévitables.","src":"p. 179","deep":"**Pourquoi** : grade III : anesthésie importante et déficit moteur important (paralysie) : perte de tissus et déficit séquellaire inévitables (tableau 7.2, p. 179).\n**Piège** : au grade III, l'algorithme prévoit l'amputation, non la revascularisation ; une amputation d'emblée peut aussi servir à limiter les désordres métaboliques majeurs d'un syndrome de revascularisation (fig. 7.7, p. 180 ; p. 183).\n**À relier** : héparine, antalgiques et soins locaux restent débutés à tous les grades (fig. 7.7, p. 180)."},{"id":"225-qroc-835","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":1,"question":"Quelle prise en charge est prévue pour une ischémie aiguë irréversible (grade III) ?","answer":"L'amputation","accept":["amputation","l'amputation"],"keywords":["amputation"],"explanation":"Dans l'algorithme de prise en charge, le grade III (irréversible) relève de l'amputation, avec héparine, antalgiques et soins locaux.","src":"p. 180","deep":"**Pourquoi** : au grade III, l'ischémie est irréversible : l'algorithme prévoit l'amputation (fig. 7.7, p. 180).\n**Piège** : une amputation d'emblée se discute aussi pour limiter les désordres métaboliques majeurs d'un syndrome de revascularisation ou après échec, surtout sur terrain débilité (p. 183).\n**À relier** : chez un malade très âgé et moribond, une prise en charge palliative est parfois la seule solution (p. 182)."},{"id":"225-qroc-836","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":2,"question":"Quelle prise en charge est prévue pour une ischémie aiguë viable avec déficit sensitif (grade II) ?","answer":"Revascularisation en urgence absolue (thrombectomie ou pontage)","accept":["revascularisation en urgence absolue","revascularisation en urgence","thrombectomie","pontage"],"keywords":["revascularisation"],"explanation":"Le grade II impose une revascularisation en urgence absolue (thrombectomie ou pontage), sans imagerie préalable qui retarderait l'intervention.","src":"p. 180","deep":"**Pourquoi** : au grade II (déficit sensitif), le membre est menacé et récupérable seulement si l'on agit vite : revascularisation en urgence absolue, par thrombectomie ou pontage (fig. 7.7, p. 180).\n**Piège** : aucune exploration ne doit retarder l'intervention en cas d'atteinte neurologique (p. 180) ; c'est la notion inacceptable de l'item (p. 188).\n**À relier** : héparine et antalgiques dès que possible ; après le geste, surveiller kaliémie, acidose et fonction rénale (p. 180, 183)."},{"id":"225-qroc-837","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":2,"question":"Que prévoit la prise en charge d'une ischémie aiguë viable de grade I ?","answer":"Imagerie en urgence, puis revascularisation dans les heures à venir","accept":["imagerie en urgence","revascularisation dans les heures à venir","imagerie puis revascularisation"],"keywords":["imagerie"],"explanation":"Au grade I (viable), une imagerie en urgence précède une revascularisation dans les heures à venir (thrombolyse, thrombectomie ou pontage).","src":"p. 180","deep":"**Pourquoi** : au grade I (viable, urgence relative), on a le temps d'une imagerie en urgence, puis d'une revascularisation dans les heures (thrombolyse, thrombectomie ou pontage) (fig. 7.7, p. 180).\n**Piège** : ne pas appliquer ce schéma au grade II, qui relève d'une revascularisation en urgence absolue sans imagerie qui retarde (p. 180).\n**À relier** : l'échodoppler est possible sans perte de temps au grade I, en l'absence d'atteinte neurologique (p. 180)."},{"id":"225-qroc-838","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":1,"question":"Quels traitements sont à débuter dès que possible dans toute ischémie aiguë de membre, quel que soit le grade ?","answer":"Héparine et antalgiques, avec soins locaux","accept":["héparine et antalgiques","héparine","héparine antalgiques soins locaux"],"keywords":["heparine","antalgique"],"explanation":"Quel que soit le grade, l'héparine et les antalgiques sont débutés dès que possible, avec des soins locaux.","src":"p. 180","deep":"**Pourquoi** : quel que soit le grade, héparine et antalgiques sont débutés dès que possible, avec des soins locaux (fig. 7.7, p. 180).\n**Piège** : l'héparine n'attend pas l'imagerie, mais le bilan de coagulation est prélevé avant (p. 182).\n**À relier** : le traitement médical comprend aussi oxygénothérapie nasale et équilibration hémodynamique (remplissage) ; antalgiques de niveau 3 souvent nécessaires d'emblée (p. 182)."},{"id":"225-qroc-839","type":"QROC","rank":"A","objective":"225-obj-09","tags":["urgence","imagerie"],"difficulty":3,"question":"Dans quelle situation peut-on réaliser une échographie doppler sans perte de temps devant une ischémie aiguë ?","answer":"Grade I sans atteinte neurologique, si les conditions locales le permettent","accept":["grade i","sans atteinte neurologique","absence d'atteinte neurologique","conditions locales"],"keywords":[],"explanation":"Le doppler ne se justifie que si les conditions locales et la sévérité le permettent, notamment au grade I en l'absence d'atteinte neurologique ; en cas de déficit neurologique (grade II), rien ne doit retarder l'intervention.","src":"p. 180","deep":"**Pourquoi** : un échodoppler n'est réalisable sans perte de temps que si les conditions locales et la sévérité le permettent, notamment au grade I sans atteinte neurologique (p. 180).\n**Piège** : dès qu'il existe un déficit neurologique (grade II), aucune exploration ne doit retarder l'intervention (p. 180, 188).\n**À relier** : l'artériographie, elle, est le plus souvent réalisée au bloc opératoire pour guider le geste (p. 180)."},{"id":"225-qroc-840","type":"QROC","rank":"A","objective":"225-obj-09","tags":["imagerie"],"difficulty":2,"question":"Quel élément fourni par l'artériographie est le plus important pour la prise en charge interventionnelle d'une ischémie aiguë ?","answer":"L'appréciation du réseau artériel d'aval","accept":["réseau artériel d'aval","réseau d'aval","lit d'aval"],"keywords":["aval"],"explanation":"L'artériographie, réalisée le plus souvent au bloc opératoire, localise l'oblitération, en précise l'aspect (athérome, anévrisme, dissection...) et surtout apprécie le réseau artériel d'aval, déterminant pour un geste percutané ou un pontage.","src":"p. 180","deep":"**Pourquoi** : l'artériographie localise l'oblitération et caractérise l'occlusion, mais surtout apprécie le réseau artériel d'aval, déterminant pour le geste (percutané ou chirurgical), notamment en cas de thrombose et de pontage (p. 180).\n**Piège** : elle n'est pas un préalable qui retarde : elle est le plus souvent réalisée au bloc opératoire (p. 180).\n**À relier** : en cas d'embolie, elle peut aussi révéler d'autres emboles asymptomatiques, homo ou controlatéraux (p. 180)."},{"id":"225-qroc-841","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie","diagnostic"],"difficulty":2,"question":"Que faut-il rechercher sur l'autre membre devant une thrombose artérielle in situ ?","answer":"Un tableau préexistant d'AOMI","accept":["aomi préexistante","tableau préexistant d'aomi","aomi","artériopathie"],"keywords":["aomi"],"explanation":"La thrombose in situ survient le plus souvent chez un sujet âgé à facteurs de risque cardiovasculaire, voire avec une AOMI préexistante à rechercher sur le membre controlatéral.","src":"p. 181","deep":"**Pourquoi** : la thrombose in situ survient le plus souvent chez un sujet âgé à facteurs de risque, voire sur une AOMI préexistante : on la recherche sur le membre controlatéral (p. 181).\n**Piège** : les deux tableaux ne sont pas toujours distincts : une embolie peut survenir sur des artères déjà atteintes d'AOMI (p. 181).\n**À relier** : après le geste, origine thrombotique = antiagrégant et contrôle des facteurs de risque (p. 183)."},{"id":"225-qroc-842","type":"QROC","rank":"B","objective":"225-obj-08","tags":["clinique","étiologie"],"difficulty":2,"question":"Quelle intensité de douleur oriente vers une thrombose in situ plutôt qu'une embolie ?","answer":"Une douleur d'intensité moyenne, d'installation progressive ou rapide","accept":["intensité moyenne","d'intensité moyenne","moyenne intensité"],"keywords":["moyenne"],"explanation":"La thrombose in situ donne une douleur d'intensité moyenne, de survenue progressive ou rapide grâce à la collatéralité préalable ; l'embolie donne une douleur brutale, aiguë et sévère.","src":"p. 181","deep":"**Pourquoi** : sur une artère déjà sténosée, les collatérales se sont développées : la thrombose in situ donne une douleur d'intensité moyenne, de survenue progressive ou rapide (p. 181).\n**Piège** : l'embolie sur artère saine, sans collatérales, donne au contraire une douleur brutale, aiguë et sévère ; mais les tableaux peuvent se chevaucher (p. 181).\n**À relier** : (A) la gravité de l'ischémie dépend de la PA systémique, des collatérales et du réseau d'aval (p. 178)."},{"id":"225-qroc-843","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"question":"Citez une cause iatrogène de thrombose artérielle in situ.","answer":"Cathétérisme, thrombopénie à l'héparine ou ergotisme","accept":["cathétérisme","thrombopénie à l'héparine","tih","ergotisme"],"keywords":[],"explanation":"Les causes iatrogènes de thrombose in situ sont le cathétérisme, la thrombopénie induite par l'héparine et l'ergotisme.","src":"p. 181","deep":"**Pourquoi** : parmi les causes de thrombose in situ figurent des causes iatrogènes : cathétérisme, thrombopénie induite par l'héparine, ergotisme (p. 181).\n**Piège** : la TIH est une complication de l'héparine, pas le simple fait d'en recevoir ; l'ergotisme est aussi une cause toxique d'artériopathie non athéromateuse (p. 174, 181).\n**À relier** : autres causes : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation/hémoconcentration du sujet âgé (p. 181)."},{"id":"225-qroc-844","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":1,"question":"Sur quel terrain une embolie sur artères saines survient-elle classiquement ?","answer":"Un sujet jeune sans antécédent vasculaire connu","accept":["sujet jeune","jeune","sujet jeune sans antécédent vasculaire"],"keywords":["jeune"],"explanation":"L'embolie sur artères saines touche classiquement un sujet jeune sans antécédent vasculaire connu, mais pouvant avoir une cardiopathie connue.","src":"p. 181","deep":"**Pourquoi** : l'embolie sur artères saines touche classiquement un sujet jeune sans antécédent vasculaire connu, mais pouvant avoir une cardiopathie connue (p. 181).\n**Piège** : « sans antécédent vasculaire » ne veut pas dire « sans cardiopathie » : la source est souvent cardiaque (FA, valvulopathie…) (p. 181).\n**À relier** : elle peut suivre des palpitations ; la thrombose in situ touche plutôt le sujet âgé à facteurs de risque (p. 181)."},{"id":"225-qroc-845","type":"QROC","rank":"B","objective":"225-obj-08","tags":["clinique","physiopathologie"],"difficulty":2,"question":"Pourquoi la douleur d'une embolie sur artères saines est-elle brutale, aiguë et sévère ?","answer":"Il n'y a pas de collatérales","accept":["absence de collatérales","pas de collatérales","absence de collatéralité","pas de collatéralité"],"keywords":["collat"],"explanation":"Sur des artères saines, l'absence de collatérales explique une douleur brutale, aiguë et sévère ; elle peut suivre des épisodes de palpitations traduisant une arythmie cardiaque.","src":"p. 181","deep":"**Pourquoi** : sur des artères saines, aucune collatéralité ne s'est développée : l'occlusion brutale donne une douleur brutale, aiguë et sévère (p. 181).\n**Piège** : les deux tableaux ne sont pas toujours aussi distincts : embolie possible sur artères déjà athéromateuses (p. 181).\n**À relier** : l'embolie peut suivre des palpitations : (A) auscultation cardiaque et ECG à la recherche d'une arythmie (p. 181-182)."},{"id":"225-qroc-846","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":3,"question":"Dans la liste des causes cardiaques d'embolie artérielle, quelle anomalie de la paroi est notamment citée à propos de l'infarctus du myocarde ?","answer":"Un faux anévrisme de paroi","accept":["faux anévrisme","faux anévrisme de paroi","faux anévrisme ventriculaire","faux anévrisme de la paroi","faux anévrisme de paroi ventriculaire"],"keywords":["faux anevrisme"],"explanation":"Parmi les causes cardiaques d'embolie : fibrillation atriale, FOP et anévrisme du septum interatrial, infarctus du myocarde avec notamment un faux anévrisme de paroi, endocardite, valvulopathies et prothèses, myxome, dyskinésie ou anévrisme du ventricule gauche.","src":"p. 181","deep":"**Pourquoi** : parmi les causes cardiaques d'embolie, le Collège cite l'infarctus du myocarde, avec notamment un faux anévrisme de paroi (p. 181).\n**Piège** : le faux anévrisme post-infarctus et la dyskinésie ou l'anévrisme ventriculaire gauche sont deux items distincts de la liste (p. 181).\n**À relier** : autres causes cardiaques : FA, FOP et anévrisme du septum interatrial, endocardite, valvulopathies et prothèses, myxome (p. 181)."},{"id":"225-qroc-847","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie"],"difficulty":2,"question":"Citez une atteinte aortique source d'embolie artérielle des membres inférieurs.","answer":"Athérome aortique, anévrisme, aortite ou tumeur aortique","accept":["athérome aortique","anévrisme","aortite","aortites","tumeur aortique"],"keywords":[],"explanation":"Les atteintes aortiques emboligènes sont l'athérome aortique, l'anévrisme, les aortites et les tumeurs aortiques.","src":"p. 181","deep":"**Pourquoi** : l'aorte est une source d'emboles vers les membres : athérome aortique, anévrisme, aortites, tumeurs aortiques (p. 181).\n**Piège** : ne pas chercher uniquement une cause cardiaque : (A) la palpation abdominale à la recherche d'un anévrisme fait partie de l'examen (p. 182).\n**À relier** : (A) l'athérome de l'aorte peut aussi emboliser au cerveau ou aux viscères (p. 166)."},{"id":"225-qroc-848","type":"QROC","rank":"B","objective":"225-obj-08","tags":["étiologie","pièges"],"difficulty":3,"question":"Comment une thrombose in situ peut-elle survenir chez un sujet sans aucun signe préalable d'AOMI ?","answer":"Par rupture d'une plaque initialement non occlusive","accept":["rupture d'une plaque","rupture de plaque","plaque non occlusive"],"keywords":["plaque"],"explanation":"Les deux tableaux ne sont pas toujours distincts : une embolie peut survenir sur des artères déjà atteintes d'AOMI, et une thrombose in situ peut résulter de la rupture d'une plaque initialement non occlusive chez un sujet sans signe préalable.","src":"p. 181","deep":"**Pourquoi** : une plaque initialement non occlusive peut se rompre et se thromboser chez un sujet sans aucun signe préalable d'AOMI (p. 181).\n**Piège** : les deux tableaux (thrombose sur AOMI connue, embolie sur artère saine) ne sont pas toujours aussi distincts (p. 181).\n**À relier** : inversement, une embolie peut survenir sur des artères déjà atteintes d'AOMI (p. 181)."},{"id":"225-qroc-849","type":"QROC","rank":"A","objective":"225-obj-09","tags":["diagnostic","étiologie"],"difficulty":1,"question":"Que recherche-t-on par l'auscultation cardiaque et l'ECG devant une ischémie aiguë de membre ?","answer":"Une arythmie (source cardiaque d'embolie)","accept":["arythmie","trouble du rythme","fibrillation atriale"],"keywords":["arythmie"],"explanation":"L'examen d'une ischémie aiguë est toujours complété par une auscultation cardiaque et un ECG à la recherche d'une arythmie.","src":"p. 182","deep":"**Pourquoi** : devant toute ischémie aiguë, l'auscultation cardiaque et l'ECG recherchent une arythmie, (rang B) la fibrillation atriale figure en tête des causes cardiaques d'embolie (p. 181-182).\n**Piège** : le bilan cardiaque détaillé (Holter, ETT, voire ETO ou IRM) n'est fait qu'après la revascularisation (p. 182).\n**À relier** : examen aussi complété par une palpation abdominale (anévrisme) et un bilan de coagulation ; à distance, anticoagulation au long cours si FA (p. 182-183)."},{"id":"225-qroc-850","type":"QROC","rank":"A","objective":"225-obj-09","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Que recherche-t-on par la palpation abdominale devant une ischémie aiguë de membre ?","answer":"Un anévrisme aortique","accept":["anévrisme aortique","anévrisme de l'aorte","anévrisme"],"keywords":["anevrisme"],"explanation":"La palpation abdominale recherche un anévrisme aortique, atteinte aortique pouvant être source d'embolie.","src":"p. 182","deep":"**Pourquoi** : devant toute ischémie aiguë, la palpation abdominale recherche un anévrisme aortique (p. 182) ; (rang B) l'anévrisme figure parmi les atteintes aortiques sources d'embolie, avec l'athérome aortique, les aortites et les tumeurs (p. 181).\n**Piège** : ne pas limiter l'examen au membre : auscultation cardiaque, ECG (arythmie) et palpation abdominale complètent toujours l'examen, avec un bilan de coagulation (p. 182).\n**À relier** : (rang B) en cas d'ischémie aiguë par embolie à partir d'un AAA, la revascularisation du membre est l'urgence, la cure de l'AAA vient ensuite (p. 186)."},{"id":"225-qroc-851","type":"QROC","rank":"A","objective":"225-obj-09","tags":["biologie","traitement"],"difficulty":2,"question":"Quel bilan biologique faut-il prélever avant de débuter l'héparine dans l'ischémie aiguë de membre ?","answer":"Le bilan de coagulation","accept":["bilan de coagulation","coagulation","bilan d'hémostase"],"keywords":["coagulation"],"explanation":"L'anticoagulation est débutée dès le diagnostic, après avoir prélevé le bilan de coagulation.","src":"p. 182","deep":"**Pourquoi** : le Collège fixe l'ordre : l'HNF est débutée dès le diagnostic, après avoir prélevé le bilan de coagulation (p. 182).\n**Piège** : aucune imagerie n'est attendue pour l'anticoagulation : héparine et antalgiques dès que possible, quel que soit le grade (fig. 7.7, p. 180).\n**À relier** : HNF : bolus 5 000 UI puis 500 UI/kg/j, TCA entre 2 et 3 (p. 182)."},{"id":"225-qroc-852","type":"QROC","rank":"A","objective":"225-obj-09","tags":["imagerie","étiologie"],"difficulty":2,"question":"Quel bilan artériel est réalisé après la revascularisation pour chercher la cause d'une ischémie aiguë ?","answer":"Échodoppler de l'aorte et des artères des membres inférieurs","accept":["échodoppler artériel","échodoppler de l'aorte","échodoppler","écho-doppler"],"keywords":["doppler"],"explanation":"Après la revascularisation, le bilan artériel comprend un échodoppler de l'aorte et des artères des membres inférieurs, voire un angioscanner ou une artériographie ; le bilan cardiaque (Holter, ETT, ETO) est également différé.","src":"p. 182","deep":"**Pourquoi** : une fois le membre sauvé, on cherche la cause : bilan artériel par échodoppler de l'aorte et des artères des membres inférieurs, voire angioscanner ou artériographie (p. 182).\n**Piège** : ces examens, comme le bilan cardiaque (Holter, ETT, voire ETO ou IRM), sont réalisés après la revascularisation : aucun ne doit retarder le geste (p. 180, 182).\n**À relier** : le traitement au long cours dépend de la cause : anticoagulation si FA, antiagrégant et contrôle des FdR si thrombose (p. 183)."},{"id":"225-qroc-853","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":1,"question":"Quel anticoagulant est utilisé dès le diagnostic d'une ischémie aiguë de membre ?","answer":"L'héparine non fractionnée (HNF)","accept":["héparine non fractionnée","hnf","héparine","héparine non fractionnée (HNF)"],"keywords":["heparine"],"explanation":"Le traitement médical comprend une anticoagulation par héparine non fractionnée dès le diagnostic, après prélèvement du bilan de coagulation.","src":"p. 182","deep":"**Pourquoi** : l'anticoagulation par HNF est débutée dès le diagnostic, après prélèvement du bilan de coagulation ; elle fait partie du traitement médical à tous les grades (p. 182 ; fig. 7.7, p. 180).\n**Piège** : ne pas attendre l'imagerie ni le geste pour l'instaurer (fig. 7.7, p. 180).\n**À relier** : posologie : bolus 5 000 UI puis 500 UI/kg/j, TCA 2-3 ; associer antalgiques (souvent niveau 3), oxygène, soins locaux (p. 182)."},{"id":"225-qroc-854","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel est le bolus initial d'héparine non fractionnée dans l'ischémie aiguë de membre ?","answer":"5 000 UI","accept":["5000 ui","5 000 ui","5000 unités","5 000 unités","5000","bolus de 5000 UI"],"keywords":[],"explanation":"Bolus de 5 000 UI d'HNF, puis perfusion continue de 500 UI/kg/j pour un TCA entre 2 et 3.","src":"p. 182","deep":"**Pourquoi** : le schéma du Collège est un bolus de 5 000 UI d'HNF, suivi d'une perfusion continue (p. 182).\n**Piège** : ne pas mélanger les unités : bolus en UI (5 000), perfusion en UI/kg/jour (500) (p. 182).\n**À relier** : objectif de TCA entre 2 et 3 ; héparine débutée après le prélèvement du bilan de coagulation (p. 182)."},{"id":"225-qroc-855","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quelle est la posologie de la perfusion continue d'héparine non fractionnée dans l'ischémie aiguë de membre ?","answer":"500 UI/kg/jour","accept":["500 ui/kg/j","500 ui/kg/jour","500 ui par kg par jour","500 ui/kg"],"keywords":["500"],"explanation":"Après un bolus de 5 000 UI, l'HNF est perfusée à 500 UI/kg/j avec un objectif de TCA entre 2 et 3.","src":"p. 182","deep":"**Pourquoi** : après le bolus de 5 000 UI, l'HNF est perfusée en continu à 500 UI/kg/j, adaptée au TCA (cible 2 à 3) (p. 182).\n**Piège** : dose exprimée par kg et par jour, pas par heure (p. 182).\n**À relier** : à distance, si la cause est une FA, le relais est une anticoagulation au long cours (p. 183)."},{"id":"225-qroc-856","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quelle position du membre est préconisée dans les soins locaux immédiats d'une ischémie aiguë ?","answer":"Une position légèrement déclive","accept":["légèrement déclive","position déclive","déclive"],"keywords":["declive"],"explanation":"Soins locaux immédiats, même après la revascularisation : protection par mousse ou coton, position légèrement déclive, éviction de tout frottement ou traumatisme cutané.","src":"p. 182","deep":"**Pourquoi** : un membre ischémique est fragile : soins locaux immédiats, même après revascularisation : protection mousse ou coton, position légèrement déclive, éviction de tout frottement ou traumatisme (p. 182).\n**Piège** : ne pas surélever le membre ; dans l'AOMI aussi, la douleur de décubitus est soulagée jambe pendante (p. 169).\n**À relier** : les soins locaux font partie du traitement médical avec héparine, antalgiques, oxygène et équilibration hémodynamique (p. 182)."},{"id":"225-qroc-857","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Sous quel contrôle l'embolectomie par sonde de Fogarty est-elle réalisée ?","answer":"Sous contrôle angiographique","accept":["contrôle angiographique","angiographique","angiographie"],"keywords":["angiograph"],"explanation":"L'embolectomie par sonde de Fogarty, méthode de référence des embolies sur artère saine, est réalisée sous contrôle angiographique ; elle peut parfois être utilisée sur des artères athéromateuses.","src":"p. 182","deep":"**Pourquoi** : l'embolectomie par sonde de Fogarty, réalisée sous contrôle angiographique, est la méthode de référence des embolies sur artère saine (p. 182).\n**Piège** : elle peut parfois être utilisée sur des artères athéromateuses, mais si le lit d'aval jambier est mauvais et l'ischémie peu sévère, on préfère la thrombolyse in situ (p. 182).\n**À relier** : une sténose résiduelle peut être traitée par angioplastie ; l'artériographie est le plus souvent faite au bloc (p. 180, 182)."},{"id":"225-qroc-858","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quelle technique de revascularisation utilise-t-on si le lit d'aval jambier est de mauvaise qualité et l'ischémie peu sévère ?","answer":"La thrombolyse in situ intra-artérielle (± thromboaspiration)","accept":["thrombolyse in situ","thrombolyse intra-artérielle","thromboaspiration","thrombolyse"],"keywords":["thrombolyse"],"explanation":"Dans ce cas, un fibrinolytique est injecté directement dans le thrombus par un cathéter laissé en place plusieurs heures, avec surveillance en milieu spécialisé et contrôles angiographiques répétés.","src":"p. 182","deep":"**Pourquoi** : si le lit d'aval jambier est mauvais et l'ischémie peu sévère, on peut injecter un fibrinolytique directement dans le thrombus (thrombolyse in situ intra-artérielle) ou recourir à la thromboaspiration (p. 182).\n**Piège** : pas de thrombolyse en cas d'ischémie sévère avec déficit neurologique (urgence absolue) ; elle n'est pas systémique (p. 180, 182).\n**À relier** : cathéter laissé plusieurs heures, surveillance en milieu spécialisé et contrôles angiographiques répétés (p. 182)."},{"id":"225-qroc-859","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel geste peut compléter la revascularisation en cas de sténose résiduelle ?","answer":"Une angioplastie","accept":["angioplastie","une angioplastie","angioplastie complémentaire"],"keywords":["angioplastie"],"explanation":"Qu'on ait recours à l'embolectomie ou à la thrombolyse, un geste d'angioplastie peut compléter la revascularisation s'il persiste une sténose résiduelle.","src":"p. 182","deep":"**Pourquoi** : après embolectomie ou thrombolyse, une sténose peut persister ; un geste d'angioplastie complète alors la revascularisation (p. 182).\n**Piège** : ne pas confondre avec le pontage, envisagé seulement en dernier ressort (souvent distal) (p. 182).\n**À relier** : en cas de revascularisation tardive, le geste est complété par une aponévrotomie de décompression (p. 183)."},{"id":"225-qroc-860","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quelle est la place du pontage dans la revascularisation de l'ischémie aiguë ?","answer":"En dernier ressort (souvent un pontage distal)","accept":["dernier ressort","en dernier recours","dernier recours"],"keywords":[],"explanation":"Dans certains cas, un pontage (souvent distal) peut être envisagé en dernier ressort.","src":"p. 182","deep":"**Pourquoi** : dans l'ischémie aiguë, les gestes de 1re ligne sont l'embolectomie (Fogarty) ou la thrombolyse/thromboaspiration ; le pontage, souvent distal, est envisagé dans certains cas en dernier ressort (p. 182).\n**Piège** : dans la figure 7.7, le pontage figure parmi les options au grade I et II : il reste possible, mais le Collège le situe en dernier ressort dans le texte (p. 180, 182).\n**À relier** : dans l'AOMI chronique, au contraire, le pontage est une technique de revascularisation à part entière (p. 176)."},{"id":"225-qroc-861","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","urgence"],"difficulty":1,"question":"Dans quelle situation propose-t-on d'emblée une amputation devant une ischémie aiguë ?","answer":"Quand l'ischémie est dépassée","accept":["ischémie dépassée","ischémie irréversible","dépassée"],"keywords":["depassee"],"explanation":"Lorsque l'ischémie est dépassée, une amputation d'emblée peut être envisagée ; elle peut aussi limiter les désordres métaboliques majeurs d'un syndrome de revascularisation ou faire suite à un échec de revascularisation sur terrain débilité.","src":"p. 183","deep":"**Pourquoi** : une ischémie dépassée (grade III : anesthésie importante, paralysie, perte tissulaire inévitable) n'est plus récupérable : une amputation d'emblée peut être envisagée (tableau 7.2, p. 179 ; p. 183).\n**Piège** : ne pas amputer un membre seulement menacé (grade II) : il relève d'une revascularisation en urgence absolue (fig. 7.7, p. 180).\n**À relier** : l'amputation peut aussi limiter les désordres métaboliques d'un syndrome de revascularisation ou suivre un échec de revascularisation, surtout sur terrain débilité (p. 183)."},{"id":"225-qroc-862","type":"QROC","rank":"A","objective":"225-obj-09","tags":["suivi","biologie"],"difficulty":2,"question":"Citez un paramètre de surveillance recherchant une acidose hyperkaliémique ou une insuffisance rénale aiguë après revascularisation d'un membre ischémique.","answer":"Diurèse horaire, ionogramme, urée, créatininémie et CPK","accept":["diurèse horaire","ionogramme","cpk","créatininémie","urée","diurèse","ionogramme sanguin","créatinine","CK","kaliémie","urée sanguine"],"keywords":[],"explanation":"Après revascularisation, on surveille la diurèse (sonde urinaire, diurèse horaire), l'ionogramme sanguin, l'urée, la créatininémie et les CPK.","src":"p. 183","deep":"**Pourquoi** : la reperfusion libère potassium, acides et myoglobine : acidose hyperkaliémique et insuffisance rénale aiguë sont recherchées systématiquement par diurèse horaire (sonde urinaire), ionogramme, urée, créatininémie et CPK (p. 178, 183).\n**Piège** : ne pas oublier la sonde urinaire avec diurèse horaire, premier élément de surveillance cité ; l'insuffisance rénale est une nécrose tubulaire aiguë (choc, myoglobine, produits de contraste) (p. 178-179, 183).\n**À relier** : traitement : bicarbonates IV, chélateur du potassium (Kayexalate®) voire dialyse, lavage du membre au sérum physiologique (p. 183)."},{"id":"225-qroc-863","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"question":"Quel geste local complète l'alcalinisation et le chélateur du potassium pour traiter les conséquences métaboliques de la revascularisation ?","answer":"Un lavage du membre au sérum physiologique","accept":["lavage du membre","lavage de membre","lavage au sérum physiologique"],"keywords":["lavage"],"explanation":"Les conséquences métaboliques sont traitées par alcalinisation progressive (bicarbonates IV), chélateur du potassium voire dialyse, et lavage du membre au sérum physiologique.","src":"p. 183","deep":"**Pourquoi** : les conséquences métaboliques se traitent par alcalinisation progressive (bicarbonates IV), chélateur du potassium voire dialyse, et lavage du membre au sérum physiologique (p. 183).\n**Piège** : le traitement n'est pas que général : le lavage du membre est un temps local cité par le Collège (p. 183).\n**À relier** : surveillance associée : diurèse horaire, ionogramme, urée, créatininémie, CPK (p. 183)."},{"id":"225-qroc-864","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","prévention"],"difficulty":1,"question":"Quel traitement au long cours est à envisager après une ischémie aiguë par embolie sur fibrillation atriale ?","answer":"Une anticoagulation au long cours","accept":["anticoagulation au long cours","anticoagulation","anticoagulant au long cours"],"keywords":["anticoag"],"explanation":"Le traitement étiologique d'une cause embolique est à envisager à plus long terme, par exemple une anticoagulation au long cours en cas de fibrillation atriale.","src":"p. 183","deep":"**Pourquoi** : après le geste, on traite la cause pour éviter la récidive : une embolie sur FA justifie une anticoagulation au long cours (p. 183).\n**Piège** : ne pas confondre avec l'origine thrombotique, qui relève d'un antiagrégant et du contrôle des facteurs de risque (p. 183).\n**À relier** : (rang B) la FA figure en tête des causes cardiaques d'embolie, et l'embolie peut suivre des épisodes de palpitations (p. 181)."},{"id":"225-qroc-865","type":"QROC","rank":"A","objective":"225-obj-09","tags":["traitement","prévention"],"difficulty":2,"question":"Quels traitements sont indispensables après une ischémie aiguë d'origine thrombotique ?","answer":"Antiagrégant plaquettaire et bon contrôle des facteurs de risque CV","accept":["antiagrégant plaquettaire","antiagrégant","antiplaquettaire"],"keywords":[],"explanation":"En cas d'origine thrombotique, un traitement antiagrégant plaquettaire et un bon contrôle des facteurs de risque cardiovasculaire sont indispensables.","src":"p. 183","deep":"**Pourquoi** : en cas d'origine thrombotique, le Collège juge indispensables un antiagrégant plaquettaire et un bon contrôle des facteurs de risque cardiovasculaire (p. 183).\n**Piège** : l'anticoagulation au long cours vise la cause embolique (ex : FA), pas la thrombose sur athérome (p. 183).\n**À relier** : c'est le même socle que l'AOMI symptomatique : antiagrégant, statine, arrêt du tabac (p. 175)."},{"id":"225-qroc-866","type":"QROC","rank":"A","objective":"225-obj-10","tags":["définition","épidémiologie"],"difficulty":2,"question":"Hors artères cérébrales, quelles sont les trois localisations anévrismales les plus fréquentes ?","answer":"Aorte (surtout sous-rénale), artères poplitées et iliaques","accept":["aorte, artères poplitées et iliaques","aorte poplitées iliaques","aorte et artères poplitées et iliaques"],"keywords":["aorte","poplit","iliaq"],"explanation":"En dehors des artères cérébrales, les anévrismes les plus fréquents siègent sur l'aorte (surtout sous-rénale, mais aussi ascendante), les artères poplitées et les artères iliaques.","src":"p. 183","deep":"**Pourquoi** : en dehors des artères cérébrales, les anévrismes siègent surtout sur l'aorte (sous-rénale surtout, mais aussi ascendante), les artères poplitées et iliaques (p. 183).\n**Piège** : devant un AAA, ne pas oublier ces localisations associées : l'échographie abdominale dépiste aussi les anévrismes poplités et iliaques (p. 184).\n**À relier** : définition : dilatation focale et permanente avec perte du parallélisme des parois et diamètre augmenté de plus de 50 % par rapport à l'amont (p. 183)."},{"id":"225-qroc-867","type":"QROC","rank":"A","objective":"225-obj-10","tags":["physiopathologie"],"difficulty":3,"question":"Quelles enzymes, dont la suractivité favorise la destruction de la matrice collagénique de la média aortique, sont citées dans l'AAA ?","answer":"Les métalloprotéases","accept":["métalloprotéases","métalloprotéinases","metalloproteases"],"keywords":["metalloprot"],"explanation":"La média aortique perd sa capacité à résister à la distension par destruction des fibres élastiques et fragmentation du collagène, favorisées par la suractivité d'enzymes détruisant la matrice collagénique (ex : métalloprotéases).","src":"p. 183","deep":"**Pourquoi** : la média aortique perd sa résistance à la distension par destruction des fibres élastiques et fragmentation du collagène, favorisées par la suractivité d'enzymes détruisant la matrice (ex : métalloprotéases) (p. 183).\n**Piège** : ce mécanisme concerne la média (et pas une sténose de la lumière comme dans l'AOMI) (p. 183).\n**À relier** : dans la grande majorité des cas, l'AAA siège sous les artères rénales (p. 183)."},{"id":"225-qroc-868","type":"QROC","rank":"A","objective":"225-obj-10","tags":["épidémiologie"],"difficulty":2,"question":"Quelle est la prévalence de l'AAA chez les hommes de plus de 65 ans dans les populations occidentales ?","answer":"De 2 à 5 %","accept":["2 à 5 %","2-5 %","entre 2 et 5 %","2 à 5"],"keywords":["2","5"],"explanation":"La prévalence des AAA, en baisse dans les populations occidentales, est de 2 à 5 % chez les hommes de plus de 65 ans ; entre 75 et 84 ans elle est d'environ 5 % chez l'homme et 3 % chez la femme.","src":"p. 183","deep":"**Pourquoi** : la prévalence de l'AAA, en baisse en Occident, est de 2 à 5 % chez l'homme de plus de 65 ans ; entre 75 et 84 ans, environ 5 % chez l'homme et 3 % chez la femme (p. 183).\n**Piège** : ne pas confondre avec l'AOMI : formes cliniques 1 à 5 % après 60 ans, jusqu'à 10-15 % en incluant les asymptomatiques (p. 168).\n**À relier** : c'est pourquoi le dépistage échographique cible notamment les hommes après 65 ans (221 p. 41 ; p. 184)."},{"id":"225-qroc-869","type":"QROC","rank":"A","objective":"225-obj-10","tags":["étiologie","épidémiologie"],"difficulty":3,"question":"Outre le tabagisme et les antécédents familiaux, quels patients sont à plus haut risque d'AAA ?","answer":"Ceux ayant une autre localisation aortique (thoracique) ou périphérique","accept":["autre localisation aortique","autre localisation artérielle périphérique","anévrisme thoracique","artériopathie périphérique"],"keywords":[],"explanation":"Les sujets atteints d'une autre localisation aortique (thoracique) ou artérielle périphérique sont à plus haut risque d'AAA, alors que les diabétiques sont moins souvent atteints.","src":"p. 183","deep":"**Pourquoi** : en dehors de l'âge, du tabac et des antécédents familiaux, une autre localisation aortique (thoracique) ou artérielle périphérique place à plus haut risque d'AAA (p. 183).\n**Piège** : le diabète ne figure pas parmi ces facteurs : les diabétiques sont même moins souvent atteints (p. 183).\n**À relier** : inversement, un AAA impose de chercher une maladie coronarienne ou une sténose carotidienne (p. 188)."},{"id":"225-qroc-870","type":"QROC","rank":"A","objective":"225-obj-10","tags":["pronostic","complications"],"difficulty":2,"question":"Quel est le risque annuel de rupture d'un anévrisme de l'aorte sous-rénale de diamètre inférieur à 40 mm ?","answer":"0,4 % par an","accept":["0,4 %","0,4 %/an","0,4","0.4 %"],"keywords":["0 4"],"explanation":"Le risque de rupture est très faible (0,4 %/an) en dessous de 40 mm, puis augmente de façon exponentielle (3 % à 50-59 mm, 15 % au-delà de 60 mm).","src":"p. 184","deep":"**Pourquoi** : le risque annuel de rupture est très faible (0,4 %/an) sous 40 mm, puis croît de façon exponentielle : 3 % à 50-59 mm, 15 % au-delà de 60 mm (p. 184).\n**Piège** : à diamètre égal, le risque est près de 4 fois plus élevé chez la femme (p. 184) ; ne pas confondre ces pourcentages avec les seuils chirurgicaux.\n**À relier** : seuil A de l'item 221 : 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an (221 p. 42) ; (rang B) item 225 : au-delà de 50-55 mm (p. 186)."},{"id":"225-qroc-871","type":"QROC","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":2,"question":"Citez une maladie génétique des tissus élastiques responsable de formes familiales d'AAA.","answer":"Maladie de Marfan, d'Ehlers-Danlos ou syndrome de Loeys-Dietz","accept":["marfan","ehlers-danlos","ehlers danlos","loeys-dietz","loeys dietz"],"keywords":[],"explanation":"Des formes familiales existent, avec parfois des entités génétiques identifiées, notamment des maladies des tissus élastiques : Marfan, Ehlers-Danlos, Loeys-Dietz.","src":"p. 184","deep":"**Pourquoi** : à côté de l'AAA athéromateux (80-90 %), il existe des formes familiales, parfois liées à une maladie génétique des tissus élastiques : Marfan, Ehlers-Danlos, Loeys-Dietz (p. 184).\n**Piège** : penser à ces maladies devant un AAA sans terrain athéromateux, plutôt que de tout attribuer à l'athérome (p. 184).\n**À relier** : (A) les antécédents familiaux d'anévrisme sont un des deux principaux facteurs de risque d'AAA, avec le tabac (p. 183)."},{"id":"225-qroc-872","type":"QROC","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":2,"question":"Citez une aortite inflammatoire pouvant évoluer vers un anévrisme de l'aorte abdominale.","answer":"Maladie de Takayasu, de Behçet ou de Horton","accept":["takayasu","maladie de takayasu","horton","maladie de horton","behçet","maladie de behçet","behcet"],"keywords":[],"explanation":"Dans d'autres cas, l'AAA est l'évolution d'une aortite inflammatoire (maladies de Takayasu, de Horton...).","src":"p. 184","deep":"**Pourquoi** : l'AAA peut être l'évolution d'une aortite : maladies de Takayasu, de Behçet ou de Horton (p. 184).\n**Piège** : ces mêmes maladies (Takayasu, Horton) figurent aussi parmi les artériopathies inflammatoires des membres inférieurs, causes non athéromateuses d'AOMI (p. 174).\n**À relier** : autrefois, les aortites infectieuses (syphilis) étaient fréquentes (p. 184)."},{"id":"225-qroc-873","type":"QROC","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":1,"question":"Quelle aortite infectieuse était fréquente par le passé, avec évolution possible vers l'AAA ?","answer":"La syphilis","accept":["syphilis","aortite syphilitique","syphilis tertiaire"],"keywords":["syphilis"],"explanation":"Par le passé, les aortites infectieuses (syphilis) étaient fréquentes.","src":"p. 184","deep":"**Pourquoi** : par le passé, les aortites infectieuses, en particulier syphilitiques, étaient une cause fréquente d'anévrisme (p. 184).\n**Piège** : ce n'est plus la cause principale : aujourd'hui, 80-90 % des AAA surviennent sur terrain athéromateux (p. 184).\n**À relier** : autres causes non athéromateuses : formes familiales (Marfan, Ehlers-Danlos, Loeys-Dietz) et aortites inflammatoires (p. 184)."},{"id":"225-qroc-874","type":"QROC","rank":"A","objective":"225-obj-12","tags":["diagnostic","clinique"],"difficulty":2,"question":"Quelle est la circonstance de découverte la plus fréquente d'un AAA asymptomatique ?","answer":"Une imagerie abdominale fortuite (échographie, scanner, IRM)","accept":["imagerie abdominale","imagerie fortuite","découverte fortuite","échographie fortuite"],"keywords":["imagerie"],"explanation":"L'AAA asymptomatique est le plus souvent découvert de façon fortuite, à la palpation abdominale (masse battante et expansive para-ombilicale) ou, plus souvent encore, lors d'une imagerie abdominale.","src":"p. 184","deep":"**Pourquoi** : l'AAA asymptomatique se découvre le plus souvent par hasard, et plus souvent sur une imagerie abdominale (échographie, scanner, IRM) qu'à la palpation (masse battante et expansive paraombilicale) (p. 184).\n**Piège** : ne pas attendre les symptômes : ils signent souvent une complication (fissuration, rupture) ; d'où le dépistage échographique des sujets à risque (p. 184).\n**À relier** : le dépistage de l'AAA fait partie du bilan du polyathéromateux, notamment chez l'homme après 65 ans (221 p. 41)."},{"id":"225-qroc-875","type":"QROC","rank":"B","objective":"225-obj-11","tags":["diagnostic","prévention"],"difficulty":2,"question":"Citez un facteur justifiant le dépistage échographique de l'AAA chez un sujet de moins de 65 ans.","answer":"Tabagisme, maladie athéromateuse ou antécédents familiaux d'anévrisme","accept":["tabagisme","maladie athéromateuse","antécédents familiaux","antécédents familiaux d'anévrisme"],"keywords":[],"explanation":"Le dépistage par échographie est indiqué chez les hommes de plus de 65 ans, ou plus jeunes s'ils ont des facteurs de risque : tabagisme, maladie athéromateuse, antécédents familiaux d'anévrisme.","src":"p. 184","deep":"**Pourquoi** : l'item 225 élargit le dépistage échographique de l'AAA aux sujets de moins de 65 ans ayant un facteur de risque : tabagisme, maladie athéromateuse ou antécédents familiaux d'anévrisme (p. 184).\n**Piège** : le diabète n'en fait pas partie : les diabétiques sont moins souvent atteints d'AAA (p. 183).\n**À relier** : (A) item 221 : dépistage notamment chez l'homme après 65 ans (221 p. 41) ; examen de dépistage = échographie abdominale (p. 184)."},{"id":"225-qroc-876","type":"QROC","rank":"A","objective":"225-obj-15","tags":["urgence","clinique"],"difficulty":2,"question":"Quel tableau clinique réalise habituellement une rupture intrapéritonéale d'AAA ?","answer":"Un tableau cataclysmique, sans possibilité d'intervenir à temps","accept":["cataclysmique","tableau cataclysmique","cataclysmique sans possibilité d'intervenir"],"keywords":["cataclysm"],"explanation":"En cas de rupture intrapéritonéale, le tableau est habituellement cataclysmique, sans la possibilité d'intervenir à temps ; la fissuration, elle, justifie un transfert d'urgence.","src":"p. 184","deep":"**Pourquoi** : la rupture intrapéritonéale provoque une hémorragie massive : tableau habituellement cataclysmique, sans possibilité d'intervenir à temps (p. 184).\n**Piège** : la fissuration (douleur abdominale ou lombaire ± choc) laisse encore le temps d'agir : urgence vitale, transfert en chirurgie vasculaire (p. 184).\n**À relier** : plus rarement, la fissuration se fait dans un organe voisin : fistule aortocave (insuffisance cardiaque à haut débit) ou aortodigestive (hémorragie digestive) (p. 184)."},{"id":"225-qroc-877","type":"QROC","rank":"A","objective":"225-obj-15","tags":["urgence"],"difficulty":1,"question":"Vers quelle structure doit être dirigé en urgence un patient présentant un AAA douloureux ?","answer":"Un centre spécialisé de chirurgie vasculaire","accept":["centre spécialisé de chirurgie vasculaire","chirurgie vasculaire","centre de chirurgie vasculaire"],"keywords":["chirurgie vasculaire"],"explanation":"Le caractère douloureux fait craindre une rupture imminente : le patient doit être dirigé d'urgence vers un centre spécialisé de chirurgie vasculaire, où un scanner abdominal confirme le diagnostic.","src":"p. 184","deep":"**Pourquoi** : un AAA douloureux fait craindre une rupture imminente : le patient est dirigé d'urgence vers un centre spécialisé de chirurgie vasculaire, où le scanner abdominal confirme le diagnostic et précise la localisation (p. 184).\n**Piège** : ne pas temporiser ni multiplier les examens : la rupture d'AAA est une urgence absolue dont le diagnostic est confirmé par scanner avant la prise en charge (p. 188).\n**À relier** : tableau d'alerte : douleur abdominale ou lombaire, associée ou non à un choc hémorragique (p. 184)."},{"id":"225-qroc-878","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique","complications"],"difficulty":2,"question":"Quelle complication d'un AAA, à partir de la thrombose intra-anévrismale, peut atteindre les membres ?","answer":"Une embolie (avec ischémie aiguë du membre)","accept":["embolie","embolique","thrombose intra-anévrismale"],"keywords":["embol"],"explanation":"Plus rarement, l'AAA se manifeste par une complication embolique à partir du thrombus intra-anévrismal, responsable d'une ischémie aiguë de membre (p. 184). (Rang B) La revascularisation du membre est alors prioritaire, la cure de l'AAA venant ensuite (p. 186).","src":"p. 184, 186","deep":"**Pourquoi** : le thrombus intra-anévrismal peut emboliser : l'AAA se révèle alors, plus rarement, par une ischémie aiguë de membre (p. 184).\n**Piège** : devant une ischémie aiguë, la palpation abdominale recherche un anévrisme, source d'embolie (p. 181-182).\n**À relier** : (rang B) dans ce cas, la revascularisation du membre est l'urgence, la cure de l'AAA venant secondairement (p. 186)."},{"id":"225-qroc-879","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique","complications"],"difficulty":2,"question":"Citez une manifestation de compression des organes adjacents par un AAA.","answer":"Érosion vertébrale, compression cave ou compression urétérale","accept":["érosion vertébrale","compression cave","compression urétérale","compression de la veine cave","compression de l'uretère"],"keywords":[],"explanation":"Plus rarement, l'AAA se manifeste par une compression des tissus et organes adjacents : érosion vertébrale, compression cave, compression urétérale.","src":"p. 184","deep":"**Pourquoi** : un AAA volumineux peut, plus rarement, comprimer ou éroder les structures voisines : érosion vertébrale, compression cave, compression urétérale (p. 184).\n**Piège** : ne pas confondre compression et fistule : la fistule est une fissuration dans un organe adjacent (aortocave, aortodigestive) (p. 184).\n**À relier** : autres modes de révélation rares : embolie à partir du thrombus et syndrome inflammatoire (p. 184)."},{"id":"225-qroc-880","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique"],"difficulty":2,"question":"Quel syndrome clinicobiologique peut, plus rarement, révéler un AAA ?","answer":"Un syndrome inflammatoire (fièvre, AEG, VS et CRP élevées)","accept":["syndrome inflammatoire","syndrome inflammatoire clinicobiologique","fièvre et vs et crp"],"keywords":["inflammatoire"],"explanation":"Un syndrome inflammatoire clinicobiologique (fièvre, altération de l'état général, augmentation de la VS et de la CRP) peut révéler un AAA, au même titre que l'embolie ou la compression d'organes.","src":"p. 184","deep":"**Pourquoi** : plus rarement, un AAA se révèle par un syndrome inflammatoire clinicobiologique : fièvre, altération de l'état général, VS et CRP augmentées (p. 184).\n**Piège** : un syndrome inflammatoire ne fait pas éliminer l'AAA ; (rang B) penser aussi qu'une aortite (Takayasu, Behçet, Horton) peut être à l'origine de l'anévrisme (p. 184).\n**À relier** : autres modes rares : embolie et compression ; le plus souvent, l'AAA reste asymptomatique et fortuit (p. 184)."},{"id":"225-qroc-881","type":"QROC","rank":"A","objective":"225-obj-13","tags":["imagerie"],"difficulty":1,"question":"Quelle alternative au scanner utilise-t-on pour explorer un AAA lorsque le scanner est contre-indiqué ?","answer":"L'IRM abdominale","accept":["irm","irm abdominale"],"keywords":["irm"],"explanation":"L'IRM abdominale est une alternative au scanner, notamment quand ce dernier est contre-indiqué.","src":"p. 185","deep":"**Pourquoi** : l'IRM abdominale est l'alternative au scanner, notamment quand celui-ci est contre-indiqué (p. 185).\n**Piège** : l'artériographie n'est pas une alternative : elle ne montre que la lumière et sous-estime la taille à cause du thrombus mural (p. 185).\n**À relier** : rôles : échographie = dépistage, mesure, suivi ; scanner injecté = examen préthérapeutique de référence (p. 184-185)."},{"id":"225-qroc-882","type":"QROC","rank":"A","objective":"225-obj-13","tags":["imagerie"],"difficulty":2,"question":"Quelles caractéristiques de l'anévrisme le scanner abdominopelvien injecté précise-t-il avant une intervention ?","answer":"Le diamètre et l'anatomie de l'anévrisme","accept":["diamètre et anatomie","diamètre et l'anatomie","diamètre et anatomie de l'anévrisme"],"keywords":["diametre","anatomi"],"explanation":"Le scanner abdominopelvien injecté, examen préthérapeutique de référence, est demandé quand une intervention est envisagée, pour préciser le diamètre et l'anatomie de l'anévrisme.","src":"p. 185","deep":"**Pourquoi** : quand une intervention est envisagée, le scanner abdominopelvien injecté précise le diamètre et l'anatomie de l'anévrisme : c'est l'examen préthérapeutique de référence (p. 185, 188).\n**Piège** : l'artériographie n'est pas utile : elle ne voit que la lumière et ne mesure pas fiablement l'AAA (thrombus mural fréquent) (p. 185).\n**À relier** : l'échographie dépiste, mesure le diamètre maximal et assure le suivi ; l'IRM remplace le scanner s'il est contre-indiqué (p. 184-185)."},{"id":"225-qroc-883","type":"QROC","rank":"B","objective":"225-obj-14","tags":["pronostic","physiopathologie"],"difficulty":1,"question":"Quel est le principal facteur prédictif du risque de rupture d'un AAA ?","answer":"Le diamètre de l'aorte (de l'anévrisme)","accept":["diamètre","diamètre de l'aorte","diamètre de l'anévrisme","taille","taille de l'anévrisme","le diamètre"],"keywords":["diametre"],"explanation":"Le diamètre est le principal facteur prédictif de rupture, d'où la surveillance échographique et le seuil d'intervention à 50-55 mm.","src":"p. 185","deep":"**Pourquoi** : le diamètre de l'aorte est le principal facteur prédictif de rupture : le risque annuel passe de 0,4 % sous 40 mm à 3 % à 50-59 mm et 15 % au-delà de 60 mm (p. 184-185).\n**Piège** : la vitesse de croissance, non linéaire et très variable, ne remplace pas la mesure du diamètre ; à diamètre égal, la femme rompt près de 4 fois plus (p. 184-185).\n**À relier** : d'où une surveillance échographique rapprochée (tous les 6 mois si > 45 mm) et une intervention au-delà de 50-55 mm (p. 185-186)."},{"id":"225-qroc-884","type":"QROC","rank":"B","objective":"225-obj-14","tags":["pronostic"],"difficulty":2,"question":"Quelle est la vitesse moyenne de croissance d'un AAA ?","answer":"2 à 4 mm par an","accept":["2-4 mm/an","2 à 4 mm par an","2 à 4 mm/an","2 à 4 mm"],"keywords":["2","4"],"explanation":"La croissance moyenne est de 2-4 mm/an, non linéaire, avec de grandes variations individuelles.","src":"p. 185","deep":"**Pourquoi** : la croissance moyenne d'un AAA est de 2 à 4 mm/an, mais elle n'est pas linéaire et varie beaucoup d'un patient à l'autre (p. 185).\n**Piège** : ne pas extrapoler une date de chirurgie à partir de la moyenne : les échographies répétées restent nécessaires (p. 185).\n**À relier** : croissance plus rapide chez l'homme, fumeur, à gros diamètre ; progression 3 fois plus rapide si le tabac est poursuivi (p. 185-186)."},{"id":"225-qroc-885","type":"QROC","rank":"B","objective":"225-obj-14","tags":["pronostic"],"difficulty":2,"question":"Citez un facteur associé à une croissance plus rapide d'un AAA.","answer":"Sexe masculin, tabagisme et diamètre anévrismal plus important","accept":["sexe masculin","homme","tabagisme","fumeur","diamètre plus important"],"keywords":[],"explanation":"La croissance est d'autant plus rapide qu'il s'agit d'un homme, fumeur, avec un diamètre anévrismal plus important ; la surveillance échographique est d'autant plus rapprochée que l'anévrisme est gros.","src":"p. 185","deep":"**Pourquoi** : la croissance d'un AAA est d'autant plus rapide que le patient est un homme, fumeur, et que l'anévrisme est déjà gros (p. 185).\n**Piège** : l'homme grossit plus vite, mais la femme rompt plus à diamètre égal (près de 4 fois) : deux notions distinctes (p. 184-185).\n**À relier** : la poursuite du tabagisme rend la progression 3 fois plus rapide, d'où un contrôle des facteurs de risque indispensable pendant le suivi (p. 186)."},{"id":"225-qroc-886","type":"QROC","rank":"B","objective":"225-obj-10","tags":["pronostic","prévention"],"difficulty":2,"question":"De quel facteur la progression d'un AAA est-elle multipliée par 3 ?","answer":"La poursuite du tabagisme","accept":["poursuite du tabagisme","tabagisme","tabac","tabagisme actif","poursuite du tabac"],"keywords":["taba"],"explanation":"La progression de l'anévrisme est 3 fois plus rapide en cas de poursuite du tabagisme, d'où l'importance du contrôle des facteurs de risque pendant le suivi.","src":"p. 186","deep":"**Pourquoi** : la poursuite du tabagisme multiplie par 3 la vitesse de progression de l'AAA, d'où le contrôle indispensable des facteurs de risque pendant le suivi (p. 186).\n**Piège** : ne pas confondre avec le « ×4 » du risque de rupture chez la femme à diamètre égal (p. 184).\n**À relier** : (A) le tabac est aussi l'un des deux principaux facteurs de risque d'apparition de l'AAA, avec les antécédents familiaux (p. 183)."},{"id":"225-qroc-887","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":2,"question":"Comment appelle-t-on la chirurgie conventionnelle « à ciel ouvert » de l'AAA ?","answer":"La mise à plat-greffe","accept":["mise à plat-greffe","mise à plat greffe","mise à plat"],"keywords":["mise a plat"],"explanation":"La chirurgie conventionnelle est la mise à plat-greffe : exclusion de la zone anévrismale avec interposition d'une prothèse vasculaire (pontage).","src":"p. 186","deep":"**Pourquoi** : la chirurgie conventionnelle « à ciel ouvert » de l'AAA est la mise à plat-greffe : exclusion de la zone anévrismale et interposition d'une prothèse vasculaire (pontage) (p. 186).\n**Piège** : ne pas confondre avec le traitement endovasculaire, endoprothèse introduite par voie fémorale (p. 186).\n**À relier** : après mise à plat-greffe : échodoppler au long cours pour les faux anévrismes anastomotiques (thrombose exceptionnelle) (p. 186)."},{"id":"225-qroc-888","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":2,"question":"En quoi consiste la mise à plat-greffe d'un AAA ?","answer":"Exclusion de la zone anévrismale et interposition d'une prothèse vasculaire","accept":["exclusion de la zone anévrismale","interposition d'une prothèse","interposition d'une prothèse vasculaire"],"keywords":["exclusion","prothese"],"explanation":"La zone anévrismale est exclue et remplacée par l'interposition d'une prothèse vasculaire (pontage).","src":"p. 186","deep":"**Pourquoi** : la mise à plat-greffe exclut la zone anévrismale et interpose une prothèse vasculaire (pontage) (p. 186).\n**Piège** : la complication surveillée n'est pas la thrombose (exceptionnelle) mais le faux anévrisme anastomotique, par échodoppler (p. 186).\n**À relier** : prothèse artérielle = risque d'infection lors d'une bactériémie, d'où une antibioprophylaxie possible avant un acte à risque (p. 186)."},{"id":"225-qroc-889","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":1,"question":"Par quelle voie introduit-on l'endoprothèse dans le traitement endovasculaire d'un AAA ?","answer":"Par voie intra-artérielle fémorale","accept":["voie fémorale","artère fémorale","intra-artérielle fémorale","voie intra-artérielle fémorale","par l'artère fémorale"],"keywords":["femoral"],"explanation":"L'endoprothèse est introduite par voie intra-artérielle fémorale puis déployée dans l'anévrisme ; la technique est moins invasive.","src":"p. 186","deep":"**Pourquoi** : l'endoprothèse est introduite par voie intra-artérielle fémorale puis déployée dans l'anévrisme : technique moins invasive que la chirurgie ouverte (p. 186).\n**Piège** : moins invasive ne veut pas dire sans suivi : imageries répétées (scanner, échographie de contraste) pour surveiller le sac et la prothèse (p. 186).\n**À relier** : elle exige des conditions anatomiques particulières ; proposée au haut risque chirurgical, possible au bas risque si anatomie favorable (p. 186)."},{"id":"225-qroc-890","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":2,"question":"Quelle contrainte limite les indications du traitement endovasculaire de l'AAA ?","answer":"Des conditions anatomiques particulières","accept":["conditions anatomiques","anatomie favorable","anatomie","conditions anatomiques particulières"],"keywords":["anatomi"],"explanation":"Le traitement endovasculaire nécessite des conditions anatomiques particulières ; si l'anatomie est favorable, il peut être proposé même chez des patients à bas risque après information éclairée.","src":"p. 186","deep":"**Pourquoi** : le traitement endovasculaire nécessite des conditions anatomiques particulières, qui peuvent limiter ses indications (p. 186).\n**Piège** : la contrainte est anatomique, pas le risque opératoire : l'endoprothèse est justement proposée aux sujets à haut risque chirurgical (p. 186).\n**À relier** : si l'anatomie est favorable, elle peut être proposée même au bas risque, après information éclairée (p. 186)."},{"id":"225-qroc-891","type":"QROC","rank":"B","objective":"225-obj-14","tags":["complications","suivi"],"difficulty":3,"question":"Citez un mécanisme d'endofuite après traitement endovasculaire d'un AAA.","answer":"Défaut de coaptation ou d'hermétisme, porosité, flux d'une branche (lombaires)","accept":["défaut de coaptation","défaut d'hermétisme","porosité de l'endoprothèse","artères lombaires","flux d'une branche artérielle"],"keywords":[],"explanation":"Les endofuites sont des flux maintenant une pression dans le sac : défaut de coaptation des extrémités avec la paroi aortique, défaut d'hermétisme entre deux endoprothèses, porosité de l'endoprothèse ou flux venant d'une branche artérielle connectée à l'aorte (ex : artères lombaires).","src":"p. 186","deep":"**Pourquoi** : une endofuite est un flux qui maintient une pression dans le sac malgré l'endoprothèse : défaut de coaptation des extrémités avec la paroi, défaut d'hermétisme entre deux endoprothèses, porosité, ou flux d'une branche connectée à l'aorte (artères lombaires) (p. 186).\n**Piège** : ne pas confondre avec le faux anévrisme anastomotique, complication de la prothèse de chirurgie conventionnelle (p. 186).\n**À relier** : conséquence : poursuite de l'évolution de l'anévrisme, voire rupture ; dépistage par scanner ou échographie au long cours (p. 186)."},{"id":"225-qroc-892","type":"QROC","rank":"B","objective":"225-obj-14","tags":["complications"],"difficulty":2,"question":"Quelle est la conséquence d'une endofuite sur l'anévrisme ?","answer":"Poursuite de l'évolutivité de l'anévrisme, voire risque de rupture","accept":["poursuite de l'évolutivité","évolutivité de l'anévrisme","risque de rupture"],"keywords":["evolutivite"],"explanation":"Les endofuites sont responsables d'une poursuite de l'évolutivité de l'anévrisme, voire d'un risque de rupture, d'où la surveillance au long cours par scanner ou échographie.","src":"p. 186","deep":"**Pourquoi** : un sac anévrismal encore sous pression continue d'évoluer : l'endofuite entraîne une poursuite de l'évolutivité de l'anévrisme, voire un risque de rupture (p. 186).\n**Piège** : une endoprothèse bien posée n'est pas un traitement « définitif » sans contrôle : surveillance au long cours par scanner ou échographie (p. 186).\n**À relier** : mécanismes : défaut de coaptation, d'hermétisme, porosité, flux d'une branche (artères lombaires) (p. 186)."},{"id":"225-qroc-893","type":"QROC","rank":"B","objective":"225-obj-14","tags":["suivi","prévention"],"difficulty":1,"question":"Que faut-il continuer à contrôler chez un patient opéré d'un AAA, même après une intervention réussie ?","answer":"Ses facteurs de risque cardiovasculaire","accept":["facteurs de risque","facteurs de risque cardiovasculaire"],"keywords":["facteurs de risque"],"explanation":"Même après une intervention réussie, le patient reste à haut risque cardiovasculaire et doit être surveillé, notamment par le contrôle de ses facteurs de risque.","src":"p. 186","deep":"**Pourquoi** : même après une cure réussie, le patient reste à haut risque cardiovasculaire : il doit être surveillé et ses facteurs de risque contrôlés (p. 186).\n**Piège** : le geste traite l'anévrisme, pas l'athérome : arrêter le suivi après l'intervention est une erreur (p. 186).\n**À relier** : (A) le porteur d'AAA risque 10 fois plus de mourir d'une atteinte coronarienne ou d'un AVC que d'une rupture (p. 184)."},{"id":"225-qroc-894","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique","imagerie"],"difficulty":2,"question":"Citez un contexte à risque élevé dans lequel on recherche un anévrisme poplité par échodoppler.","answer":"Risque élevé : AAA ou anévrisme poplité controlatéral","accept":["aaa","anévrisme poplité controlatéral","ap controlatéral","risque élevé"],"keywords":[],"explanation":"L'anévrisme poplité est découvert à la palpation (masse battante) ou à l'échodoppler, notamment chez les patients à risque élevé (AAA ou anévrisme poplité controlatéral).","src":"p. 186","deep":"**Pourquoi** : l'anévrisme poplité est associé à un AAA dans 30 % des cas et bilatéral dans près de la moitié des cas : un AAA ou un anévrisme poplité controlatéral justifie de le rechercher par échodoppler (p. 186).\n**Piège** : ne pas oublier l'autre jambe ni l'aorte devant un anévrisme poplité, et l'inverse (p. 186).\n**À relier** : l'examen de l'artéritique comprend la recherche systématique d'anévrisme au creux poplité et à l'abdomen (p. 170)."},{"id":"225-qroc-895","type":"QROC","rank":"A","objective":"225-obj-12","tags":["clinique"],"difficulty":2,"question":"En dehors de la palpation d'une masse battante, quels tableaux peuvent révéler un anévrisme poplité ?","answer":"Une artériopathie progressive ou une ischémie aiguë","accept":["artériopathie progressive","ischémie aiguë","artériopathie","ischémie"],"keywords":[],"explanation":"L'anévrisme poplité peut être découvert dans sa période asymptomatique (masse battante au creux poplité), à l'échodoppler, ou dans un tableau d'artériopathie progressive voire d'ischémie aiguë.","src":"p. 186","deep":"**Pourquoi** : l'anévrisme poplité peut être découvert à l'échodoppler ou se révéler par une artériopathie progressive, voire par une ischémie aiguë (p. 186).\n**Piège** : ne pas oublier l'ischémie aiguë parmi ses modes de révélation : (rang B) l'anévrisme poplité thrombosé est une cause de thrombose artérielle in situ (p. 181).\n**À relier** : à l'examen : masse battante au creux poplité, pouls « trop bien perçu » (p. 186)."},{"id":"225-qroc-896","type":"QROC","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":3,"question":"À quelles deux conditions le traitement endovasculaire d'un AAA peut-il être proposé même chez un patient à bas risque chirurgical ?","answer":"Anatomie favorable et information éclairée du patient","accept":["anatomie favorable","information éclairée","anatomie favorable et information éclairée"],"keywords":["anatomie","information"],"explanation":"Si l'anatomie est favorable, l'endoprothèse peut être proposée même chez des patients à bas risque, après une information éclairée, sachant qu'elle impose ensuite des imageries répétées de surveillance.","src":"p. 186","deep":"**Pourquoi** : l'endoprothèse est surtout proposée au haut risque chirurgical, mais si l'anatomie est favorable, elle peut être proposée même au bas risque, après une information éclairée du patient (p. 186).\n**Piège** : l'information doit porter sur la contrepartie : des imageries répétées à vie pour surveiller le sac et la prothèse (p. 186).\n**À relier** : contrainte principale : des conditions anatomiques particulières (p. 186)."},{"id":"225-qroc-897","type":"QROC","rank":"B","objective":"225-obj-15","tags":["traitement","urgence"],"difficulty":2,"question":"Dans le traitement d'un anévrisme rompu, chez quels patients l'endoprothèse est-elle d'autant plus souvent proposée ?","answer":"Ceux à très haut risque périopératoire (comorbidités)","accept":["très haut risque périopératoire","haut risque périopératoire","comorbidités","très haut risque"],"keywords":["risque"],"explanation":"L'anévrisme rompu est une urgence absolue ; le traitement par endoprothèse, de résultats satisfaisants dans les équipes expérimentées, est d'autant plus souvent proposé que le sujet est à très haut risque périopératoire (comorbidités).","src":"p. 186","deep":"**Pourquoi** : pour l'anévrisme rompu, l'endoprothèse donne des résultats satisfaisants dans les équipes expérimentées, et elle est d'autant plus souvent proposée que le sujet est à très haut risque périopératoire (comorbidités) (p. 186).\n**Piège** : l'endoprothèse n'est pas contre-indiquée en cas de rupture ; et aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention chez un patient en choc (p. 186).\n**À relier** : (A) la rupture d'AAA est une urgence absolue, confirmée par scanner avant la prise en charge thérapeutique (p. 188)."},{"id":"225-qru-701","type":"QRU","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":1,"stem":"Un homme de 62 ans, fumeur, consulte pour une crampe du mollet droit apparaissant après environ 200 mètres de marche sur terrain plat, l'obligeant à s'arrêter et disparaissant en 3 minutes. Il n'a ni douleur de repos ni plaie. À quel stade correspond ce tableau ?","options":[{"t":"Grade II de Rutherford","ok":false,"why":"Faux : le grade II de Rutherford (catégorie 4) est la douleur ischémique de repos ; la claudication est le grade I (catégories 1 à 3) (tableau 7.1, p. 168)."},{"t":"Stade IV de Leriche et Fontaine","ok":false,"why":"Faux : le stade IV suppose un ulcère ou une gangrène ; ici, aucune plaie (tableau 7.1, p. 168)."},{"t":"Stade II de Leriche et Fontaine","ok":true,"why":"Juste : douleur d'effort reproductible cédant à l'arrêt, sans douleur de repos ni trouble trophique = claudication intermittente, stade II (grade I de Rutherford) (p. 168)."},{"t":"Stade III de Leriche et Fontaine","ok":false,"why":"Faux : le stade III est la douleur de décubitus (brûlures de l'avant-pied soulagées jambe pendante) ; ce patient n'a pas de douleur de repos (p. 169)."},{"t":"Stade I de Leriche et Fontaine","ok":false,"why":"Faux : le stade I est l'AOMI asymptomatique ; ici la marche déclenche une douleur (p. 168)."}],"explanation":"Douleur de type crampe du mollet à la marche, cédant à l'arrêt en moins de 5 minutes, sans douleur de repos ni trouble trophique : claudication intermittente, stade II de Leriche et Fontaine, grade I de Rutherford.","src":"p. 168-169","deep":"**Pourquoi** : crampe du mollet déclenchée par une distance de marche, qui oblige à s'arrêter et cède en moins de 5 min : c'est la claudication intermittente, traduction d'une ischémie d'effort (le débit ne suit plus la demande du muscle) (p. 168).\n**Piège** : les deux classifications ne se superposent pas : Rutherford grade I = claudication (catégories 1-3), grade II = douleur de repos (catégorie 4) (tableau 7.1, p. 168).\n**À relier** : claudication sévère si distance de marche < 100 m ; douleur de décubitus (III) ou trouble trophique (IV) = ischémie permanente, à haut risque d'amputation sans revascularisation (p. 169)."},{"id":"225-qru-702","type":"QRU","rank":"A","objective":"225-obj-04","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Chez un patient de 70 ans, les pressions systoliques mesurées sont : bras droit 150 mmHg, bras gauche 140 mmHg ; cheville droite : tibiale postérieure 90 et pédieuse 100 mmHg ; cheville gauche : tibiale postérieure 135 et pédieuse 140 mmHg. Quelle est l'interprétation ?","options":[{"t":"IPS ininterprétable en raison d'une médiacalcose des deux chevilles","ok":false,"why":"Faux : la médiacalcose donne un IPS anormalement élevé (> 1,40) ; ici les deux IPS sont ≤ 0,93 (p. 171)."},{"t":"AOMI sévère à droite (IPS < 0,70), IPS gauche non pathologique","ok":true,"why":"Juste : 100/150 ≈ 0,67 (< 0,70 = sévère) à droite ; 140/150 ≈ 0,93 à gauche ; une seule cheville < 0,90 suffit au diagnostic (p. 171)."},{"t":"IPS normal des deux côtés","ok":false,"why":"Faux : à droite, l'IPS vaut environ 0,67, en dessous du seuil de 0,90 (p. 171)."},{"t":"IPS droit à 0,60, calculé avec la pression de cheville la plus basse","ok":false,"why":"Faux : on retient la plus élevée des deux pressions de cheville (100 et non 90), rapportée à la pression brachiale la plus élevée (p. 171)."},{"t":"AOMI bilatérale, car l'IPS gauche est inférieur à 1,00 et donc anormal","ok":false,"why":"Faux : l'AOMI se définit par un IPS < 0,90 ; 0,93 n'est pas pathologique (p. 171)."}],"explanation":"L'IPS de chaque membre est la pression de cheville la plus élevée (tibiale postérieure ou pédieuse) divisée par la pression brachiale la plus élevée. L'AOMI est retenue si au moins une cheville a un IPS < 0,90, et elle est sévère si l'IPS est < 0,70.","src":"p. 170-171","deep":"**Pourquoi** : pour chaque membre, IPS = pression de cheville la plus élevée (tibiale postérieure ou pédieuse) / pression brachiale la plus élevée des deux bras : à droite 100/150 ≈ 0,67, à gauche 140/150 ≈ 0,93 (p. 171).\n**Piège** : prendre la pression la plus basse (cheville ou bras) ou juger anormal un IPS entre 0,90 et 1,00 : le seuil d'AOMI est < 0,90, la normale 1,00-1,40 (p. 171).\n**À relier** : un IPS < 0,90 est aussi un marqueur de risque cardiovasculaire élevé (infarctus, AVC) : il impose le bilan des autres territoires (p. 170-171)."},{"id":"225-qru-703","type":"QRU","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":2,"stem":"Un homme de 75 ans, en fibrillation atriale non anticoagulée, présente depuis 4 heures une douleur brutale du membre inférieur droit. Le membre est froid et pâle, les pouls poplité et distaux sont abolis, le déficit sensitif remonte au-delà des orteils et il existe un déficit moteur modéré. Quelle est la conduite adaptée ?","options":[{"t":"Héparine non fractionnée et antalgiques dès que possible, puis revascularisation en urgence absolue","ok":true,"why":"Juste : au grade II, héparine et antalgiques d'emblée puis revascularisation en urgence absolue (thrombectomie ou pontage) (fig. 7.7, p. 180)."},{"t":"Échodoppler puis angioscanner avant tout geste, quitte à différer la prise en charge de quelques heures","ok":false,"why":"Faux : l'échodoppler n'est envisageable sans perte de temps qu'au grade I sans atteinte neurologique ; ici le déficit neurologique interdit tout retard (p. 180)."},{"t":"Surveillance, le membre étant encore viable","ok":false,"why":"Faux : « viable » correspond au grade I sans déficit ; un déficit sensitif au-delà des orteils avec déficit moteur = grade IIb (tableau 7.2, p. 179)."},{"t":"Amputation d'emblée","ok":false,"why":"Faux : l'amputation d'emblée se discute pour l'ischémie dépassée (grade III : anesthésie importante, paralysie) ; ici le déficit moteur est modéré (p. 179, 183)."},{"t":"Thrombolyse intra-artérielle de première intention","ok":false,"why":"Faux : la thrombolyse in situ s'adresse aux ischémies peu sévères avec lit d'aval jambier de mauvaise qualité, pas à un grade IIb avec déficit neurologique (p. 182)."}],"explanation":"Déficit sensitif au-delà des orteils et déficit moteur modéré : grade IIb de Rutherford (ischémie immédiatement menaçante). La prise en charge repose sur l'héparine, les antalgiques et une revascularisation en urgence absolue, sans exploration retardant l'intervention.","src":"p. 179-180","deep":"**Pourquoi** : déficit sensitif dépassant les orteils + déficit moteur modéré = grade IIb (ischémie immédiatement menaçante) : les nerfs souffrent dès 2 h et les muscles à 6-8 h, le membre n'est récupérable que si la prise en charge est immédiate (p. 178-179).\n**Piège** : demander une imagerie avant le geste : en cas d'atteinte neurologique (grade II), aucune exploration ne doit retarder l'intervention (notion inacceptable, p. 180, 188).\n**À relier** : héparine (après le bilan de coagulation) et antalgiques dès que possible à tous les grades ; grade I = imagerie en urgence puis revascularisation dans les heures ; grade III = amputation (fig. 7.7, p. 180)."},{"id":"225-qru-704","type":"QRU","rank":"A","objective":"225-obj-14","tags":["traitement"],"difficulty":2,"stem":"Un homme de 66 ans, fumeur, asymptomatique, a un anévrisme de l'aorte sous-rénale mesuré à 56 mm à l'échographie. Quelle est la prise en charge ?","options":[{"t":"Intervention en urgence dans les 24 heures","ok":false,"why":"Faux : l'anévrisme est asymptomatique ; l'urgence est réservée à la fissuration ou à la rupture (douleur abdominale ou lombaire ± choc) (p. 184)."},{"t":"Simple surveillance échographique tous les 6 mois, sans aucune intervention","ok":false,"why":"Faux : (rang B) la surveillance semestrielle concerne les AAA > 45 mm encore sous le seuil (p. 185) ; à 56 mm, le seuil de 55 mm de l'item 221 est dépassé (221 p. 42)."},{"t":"Intervention programmée « à froid », après un scanner injecté","ok":true,"why":"Juste : diamètre ≥ 55 mm = indication chirurgicale (221 p. 42) ; le scanner injecté précise diamètre et anatomie avant le geste (p. 185)."},{"t":"Contrôle des facteurs de risque seul, la rupture étant considérée comme improbable","ok":false,"why":"Faux : le risque annuel de rupture est de 3 % entre 50 et 59 mm et de 15 % au-delà de 60 mm (p. 184) ; le contrôle des FdR accompagne le geste, sans le remplacer."},{"t":"Artériographie pour mesurer précisément le diamètre","ok":false,"why":"Faux : l'artériographie ne montre que la lumière ; le thrombus mural, fréquent, fait sous-estimer la taille (p. 185)."}],"explanation":"Un AAA asymptomatique de plus de 50-55 mm justifie une intervention programmée « à froid » (mise à plat-greffe ou endoprothèse), précédée d'un scanner abdominopelvien injecté qui précise diamètre et anatomie.","src":"p. 185-186","deep":"**Pourquoi** : à 56 mm, le seuil chirurgical de l'AAA asymptomatique est dépassé : item 221, 55 mm (50 mm chez la femme) ou croissance ≥ 5 mm/an (221 p. 42) ; (rang B) l'item 225 retient « au-delà de 50-55 mm », intervention programmée « à froid » (p. 186).\n**Piège** : asymptomatique = geste programmé, pas une urgence ; seule la rupture ou la fissuration (douleur abdominale ou lombaire) est une urgence (p. 184, 188).\n**À relier** : le scanner abdominopelvien injecté est l'examen préthérapeutique de référence (diamètre + anatomie), l'échographie servant au dépistage et au suivi (p. 184-185, 188)."},{"id":"225-qru-705","type":"QRU","rank":"B","objective":"225-obj-02","tags":["étiologie","clinique"],"difficulty":2,"stem":"Concernant l'AOMI du patient diabétique, quelle proposition est exacte ?","options":[{"t":"La gangrène y est moins fréquente que chez le patient non diabétique","ok":false,"why":"Faux : la gangrène est plus fréquente chez le diabétique, souvent avec des lésions infectées (p. 169)."},{"t":"Elle est plus souvent grave d'emblée, plus distale, de pronostic plus sévère","ok":true,"why":"Juste : c'est la particularité de l'AOMI liée au diabète, alors que le tabac est plus fréquent chez le sujet jeune (p. 168)."},{"t":"L'IPS y est toujours abaissé, ce qui rend la pression d'orteil inutile","ok":false,"why":"Faux : la médiacalcose fréquente du diabétique donne un IPS > 1,40 non interprétable ; on mesure alors la pression d'orteil (p. 170-171)."},{"t":"Elle touche presque exclusivement les artères aorto-iliaques proximales","ok":false,"why":"Faux : l'atteinte du diabétique est plus distale (p. 168) ; l'atteinte aorto-iliaque donne plutôt une claudication fessière (syndrome de Leriche, p. 169)."},{"t":"Elle survient plus souvent chez le sujet jeune que celle du patient fumeur","ok":false,"why":"Faux : c'est le tabagisme qui prédomine chez le sujet plus jeune (p. 168)."}],"explanation":"Le tabagisme est plus fréquent chez le sujet plus jeune ; le diabète est plus souvent responsable de formes graves d'emblée, avec une atteinte plus distale et un pronostic plus sévère.","src":"p. 168, 171","deep":"**Pourquoi** : tabac et diabète sont les deux grands facteurs de risque ; le tabac domine chez le plus jeune, le diabète donne des formes graves d'emblée, plus distales, de pronostic plus sévère (p. 168).\n**Piège** : chez le diabétique âgé ou dialysé, la médiacalcose rigidifie les artères : IPS faussement élevé (> 1,40), d'où la pression d'orteil (index < 0,70 = AOMI) (p. 171).\n**À relier** : la neuropathie diabétique peut masquer la claudication : AOMI « masquée » révélée d'emblée par une ischémie permanente, d'où le dépistage des populations à risque (p. 169)."},{"id":"225-qru-706","type":"QRU","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"La mesure de la TcPO2 au dos du pied, après hyperémie par la chaleur, d'un patient suspect d'ischémie critique donne 22 mmHg. Quelle est l'interprétation ?","options":[{"t":"Valeur normale","ok":false,"why":"Faux : chez le sujet sain, la TcPO2 au dos du pied dépasse 50 mmHg (p. 171)."},{"t":"Hypoxie critique","ok":false,"why":"Faux : l'hypoxie critique correspond à une TcPO2 < 10 mmHg (p. 171)."},{"t":"Mesure ininterprétable, la PO2 cutanée de repos étant de 3 à 4 mmHg","ok":false,"why":"Faux : c'est justement pour cela qu'on provoque une hyperémie ; la valeur après hyperémie est interprétable (p. 171)."},{"t":"Bonne compensation métabolique de l'artériopathie","ok":false,"why":"Faux : une bonne compensation correspond à une TcPO2 > 35 mmHg (p. 171)."},{"t":"Hypoxie continue","ok":true,"why":"Juste : entre 10 et 35 mmHg, la TcPO2 traduit une hypoxie continue (p. 171)."}],"explanation":"TcPO2 après hyperémie : > 50 mmHg normale ; > 35 bonne compensation ; 10-35 hypoxie continue ; < 10 hypoxie critique.","src":"p. 171","deep":"**Pourquoi** : à l'état basal, la PO2 cutanée est très basse (3-4 mmHg) et ne distingue pas peau saine et ischémique ; on artérialise le flux par une hyperémie (chaleur) avant de lire la valeur : 22 mmHg tombe dans la zone 10-35 = hypoxie continue (p. 171).\n**Piège** : ne confonds pas avec l'hypoxie critique (< 10 mmHg) ni avec les pressions de l'ischémie critique (cheville < 50 mmHg, hallux < 30 mmHg) (p. 169, 171).\n**À relier** : la TcPO2 sert au diagnostic de l'ischémie critique et au choix du niveau d'amputation (zone bien oxygénée) (p. 171, 177)."},{"id":"225-qru-707","type":"QRU","rank":"A","objective":"225-obj-16","tags":["physiopathologie","étiologie"],"difficulty":1,"stem":"Quelle est la conséquence physiopathologique d'une sténose athéromateuse d'une artère rénale ?","options":[{"t":"HTA rénovasculaire par activation de la cascade rénine-angiotensine-aldostérone","ok":true,"why":"Juste : l'ischémie rénale active le SRAA, d'où une HTA rénovasculaire, une des étiologies d'HTA secondaire (p. 166)."},{"t":"Angor digestif postprandial","ok":false,"why":"Faux : il traduit une sténose du tronc cœliaque ou des artères mésentériques (ischémie mésentérique chronique), pas de l'artère rénale (p. 166)."},{"t":"Claudication fessière avec troubles de l'érection par atteinte aorto-iliaque","ok":false,"why":"Faux : c'est le syndrome de Leriche, lié à une atteinte aorto-iliaque (p. 169)."},{"t":"Ischémie rénale sans aucun retentissement sur la pression artérielle","ok":false,"why":"Faux : la réponse physiopathologique à l'ischémie rénale est l'activation du SRAA, donc une HTA (p. 166)."},{"t":"Hypotension par inhibition de la cascade rénine-angiotensine-aldostérone, avec insuffisance rénale fonctionnelle","ok":false,"why":"Faux : l'ischémie rénale active (et n'inhibe pas) la cascade rénine-angiotensine-aldostérone, ce qui élève la pression (p. 166)."}],"explanation":"L'athérome des artères rénales provoque une ischémie rénale et une activation de la cascade rénine-angiotensine-aldostérone, responsable d'une HTA rénovasculaire (HTA secondaire).","src":"p. 166","deep":"**Pourquoi** : la sténose athéromateuse de l'artère rénale rend le rein ischémique ; il répond en activant le système rénine-angiotensine-aldostérone, d'où une HTA rénovasculaire, cause d'HTA secondaire (p. 166).\n**Piège** : ne pas attribuer au rein les autres sténoses viscérales : tronc cœliaque et mésentériques donnent l'ischémie mésentérique (angor digestif) (p. 166).\n**À relier** : l'athérome aortique s'associe souvent à l'atteinte des autres branches de l'aorte (coronaires, digestives, rénales) : penser polyvasculaire (p. 166)."},{"id":"225-qru-708","type":"QRU","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Quel principe doit guider le niveau d'une amputation de membre inférieur pour ischémie permanente non revascularisable ?","options":[{"t":"Amputer au niveau de la dernière artère palpable, quelle que soit l'oxygénation de la peau","ok":false,"why":"Faux : le niveau est choisi en zone saine et bien oxygénée, ce que mesure la TcPO2, pas d'après le pouls palpable (p. 177)."},{"t":"Zone saine et bien oxygénée (TcPO2), en conservant l'appui ou le genou si possible","ok":true,"why":"Juste : règle du Collège : zone saine et bien oxygénée, en sauvegardant autant que possible l'appui (orteil, transmétatarsienne) ou le genou pour espérer un appareillage (p. 177)."},{"t":"Amputer toujours à la cuisse pour éviter tout problème de cicatrisation du moignon","ok":false,"why":"Faux : on cherche au contraire à garder l'appui ou le genou pour l'appareillage et l'autonomie (p. 177)."},{"t":"Amputer avant toute tentative de revascularisation, pour traiter rapidement la douleur","ok":false,"why":"Faux : l'amputation est le geste ultime, à défaut de toute possibilité de revascularisation (p. 176)."},{"t":"Choisir le niveau d'amputation d'après la seule valeur de l'IPS de repos du membre","ok":false,"why":"Faux : le critère est l'oxygénation de la zone d'amputation (TcPO2) ; l'IPS de repos est un outil diagnostique, parfois pris en défaut (médiacalcose) (p. 171, 177)."}],"explanation":"L'amputation, geste ultime, doit être faite en zone saine et bien oxygénée, en sauvegardant autant que possible l'appui (orteil, transmétatarsienne) ou le genou afin de permettre un appareillage.","src":"p. 176-177","deep":"**Pourquoi** : l'amputation, geste ultime faute de revascularisation possible, vise à traiter la douleur et/ou limiter l'infection ; elle se fait en zone saine et bien oxygénée (intérêt de la TcPO2) (p. 176-177).\n**Piège** : amputer « haut par sécurité » : on préserve autant que possible l'appui (orteil, transmétatarsienne) ou le genou pour permettre l'appareillage et la marche (p. 177).\n**À relier** : ischémie critique = revasculariser autant que possible ; amputation seulement en cas d'impossibilité ou d'échec sans autre option (p. 177)."},{"id":"225-qru-709","type":"QRU","rank":"B","objective":"225-obj-11","tags":["prévention","diagnostic"],"difficulty":2,"stem":"Parmi ces patients, lequel doit bénéficier d'un dépistage échographique de l'anévrisme de l'aorte abdominale ?","options":[{"t":"Une femme de 30 ans sans antécédent","ok":false,"why":"Faux : ni âge, ni tabac, ni athérome, ni antécédent familial : aucun critère de dépistage (p. 184)."},{"t":"Un diabétique de 50 ans sans autre facteur de risque","ok":false,"why":"Faux : le diabète ne fait pas partie des critères ; les diabétiques sont même moins souvent atteints d'AAA (p. 183)."},{"t":"Un homme de 55 ans non fumeur, sans athérome ni antécédent familial","ok":false,"why":"Faux : avant 65 ans, il faut un facteur de risque (tabac, athérome, antécédent familial d'anévrisme) (p. 184)."},{"t":"Un homme de 52 ans, fumeur, atteint d'une AOMI","ok":true,"why":"Juste : sujet plus jeune cumulant tabagisme et maladie athéromateuse, deux critères de dépistage (p. 184)."},{"t":"Un homme de 40 ans sans facteur de risque","ok":false,"why":"Faux : le dépistage cible l'homme > 65 ans, ou plus jeune seulement avec facteur de risque (p. 184)."}],"explanation":"L'échographie de dépistage de l'AAA s'adresse aux hommes de plus de 65 ans ou plus jeunes avec facteurs de risque (tabagisme, maladie athéromateuse, antécédents familiaux d'anévrisme).","src":"p. 184","deep":"**Pourquoi** : (rang B) l'item 225 cible le dépistage échographique de l'AAA chez l'homme > 65 ans ou plus jeune avec facteurs de risque : tabagisme, maladie athéromateuse, antécédents familiaux d'anévrisme (p. 184) ; ce fumeur de 52 ans avec AOMI en relève.\n**Piège** : le diabète n'est pas un critère : les diabétiques sont moins souvent atteints d'AAA (p. 183).\n**À relier** : l'item 221 (rang A) retient le dépistage de l'AAA « notamment chez l'homme après 65 ans » dans le bilan du polyathéromateux (221 p. 41) ; 80-90 % des AAA surviennent sur terrain athéromateux (p. 184)."},{"id":"225-qcm-701","type":"QRM","rank":"B","objective":"225-obj-17","tags":["paraclinique","imagerie"],"difficulty":2,"stem":"Un patient de 70 ans, polyathéromateux, amaigri, décrit des douleurs abdominales survenant après les repas ; un souffle abdominal est entendu. Une sténose du tronc cœliaque ou des artères mésentériques est suspectée. Quels examens peuvent confirmer la sténose artérielle ?","options":[{"t":"Échodoppler des artères digestives","ok":true,"why":"Juste : examen non invasif qui diagnostique la sténose des artères digestives (p. 166)."},{"t":"Artériographie diagnostique de première intention","ok":false,"why":"Faux : l'artériographie n'est réalisée que lors d'une procédure de revascularisation endovasculaire (p. 166)."},{"t":"Angioscanner","ok":true,"why":"Juste : l'angioscanner fait partie des imageries permettant de diagnostiquer la sténose (p. 166)."},{"t":"Test de marche sur tapis roulant (protocole de Strandness)","ok":false,"why":"Faux : c'est un test spécifique de l'AOMI des membres inférieurs (distance de marche, pressions de cheville après effort) (p. 171)."},{"t":"Angio-IRM","ok":true,"why":"Juste : alternative à l'angioscanner pour diagnostiquer la sténose (p. 166)."}],"explanation":"L'ischémie mésentérique chronique se manifeste par un angor digestif (douleurs postprandiales) avec parfois un souffle abdominal ; la sténose se diagnostique par échodoppler des artères digestives, angioscanner ou angio-IRM.","src":"p. 166","deep":"**Pourquoi** : angor digestif (douleur postprandiale), amaigrissement par restriction alimentaire et souffle abdominal évoquent une ischémie mésentérique chronique (A, p. 166) ; (rang B) la sténose se confirme par échodoppler des artères digestives, angioscanner ou angio-IRM (p. 166).\n**Piège** : l'artériographie n'est pas diagnostique : elle n'est réalisée qu'au cours d'une revascularisation endovasculaire (p. 166).\n**À relier** : la forme aiguë est une urgence vitale (douleur aiguë pauvre en signes physiques, vidange digestive, FA), à ne pas confondre avec l'angor digestif chronique (p. 167)."},{"id":"225-qcm-702","type":"QRM","rank":"A","objective":"225-obj-16","tags":["physiopathologie","épidémiologie"],"difficulty":2,"stem":"Concernant l'athérome de l'aorte, quelles propositions sont exactes ?","options":[{"t":"Les emboles fibrinocruoriques n'atteignent que les membres inférieurs","ok":false,"why":"Faux : ils peuvent toucher le cerveau (plaques de l'aorte ascendante ou horizontale), les membres ou les viscères abdominaux (p. 166)."},{"t":"Les sièges préférentiels sont la bifurcation aortique et l'origine des branches naissant de l'aorte","ok":true,"why":"Juste : tous les segments peuvent être atteints, mais ce sont les sièges préférentiels (p. 166)."},{"t":"Les calcifications aortiques asymptomatiques n'ont aucune valeur pronostique","ok":false,"why":"Faux : le risque cardiovasculaire augmente avec leur présence et leur extension, même asymptomatiques (p. 166)."},{"t":"Le tabagisme est le facteur de risque le plus fortement associé à ces lésions","ok":true,"why":"Juste : parmi tous les facteurs de risque, c'est le tabagisme (p. 166)."},{"t":"Les plaques sont le plus souvent symptomatiques","ok":false,"why":"Faux : elles sont le plus souvent asymptomatiques et découvertes fortuitement (calcifications à l'imagerie) (p. 166)."}],"explanation":"L'athérome aortique touche surtout la bifurcation et l'origine des branches, est le plus souvent asymptomatique, et son extension est un marqueur de risque cardiovasculaire ; le tabagisme est le facteur le plus associé.","src":"p. 166","deep":"**Pourquoi** : l'athérome aortique peut toucher tous les segments mais siège surtout à la bifurcation et à l'origine des branches de l'aorte ; le tabac est le facteur le plus associé ; il est le plus souvent asymptomatique, découvert sur des calcifications à l'imagerie (p. 166).\n**Piège** : « asymptomatique » ne veut pas dire « sans valeur » : la présence et l'extension des calcifications augmentent le risque cardiovasculaire global (p. 166).\n**À relier** : les plaques de l'aorte ascendante ou horizontale peuvent emboliser au cerveau ; les plaques aortiques sont souvent associées à une atteinte coronaire, digestive ou rénale (p. 166)."},{"id":"225-qcm-703","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique"],"difficulty":2,"stem":"Concernant la mesure de l'index de pression systolique (IPS), quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Un IPS supérieur à 1,40 traduit une sténose serrée","ok":false,"why":"Faux : il témoigne d'une rigidité artérielle par médiacalcose ; la pression d'orteil remplace alors celle de cheville (p. 171)."},{"t":"La pression de l'artère fibulaire est systématiquement mesurée à la cheville","ok":false,"why":"Faux : seules la tibiale postérieure et la pédieuse sont mesurées ; la fibulaire, difficile à repérer, ne l'est pas (p. 170)."},{"t":"Le dénominateur est la pression systolique la plus basse des deux bras","ok":false,"why":"Faux : on divise par la pression systolique brachiale la plus élevée des deux bras (p. 171)."},{"t":"La pression systolique de cheville est lue à la disparition du signal doppler lors du gonflage","ok":false,"why":"Faux : elle correspond à la réapparition du signal pendant le dégonflage progressif (p. 170)."},{"t":"Pour chaque membre, on retient la pression la plus élevée des deux artères de cheville (tibiale postérieure et pédieuse)","ok":true,"why":"Juste : la pression de cheville est la plus élevée des deux artères, rapportée à la pression brachiale la plus élevée (p. 170-171)."}],"explanation":"IPS = pression systolique de cheville la plus élevée (tibiale postérieure ou pédieuse) / pression systolique brachiale la plus élevée ; normal entre 1,00 et 1,40 ; AOMI si < 0,90 ; la fibulaire n'est pas mesurée.","src":"p. 170-171","deep":"**Pourquoi** : brassard à la cheville gonflé jusqu'à disparition du signal doppler puis dégonflé : la pression systolique est lue à la réapparition du signal ; on garde la plus élevée des deux artères de cheville (tibiale postérieure, pédieuse) et la plus élevée des deux bras (p. 170-171).\n**Piège** : un IPS > 1,40 n'est pas une sténose serrée mais une médiacalcose (artère rigide, incompressible) : on passe à la pression d'orteil (p. 171).\n**À relier** : normal 1,00-1,40 ; AOMI < 0,90 ; sévère < 0,70 ; chez le diabétique, l'insuffisant rénal ou le sujet très âgé, la pression d'orteil évite les faux négatifs (p. 170-171)."},{"id":"225-qcm-704","type":"QRM","rank":"A","objective":"225-obj-04","tags":["paraclinique","pièges"],"difficulty":3,"stem":"Concernant les tests de marche dans le bilan d'une AOMI, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une baisse de l'IPS de plus de 20 % juste après la marche est évocatrice d'AOMI","ok":true,"why":"Juste : critère du Collège, avec la baisse de pression de cheville > 30 mmHg (p. 171)."},{"t":"Le protocole de Strandness utilise une vitesse de 5 km/h et une pente de 15 %","ok":false,"why":"Faux : le protocole de Strandness, c'est 3,2 km/h et une pente de 10 % (p. 171)."},{"t":"Il est inutile quand l'IPS de repos est supérieur à 0,90","ok":false,"why":"Faux : c'est précisément chez le claudicant à IPS de repos > 0,90 qu'il sensibilise le diagnostic (p. 171)."},{"t":"Une baisse de la pression systolique de cheville de plus de 10 mmHg après la marche est évocatrice d'AOMI","ok":false,"why":"Faux : le seuil est une baisse de plus de 30 mmHg (p. 171)."},{"t":"Le test de marche de 6 minutes est spécifique de l'AOMI","ok":false,"why":"Faux : il n'est pas spécifique et évalue le handicap fonctionnel en général (p. 171)."}],"explanation":"Le test de marche sur tapis roulant (Strandness : 3,2 km/h, pente 10 %) évalue distance de gêne et de marche et réévalue les pressions de cheville : une baisse de pression > 30 mmHg et/ou de l'IPS > 20 % est évocatrice d'AOMI.","src":"p. 171","deep":"**Pourquoi** : un claudicant peut avoir un IPS de repos > 0,90 ; l'effort sur tapis (Strandness : 3,2 km/h, pente 10 %) démasque la sténose : baisse de pression de cheville > 30 mmHg et/ou de l'IPS > 20 % juste après la marche = évocateur d'AOMI (p. 171).\n**Piège** : le test de 6 minutes n'est pas spécifique de l'AOMI (il mesure le handicap global, ex. insuffisance cardiaque) (p. 171).\n**À relier** : ce test sert aussi au diagnostic différentiel des douleurs à la marche (canal lombaire étroit, etc.) et au suivi de la distance de marche (p. 171, 174)."},{"id":"225-qcm-705","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Un patient de 66 ans, ancien fumeur, a une AOMI symptomatique (claudication à 150 m), une HTA et un LDL-cholestérol à 1,6 g/L. Quelles propositions concernant son traitement médicamenteux sont exactes ?","options":[{"t":"Une statine est systématique, avec un LDL < 0,55 g/L et une réduction d'au moins 50 %","ok":true,"why":"Juste : le recours aux statines est systématique avec ces deux objectifs (p. 175)."},{"t":"Une bithérapie antiplaquettaire est prescrite à vie dès le diagnostic","ok":false,"why":"Faux : l'AOMI symptomatique relève d'un seul antiagrégant (aspirine ou clopidogrel) (p. 175) ; (rang B) la bithérapie est limitée à 1-6 mois après angioplastie (p. 176)."},{"t":"Les bêtabloquants sont contre-indiqués dans l'AOMI","ok":false,"why":"Faux : ils peuvent être proposés si indication formelle, avec prudence seulement en ischémie critique sans revascularisation possible (p. 175)."},{"t":"Un IEC ou un sartan peut être considéré, quel que soit le niveau de pression artérielle","ok":true,"why":"Juste : chez tout patient avec AOMI, en l'absence de contre-indication (p. 175)."},{"t":"Un antiagrégant plaquettaire (aspirine ou clopidogrel) est indiqué","ok":true,"why":"Juste : tout patient atteint d'AOMI symptomatique doit en bénéficier pour réduire infarctus et AVC (p. 175)."}],"explanation":"Traitement général de l'AOMI symptomatique : statine systématique (LDL < 0,55 g/L), antiagrégant plaquettaire (aspirine ou clopidogrel), IEC ou sartan possible chez tous, contrôle des facteurs de risque.","src":"p. 175","deep":"**Pourquoi** : toute AOMI symptomatique justifie un traitement général pour réduire infarctus et AVC : antiagrégant (aspirine ou clopidogrel), statine systématique (LDL < 0,55 g/L et baisse ≥ 50 %), IEC ou sartan envisageable quel que soit le niveau de PA (p. 175).\n**Piège** : bêtabloquant non contre-indiqué : possible si indication formelle (cardiopathie ischémique, IC à FE altérée…), avec prudence en ischémie critique non revascularisable (p. 175).\n**À relier** : (rang B) la bithérapie antiplaquettaire n'est proposée que 1 à 6 mois après une angioplastie (p. 176) ; cibles : PAS ≤ 120-129, HbA1c < 7 %, arrêt du tabac (p. 175)."},{"id":"225-qcm-706","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement","physiopathologie"],"difficulty":2,"stem":"Un patient claudicant est inclus dans un programme de marche régulière avec arrêt du tabac. Quels effets en sont attendus ?","options":[{"t":"Une disparition possible de la claudication","ok":true,"why":"Juste : la marche régulière et l'arrêt du tabac peuvent aller jusqu'à faire disparaître la claudication (p. 175)."},{"t":"Une amélioration de l'état métabolique musculaire (augmentation du pool mitochondrial)","ok":true,"why":"Juste : c'est l'effet musculaire décrit par le Collège (p. 175)."},{"t":"Un développement de la circulation collatérale","ok":true,"why":"Juste : l'effort répété et l'arrêt du tabac favorisent les collatérales, qui contournent la sténose (p. 175)."},{"t":"Un allongement de la distance de marche","ok":true,"why":"Juste : conséquence des collatérales et du meilleur métabolisme musculaire (p. 175)."},{"t":"Une dispense de statine et d'antiplaquettaire","ok":false,"why":"Faux : statine + antiplaquettaire et contrôle des facteurs de risque sont indiqués dans tous les cas de claudication (fig. 7.6, p. 177)."}],"explanation":"Arrêt du tabac et marche régulière favorisent la circulation collatérale et l'état métabolique musculaire, allongent la distance de marche voire font disparaître la claudication, sans dispenser du traitement médicamenteux.","src":"p. 175","deep":"**Pourquoi** : arrêt du tabac et marche régulière favorisent le développement de la circulation collatérale et améliorent le métabolisme musculaire (pool mitochondrial) : la distance de marche s'allonge, la claudication peut disparaître (p. 175).\n**Piège** : la marche complète le traitement général, elle ne le remplace pas : statine et antiplaquettaire restent indiqués dans tous les cas (fig. 7.6, p. 177).\n**À relier** : programme minimal 30-45 min, au moins 3 fois/semaine, en ralentissant ou s'arrêtant au seuil de la douleur ; réadaptation supervisée préférable, avec éducation thérapeutique (p. 175)."},{"id":"225-qcm-707","type":"QRM","rank":"A","objective":"225-obj-05","tags":["traitement"],"difficulty":2,"stem":"Dans quelles situations une revascularisation est-elle proposée au cours de l'AOMI ?","options":[{"t":"Ischémie permanente, autant que possible","ok":true,"why":"Juste : c'est l'indication principale, le pronostic du membre étant engagé (p. 176)."},{"t":"Claudication légère bien tolérée, d'emblée pour prévenir l'amputation","ok":false,"why":"Faux : une claudication non invalidante relève de la réadaptation à la marche et du traitement médical (fig. 7.6, p. 177)."},{"t":"Uniquement au stade de gangrène étendue","ok":false,"why":"Faux : elle est proposée dès l'ischémie permanente (douleur de décubitus, stade III, ou troubles trophiques, stade IV) (p. 169, 176)."},{"t":"Périmètre de marche très faible (< 100 m) avec handicap fonctionnel important, parfois d'emblée","ok":true,"why":"Juste : par exemple un handicap professionnel important (p. 176)."},{"t":"Atteinte aorto-iliaque sévère rendant illusoire le développement de collatérales","ok":true,"why":"Juste : indication d'emblée possible chez le claudicant (p. 176)."}],"explanation":"Revascularisation : ischémie permanente (autant que possible) ; claudication sévère altérant la qualité de vie après traitement médical bien mené, ou d'emblée si périmètre très faible (< 100 m) avec handicap important ou atteinte aorto-iliaque sévère.","src":"p. 176","deep":"**Pourquoi** : en ischémie permanente (stades III-IV), le membre est menacé : revascularisation proposée autant que possible ; chez le claudicant, traitement médical et réadaptation d'abord, revascularisation si claudication sévère altérant la qualité de vie (p. 176).\n**Piège** : revascularisation possible d'emblée chez le claudicant seulement si périmètre < 100 m avec handicap important (ex. professionnel) et/ou atteinte aorto-iliaque sévère rendant les collatérales illusoires (p. 176).\n**À relier** : en cas d'impossibilité ou d'échec de revascularisation de l'ischémie critique, l'amputation est à envisager (p. 177)."},{"id":"225-qcm-708","type":"QRM","rank":"B","objective":"225-obj-05","tags":["traitement"],"difficulty":3,"stem":"À propos des techniques de revascularisation dans l'AOMI, quelles propositions sont exactes ?","options":[{"t":"L'angioplastie des artères du pied est impossible","ok":false,"why":"Faux : l'angioplastie des artères distales (pied) s'est développée ces dernières années (p. 176)."},{"t":"Le pontage fémorofémoral croisé est un pontage anatomique de première intention","ok":false,"why":"Faux : c'est un pontage extra-anatomique, comme l'axillofémoral (p. 176)."},{"t":"L'angioplastie donne de meilleurs résultats sur les lésions courtes et proximales","ok":true,"why":"Juste : les résultats sont d'autant plus favorables que les lésions sont courtes et proximales (p. 176)."},{"t":"L'angioplastie sous-adventicielle est réservée aux sténoses courtes","ok":false,"why":"Faux : elle est proposée au contraire en cas d'occlusions longues (p. 176)."},{"t":"Le pontage est de préférence réalisé avec du matériel veineux","ok":true,"why":"Juste : matériel veineux de préférence, prothèse vasculaire à défaut (p. 176)."}],"explanation":"L'angioplastie (ballonnet ± stent) est d'autant plus efficace que les lésions sont courtes et proximales ; le pontage utilise de préférence du matériel veineux ; les pontages croisés fémorofémoral ou axillofémoral sont extra-anatomiques.","src":"p. 176","deep":"**Pourquoi** : la technique dépend de l'étendue et de la sévérité des lésions et de l'état du patient ; l'angioplastie réussit d'autant mieux que les lésions sont courtes et proximales, l'angioplastie sous-adventicielle étant possible pour les occlusions longues (p. 176).\n**Piège** : pontages croisé fémorofémoral et axillofémoral = extra-anatomiques ; les plus fréquents (aorto-bi-iliaque/bifémoral, fémoropoplité, fémorojambier) suivent l'anatomie (p. 176).\n**À relier** : pontage de préférence veineux, sinon prothèse ; après angioplastie, bithérapie antiplaquettaire 1 à 6 mois ; toute revascularisation impose une surveillance échodoppler (thrombose, dégradation) (p. 176)."},{"id":"225-qcm-709","type":"QRM","rank":"A","objective":"225-obj-09","tags":["physiopathologie","complications"],"difficulty":2,"stem":"Concernant le syndrome des loges au cours de l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Il est prévenu par une aponévrotomie de décompression systématique après toute revascularisation, même précoce","ok":false,"why":"Faux : l'aponévrotomie complète la revascularisation tardive, pour prévenir le syndrome des loges (p. 183)."},{"t":"Il résulte d'un œdème musculaire comprimant les tissus dans des loges aponévrotiques inextensibles","ok":true,"why":"Juste : l'œdème d'anoxie, dans des loges inextensibles, peut aller jusqu'à l'arrêt total de la circulation (p. 178)."},{"t":"Seule une aponévrotomie de décharge permet de libérer le muscle et de restaurer la circulation capillaire","ok":true,"why":"Juste : c'est le seul geste efficace une fois le syndrome des loges installé (p. 178)."},{"t":"Il est corrigé par une perfusion de bicarbonates","ok":false,"why":"Faux : les bicarbonates IV compensent l'acidose métabolique de la reperfusion (p. 183) ; la compression des loges est chirurgicale."},{"t":"Il est traité par une héparinothérapie à dose majorée","ok":false,"why":"Faux : l'héparine traite le processus thrombotique ; elle ne lève pas la compression (p. 178, 182)."}],"explanation":"L'anoxie musculaire entraîne vasodilatation capillaire, œdème et hausse de la pression interstitielle ; dans des loges aponévrotiques inextensibles, la compression arrête la circulation et seule l'aponévrotomie de décharge permet de la restaurer.","src":"p. 178, 183","deep":"**Pourquoi** : l'anoxie musculaire dilate les capillaires → œdème → hausse de la pression interstitielle ; dans des loges aponévrotiques inextensibles, l'œdème comprime jusqu'à l'arrêt circulatoire, et seule l'aponévrotomie de décharge rétablit la circulation capillaire (p. 178).\n**Piège** : l'aponévrotomie complète « généralement systématiquement » la revascularisation tardive (loge antéroexterne de jambe), pas toute revascularisation précoce (p. 183).\n**À relier** : autre conséquence de la reperfusion à rechercher systématiquement : acidose hyperkaliémique et insuffisance rénale aiguë (diurèse horaire, ionogramme, créatinine, CPK) (p. 183)."},{"id":"225-qcm-710","type":"QRM","rank":"A","objective":"225-obj-09","tags":["complications","physiopathologie"],"difficulty":3,"stem":"Quels mécanismes participent à l'insuffisance rénale aiguë après revascularisation d'une ischémie aiguë de membre ?","options":[{"t":"Un choc et une instabilité de la pression de perfusion rénale","ok":true,"why":"Juste : ils favorisent la nécrose tubulaire aiguë (p. 178)."},{"t":"Une thrombose bilatérale des artères rénales","ok":false,"why":"Faux : le Collège décrit une nécrose tubulaire aiguë, sans occlusion des artères rénales (p. 178-179)."},{"t":"La précipitation intratubulaire de myoglobine","ok":true,"why":"Juste : la myoglobine issue de la rhabdomyolyse précipite dans les tubules (p. 178)."},{"t":"La toxicité directe de la myoglobine en milieu acide","ok":true,"why":"Juste : l'acidose de reperfusion rend la myoglobine directement toxique pour le tubule (p. 179)."},{"t":"La toxicité des produits de contraste utilisés lors d'une artériographie","ok":true,"why":"Juste : elle s'ajoute aux autres mécanismes (p. 179)."}],"explanation":"L'insuffisance rénale de la reperfusion est une nécrose tubulaire aiguë secondaire au choc et à l'instabilité de perfusion rénale, à la précipitation intratubulaire de myoglobine, à sa toxicité en milieu acide et à celle des produits de contraste.","src":"p. 178-179","deep":"**Pourquoi** : la reperfusion libère les produits des cellules lysées (rhabdomyolyse) ; l'insuffisance rénale est une nécrose tubulaire aiguë, par choc et instabilité de la perfusion rénale, précipitation intratubulaire de myoglobine, toxicité de la myoglobine en milieu acide et des produits de contraste (p. 178-179).\n**Piège** : ce n'est pas une occlusion des artères rénales ; et la reperfusion, bien que nécessaire, est elle-même source de complications (p. 178).\n**À relier** : à rechercher systématiquement : diurèse horaire (sonde), ionogramme, urée, créatinine, CPK ; acidose → bicarbonates IV, hyperkaliémie → Kayexalate® voire dialyse (p. 183)."},{"id":"225-qcm-711","type":"QRM","rank":"B","objective":"225-obj-08","tags":["étiologie","diagnostic"],"difficulty":3,"stem":"Un homme de 32 ans, sans antécédent vasculaire, ressent depuis 2 heures une douleur très brutale et intense du membre inférieur gauche, qui est froid et livide, après un épisode de palpitations. Quelles propositions sont exactes ?","options":[{"t":"L'examen doit comprendre une auscultation cardiaque et un ECG à la recherche d'une arythmie","ok":true,"why":"Juste : ils font partie de l'examen initial de toute ischémie aiguë, ici pour rechercher une fibrillation atriale (p. 182)."},{"t":"Une embolie sur artères saines est l'hypothèse la plus probable","ok":true,"why":"Juste : sujet jeune sans antécédent vasculaire, douleur brutale et sévère, palpitations préalables (p. 181)."},{"t":"Le bilan cardiaque complet (Holter, ETT) doit précéder la revascularisation","ok":false,"why":"Faux : Holter, ETT, ETO ou IRM ne sont réalisés qu'après la revascularisation (p. 182)."},{"t":"L'intensité de la douleur s'explique par l'absence de collatérales","ok":true,"why":"Juste : sur artères saines, aucune collatéralité ne s'est développée, d'où une douleur brutale, aiguë et sévère (p. 181)."},{"t":"Il faut rechercher en priorité une AOMI préexistante sur l'autre membre","ok":false,"why":"Faux : cette recherche oriente vers la thrombose in situ du sujet âgé à facteurs de risque (p. 181)."}],"explanation":"L'embolie sur artères saines survient chez un sujet jeune sans antécédent vasculaire, avec douleur brutale et sévère (absence de collatérales), parfois après des palpitations. L'ECG et l'auscultation cardiaque sont immédiats ; le bilan cardiaque détaillé suit la revascularisation.","src":"p. 181-182","deep":"**Pourquoi** : sujet jeune, sans antécédent vasculaire, douleur très brutale et intense après des palpitations : embolie sur artères saines, d'origine cardiaque (arythmie) ; la douleur est sévère car il n'existe pas de collatérales préalables (p. 181).\n**Piège** : rechercher une AOMI sur l'autre membre oriente vers la thrombose in situ du sujet âgé, et le bilan cardiaque complet (Holter, ETT, voire ETO) vient après la revascularisation (p. 181-182).\n**À relier** : (A) l'examen est toujours complété par auscultation cardiaque, ECG, palpation abdominale (anévrisme) et bilan de coagulation (p. 182) ; référence pour l'embolie sur artère saine : embolectomie par sonde de Fogarty (p. 182)."},{"id":"225-qcm-712","type":"QRM","rank":"A","objective":"225-obj-09","tags":["urgence","traitement"],"difficulty":2,"stem":"Un patient de 80 ans présente une ischémie aiguë du membre inférieur viable (grade I de Rutherford) : aucun déficit sensitif ni moteur. Quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une amputation d'emblée est indiquée","ok":false,"why":"Faux : l'amputation concerne le grade III, irréversible (anesthésie importante, paralysie) (p. 179-180)."},{"t":"Un échodoppler est contre-indiqué car il retarderait la prise en charge","ok":false,"why":"Faux : au grade I, sans atteinte neurologique, un échodoppler peut être fait sans perte de temps (p. 180)."},{"t":"Héparine et antalgiques dès que possible, imagerie en urgence puis revascularisation dans les heures à venir","ok":true,"why":"Juste : c'est l'algorithme du grade I (fig. 7.7, p. 180)."},{"t":"Aucun traitement n'est nécessaire, le membre étant viable","ok":false,"why":"Faux : héparine et antalgiques sont débutés dès que possible quel que soit le grade (fig. 7.7, p. 180)."},{"t":"Une revascularisation en urgence absolue est faite sans aucune imagerie","ok":false,"why":"Faux : l'urgence absolue sans imagerie préalable concerne le grade II ; au grade I, l'imagerie en urgence précède la revascularisation (p. 180)."}],"explanation":"Grade I (viable) : pas de menace immédiate, urgence relative ; héparine et antalgiques, imagerie en urgence puis revascularisation dans les heures à venir (thrombolyse, thrombectomie ou pontage).","src":"p. 179-180","deep":"**Pourquoi** : grade I = membre viable, sans déficit sensitif ni moteur, pas de menace immédiate (urgence relative) : on a le temps d'une imagerie en urgence, puis revascularisation dans les heures à venir (thrombolyse, thrombectomie, pontage) (tableau 7.2 et fig. 7.7, p. 179-180).\n**Piège** : « viable » ne veut pas dire « rien à faire » : héparine et antalgiques dès que possible à tous les grades, soins locaux (fig. 7.7, p. 180).\n**À relier** : l'échodoppler n'est envisageable sans perte de temps qu'en l'absence d'atteinte neurologique ; dès le grade II, aucune exploration ne doit retarder l'intervention (p. 180)."},{"id":"225-qcm-713","type":"QRM","rank":"A","objective":"225-obj-09","tags":["traitement"],"difficulty":2,"stem":"Concernant la thrombolyse in situ dans l'ischémie aiguë de membre, quelles propositions sont exactes ?","options":[{"t":"Elle nécessite une surveillance en milieu spécialisé avec contrôles angiographiques répétés","ok":true,"why":"Juste : le cathéter reste en place plusieurs heures, d'où cette surveillance (p. 182)."},{"t":"Un fibrinolytique est injecté directement dans le thrombus par un cathéter laissé en place plusieurs heures","ok":true,"why":"Juste : c'est le principe de la thrombolyse in situ intra-artérielle (p. 182)."},{"t":"Elle est le traitement de référence de l'embolie sur artère saine","ok":false,"why":"Faux : la référence est l'embolectomie par sonde de Fogarty sous contrôle angiographique (p. 182)."},{"t":"Elle est indiquée en première intention en cas d'ischémie sévère avec déficit neurologique","ok":false,"why":"Faux : elle s'adresse aux ischémies peu sévères avec lit d'aval jambier de mauvaise qualité (p. 182) ; le déficit neurologique impose une revascularisation en urgence absolue (p. 180)."},{"t":"Elle est administrée par voie intraveineuse systémique","ok":false,"why":"Faux : elle est réalisée par voie intra-artérielle, au contact du thrombus (p. 182)."}],"explanation":"La thrombolyse in situ intra-artérielle (et la thromboaspiration) s'utilise si le lit d'aval jambier est de mauvaise qualité et l'ischémie peu sévère ; elle impose un cathéter en place plusieurs heures, une surveillance spécialisée et des contrôles angiographiques.","src":"p. 182","deep":"**Pourquoi** : la thrombolyse in situ injecte un fibrinolytique directement dans le thrombus par voie intra-artérielle, le cathéter restant en place plusieurs heures, sous surveillance spécialisée avec contrôles angiographiques répétés (p. 182).\n**Piège** : indication restreinte : lit d'aval jambier de mauvaise qualité ET ischémie peu sévère ; la référence pour l'embolie sur artère saine est l'embolectomie par sonde de Fogarty (p. 182).\n**À relier** : une sténose résiduelle peut être traitée par angioplastie dans les deux techniques ; pontage (souvent distal) en dernier ressort (p. 182)."},{"id":"225-qcm-714","type":"QRM","rank":"A","objective":"225-obj-10","tags":["épidémiologie","pronostic"],"difficulty":2,"stem":"Concernant le risque de rupture des anévrismes de l'aorte sous-rénale, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Le porteur d'un AAA décède plus souvent de rupture que d'un événement coronarien ou d'un AVC","ok":false,"why":"Faux : il risque environ 10 fois plus de décéder d'une autre atteinte cardiovasculaire (coronarienne ou AVC) que de rupture (p. 184)."},{"t":"Le risque annuel est indépendant du diamètre de l'anévrisme","ok":false,"why":"Faux : il dépend du diamètre et augmente de façon exponentielle (p. 184)."},{"t":"Le risque annuel est d'environ 15 % entre 50 et 59 mm","ok":false,"why":"Faux : il est d'environ 3 % entre 50 et 59 mm ; 15 % correspond aux AAA de plus de 60 mm (p. 184)."},{"t":"Le risque annuel est de 3 % pour un diamètre inférieur à 40 mm","ok":false,"why":"Faux : il est très faible sous 40 mm, 0,4 %/an ; 3 % correspond à 50-59 mm (p. 184)."},{"t":"À diamètre égal, le risque est près de 4 fois plus important chez la femme","ok":true,"why":"Juste : c'est le chiffre du Collège (p. 184)."}],"explanation":"Risque annuel de rupture : 0,4 % sous 40 mm, 3 % à 50-59 mm, 15 % au-delà de 60 mm ; près de 4 fois plus élevé chez la femme à diamètre égal ; mais le porteur d'AAA meurt 10 fois plus souvent d'une autre atteinte cardiovasculaire que de rupture.","src":"p. 184","deep":"**Pourquoi** : le risque de rupture croît de façon exponentielle avec le diamètre : 0,4 %/an sous 40 mm, 3 % à 50-59 mm, 15 % au-delà de 60 mm ; à diamètre égal, il est près de 4 fois plus élevé chez la femme (p. 184).\n**Piège** : la rupture n'est pas la première cause de décès du porteur d'AAA : il risque 10 fois plus de mourir d'une atteinte coronarienne ou d'un AVC (p. 184).\n**À relier** : d'où l'importance des mesures préventives générales (p. 184) ; l'item 221 retient par ailleurs un seuil chirurgical plus bas chez la femme (50 mm contre 55 mm, 221 p. 42)."},{"id":"225-qcm-715","type":"QRM","rank":"B","objective":"225-obj-11","tags":["étiologie"],"difficulty":2,"stem":"Concernant l'étiologie des anévrismes de l'aorte abdominale, quelles propositions sont exactes ?","options":[{"t":"Les aortites infectieuses (syphilis) en sont aujourd'hui la première cause","ok":false,"why":"Faux : elles étaient fréquentes par le passé ; aujourd'hui l'athérome est en cause dans 80-90 % des cas (p. 184)."},{"t":"Le diabète est le facteur de risque le plus fortement associé","ok":false,"why":"Faux : les diabétiques sont moins souvent atteints ; les principaux facteurs sont le tabagisme et les antécédents familiaux d'anévrisme (p. 183)."},{"t":"Dans 80 à 90 % des cas, l'AAA survient chez un sujet atteint de maladie athéromateuse","ok":true,"why":"Juste : notamment AOMI, mais aussi atteinte coronarienne ou carotidienne (p. 184)."},{"t":"Les maladies de Takayasu et de Horton n'ont aucun lien avec les anévrismes aortiques","ok":false,"why":"Faux : l'AAA peut être l'évolution d'une aortite (Takayasu, Behçet, Horton) (p. 184)."},{"t":"Il existe des formes familiales, parfois liées à des maladies des tissus élastiques comme le syndrome de Marfan","ok":true,"why":"Juste : Marfan, Ehlers-Danlos, Loeys-Dietz (p. 184)."}],"explanation":"L'AAA est athéromateux dans 80 à 90 % des cas ; plus rarement : formes familiales (maladies des tissus élastiques : Marfan, Ehlers-Danlos, Loeys-Dietz) ou évolution d'une aortite (Takayasu, Horton).","src":"p. 184","deep":"**Pourquoi** : dans 80-90 % des cas, l'AAA survient chez un athéromateux (AOMI surtout, coronaires, carotides) ; sinon formes familiales (maladies des tissus élastiques : Marfan, Ehlers-Danlos, Loeys-Dietz) ou évolution d'une aortite (Takayasu, Behçet, Horton) (p. 184).\n**Piège** : la syphilis était une cause fréquente autrefois, plus aujourd'hui ; et le diabète ne figure pas parmi les facteurs de risque d'AAA : les diabétiques sont même moins souvent atteints (p. 183-184).\n**À relier** : (A) facteurs de risque d'AAA en dehors de l'âge : tabagisme et antécédents familiaux d'anévrisme (p. 183, 187)."},{"id":"225-qcm-716","type":"QRM","rank":"B","objective":"225-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant le traitement endovasculaire d'un anévrisme de l'aorte abdominale, quelles propositions sont exactes ?","options":[{"t":"Il nécessite des conditions anatomiques particulières qui peuvent limiter ses indications","ok":true,"why":"Juste : c'est la principale limite de la technique (p. 186)."},{"t":"Il ne nécessite plus aucune imagerie de surveillance après la pose","ok":false,"why":"Faux : il impose des imageries répétées (scanner, échographie de contraste) pour surveiller le sac et l'endoprothèse (p. 186)."},{"t":"Il est contre-indiqué en cas de rupture, qui impose la chirurgie ouverte","ok":false,"why":"Faux : l'endoprothèse est aussi proposée pour l'anévrisme rompu, avec de bons résultats dans les équipes expérimentées (p. 186)."},{"t":"Il est réservé aux patients à très bas risque chirurgical","ok":false,"why":"Faux : il est proposé surtout aux sujets à haut risque chirurgical, et possible au bas risque si l'anatomie est favorable (p. 186)."},{"t":"L'endoprothèse est introduite par voie intra-artérielle fémorale","ok":true,"why":"Juste : c'est la voie d'abord du traitement endovasculaire (p. 186)."}],"explanation":"L'endoprothèse (voie fémorale) est moins invasive, proposée aux sujets à haut risque chirurgical, mais exige une anatomie favorable et une surveillance par imageries répétées.","src":"p. 186","deep":"**Pourquoi** : l'endoprothèse, introduite par voie artérielle fémorale et déployée dans l'anévrisme, est moins invasive que la mise à plat-greffe ; elle est proposée au haut risque chirurgical mais exige une anatomie favorable (p. 186).\n**Piège** : « moins invasive » ne veut pas dire « sans suivi » : imageries répétées (scanner, échographie de contraste) pour surveiller le sac et la position de la prothèse (endofuites) (p. 186).\n**À relier** : si l'anatomie est favorable, possible même au bas risque après information éclairée ; aussi proposée pour l'AAA rompu, d'autant plus que le risque périopératoire est très élevé (p. 186)."},{"id":"225-qcm-717","type":"QRM","rank":"B","objective":"225-obj-14","tags":["suivi","complications"],"difficulty":2,"stem":"Un homme de 72 ans a été opéré d'un AAA. Concernant son suivi, quelles propositions sont exactes ?","options":[{"t":"La thrombose de prothèse est une complication fréquente de la chirurgie conventionnelle","ok":false,"why":"Faux : la thrombose est exceptionnelle ; le risque surveillé est le faux anévrisme anastomotique (p. 186)."},{"t":"Après une mise à plat-greffe, l'échodoppler à long terme dépiste notamment les faux anévrismes anastomotiques","ok":true,"why":"Juste : c'est la surveillance des prothèses de chirurgie conventionnelle (p. 186)."},{"t":"Une antibioprophylaxie peut se justifier lors d'un acte à risque bactérien, du fait du risque d'infection de la prothèse","ok":true,"why":"Juste : une bactériémie expose toute prothèse artérielle à l'infection (p. 186)."},{"t":"Après endoprothèse, un scanner ou une échographie surveillent notamment les endofuites","ok":true,"why":"Juste : les endofuites entretiennent l'évolution de l'anévrisme, voire un risque de rupture (p. 186)."},{"t":"Une fois l'intervention réussie, le contrôle des facteurs de risque n'est plus nécessaire","ok":false,"why":"Faux : le patient reste à haut risque cardiovasculaire et doit contrôler ses facteurs de risque (p. 186)."}],"explanation":"Après AAA traité, le patient reste à haut risque cardiovasculaire ; échodoppler pour les prothèses conventionnelles (faux anévrismes anastomotiques), scanner ou échographie pour les endoprothèses (endofuites) ; antibioprophylaxie lors d'actes à risque bactérien.","src":"p. 186","deep":"**Pourquoi** : même après une cure réussie, le patient reste à haut risque cardiovasculaire : surveillance et contrôle des facteurs de risque (p. 186).\n**Piège** : complication propre à chaque technique : prothèse chirurgicale = faux anévrismes anastomotiques (échodoppler ; thrombose exceptionnelle) ; endoprothèse = endofuites (scanner ou échographie) (p. 186).\n**À relier** : une prothèse artérielle expose à un risque d'infection lors d'une bactériémie, d'où une antibioprophylaxie possible lors d'un acte à risque bactérien (p. 186) ; (A) penser aussi à rechercher une maladie coronarienne ou une sténose carotidienne (p. 188)."},{"id":"225-qcm-718","type":"QRM","rank":"B","objective":"225-obj-14","tags":["complications","physiopathologie"],"difficulty":3,"stem":"Concernant les endofuites après pose d'une endoprothèse aortique, quelles propositions sont exactes ?","options":[{"t":"Elles sont responsables d'une poursuite de l'évolutivité de l'anévrisme, voire d'un risque de rupture","ok":true,"why":"Juste : la pression persistante dans le sac fait évoluer l'anévrisme (p. 186)."},{"t":"Elles peuvent résulter d'un défaut d'hermétisme entre deux endoprothèses","ok":true,"why":"Juste : jonction non étanche entre deux modules, un des mécanismes décrits (p. 186)."},{"t":"Elles peuvent résulter d'un défaut de coaptation des extrémités de l'endoprothèse avec la paroi aortique","ok":true,"why":"Juste : l'extrémité n'est pas plaquée contre la paroi, le sang passe autour (p. 186)."},{"t":"Elles peuvent provenir d'une branche artérielle connectée à l'aorte, comme les artères lombaires","ok":true,"why":"Juste : flux rétrograde par une branche qui remet le sac sous pression (p. 186)."},{"t":"Elles sont dépistées par une artériographie diagnostique de première intention","ok":false,"why":"Faux : la surveillance au long cours repose sur le scanner ou l'échographie (p. 186)."}],"explanation":"Les endofuites sont des flux maintenant une pression dans le sac anévrismal (défaut de coaptation, défaut d'hermétisme entre endoprothèses, porosité, flux d'une branche comme les artères lombaires) ; elles font poursuivre l'évolution de l'anévrisme et menacent de rupture.","src":"p. 186","deep":"**Pourquoi** : une endofuite est un flux qui maintient une pression dans le sac anévrismal malgré l'endoprothèse : l'anévrisme continue d'évoluer et peut se rompre (p. 186).\n**Piège** : 4 mécanismes : défaut de coaptation des extrémités avec la paroi, défaut d'hermétisme entre deux endoprothèses, porosité, flux d'une branche connectée à l'aorte (artères lombaires) ; dépistage par scanner ou échographie, pas par artériographie (p. 186).\n**À relier** : après chirurgie conventionnelle, la complication surveillée est différente : faux anévrisme anastomotique, par échodoppler (p. 186)."},{"id":"225-qcm-719","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","complications"],"difficulty":2,"stem":"Concernant les ulcères et la gangrène de l'AOMI, quelles propositions sont exactes ?","options":[{"t":"Ils sont généralement de faible surface mais peuvent être creusants jusqu'à l'aponévrose ou l'os","ok":true,"why":"Juste : faible surface, mais profondeur possible jusqu'à l'aponévrose ou l'os (p. 169)."},{"t":"Les ulcères siègent le plus souvent aux zones de frottement ou d'appui (orteil, bord externe du pied, talon)","ok":true,"why":"Juste : orteil, dos et bord externe du pied, talon (p. 169)."},{"t":"L'ulcère « suspendu » siège à la malléole interne","ok":false,"why":"Faux : l'ulcère suspendu siège à la face antérieure de la jambe (p. 169)."},{"t":"Ils sont habituellement indolores","ok":false,"why":"Faux : plaies, ulcères et gangrènes de l'AOMI sont souvent très algiques (p. 169)."},{"t":"La gangrène, plus fréquente chez le diabétique, est souvent infectée","ok":true,"why":"Juste : elle siège surtout aux orteils ou au talon et peut s'étendre à l'avant-pied voire à la jambe (p. 169)."}],"explanation":"Ulcères artériels : zones d'appui ou de frottement, faible surface mais creusants, souvent très douloureux ; gangrène surtout aux orteils ou au talon, plus fréquente et souvent infectée chez le diabétique.","src":"p. 169","deep":"**Pourquoi** : au stade IV, la peau devient mince, fragile, dépilée, puis apparaissent ulcères et gangrène, souvent très douloureux, portes d'entrée d'infection (cellulite, arthrite, ostéite, septicémie) (p. 169).\n**Piège** : l'ulcère « suspendu » siège à la face antérieure de la jambe, pas à la malléole ; un geste minime (pédicure agressif) peut déclencher l'ulcère (p. 169).\n**À relier** : ischémie permanente (stades III-IV) = revascularisation autant que possible ; soins de plaies par une équipe multidisciplinaire spécialisée (p. 176)."},{"id":"225-qcm-720","type":"QRM","rank":"A","objective":"225-obj-03","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Concernant les formes atypiques de claudication artérielle, quelles propositions sont exactes ?","options":[{"t":"La douleur est toujours localisée au mollet","ok":false,"why":"Faux : elle peut siéger au pied, à la cuisse ou à la fesse (atteinte aorto-iliaque) (p. 169)."},{"t":"La douleur cède habituellement après 30 minutes de repos","ok":false,"why":"Faux : la douleur disparaît habituellement en moins de 5 minutes à l'arrêt (p. 168)."},{"t":"Une parésie du membre sans douleur avec dérobement des jambes en est une forme habituelle","ok":false,"why":"Faux : ce tableau évoque une atteinte médullaire, diagnostic différentiel de l'AOMI (p. 174)."},{"t":"La distance de marche peut varier d'un jour à l'autre","ok":true,"why":"Juste : classiquement stable, elle peut varier dans les formes atypiques (p. 169)."},{"t":"La douleur peut être remplacée par une paresthésie ou un engourdissement d'effort","ok":true,"why":"Juste : forme atypique décrite par le Collège (p. 169)."}],"explanation":"Formes atypiques de claudication : distance de marche variable d'un jour à l'autre, autres localisations (pied, cuisse, fesse), douleur de faible intensité, paresthésie ou engourdissement d'effort, sujet qui ralentit sans s'arrêter.","src":"p. 168-169","deep":"**Pourquoi** : la forme typique est une crampe du mollet à distance de marche stable, qui cède en moins de 5 min ; les formes atypiques sont fréquentes : distance variable, pied/cuisse/fesse, douleur faible, paresthésie ou engourdissement d'effort, patient qui ralentit sans s'arrêter (p. 168-169).\n**Piège** : parésie sans douleur avec dérobement des jambes = atteinte médullaire, diagnostic différentiel (p. 174).\n**À relier** : avant d'interroger sur la marche, s'assurer que le patient marche vraiment : sujet âgé ou neuropathe peut être révélé d'emblée par une ischémie permanente (AOMI masquée) (p. 169)."},{"id":"225-qcm-721","type":"QRM","rank":"A","objective":"225-obj-03","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un patient de 74 ans se plaint de douleurs des membres inférieurs. Quelles propositions concernant les diagnostics différentiels de l'AOMI sont exactes ?","options":[{"t":"Un canal lombaire étroit donne des douleurs ou paresthésies à l'effort cédant au repos","ok":true,"why":"Juste : c'est le principal diagnostic différentiel neurologique de la claudication (p. 174)."},{"t":"Une claudication veineuse post-thrombotique donne des douleurs de décubitus","ok":false,"why":"Faux : elle figure parmi les douleurs à la marche ; les douleurs de décubitus non artérielles sont neuropathiques, SDRC ou radiculaires (p. 174)."},{"t":"Le seul diagnostic différentiel de l'ulcère artériel est l'ulcère neuropathique","ok":false,"why":"Faux : il faut discuter les ulcères veineux, microcirculatoires, neuropathiques et traumatiques (p. 174)."},{"t":"Les douleurs musculaires sous statines excluent le diagnostic d'AOMI","ok":false,"why":"Faux : elles peuvent mimer une AOMI, mais les tableaux peuvent être intriqués (p. 174)."},{"t":"Une neuropathie sensorielle ou un syndrome régional douloureux complexe peuvent expliquer une douleur de décubitus","ok":true,"why":"Juste : avec la compression radiculaire, ce sont les diagnostics différentiels de la douleur de décubitus (p. 174)."}],"explanation":"Chez le sujet âgé, plusieurs causes de douleurs de membre peuvent coexister ; à la marche : canal lombaire étroit, atteinte médullaire, causes veineuses, rhumatologiques, musculaires (statines) ; au repos : neuropathies, syndromes régionaux douloureux complexes, compression radiculaire.","src":"p. 174","deep":"**Pourquoi** : chez le sujet âgé, plusieurs causes de douleur de membre coexistent souvent ; on les classe selon le contexte : à la marche (canal lombaire étroit, médullaire, veineuse, rhumato, statines), de décubitus (neuropathie, SDRC, compression radiculaire), ulcères (veineux, microcirculatoire, neuropathique, traumatique) (p. 174).\n**Piège** : une cause n'exclut pas l'autre : douleurs sous statines ou canal lombaire étroit peuvent être intriqués avec une vraie AOMI (p. 174).\n**À relier** : le test de marche avec mesure des pressions de cheville aide au diagnostic différentiel des douleurs à la marche (p. 171)."}],"edn":[{"id":"225-kfp-01","type":"KFP","rank":"A","objective":"225-obj-03","difficulty":2,"scenario":"Mme B., 68 ans, diabétique de type 2 et tabagique, consulte pour une gêne du mollet gauche apparaissant après environ 250 mètres de marche, cédant rapidement à l'arrêt. Elle rapporte aussi une fatigabilité inhabituelle à la marche depuis quelques mois. L'examen retrouve un pouls pédieux gauche non perçu et un IPS à 0,68 à gauche.","questions":[{"stem":"Quel est le stade clinique le plus probable selon la classification de Leriche et Fontaine ?","max":1,"options":["Stade I","Stade II","Stade III","Stade IV","Stade 0","Ischémie mésentérique","Syndrome des loges","Médiacalcose isolée"],"correct":[1],"explanation":"Gêne du mollet déclenchée par une distance de marche et cédant rapidement à l'arrêt, sans douleur de repos ni trouble trophique : claudication intermittente = stade II de Leriche et Fontaine (grade I de Rutherford) (tableau 7.1, p. 168). Piège : la fatigabilité à la marche ne change pas le stade en l'absence de douleur de repos ou de trouble trophique ; associée à une claudication fessière et à une impuissance, elle évoquerait un syndrome de Leriche (atteinte aorto-iliaque) (p. 169) ; stade III = douleur de décubitus, IV = ulcère ou gangrène."},{"stem":"Quelle valeur d'IPS ce résultat traduit-il ?","max":1,"options":["Une AOMI sévère","Un IPS normal","Une médiacalcose","Une absence d'AOMI","Une ischémie critique certaine","Un IPS non interprétable","Une AOMI légère non significative","Un test de marche positif"],"correct":[0],"explanation":"IPS = pression de cheville la plus élevée / pression brachiale la plus élevée ; AOMI si < 0,90, sévère si < 0,70 : 0,68 = AOMI sévère (p. 171). Piège : ce n'est pas une « ischémie critique », définie par une ischémie permanente avec pression de cheville < 50 mmHg ou d'hallux < 30 mmHg (p. 169) ; chez cette diabétique, un IPS > 1,40 aurait fait évoquer une médiacalcose (p. 171)."},{"stem":"Quelles mesures sont appropriées à ce stade, en l'absence de projet de revascularisation immédiat ?","max":2,"options":["Échodoppler artériel des membres inférieurs","Angioscanner des membres inférieurs","Contrôle des facteurs de risque cardiovasculaire","Artériographie diagnostique","Mesure de la TcPO2 de repos sans hyperémie préalable","IRM cérébrale systématique","Angio-IRM des membres inférieurs","Bilan hépatique systématique"],"correct":[0,2],"explanation":"L'échodoppler artériel, non invasif, localise et quantifie les sténoses (p. 172) ; le contrôle des facteurs de risque (arrêt du tabac, diabète) s'applique à tout stade (p. 175). Angioscanner et angio-IRM ne sont demandés que s'il existe une indication de revascularisation, et l'artériographie est réservée aux procédures de revascularisation (p. 172-173). Piège : la TcPO2 se lit après hyperémie, la PO2 cutanée basale (3-4 mmHg) ne distinguant pas peau saine et ischémique (p. 171)."}],"src":"p. 168-173"},{"id":"225-kfp-02","type":"KFP","rank":"A","objective":"225-obj-07","difficulty":3,"scenario":"M. R., 58 ans, en fibrillation atriale connue mais non traitée, présente brutalement une douleur intense du pied et de la jambe droite. À l'examen : membre froid, pâle, pouls poplité et distaux abolis, sensibilité conservée, motricité normale.","questions":[{"stem":"Quel grade de sévérité selon la classification de Rutherford correspond à ce tableau ?","max":1,"options":["Grade I","Grade IIa","Grade IIb","Grade III","Grade 0","Grade IV","Non classable","Grade attribué uniquement après imagerie"],"correct":[0],"explanation":"Pas de déficit sensitif ni moteur = grade I de Rutherford : membre viable, pas de menace immédiate, urgence relative (tableau 7.2, p. 179). Piège : le grade se fixe sur la clinique (sensibilité, motricité), pas sur l'imagerie ; un déficit sensitif limité aux orteils = IIa, au-delà avec déficit moteur modéré = IIb (p. 179). Conduite : imagerie en urgence puis revascularisation dans les heures (fig. 7.7, p. 180)."},{"stem":"Quelle est la mesure thérapeutique à instaurer en priorité, dès le diagnostic posé ?","max":1,"options":["Une anticoagulation par héparine non fractionnée","Une antibiothérapie probabiliste","Une corticothérapie","Un traitement thrombolytique systémique d'emblée","Une amputation d'emblée","Un jeûne strict prolongé","Une kinésithérapie de mobilisation immédiate","Une simple surveillance sans traitement"],"correct":[0],"explanation":"HNF dès le diagnostic, après prélèvement du bilan de coagulation : bolus de 5 000 UI puis 500 UI/kg/j, TCA entre 2 et 3, avec antalgiques (souvent de niveau 3), oxygène et soins locaux (p. 182). Piège : pas de thrombolyse systémique ; la thrombolyse se fait in situ, par voie intra-artérielle, pour une ischémie peu sévère avec lit d'aval jambier médiocre (p. 182)."},{"stem":"Quel(s) élément(s) du bilan étiologique cardiaque doi(ven)t être réalisé(s) sans retarder la prise en charge ?","max":2,"options":["Un ECG","Une auscultation cardiaque","Une échographie cardiaque transœsophagienne immédiate systématique","Une coronarographie systématique en urgence","Une échocardiographie transthoracique avant la revascularisation","Un holter-ECG de 7 jours avant tout traitement","Une IRM cardiaque en urgence","Un cathétérisme droit"],"correct":[0,1],"explanation":"L'examen de toute ischémie aiguë est complété par une auscultation cardiaque et un ECG (arythmie, ici FA connue), ainsi que par une palpation abdominale (anévrisme) et un bilan de coagulation (p. 182). Piège : Holter, ETT, voire ETO ou IRM ne sont faits qu'après la revascularisation (p. 182). À relier : (rang B) FA chez un patient sans antécédent artériel = embolie sur artère saine probable (p. 181) ; à distance, anticoagulation au long cours de la FA (p. 183)."}],"src":"p. 178-182"},{"id":"225-kfp-03","type":"KFP","rank":"B","objective":"225-obj-12","difficulty":2,"scenario":"M. T., 71 ans, fumeur, est adressé pour une masse abdominale battante et expansive découverte à la palpation lors d'une consultation systématique. Il est asymptomatique par ailleurs. Une échographie confirme un anévrisme de l'aorte abdominale sous-rénale mesuré à 52 mm.","questions":[{"stem":"Quel examen complémentaire est indiqué pour préciser le bilan préthérapeutique ?","max":1,"options":["Un scanner abdominopelvien injecté","Une artériographie diagnostique isolée","Une IRM abdominale en première intention","Une IRM cérébrale","Une coloscopie","Un test de marche","Une biopsie de la paroi aortique","Un dosage de la ferritine"],"correct":[0],"explanation":"Le scanner abdominopelvien injecté est l'examen préthérapeutique de référence : il précise diamètre et anatomie avant le geste (p. 185). L'échographie dépiste, mesure et suit l'AAA ; l'IRM est une alternative surtout si le scanner est contre-indiqué (p. 184-185). Piège : l'artériographie ne voit que la lumière et sous-estime la taille à cause du thrombus mural (p. 185)."},{"stem":"Compte tenu du diamètre mesuré, quelle est la conduite à tenir la plus appropriée ?","max":1,"options":["Programmer une intervention « à froid »","Surveiller par échographie tous les 5 ans","Ne réaliser aucune surveillance particulière","Traiter uniquement par antibiotiques","Attendre l'apparition de symptômes avant tout geste","Proposer une simple aponévrotomie","Réaliser une amputation préventive","Prescrire un traitement anticoagulant curatif isolé"],"correct":[0],"explanation":"(Rang B) Au-delà de 50-55 mm, le risque de rupture devient important : intervention programmée « à froid », mise à plat-greffe ou endoprothèse (p. 186). Contradiction connue : l'item 221 (rang A) retient 55 mm chez l'homme (50 mm chez la femme) ou une croissance ≥ 5 mm/an (221 p. 42) ; à 52 mm chez un homme, la décision relève donc du seuil 50-55 mm de l'item 225. Le risque annuel de rupture est de 3 % entre 50 et 59 mm (p. 184)."},{"stem":"Quel(s) élément(s) doi(ven)t être surveillé(s) après le traitement, quelle que soit la technique choisie ?","max":2,"options":["Le risque cardiovasculaire général persistant","L'apparition d'une complication locale (faux anévrisme ou endofuite selon la technique)","Le taux de plaquettes de façon hebdomadaire à vie","La fonction thyroïdienne annuelle","L'arrêt de toute imagerie de surveillance après une chirurgie conventionnelle","La fonction pulmonaire par EFR annuelle","La glycémie capillaire quotidienne à vie chez le non-diabétique","Le poids uniquement"],"correct":[0,1],"explanation":"Même après une intervention réussie, le patient reste à haut risque cardiovasculaire (surveillance, contrôle des facteurs de risque) (p. 186). Complication locale propre à la technique : prothèse de chirurgie conventionnelle = échodoppler au long cours pour les faux anévrismes anastomotiques (thrombose exceptionnelle) ; endoprothèse = scanner ou échographie pour les endofuites (p. 186). Piège : la chirurgie ouverte n'arrête donc pas l'imagerie de surveillance."}],"src":"p. 183-186"},{"id":"225-tcs-01","type":"TCS","rank":"A","objective":"225-obj-04","difficulty":2,"vignette":"Un homme de 62 ans, tabagique, consulte pour une douleur du mollet droit apparaissant à la marche. L'examen clinique retrouve un pouls pédieux droit faible.","items":[{"hypothesis":"Si vous pensiez à une AOMI","newInfo":"et que vous constatez un IPS mesuré à 0,80 à droite","panel":[0,0,1,8,6],"explanation":"IPS < 0,90 sur au moins une cheville = AOMI (p. 171) : 0,80 confirme l'hypothèse, sans critère de sévérité (< 0,70). À relier : un IPS < 0,90 est aussi un marqueur de risque cardiovasculaire élevé (p. 171)."},{"hypothesis":"Si vous pensiez à une AOMI sévère","newInfo":"et que vous constatez un IPS mesuré à 0,65 à droite","panel":[0,0,1,5,9],"explanation":"Un IPS < 0,70 définit l'AOMI sévère (p. 171) : l'hypothèse est fortement renforcée. Piège : sévère n'est pas critique ; l'ischémie critique suppose une ischémie permanente avec effondrement des pressions (cheville < 50 mmHg, hallux < 30 mmHg) (p. 169)."},{"hypothesis":"Si vous pensiez à une médiacalcose","newInfo":"et que vous constatez un IPS mesuré à 1,55 à droite chez ce patient par ailleurs non diabétique","panel":[0,1,2,9,3],"explanation":"Un IPS > 1,40 traduit une rigidité artérielle par médiacalcose (p. 171) : l'hypothèse est renforcée, sans certitude car le terrain classique (diabétique âgé, dialysé) manque. La pression de cheville n'est alors pas fiable : on mesure la pression d'orteil (index < 0,70 = AOMI) (p. 171)."},{"hypothesis":"Si vous pensiez à une claudication d'origine artérielle plutôt que neurogène","newInfo":"et que vous constatez que la douleur cède en moins de 5 minutes à l'arrêt de la marche","panel":[0,0,1,8,6],"explanation":"La claudication artérielle typique cède habituellement en moins de 5 minutes à l'arrêt (p. 168) : l'information conforte l'origine artérielle. Piège : le canal lombaire étroit cède lui aussi au repos (p. 174) ; c'est l'IPS, éventuellement après test de marche (baisse de pression de cheville > 30 mmHg), qui tranche (p. 171)."}],"src":"p. 168-171"},{"id":"225-tcs-02","type":"TCS","rank":"A","objective":"225-obj-07","difficulty":3,"vignette":"Un homme de 66 ans consulte aux urgences pour une douleur brutale de la jambe gauche apparue il y a 4 heures, avec un membre froid et des pouls abolis en aval du genou.","items":[{"hypothesis":"Si vous pensiez à une ischémie aiguë de grade I (viable)","newInfo":"et que vous constatez une sensibilité et une motricité parfaitement conservées","panel":[0,0,1,8,6],"explanation":"Sans déficit sensitif ni moteur, l'ischémie est de grade I (viable, urgence relative) (tableau 7.2, p. 179) : héparine et antalgiques, imagerie en urgence puis revascularisation dans les heures (fig. 7.7, p. 180)."},{"hypothesis":"Si vous pensiez à une ischémie de grade IIb (immédiatement menaçante)","newInfo":"et que vous constatez une anesthésie du pied dépassant les orteils avec un déficit moteur modéré","panel":[0,0,1,5,9],"explanation":"Déficit sensitif au-delà des orteils + déficit moteur modéré = grade IIb, récupération possible seulement si prise en charge immédiate (tableau 7.2, p. 179) : revascularisation en urgence absolue, sans exploration qui retarde (p. 180)."},{"hypothesis":"Si vous pensiez qu'une anticoagulation par héparine devait être débutée sans attendre l'imagerie","newInfo":"et que le bilan de coagulation vient d'être prélevé","panel":[0,0,1,5,9],"explanation":"L'HNF est débutée dès le diagnostic, après avoir prélevé le bilan de coagulation : bolus de 5 000 UI puis 500 UI/kg/j, TCA entre 2 et 3 (p. 182) ; héparine et antalgiques dès que possible, quel que soit le grade (fig. 7.7, p. 180). Piège : aucune imagerie n'est attendue pour l'anticoagulation. À relier : à distance, une cause embolique sur fibrillation atriale justifie une anticoagulation au long cours (p. 183)."},{"hypothesis":"Si vous pensiez qu'un échodoppler pouvait être réalisé sans délai avant la revascularisation","newInfo":"et que vous constatez l'apparition d'une anesthésie du pied","panel":[9,4,1,0,1],"explanation":"L'échodoppler n'est envisageable sans perte de temps qu'en l'absence d'atteinte neurologique (grade I) ; dès qu'apparaît un déficit (grade II), aucune exploration ne doit retarder l'intervention (p. 180) : réaliser une imagerie inutile qui retarde est une notion inacceptable (p. 188)."}],"src":"p. 178-182"},{"id":"225-tcs-03","type":"TCS","rank":"B","objective":"225-obj-14","difficulty":2,"vignette":"Un homme de 70 ans, fumeur actif, est suivi pour un anévrisme de l'aorte abdominale sous-rénale de 42 mm, stable sur les dernières échographies.","items":[{"hypothesis":"Si vous pensiez qu'une surveillance échographique moins rapprochée que tous les 6 mois suffisait","newInfo":"et que le diamètre reste stable à 42 mm sur plusieurs contrôles","panel":[0,0,2,9,4],"explanation":"Sous le seuil, les petits AAA sont surveillés par échographies répétées, d'autant plus rapprochées que le diamètre approche du seuil d'intervention ; le Collège ne fixe un rythme que pour les AAA > 45 mm (tous les 6 mois) (p. 185). À 42 mm et stable, une surveillance espacée reste cohérente, mais le tabagisme actif accélère la croissance (p. 185-186)."},{"hypothesis":"Si vous pensiez qu'une surveillance renforcée tous les 6 mois était nécessaire","newInfo":"et que le diamètre passe à 47 mm lors du contrôle suivant","panel":[0,0,1,8,6],"explanation":"Au-delà de 45 mm, l'échographie est répétée tous les 6 mois (p. 185) : 47 mm conforte cette hypothèse. À relier : le diamètre est le principal facteur prédictif de rupture (p. 185)."},{"hypothesis":"Si vous pensiez qu'une intervention programmée devenait indiquée","newInfo":"et que le diamètre atteint 56 mm sur le contrôle suivant","panel":[0,0,1,5,9],"explanation":"Au-delà de 50-55 mm, le risque de rupture devient important et une intervention « à froid » est programmée, chirurgie ouverte ou endoprothèse (p. 186) ; 56 mm dépasse aussi le seuil de 55 mm de l'item 221 (221 p. 42). Bilan préalable : scanner abdominopelvien injecté (p. 185)."},{"hypothesis":"Si vous pensiez que l'arrêt du tabac ralentirait la progression de l'anévrisme","newInfo":"et que le patient poursuit son tabagisme malgré les conseils","panel":[0,0,1,3,11],"explanation":"La progression de l'AAA est 3 fois plus rapide si le tabagisme se poursuit, et la croissance est plus rapide chez l'homme fumeur (p. 185-186) : l'information renforce l'intérêt de l'arrêt du tabac, indispensable pendant le suivi."}],"src":"p. 185-186"},{"id":"225-kfp-52","type":"KFP","rank":"A","objective":"225-obj-05","difficulty":3,"scenario":"M. P., 74 ans, diabétique de type 2 depuis 20 ans, ancien fumeur, consulte pour des douleurs nocturnes de l'avant-pied droit depuis 3 semaines, qu'il soulage en laissant pendre la jambe hors du lit. Il présente un ulcère de la pulpe du 2e orteil droit. Les pouls distaux droits ne sont pas perçus. L'IPS droit mesuré au doppler de poche est à 1,50.","questions":[{"stem":"Comment interprétez-vous l'IPS et quels examens réalisez-vous pour évaluer l'ischémie ?","max":3,"options":["L'IPS > 1,40 traduit une médiacalcose et n'est pas interprétable","Mesure de la pression d'orteil (index de pression d'orteil)","Mesure de la TcPO2","L'IPS > 1,40 élimine une AOMI","L'IPS à 1,50 est normal","Artériographie diagnostique en 1re intention","Scintigraphie myocardique"],"correct":[0,1,2],"explanation":"Un IPS > 1,40 traduit une médiacalcose (diabétique âgé, dialysé) : la pression de cheville n'est pas fiable et on mesure la pression d'orteil (index < 0,70 = AOMI ; pression < 30 mmHg en ischémie critique) (p. 171). La TcPO2 après hyperémie évalue l'ischémie critique (< 10 mmHg = hypoxie critique) (p. 171). Piège : un IPS élevé n'élimine pas l'AOMI ; l'artériographie est réservée aux procédures de revascularisation (p. 173)."},{"stem":"À quel stade de Leriche-Fontaine classez-vous cette artériopathie ?","max":1,"options":["Stade IV","Stade III","Stade II","Stade I","Grade I de Rutherford","Catégorie 0 de Rutherford"],"correct":[0],"explanation":"Un ulcère (trouble trophique) classe l'artériopathie au stade IV de Leriche-Fontaine (grade III de Rutherford, perte de substance) (tableau 7.1, p. 168). Les douleurs nocturnes soulagées jambe pendante (stade III) font aussi partie de l'ischémie permanente (p. 169). Piège : chez le diabétique, une neuropathie peut masquer l'AOMI, révélée d'emblée par une ischémie permanente (AOMI « masquée ») (p. 169)."},{"stem":"Quelles mesures thérapeutiques retenez-vous ?","max":4,"options":["Revascularisation proposée autant que possible, après bilan d'imagerie","Statine","Antiplaquettaire (aspirine ou clopidogrel)","Soins de plaies multidisciplinaires","Pentoxifylline pour améliorer le pronostic vital","Amputation d'emblée de l'avant-pied","Surélévation permanente du membre la nuit","Abstention de revascularisation en l'absence de claudication"],"correct":[0,1,2,3],"explanation":"En ischémie permanente, la revascularisation est proposée autant que possible (p. 176) ; statine et antiplaquettaire (aspirine ou clopidogrel) chez toute AOMI symptomatique (p. 175) ; soins de plaies par une équipe multidisciplinaire (p. 176). Pièges : la pentoxifylline améliore modestement le périmètre de marche sans bénéfice pronostique (p. 176) ; l'amputation n'est envisagée qu'en cas d'impossibilité ou d'échec de la revascularisation (p. 177) ; la position déclive soulage la douleur de décubitus (p. 169)."}],"src":"p. 168-178"},{"id":"225-tcs-51","type":"TCS","rank":"B","objective":"225-obj-05","difficulty":2,"vignette":"Un homme de 67 ans, ancien fumeur, a une AOMI confirmée (IPS gauche à 0,62) révélée par une claudication du mollet gauche. Il reçoit une statine et un antiplaquettaire.","items":[{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et que son périmètre de marche est de 800 m avec une gêne modérée,","panel":[6,7,2,0,0],"explanation":"Chez le claudicant, la revascularisation se discute si la claudication sévère altère la qualité de vie après traitement médical bien mené, ou d'emblée si périmètre < 100 m avec handicap important ou atteinte aorto-iliaque sévère (p. 176) : à 800 m avec gêne modérée, on reste à la réadaptation à la marche (fig. 7.6, p. 177)."},{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et qu'il présente depuis 3 semaines des douleurs de décubitus soulagées jambe pendante,","panel":[0,0,0,3,12],"explanation":"Douleurs de décubitus soulagées jambe pendante = ischémie permanente (stade III) (p. 169) : la revascularisation est proposée autant que possible (p. 176)."},{"hypothesis":"Si vous envisagiez une revascularisation,","newInfo":"et que sa claudication est devenue invalidante à 80 m malgré un traitement médical bien conduit,","panel":[0,0,1,7,7],"explanation":"Claudication sévère (< 100 m) altérant la qualité de vie malgré un traitement médical bien mené : indication de revascularisation à envisager (p. 176 ; fig. 7.6, p. 177)."},{"hypothesis":"Si vous envisagiez une angioplastie endovasculaire,","newInfo":"et que l'imagerie montre une lésion courte et proximale,","panel":[0,0,1,6,8],"explanation":"(Rang B) Les résultats de l'angioplastie (ballonnet ± stent) sont d'autant plus favorables que les lésions sont courtes et proximales (p. 176)."},{"hypothesis":"Si vous envisagiez une angioplastie endovasculaire,","newInfo":"et que l'imagerie montre des lésions étendues,","panel":[4,8,3,0,0],"explanation":"(Rang B) Le choix dépend de l'étendue et de la sévérité des lésions et de l'état du patient ; les résultats de l'angioplastie sont moins bons sur les lésions longues, même si l'angioplastie sous-adventicielle est possible pour les occlusions longues ; pontage (de préférence veineux) et techniques hybrides restent des options (p. 176)."}],"src":"p. 175-178"}],"trees":[{"id":"225-tree-01","title":"Démarche diagnostique devant une suspicion d'AOMI","rank":"A","objective":"225-obj-04","intro":"L'index de pression systolique (IPS) est le premier examen à réaliser devant une suspicion d'artériopathie oblitérante des membres inférieurs.","root":"n1","nodes":{"n1":{"type":"question","text":"Le patient se plaint-il de douleur à la marche ou plutôt de douleur/troubles trophiques permanents ?","options":[{"label":"Douleur à la marche (claudication)","to":"n2"},{"label":"Douleur ou troubles trophiques au repos","to":"n9"}]},"n2":{"type":"action","text":"Mesurer l'index de pression systolique (IPS) au repos.","to":"n3"},"n3":{"type":"question","text":"Quel est le résultat de l'IPS ?","options":[{"label":"< 0,90","to":"n4"},{"label":"1,00-1,40 mais patient symptomatique","to":"n5"},{"label":"> 1,40","to":"n6"}]},"n4":{"type":"end","tone":"ok","text":"AOMI confirmée ; compléter par un échodoppler artériel des membres inférieurs.","note":"IPS < 0,90 sur au moins une cheville ; < 0,70 définit une AOMI sévère."},"n5":{"type":"action","text":"Réaliser un test de marche sur tapis roulant (protocole de Strandness : 3,2 km/h, pente 10 %).","to":"n7"},"n6":{"type":"action","text":"Suspecter une médiacalcose : mesurer la pression (index) d'orteil.","to":"n6b"},"n6b":{"type":"question","text":"L'index de pression d'orteil est-il < 0,70 ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"n8b"}]},"n7":{"type":"question","text":"Après l'effort, la pression de cheville chute-t-elle > 30 mmHg ou l'IPS > 20 % ?","options":[{"label":"Oui","to":"n8"},{"label":"Non","to":"n8b"}]},"n8":{"type":"end","tone":"ok","text":"AOMI démasquée par le test de marche malgré un IPS de repos normal."},"n8b":{"type":"end","tone":"info","text":"Évoquer un diagnostic différentiel de la claudication (canal lombaire étroit, claudication veineuse, cause rhumatologique ou musculaire)."},"n9":{"type":"action","text":"Rechercher une ischémie critique : pression de cheville < 50 mmHg ou d'hallux < 30 mmHg.","to":"n10"},"n10":{"type":"end","tone":"warn","text":"Ischémie permanente/critique : discuter systématiquement une revascularisation."}},"src":"p. 170-172"},{"id":"225-tree-02","title":"Stratégie de prise en charge de la claudication intermittente","rank":"A","objective":"225-obj-05","intro":"Le traitement des facteurs de risque et l'antiplaquettaire s'appliquent à tous les patients ; la suite dépend du retentissement fonctionnel.","root":"n1","nodes":{"n1":{"type":"action","text":"Débuter contrôle des facteurs de risque, statine et antiplaquettaire (± IEC si HTA ou insuffisance cardiaque).","to":"n2"},"n2":{"type":"question","text":"Périmètre de marche < 100 m et/ou atteinte aorto-iliaque sévère et extensive ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"end","tone":"warn","text":"Envisager d'emblée une revascularisation (angioplastie ou chirurgie)."},"n4":{"type":"action","text":"Proposer une réadaptation à la marche, de préférence supervisée, avec éducation thérapeutique.","to":"n5"},"n5":{"type":"question","text":"Disparition de la claudication ou allongement significatif du périmètre de marche ?","options":[{"label":"Oui","to":"n6"},{"label":"Non, échec du traitement médical bien conduit","to":"n3"}]},"n6":{"type":"end","tone":"ok","text":"Poursuivre la réadaptation et le traitement médical ; réévaluer périodiquement."}},"src":"p. 176-177"},{"id":"225-tree-03","title":"Prise en charge de l'ischémie aiguë de membre selon la sévérité","rank":"A","objective":"225-obj-09","intro":"Le degré d'urgence dépend du grade de sévérité de Rutherford ; aucune exploration ne doit retarder l'intervention en cas de déficit neurologique.","root":"n1","nodes":{"n1":{"type":"action","text":"Débuter sans délai héparine non fractionnée, antalgiques et soins locaux.","to":"n2"},"n2":{"type":"question","text":"Quel est le grade de sévérité (Rutherford) ?","options":[{"label":"Grade I (viable, pas de déficit)","to":"n3"},{"label":"Grade IIa/IIb (déficit sensitif ± moteur)","to":"n5"},{"label":"Grade III (irréversible)","to":"n7"}]},"n3":{"type":"action","text":"Un échodoppler peut être réalisé sans perte de temps si les conditions le permettent, puis débuter le bilan étiologique.","to":"n4"},"n4":{"type":"end","tone":"info","text":"Revascularisation dans les heures suivantes (thrombolyse, thromboaspiration, thrombectomie ou pontage selon le contexte)."},"n5":{"type":"action","text":"N'engager aucune exploration retardant la prise en charge ; alerter l'équipe chirurgicale au plus tôt.","to":"n6"},"n6":{"type":"end","tone":"danger","text":"Revascularisation en urgence absolue (thrombectomie/pontage)."},"n7":{"type":"end","tone":"danger","text":"Ischémie dépassée : amputation d'emblée."}},"src":"p. 179-180"},{"id":"225-tree-04","title":"Orientation étiologique devant une ischémie aiguë de membre","rank":"B","objective":"225-obj-08","intro":"Deux grands tableaux s'opposent, sans être toujours totalement distincts : la thrombose in situ et l'embolie sur artère saine.","root":"n1","nodes":{"n1":{"type":"question","text":"Sujet âgé, facteurs de risque cardiovasculaire, antécédent d'AOMI, douleur d'intensité moyenne d'installation progressive ?","options":[{"label":"Oui, tableau évocateur de thrombose","to":"n2"},{"label":"Non : sujet jeune, douleur brutale et sévère, sans antécédent vasculaire","to":"n4"}]},"n2":{"type":"action","text":"Orienter vers une thrombose artérielle in situ ; rechercher une AOMI controlatérale, une déshydratation ou une coagulopathie.","to":"n3"},"n3":{"type":"end","tone":"info","text":"Bilan étiologique : auscultation cardiaque, ECG, palpation abdominale, bilan de coagulation."},"n4":{"type":"action","text":"Orienter vers une embolie sur artère saine ; rechercher une cardiopathie emboligène (fibrillation atriale, infarctus, endocardite, myxome).","to":"n5"},"n5":{"type":"question","text":"L'auscultation cardiaque, l'ECG ou la palpation abdominale retrouvent-ils une source embolique ?","options":[{"label":"Oui (ex. fibrillation atriale, anévrisme aortique)","to":"n6"},{"label":"Non, bilan initial négatif","to":"n7"}]},"n6":{"type":"end","tone":"ok","text":"Traiter la cause après revascularisation (ex. anticoagulation au long cours si fibrillation atriale)."},"n7":{"type":"end","tone":"info","text":"Compléter à distance par un bilan cardiaque (Holter, ETT ± ETO/IRM) et un bilan artériel (échodoppler, angioscanner)."}},"src":"p. 181-183"},{"id":"225-tree-05","title":"Surveillance et décision d'intervention d'un anévrisme de l'aorte abdominale asymptomatique","rank":"B","objective":"225-obj-14","intro":"Le diamètre de l'anévrisme est le principal facteur prédictif de rupture et détermine le rythme de surveillance et l'indication opératoire.","root":"n1","nodes":{"n1":{"type":"question","text":"Quel est le diamètre de l'anévrisme de l'aorte abdominale ?","options":[{"label":"< 45 mm","to":"n2"},{"label":"45-54 mm","to":"n3"},{"label":"> 50-55 mm","to":"n5"}]},"n2":{"type":"end","tone":"ok","text":"Surveillance échographique standard et contrôle des facteurs de risque (arrêt du tabac)."},"n3":{"type":"action","text":"Renforcer la surveillance échographique (tous les 6 mois) et intensifier le contrôle des facteurs de risque.","to":"n4"},"n4":{"type":"end","tone":"info","text":"Réévaluer le diamètre à 6 mois ; discuter l'intervention si le seuil est atteint ou si progression rapide."},"n5":{"type":"question","text":"Le patient est-il à haut risque chirurgical, avec une anatomie favorable au traitement endovasculaire ?","options":[{"label":"Oui","to":"n6"},{"label":"Non ou anatomie défavorable","to":"n7"}]},"n6":{"type":"end","tone":"ok","text":"Traitement endovasculaire (endoprothèse) avec surveillance itérative à la recherche d'endofuites."},"n7":{"type":"end","tone":"ok","text":"Chirurgie conventionnelle à ciel ouvert (exclusion et interposition d'une prothèse)."}},"src":"p. 185-186"},{"id":"225-tree-06","title":"Conduite à tenir devant un anévrisme de l'aorte abdominale symptomatique","rank":"A","objective":"225-obj-15","intro":"Toute douleur chez un porteur connu ou suspecté d'AAA doit faire craindre une fissuration ou une rupture, urgence absolue.","root":"n1","nodes":{"n1":{"type":"question","text":"Douleur abdominale ou lombaire chez un patient porteur (connu ou suspecté) d'un AAA ?","options":[{"label":"Oui, avec choc hémorragique","to":"n2"},{"label":"Oui, patient hémodynamiquement stable","to":"n4"}]},"n2":{"type":"action","text":"Diriger en urgence vers un centre de chirurgie vasculaire ; ne réaliser que le scanner diagnostique.","to":"n3"},"n3":{"type":"end","tone":"danger","text":"Traitement en urgence absolue : chirurgie à ciel ouvert ou endoprothèse selon l'expérience de l'équipe."},"n4":{"type":"action","text":"Réaliser un scanner abdominal pour confirmer une fissuration/rupture ou une autre complication.","to":"n5"},"n5":{"type":"question","text":"Le scanner confirme-t-il une fissuration ou une complication (fistule, embolie, syndrome inflammatoire) ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n6"}]},"n6":{"type":"end","tone":"info","text":"Reprendre la surveillance programmée selon le diamètre de l'anévrisme."}},"src":"p. 184-186"}],"treatments":{"data":[{"id":"225-tx-01","rank":"A","class":"Contrôle des facteurs de risque cardiovasculaire","molecules":[],"context":"Mesure de fond appliquée à tout stade d'AOMI et chez tout porteur d'anévrisme de l'aorte.","indications":["Arrêt du tabac","Équilibre du diabète","Contrôle tensionnel","Contrôle du LDL-cholestérol","Régime méditerranéen, IMC cible 20-25 kg/m²"],"contraindications":[],"sideEffects":[],"monitoring":["HbA1c cible < 7 %","PAS 120-129 mmHg, PAD 70-79 mmHg","LDL-cholestérol < 0,55 g/L avec réduction ≥ 50 %"],"interactions":[],"pearls":["S'applique à tous les stades de l'AOMI, symptomatique ou non.","Le tabagisme accélère aussi la progression d'un anévrisme de l'aorte abdominale."],"src":"p. 175"},{"id":"225-tx-02","rank":"A","class":"Antiplaquettaires","molecules":["aspirine","clopidogrel"],"context":"Réduction du risque de complications cardiovasculaires (infarctus, AVC) chez le patient artériopathe.","indications":["AOMI symptomatique (systématique)","AOMI asymptomatique avec autre localisation athéromateuse (discuté)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Débattu en cas d'AOMI purement asymptomatique isolée."],"src":"p. 175"},{"id":"225-tx-03","rank":"A","class":"Statines","molecules":["statine"],"context":"Traitement hypolipémiant systématique du patient AOMI, quel que soit le LDL initial.","indications":["Tout patient AOMI"],"contraindications":[],"sideEffects":[],"monitoring":["LDL-cholestérol cible < 0,55 g/L (< 1,4 mmol/L) avec réduction ≥ 50 % par rapport à la valeur initiale"],"interactions":[],"pearls":["L'instauration d'une statine peut s'accompagner d'une augmentation du périmètre de marche.","Des douleurs musculaires sous statines peuvent mimer une claudication et créer un piège diagnostique."],"src":"p. 175-176"},{"id":"225-tx-04","rank":"A","class":"Inhibiteurs de l'enzyme de conversion (IEC) / sartans","molecules":["IEC","sartan"],"context":"Intérêt pronostique chez le patient AOMI, pouvant être envisagé quel que soit le niveau tensionnel en l'absence de contre-indication.","indications":["AOMI, notamment si HTA associée"],"contraindications":[],"sideEffects":[],"monitoring":["Cible de pression artérielle < 140/90 mmHg"],"interactions":[],"pearls":[],"src":"p. 175"},{"id":"225-tx-05","rank":"A","class":"Bêtabloquants","molecules":[],"context":"Utilisables chez le patient AOMI en présence d'une indication cardiologique formelle.","indications":["Cardiopathie ischémique associée","Insuffisance cardiaque à fraction d'éjection altérée","Certaines arythmies"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Prudence en cas d'ischémie critique non revascularisable."],"src":"p. 175"},{"id":"225-tx-07","rank":"B","class":"Traitements vasoactifs","molecules":["pentoxifylline"],"context":"Bénéfice modeste sur le périmètre de marche de la claudication, sans effet pronostique démontré à long terme.","indications":["Amélioration symptomatique modeste du périmètre de marche"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Plusieurs molécules de cette classe ont été retirées du marché pour futilité ou déremboursées."],"src":"p. 176"},{"id":"225-tx-08","rank":"B","class":"Prostaglandines","molecules":["prostaglandines"],"context":"Ischémie critique non revascularisable, en perfusions quotidiennes durant plusieurs semaines en milieu spécialisé.","indications":["Ischémie critique non revascularisable"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 176"},{"id":"225-tx-09","rank":"A","class":"Réadaptation à la marche et arrêt du tabac (traitement à visée locale)","molecules":[],"context":"Traitement de première ligne de la claudication non invalidante, idéalement supervisé.","indications":["Claudication intermittente"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Marche régulière 30-45 min, ≥ 3 fois/semaine, en s'arrêtant au seuil de la douleur.","La réadaptation supervisée donne de meilleurs résultats que le programme non supervisé et s'accompagne d'une éducation thérapeutique."],"src":"p. 175-176"},{"id":"225-tx-10","rank":"A","class":"Angioplastie endovasculaire (± stent) de l'AOMI","molecules":[],"context":"Technique de revascularisation de référence pour les lésions courtes et proximales.","indications":["Ischémie permanente","Claudication sévère invalidante après échec du traitement médical bien conduit"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance clinique et écho-Doppler systématique après le geste"],"interactions":[],"pearls":["Bithérapie antiplaquettaire poursuivie 1 à 6 mois après le geste selon sa localisation.","L'angioplastie sous-adventicielle peut être proposée en cas d'occlusion longue."],"src":"p. 176"},{"id":"225-tx-11","rank":"A","class":"Chirurgie de revascularisation (pontage, endartériectomie) de l'AOMI","molecules":[],"context":"Traitée essentiellement par pontage (matériel veineux de préférence) pour court-circuiter les lésions étendues.","indications":["Ischémie permanente","Claudication sévère invalidante après échec du traitement médical"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance clinique et écho-Doppler systématique après le geste"],"interactions":[],"pearls":["Pontages les plus fréquents : aorto-bi-iliaque (ou bifémoral), fémoropoplité, fémorojambier.","Techniques hybrides possibles (chirurgie associée à l'endovasculaire)."],"src":"p. 176"},{"id":"225-tx-12","rank":"A","class":"Amputation","molecules":[],"context":"Geste ultime en l'absence de toute possibilité de revascularisation.","indications":["Ischémie dépassée","Échec de la revascularisation avec désordres métaboliques majeurs"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Doit être réalisée en zone saine et bien oxygénée, guidée par la mesure de TcPO2.","Préférer une amputation limitée (orteil, transmétatarsienne) ou sous le genou pour permettre l'appareillage."],"src":"p. 176-177"},{"id":"225-tx-13","rank":"A","class":"Anticoagulation par héparine non fractionnée (ischémie aiguë de membre)","molecules":["héparine non fractionnée"],"context":"Débutée dès le diagnostic d'ischémie aiguë, après le prélèvement du bilan de coagulation.","indications":["Ischémie aiguë de membre, dès la suspicion diagnostique"],"contraindications":[],"sideEffects":[],"monitoring":["TCA cible entre 2 et 3"],"interactions":[],"pearls":["Posologie : bolus de 5 000 UI puis perfusion continue de 500 UI/kg/j."],"src":"p. 182"},{"id":"225-tx-14","rank":"A","class":"Embolectomie à la sonde de Fogarty","molecules":[],"context":"Méthode de revascularisation de référence de l'embolie sur artère saine, réalisée sous contrôle angiographique.","indications":["Ischémie aiguë de membre par embolie sur artère saine"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Peut aussi être utilisée sur des artères athéromateuses."],"src":"p. 182"},{"id":"225-tx-15","rank":"B","class":"Thrombolyse in situ / thromboaspiration","molecules":[],"context":"Alternative à l'embolectomie lorsque le lit d'aval jambier est de mauvaise qualité et l'ischémie peu sévère.","indications":["Ischémie aiguë peu sévère avec lit d'aval jambier de mauvaise qualité"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance en milieu spécialisé avec contrôles angiographiques répétés"],"interactions":[],"pearls":["Injection du fibrinolytique directement dans le thrombus via un cathéter laissé en place plusieurs heures."],"src":"p. 182"},{"id":"225-tx-16","rank":"A","class":"Aponévrotomie de décompression","molecules":[],"context":"Geste systématique en cas de revascularisation tardive pour prévenir ou traiter le syndrome des loges.","indications":["Syndrome des loges","Revascularisation tardive d'une ischémie aiguë"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le plus souvent réalisée sur la loge antéro-externe de jambe ; d'autres loges, y compris le pied, peuvent être décomprimées."],"src":"p. 178-183"},{"id":"225-tx-17","rank":"A","class":"Traitement des conséquences métaboliques de la revascularisation","molecules":["bicarbonates","polystyrène sulfonate de sodium"],"context":"Prise en charge du syndrome de revascularisation (acidose, hyperkaliémie, insuffisance rénale).","indications":["Acidose métabolique et hyperkaliémie post-revascularisation","Insuffisance rénale aiguë débutante"],"contraindications":[],"sideEffects":[],"monitoring":["Diurèse (sonde urinaire), ionogramme, urée, créatininémie, CPK"],"interactions":[],"pearls":["Recours possible à la dialyse en cas d'échec.","Lavage de membre au sérum physiologique associé."],"src":"p. 183"},{"id":"225-tx-18","rank":"A","class":"Chirurgie conventionnelle de l'anévrisme de l'aorte abdominale (mise à plat-greffe)","molecules":[],"context":"Exclusion de la zone anévrismale et interposition d'une prothèse vasculaire.","indications":["AAA > 50-55 mm de diamètre, intervention « à froid »","AAA rompu"],"contraindications":[],"sideEffects":[],"monitoring":["Surveillance écho-Doppler à long terme (risque de faux anévrisme anastomotique)"],"interactions":[],"pearls":["La thrombose de la prothèse est exceptionnelle."],"src":"p. 185-186"},{"id":"225-tx-19","rank":"A","class":"Traitement endovasculaire de l'anévrisme de l'aorte abdominale (endoprothèse)","molecules":[],"context":"Moins invasif, préféré chez les sujets à haut risque chirurgical si l'anatomie est favorable.","indications":["AAA > 50-55 mm avec anatomie favorable","AAA rompu, notamment si très haut risque périopératoire"],"contraindications":["Anatomie défavorable limitant la faisabilité"],"sideEffects":[],"monitoring":["Surveillance itérative au long cours par scanner et échographie de contraste (endofuites)"],"interactions":[],"pearls":["Les endofuites peuvent faire progresser voire rompre l'anévrisme malgré le traitement."],"src":"p. 186"},{"id":"225-tx-20","rank":"B","class":"Antibioprophylaxie chez le porteur de prothèse vasculaire","molecules":[],"context":"Justifiée lors de tout acte à risque bactérien du fait du risque d'infection de la prothèse.","indications":["Geste à risque bactérien chez un porteur de prothèse vasculaire ou d'endoprothèse"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 186"},{"id":"225-tx-21","rank":"A","class":"Revascularisation de l'ischémie mésentérique chronique","molecules":[],"context":"Ischémie mésentérique chronique : le traitement repose sur la revascularisation, de préférence par voie endovasculaire.","indications":["Ischémie mésentérique chronique symptomatique (angor digestif)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 166, 187"}],"strategies":[{"id":"225-strat-01","rank":"A","title":"Traitement de fond de l'AOMI, tous stades confondus","content":"**Objectif** : améliorer le pronostic cardiovasculaire et vital global.\n\n- Contrôle des facteurs de risque : arrêt du tabac, équilibre du diabète (HbA1c < 7 %), objectif tensionnel PAS 120-129 / PAD 70-79 mmHg, IMC 20-25 kg/m², régime méditerranéen, réentraînement 3 fois/semaine pendant 12 semaines.\n- Statine systématique, cible LDL < 0,55 g/L avec réduction ≥ 50 %.\n- Antiplaquettaire (aspirine ou clopidogrel) si AOMI symptomatique ; discuté si asymptomatique isolée.\n- IEC (ou sartan) d'intérêt pronostique, cible PA < 140/90 mmHg.\n- Bêtabloquant possible si indication cardiologique formelle, prudence en ischémie critique non revascularisable.","src":"p. 175"},{"id":"225-strat-02","rank":"A","title":"Stratégie de prise en charge de la claudication intermittente","content":"1. Dans tous les cas : prise en charge des facteurs de risque cardiovasculaire, statine, antiplaquettaire (± IEC si HTA ou insuffisance cardiaque).\n2. Si claudication très invalidante (périmètre de marche < 100 m) ou atteinte aorto-iliaque sévère et extensive : envisager d'emblée une revascularisation.\n3. Sinon : réadaptation à la marche, de préférence supervisée en centre de réadaptation.\n4. Si disparition de la claudication ou allongement significatif du périmètre de marche : poursuite du traitement médical.\n5. En cas d'échec du traitement médical bien conduit : envisager une revascularisation (angioplastie ou chirurgie).","src":"p. 176-177"},{"id":"225-strat-03","rank":"A","title":"Indications de la revascularisation dans l'AOMI","content":"- Systématiquement proposée en cas d'**ischémie permanente**.\n- Discutée en cas de **claudication sévère invalidante**, notamment après échec du traitement médical bien conduit (réadaptation incluse), ou d'emblée si périmètre de marche très faible (< 100 m) avec fort retentissement fonctionnel ou atteinte aorto-iliaque sévère.\n- Choix de la technique selon l'étendue et la sévérité des lésions : angioplastie endovasculaire ± stent pour les lésions courtes/proximales (bithérapie antiplaquettaire 1-6 mois), chirurgie (pontage, endartériectomie) pour les lésions étendues ; techniques hybrides possibles.\n- Surveillance clinique et écho-Doppler systématique après le geste, quelle que soit la méthode.","src":"p. 176"},{"id":"225-strat-04","rank":"A","title":"Prise en charge de l'ischémie aiguë de membre selon le degré d'urgence","content":"1. Dès la suspicion : héparine non fractionnée, antalgiques et soins locaux, quel que soit le grade.\n2. **Grade III (irréversible)** : amputation.\n3. **Grade IIa/IIb (viable avec déficit sensitif ± moteur)** : revascularisation en urgence absolue (thrombectomie/pontage), sans aucune exploration retardant l'intervention.\n4. **Grade I (viable)** : imagerie possible sans perte de temps, puis revascularisation dans les heures suivantes (thrombolyse, thromboaspiration, thrombectomie ou pontage) et bilan étiologique.\n5. Dans tous les cas : traitement médical associé (anticoagulation, analgésie, correction des troubles hydroélectrolytiques) et surveillance des conséquences métaboliques de la revascularisation.","src":"p. 179-183"},{"id":"225-strat-05","rank":"A","title":"Surveillance et traitement de l'anévrisme de l'aorte abdominale selon le diamètre","content":"- Diamètre < 45 mm : surveillance échographique standard, contrôle des facteurs de risque.\n- Diamètre approchant le seuil d'intervention (> 45 mm) : surveillance échographique renforcée, tous les 6 mois.\n- Diamètre > 50-55 mm : intervention programmée « à froid », chirurgie conventionnelle (mise à plat-greffe) ou endoprothèse selon le terrain et l'anatomie.\n- Après traitement, quel qu'il soit : surveillance à vie du risque cardiovasculaire général, écho-Doppler après chirurgie (faux anévrisme), scanner/échographie après endoprothèse (endofuites).","src":"p. 185-186"},{"id":"225-strat-06","rank":"A","title":"Conduite à tenir devant un anévrisme de l'aorte abdominale symptomatique","content":"1. Douleur abdominale ou lombaire chez un porteur (connu ou suspecté) d'AAA : urgence absolue.\n2. Aucune imagerie autre que le scanner diagnostique ne doit retarder l'intervention chez un patient en choc hémorragique.\n3. Diriger le patient sans délai vers un centre spécialisé de chirurgie vasculaire.\n4. Traitement chirurgical à ciel ouvert ou par endoprothèse (de plus en plus proposée même en contexte de rupture), selon l'expérience de l'équipe et le terrain.\n5. En cas d'ischémie aiguë de membre par embolie à partir de l'AAA : revascularisation du membre en urgence, cure de l'AAA secondairement.","src":"p. 184-186"}]},"cases":[{"id":"225-case-01","title":"M. Lefèvre, 64 ans, douleur du mollet à la marche","rank":"A","summary":"Claudication intermittente révélant une AOMI, du diagnostic à une revascularisation après échec du traitement médical, puis épisode d'ischémie aiguë.","difficulty":2,"timeline":["Consultation initiale","Bilan diagnostique","Diagnostic et sévérité","Traitement médical","Échec médical et revascularisation","Suivi à long terme et complication"],"steps":[{"id":"225-case-01-s01","phase":0,"narrative":"M. Lefèvre, 64 ans, tabagique à 40 paquets-années, consulte pour une gêne du mollet gauche apparaissant systématiquement après 300 mètres de marche et cédant rapidement à l'arrêt.","question":{"type":"QRM","stem":"Quels éléments de l'interrogatoire faut-il rechercher chez ce patient ?","options":[{"t":"Le délai de disparition de la douleur à l'arrêt de la marche","ok":true,"why":"Une disparition en moins de 5 minutes est caractéristique de la claudication artérielle."},{"t":"La présence de troubles de l'érection","ok":true,"why":"Ils peuvent s'intégrer dans un syndrome de Leriche en cas d'atteinte aorto-iliaque."},{"t":"Un antécédent d'angor ou de symptômes neurologiques déficitaires","ok":true,"why":"L'AOMI est fréquemment associée à d'autres atteintes athéromateuses à rechercher systématiquement."},{"t":"La notion de douleur nocturne calmée en position debout","ok":false,"why":"C'est la position déclive, pas la position debout prolongée, qui soulage les douleurs de décubitus de l'ischémie permanente."},{"t":"La prise d'un traitement par statine, source possible de myalgies simulatrices","ok":true,"why":"Les douleurs musculaires sous statine peuvent mimer une claudication et constituer un piège diagnostique."}],"explanation":"La claudication artérielle typique cède en moins de 5 minutes ; il faut aussi rechercher un syndrome de Leriche, les autres atteintes athéromateuses et éliminer les diagnostics différentiels, notamment médicamenteux."},"reveal":"Le patient rapporte une disparition de la douleur en 3 minutes environ, sans trouble de l'érection ni antécédent cardiovasculaire connu ; il ne prend pas de statine.","src":"p. 168-169"},{"id":"225-case-01-s02","phase":0,"narrative":"À l'examen bilatéral et comparatif, le pouls pédieux gauche est aboli, le pouls poplité est perçu ; le temps de recoloration cutanée est de 2 secondes.","question":{"type":"QRU","stem":"Quel examen complémentaire réaliser en première intention ?","options":[{"t":"Échodoppler artériel des membres inférieurs","ok":false,"why":"C'est l'examen de 1re intention pour localiser une sténose, mais il n'est pas le tout premier geste devant une suspicion clinique."},{"t":"Index de pression systolique (IPS)","ok":true,"why":"L'IPS est l'examen de première intention devant toute suspicion d'AOMI."},{"t":"Angioscanner des membres inférieurs","ok":false,"why":"Il n'est demandé qu'en vue d'une revascularisation, pas en première intention."},{"t":"Artériographie","ok":false,"why":"Elle est réservée aux procédures de revascularisation."},{"t":"Test de marche sur tapis roulant","ok":false,"why":"Il est utile seulement si l'IPS de repos est normal chez un patient symptomatique."}],"explanation":"L'IPS, simple et non invasif, est le premier examen à réaliser devant une suspicion clinique d'AOMI."},"reveal":"L'IPS est mesuré au doppler de poche des deux côtés.","src":"p. 170-171"},{"id":"225-case-01-s03","phase":1,"narrative":"L'IPS retrouve 0,65 à gauche et 1,05 à droite.","question":{"type":"QRM","stem":"Comment interpréter ce résultat ?","options":[{"t":"Le diagnostic d'AOMI est confirmé côté gauche","ok":true,"why":"Un IPS < 0,90 sur au moins une cheville affirme le diagnostic d'AOMI."},{"t":"L'AOMI gauche est sévère","ok":true,"why":"Un IPS inférieur à 0,70 (ici 0,65) définit une AOMI sévère."},{"t":"Un IPS élevé à droite éliminerait formellement toute atteinte controlatérale","ok":false,"why":"Un IPS normal n'élimine pas une AOMI infraclinique ou débutante controlatérale."},{"t":"Il faut envisager une médiacalcose devant ce résultat","ok":false,"why":"La médiacalcose se traduit par un IPS anormalement élevé (> 1,40), non par un IPS abaissé."},{"t":"Cet IPS abaissé est aussi un marqueur de risque cardiovasculaire général","ok":true,"why":"Un IPS bas est associé à un risque accru d'événement coronarien ou cérébral, au-delà de son intérêt diagnostique local."}],"explanation":"Un IPS < 0,90 confirme l'AOMI ; ici 0,65 est même inférieur au seuil de sévérité de 0,70, ce qui doit être noté."},"reveal":"Le compte-rendu conclut à une AOMI gauche sévère (IPS 0,65) et une absence d'AOMI droite au repos.","src":"p. 171"},{"id":"225-case-01-s04","phase":1,"narrative":"M. Lefèvre demande des précisions sur le stade de sa maladie.","question":{"type":"QROC","question":"Quel stade de la classification de Leriche et Fontaine correspond à la situation clinique actuelle de M. Lefèvre ?","answer":"Stade II (claudication intermittente)","accept":["stade 2","II","claudication"],"keywords":["Leriche","Fontaine","claudication"],"explanation":"Le patient présente une claudication intermittente sans douleur de repos ni trouble trophique, correspondant au stade II de Leriche et Fontaine (catégorie Rutherford I à III selon la sévérité)."},"reveal":"Le patient est informé qu'il s'agit d'un stade II, avec un risque cardiovasculaire global à évaluer.","src":"p. 168-169"},{"id":"225-case-01-s05","phase":2,"narrative":"Le médecin souhaite préciser la localisation et la sévérité des lésions avant toute décision thérapeutique.","question":{"type":"QRM","stem":"Quel(s) examen(s) complémentaire(s) est/sont justifié(s) à ce stade ?","options":[{"t":"Échodoppler artériel des membres inférieurs","ok":true,"why":"C'est l'examen de 1re intention pour localiser et quantifier les sténoses."},{"t":"Angioscanner des membres inférieurs d'emblée","ok":false,"why":"Il n'est indiqué qu'en vue d'un projet de revascularisation, pas en routine diagnostique."},{"t":"Bilan des autres localisations athéromateuses (ECG, recherche de souffle carotidien)","ok":true,"why":"L'AOMI impose un bilan cardiovasculaire général du fait de la fréquence des atteintes associées."},{"t":"Artériographie systématique","ok":false,"why":"Elle est réservée aux procédures de revascularisation."},{"t":"Bilan lipidique et glycémique","ok":true,"why":"Le bilan des facteurs de risque cardiovasculaire fait partie de l'évaluation initiale."}],"explanation":"L'échodoppler artériel et le bilan des facteurs de risque et des autres localisations athéromateuses sont les examens pertinents à ce stade ; l'imagerie en coupe n'est utile qu'en cas de projet de revascularisation."},"reveal":"L'échodoppler confirme une sténose serrée de l'artère fémorale superficielle gauche ; le bilan ne retrouve pas d'autre localisation symptomatique.","src":"p. 172-175"},{"id":"225-case-01-s06","phase":2,"narrative":"Le bilan étiologique retrouve un tabagisme actif, une hypercholestérolémie et une pression artérielle à 148/92 mmHg.","question":{"type":"QRM","stem":"Quels facteurs de risque de l'AOMI sont présents chez ce patient ?","options":[{"t":"Le tabagisme","ok":true,"why":"C'est l'un des deux principaux facteurs de risque de l'AOMI, plus fréquent chez le sujet jeune."},{"t":"L'hypercholestérolémie","ok":true,"why":"Elle est fréquemment associée à l'AOMI."},{"t":"L'hypertension artérielle","ok":true,"why":"Elle est fréquemment associée à l'AOMI."},{"t":"Le diabète","ok":false,"why":"Aucun élément du dossier ne rapporte de diabète chez ce patient."},{"t":"L'âge du patient élimine tout risque supplémentaire de progression","ok":false,"why":"L'âge n'élimine rien ; ce n'est pas un facteur protecteur mentionné."}],"explanation":"Le tabagisme, l'hypercholestérolémie et l'HTA sont les facteurs de risque retrouvés chez ce patient ; le diabète n'est pas présent ici."},"reveal":"Un sevrage tabagique et une statine sont proposés en association au traitement antiplaquettaire.","src":"p. 168, 175"},{"id":"225-case-01-s07","phase":3,"narrative":"Le traitement de fond est mis en place.","question":{"type":"QRM","stem":"Quelles mesures thérapeutiques générales sont indiquées chez ce patient AOMI symptomatique ?","options":[{"t":"Antiplaquettaire (aspirine ou clopidogrel)","ok":true,"why":"Indiqué chez tout patient AOMI symptomatique."},{"t":"Statine avec objectif de LDL < 0,55 g/L","ok":true,"why":"Traitement systématique, avec réduction ≥ 50 % du LDL initial."},{"t":"Arrêt du tabac","ok":true,"why":"Mesure de fond indispensable à tout stade de la maladie."},{"t":"Anticoagulation curative systématique par AVK","ok":false,"why":"L'antithrombotique indiqué chez tout patient AOMI symptomatique est un antiplaquettaire (aspirine ou clopidogrel), pas un AVK."},{"t":"Objectif tensionnel PAS 120-129 / PAD 70-79 mmHg","ok":true,"why":"C'est la cible tensionnelle recommandée chez le patient AOMI."}],"explanation":"Le traitement de fond de l'AOMI symptomatique repose sur le contrôle des facteurs de risque (arrêt du tabac, cibles tensionnelles), une statine (LDL < 0,55 g/L) et un antiplaquettaire (aspirine ou clopidogrel), et non sur une anticoagulation par AVK."},"reveal":"M. Lefèvre débute aspirine, statine et un inhibiteur de l'enzyme de conversion, avec sevrage tabagique accompagné.","src":"p. 175"},{"id":"225-case-01-s08","phase":3,"narrative":"En complément du traitement médicamenteux, le médecin propose une prise en charge non pharmacologique.","question":{"type":"QROC","question":"Quelle mesure non médicamenteuse est le traitement de première ligne de la claudication non invalidante ?","answer":"La marche régulière, idéalement supervisée (réadaptation)","accept":["réadaptation à la marche","réentraînement à la marche","marche supervisée"],"keywords":["marche","supervisée","réadaptation"],"explanation":"La réadaptation à la marche, de préférence supervisée, associée à une éducation thérapeutique, est le traitement de première ligne de la claudication non invalidante."},"reveal":"Le patient est orienté vers un programme de réadaptation à la marche supervisée, avec un objectif de 30 à 45 minutes au moins 3 fois par semaine.","src":"p. 175-176"},{"id":"225-case-01-s09","phase":4,"narrative":"Six mois plus tard, malgré une observance correcte et l'arrêt du tabac, le périmètre de marche reste inférieur à 90 mètres et impacte fortement la vie quotidienne du patient.","question":{"type":"QRM","stem":"Que faut-il envisager à ce stade ?","options":[{"t":"Une revascularisation, du fait de l'échec du traitement médical bien conduit avec périmètre de marche < 100 m","ok":true,"why":"La revascularisation est discutée en cas de claudication sévère invalidante après échec du traitement médical bien mené."},{"t":"Un simple renforcement du traitement vasoactif sans autre exploration","ok":false,"why":"Le bénéfice des traitements vasoactifs est modeste et sans effet pronostique ; ce n'est pas la priorité devant cet échec."},{"t":"Une nouvelle imagerie en vue d'un projet de revascularisation (angioscanner ou angio-IRM)","ok":true,"why":"Ces examens sont indiqués lorsqu'une revascularisation est envisagée."},{"t":"L'arrêt de la statine puisque le LDL est désormais à l'objectif","ok":false,"why":"La statine doit être poursuivie au long cours indépendamment du résultat sur la claudication."},{"t":"Une amputation d'emblée","ok":false,"why":"L'amputation est le geste ultime, réservé à l'absence de toute possibilité de revascularisation."}],"explanation":"Après échec du traitement médical bien conduit avec un périmètre de marche sévèrement réduit, la revascularisation doit être discutée, précédée d'une imagerie dédiée."},"reveal":"Un angioscanner confirme une sténose serrée et courte de l'artère fémorale superficielle gauche, accessible à un traitement endovasculaire.","src":"p. 176"},{"id":"225-case-01-s10","phase":4,"narrative":"La sténose est courte et proximale.","question":{"type":"QRU","stem":"Quelle technique de revascularisation est la plus adaptée à cette lésion ?","options":[{"t":"Pontage fémoropoplité d'emblée","ok":false,"why":"La chirurgie est plutôt réservée aux lésions étendues, non aux lésions courtes et proximales."},{"t":"Angioplastie endovasculaire ± stent","ok":true,"why":"Les résultats de l'angioplastie sont d'autant plus favorables que les lésions sont courtes et proximales."},{"t":"Amputation transmétatarsienne","ok":false,"why":"Non indiquée : il ne s'agit pas d'une ischémie dépassée."},{"t":"Aponévrotomie de décompression","ok":false,"why":"Ce geste concerne le syndrome des loges de l'ischémie aiguë, sans rapport avec cette situation."},{"t":"Sympathectomie lombaire","ok":false,"why":"Cette technique n'est pas mentionnée comme option de revascularisation dans ce contexte."}],"explanation":"Pour une lésion courte et proximale, l'angioplastie endovasculaire (± stent) est privilégiée, suivie d'une bithérapie antiplaquettaire de 1 à 6 mois."},"reveal":"Le patient bénéficie d'une angioplastie avec pose de stent, suivie d'une bithérapie antiplaquettaire pendant 3 mois et d'une surveillance écho-Doppler.","src":"p. 176"},{"id":"225-case-01-s11","phase":5,"narrative":"Deux ans plus tard, M. Lefèvre, dont le suivi cardiologique a révélé une fibrillation atriale méconnue, se présente aux urgences pour une douleur brutale et intense du membre inférieur droit, avec un pied froid et livide, sans trouble sensitif ni moteur.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir immédiate ?","options":[{"t":"Débuter une anticoagulation par héparine non fractionnée après prélèvement du bilan de coagulation","ok":true,"why":"L'anticoagulation est débutée dès le diagnostic d'ischémie aiguë, après le prélèvement du bilan de coagulation."},{"t":"Surélever le membre ischémique pour limiter l'œdème","ok":false,"why":"Les soins locaux immédiats imposent au contraire une position légèrement déclive, avec protection du membre (mousse ou coton) et éviction de tout frottement ou traumatisme cutané."},{"t":"Évoquer en priorité une origine embolique devant le contexte de fibrillation atriale","ok":true,"why":"La fibrillation atriale est la principale cause cardiaque d'embolie artérielle des membres."},{"t":"Réaliser d'emblée une amputation puisque le tableau est douloureux","ok":false,"why":"L'amputation n'est envisagée qu'en cas d'ischémie dépassée (grade III) ou d'échec de revascularisation, non à ce stade."},{"t":"Alerter l'équipe chirurgicale vasculaire sans délai","ok":true,"why":"Le pronostic dépend de la rapidité de la prise en charge d'une ischémie aiguë."}],"explanation":"Devant ce tableau typique d'ischémie aiguë sans déficit neurologique (grade I), l'héparine est débutée dès le diagnostic après prélèvement du bilan de coagulation, avec des soins locaux en position légèrement déclive, et l'équipe chirurgicale est alertée sans délai : aucune exploration ne doit retarder la prise en charge."},"reveal":"L'échodoppler réalisé sans perte de temps confirme une occlusion fémorale droite ; une embolectomie à la sonde de Fogarty est réalisée en urgence, orientée par le contexte de fibrillation atriale.","src":"p. 179-182"},{"id":"225-case-01-s12","phase":5,"narrative":"La revascularisation est un succès ; le patient est revu en consultation de suivi à distance de l'épisode aigu.","question":{"type":"QROC","question":"Quel traitement étiologique au long cours doit être instauré du fait du contexte de fibrillation atriale ?","answer":"Une anticoagulation au long cours","accept":["anticoagulant au long cours","AOD ou AVK au long cours"],"keywords":["anticoagulation","long cours","fibrillation"],"explanation":"En cas d'ischémie aiguë d'origine embolique liée à une fibrillation atriale, le traitement étiologique à distance repose sur une anticoagulation au long cours."},"reveal":"Une anticoagulation au long cours est instaurée ; le suivi de l'AOMI et le contrôle des facteurs de risque cardiovasculaire sont poursuivis, le pronostic restant grave à long terme.","src":"p. 183"}]},{"id":"225-case-02","title":"Mme Vasseur, 72 ans, masse battante découverte à l'examen","rank":"A","summary":"Anévrisme de l'aorte abdominale de découverte fortuite, du dépistage à la surveillance, puis à la décision d'intervention.","difficulty":2,"timeline":["Découverte fortuite","Confirmation diagnostique","Surveillance initiale","Progression du diamètre","Décision thérapeutique","Suivi post-opératoire"],"steps":[{"id":"225-case-02-s01","phase":0,"narrative":"Mme Vasseur, 72 ans, hypertendue et ancienne fumeuse, consulte son médecin traitant pour le renouvellement de son traitement antihypertenseur. À la palpation abdominale systématique, celui-ci perçoit une masse battante et expansive péri-ombilicale.","question":{"type":"QRM","stem":"Que faut-il suspecter et rechercher devant cette découverte ?","options":[{"t":"Un anévrisme de l'aorte abdominale","ok":true,"why":"Une masse battante et expansive de l'abdomen évoque en premier lieu un anévrisme de l'aorte."},{"t":"Un souffle abdominal à l'auscultation","ok":true,"why":"Un souffle peut accompagner la masse anévrismale et doit être recherché."},{"t":"Des pouls périphériques et une recherche d'anévrisme poplité","ok":true,"why":"Les anévrismes poplités sont fréquemment associés à l'AAA et doivent être recherchés systématiquement."},{"t":"Une origine exclusivement tumorale, sans autre exploration nécessaire","ok":false,"why":"Le caractère battant et expansif oriente avant tout vers une origine vasculaire, à explorer avant d'évoquer une autre cause."},{"t":"Les autres facteurs de risque cardiovasculaire de la patiente","ok":true,"why":"L'AAA est le plus souvent associé à un terrain athéromateux qu'il convient de caractériser."}],"explanation":"Une masse battante et expansive péri-ombilicale évoque en premier lieu un AAA ; l'examen doit rechercher un souffle, une localisation poplitée associée et les facteurs de risque athéromateux."},"reveal":"Le médecin décide de compléter par une imagerie abdominale.","src":"p. 183-184"},{"id":"225-case-02-s02","phase":0,"narrative":"Le médecin doit choisir l'examen de dépistage le plus adapté.","question":{"type":"QRU","stem":"Quel examen de première intention prescrire ?","options":[{"t":"Scanner abdominopelvien injecté","ok":false,"why":"C'est l'examen préthérapeutique de référence, pas l'examen de dépistage de première intention."},{"t":"Échographie abdominale","ok":true,"why":"L'échographie abdominale est l'examen de dépistage, de mesure et de surveillance de l'AAA."},{"t":"Artériographie","ok":false,"why":"Elle n'est pas utile au diagnostic d'AAA, car elle sous-estime la taille en cas de thrombus mural."},{"t":"IRM abdominale","ok":false,"why":"Elle est réservée comme alternative en cas de contre-indication au scanner, pas en dépistage de première intention."},{"t":"Angioscanner des membres inférieurs","ok":false,"why":"Cet examen explore les artères des membres inférieurs, non l'aorte abdominale."}],"explanation":"L'échographie abdominale est l'examen de dépistage recommandé, non invasif, permettant de mesurer le diamètre et d'assurer le suivi."},"reveal":"L'échographie confirme un anévrisme de l'aorte abdominale sous-rénale mesuré à 42 mm de diamètre.","src":"p. 184"},{"id":"225-case-02-s03","phase":1,"narrative":"Le diagnostic d'AAA est confirmé à 42 mm.","question":{"type":"QRM","stem":"Concernant l'étiologie de cet anévrisme, quelles propositions sont exactes ?","options":[{"t":"Dans 80 à 90 % des cas, l'AAA survient sur un terrain athéromateux","ok":true,"why":"C'est la cause prédominante de l'AAA, souvent associée à une AOMI ou une atteinte coronarienne."},{"t":"Une maladie du tissu élastique (Marfan, Ehlers-Danlos, Loeys-Dietz) peut être en cause dans les formes familiales","ok":true,"why":"Ces maladies génétiques sont citées parmi les étiologies des formes non athéromateuses."},{"t":"Une aortite (Takayasu, Horton) peut être responsable d'un AAA","ok":true,"why":"Les aortites sont une étiologie possible, plus rare que l'origine athéromateuse."},{"t":"Le diabète est le principal facteur de risque d'AAA","ok":false,"why":"Les diabétiques sont au contraire décrits comme moins souvent atteints d'AAA."},{"t":"Les antécédents familiaux d'anévrisme ne jouent aucun rôle","ok":false,"why":"Les antécédents familiaux d'anévrisme sont au contraire un facteur de risque reconnu, en dehors de l'âge et du tabac."}],"explanation":"L'athérome est la cause prédominante de l'AAA (80-90 %), avec des formes familiales (maladies du tissu élastique) ou secondaires à une aortite ; le diabète n'est pas un facteur de risque, contrairement au tabac et aux antécédents familiaux."},"reveal":"Le bilan ne retrouve pas de contexte familial ni de signe d'aortite ; l'origine est jugée athéromateuse.","src":"p. 184"},{"id":"225-case-02-s04","phase":1,"narrative":"Devant ce diagnostic, le médecin complète le bilan de localisation.","question":{"type":"QROC","question":"Quelles autres localisations anévrismales faut-il systématiquement rechercher devant un AAA ?","answer":"Les localisations poplitées et iliaques","accept":["anévrismes poplités","anévrismes iliaques","poplité et iliaque"],"keywords":["poplité","iliaque"],"explanation":"L'échographie de dépistage recherche également les localisations poplitées et iliaques, fréquemment associées à l'AAA."},"reveal":"Aucune localisation poplitée ou iliaque associée n'est retrouvée chez cette patiente.","src":"p. 184-187"},{"id":"225-case-02-s05","phase":2,"narrative":"Le diamètre de 42 mm ne justifie pas d'intervention immédiate.","question":{"type":"QRM","stem":"Quelles sont les modalités de prise en charge à ce stade ?","options":[{"t":"Surveillance échographique répétée","ok":true,"why":"Les anévrismes de petite taille sont surveillés par des échographies répétées."},{"t":"Contrôle strict des facteurs de risque cardiovasculaire, notamment arrêt du tabac","ok":true,"why":"Le contrôle des facteurs de risque est indispensable pendant toute la période de suivi, la progression étant plus rapide en cas de tabagisme persistant."},{"t":"Intervention chirurgicale programmée immédiate","ok":false,"why":"Le seuil d'intervention à froid se situe à 50-55 mm ; 42 mm ne justifie pas d'intervention immédiate."},{"t":"Antibioprophylaxie systématique en l'absence de tout geste invasif","ok":false,"why":"L'antibioprophylaxie ne concerne que les gestes à risque bactérien chez un porteur de prothèse, non la simple surveillance d'un anévrisme natif."},{"t":"Recherche et prise en charge du risque cardiovasculaire global","ok":true,"why":"Le porteur d'AAA a un risque de décès cardiovasculaire bien supérieur à celui de rupture, justifiant une prise en charge globale."}],"explanation":"À 42 mm, la prise en charge repose sur la surveillance échographique et le contrôle rigoureux des facteurs de risque cardiovasculaire, la patiente étant à haut risque de complication cardiovasculaire globale."},"reveal":"Une surveillance échographique annuelle est programmée et l'arrêt du tabac est fortement encouragé.","src":"p. 185-186"},{"id":"225-case-02-s06","phase":2,"narrative":"La patiente peine à arrêter le tabac malgré les conseils reçus.","question":{"type":"OPEN","prompt":"Expliquez à la patiente, en quelques phrases, pourquoi l'arrêt du tabac est particulièrement important dans sa situation.","rubric":[{"point":"Le tabagisme actif accélère la croissance de l'anévrisme (environ 3 fois plus rapide)","weight":2},{"point":"Le tabac est un facteur de risque majeur de progression et de complication cardiovasculaire","weight":1},{"point":"Le risque principal chez le porteur d'AAA reste le risque cardiovasculaire global, pas seulement la rupture","weight":1}],"model":"La poursuite du tabagisme accélère nettement la croissance de l'anévrisme, environ trois fois plus vite que chez un non-fumeur. Au-delà du risque local, le tabac est aussi le principal facteur de risque cardiovasculaire général : chez une porteuse d'AAA, le risque de décès par complication cardiovasculaire (infarctus, AVC) est bien plus élevé que celui de rupture de l'anévrisme lui-même. L'arrêt du tabac est donc une priorité, autant pour l'anévrisme que pour le pronostic global."},"reveal":"Une consultation d'aide au sevrage tabagique est organisée.","src":"p. 186"},{"id":"225-case-02-s07","phase":3,"narrative":"Deux ans plus tard, l'échographie de contrôle retrouve un anévrisme mesurant désormais 48 mm de diamètre.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir devant cette progression ?","options":[{"t":"Renforcer la surveillance échographique, à un rythme semestriel","ok":true,"why":"Au-delà de 45 mm, la surveillance échographique est renforcée, tous les 6 mois."},{"t":"Programmer une intervention chirurgicale immédiate","ok":false,"why":"Le seuil habituel d'intervention (50-55 mm) n'est pas encore atteint."},{"t":"Renforcer le contrôle des facteurs de risque cardiovasculaire","ok":true,"why":"Le contrôle des facteurs de risque reste indispensable pendant toute la surveillance."},{"t":"Arrêter toute surveillance puisque le diamètre reste inférieur à 50 mm","ok":false,"why":"Au contraire, la surveillance doit être renforcée à l'approche du seuil d'intervention."},{"t":"Envisager d'emblée une endoprothèse quelle que soit l'anatomie","ok":false,"why":"Une intervention n'est envisagée qu'au-delà du seuil de 50-55 mm, sous réserve d'une anatomie et d'un terrain adaptés."}],"explanation":"Entre 45 et 50 mm, la surveillance échographique est renforcée (tous les 6 mois) et le contrôle des facteurs de risque poursuivi, sans indication opératoire immédiate."},"reveal":"Le rythme de surveillance est porté à 6 mois.","src":"p. 185-186"},{"id":"225-case-02-s08","phase":3,"narrative":"Un an après, l'échographie retrouve un anévrisme à 56 mm de diamètre, sans douleur ni signe de complication.","question":{"type":"QRM","stem":"Que faut-il envisager à ce stade ?","options":[{"t":"Une intervention programmée « à froid »","ok":true,"why":"Au-delà de 50-55 mm, le risque de rupture devient important et une intervention programmée est indiquée."},{"t":"Un scanner abdominopelvien injecté pour préciser le diamètre et l'anatomie avant l'intervention","ok":true,"why":"C'est l'examen préthérapeutique de référence, précisant diamètre et anatomie en vue de l'intervention."},{"t":"Une simple surveillance échographique supplémentaire sans projet opératoire","ok":false,"why":"Le seuil d'intervention est atteint ; la simple surveillance n'est plus suffisante."},{"t":"Une artériographie pour mesurer précisément le diamètre de l'anévrisme","ok":false,"why":"L'artériographie n'est pas utile pour mesurer un AAA car elle sous-estime la taille en présence de thrombus mural."},{"t":"Une amputation de principe","ok":false,"why":"Ce geste n'a aucun rapport avec la prise en charge d'un anévrisme de l'aorte abdominale."}],"explanation":"Au-delà de 50-55 mm, une intervention à froid est programmée, précédée d'un scanner abdominopelvien injecté, examen préthérapeutique de référence."},"reveal":"Le scanner confirme un anévrisme de 56 mm, sous-rénal, avec une anatomie favorable à un traitement endovasculaire.","src":"p. 185-186"},{"id":"225-case-02-s09","phase":4,"narrative":"Compte tenu de son âge et de comorbidités modérées, l'équipe discute la meilleure technique.","question":{"type":"QRU","stem":"Quel traitement privilégier chez cette patiente, compte tenu d'une anatomie favorable ?","options":[{"t":"Chirurgie conventionnelle à ciel ouvert uniquement","ok":false,"why":"Ce n'est pas la seule option ; le traitement endovasculaire est envisageable si l'anatomie est favorable."},{"t":"Traitement endovasculaire par endoprothèse","ok":true,"why":"Moins invasif, il est proposé lorsque l'anatomie est favorable, y compris chez des patients à risque non nécessairement élevé après information éclairée."},{"t":"Abstention thérapeutique définitive","ok":false,"why":"Au-delà du seuil de 50-55 mm, une intervention est indiquée, pas l'abstention."},{"t":"Simple surveillance rapprochée sans intervention","ok":false,"why":"Le seuil d'intervention étant dépassé, la surveillance seule n'est plus adaptée."},{"t":"Embolectomie à la sonde de Fogarty","ok":false,"why":"Ce geste concerne la revascularisation d'une ischémie aiguë de membre, non le traitement d'un AAA."}],"explanation":"Avec une anatomie favorable, le traitement endovasculaire par endoprothèse, moins invasif, est une option de choix après information éclairée de la patiente."},"reveal":"Après information de la patiente sur les bénéfices et la nécessité d'une surveillance itérative, elle opte pour le traitement endovasculaire.","src":"p. 186"},{"id":"225-case-02-s10","phase":4,"narrative":"Avant l'intervention, la patiente demande quelles complications sont spécifiquement surveillées après la pose d'une endoprothèse.","question":{"type":"QROC","question":"Quelle complication spécifique du traitement endovasculaire doit être recherchée par la surveillance itérative ?","answer":"Une endofuite","accept":["endofuite","fuite péri-prothétique"],"keywords":["endofuite"],"explanation":"Les endofuites, flux maintenant une pression dans le sac anévrismal, peuvent faire progresser voire rompre l'anévrisme et justifient une surveillance itérative par scanner ou échographie de contraste."},"reveal":"L'endoprothèse est posée sans complication immédiate.","src":"p. 186"},{"id":"225-case-02-s11","phase":5,"narrative":"La patiente est revue en consultation de suivi post-opératoire.","question":{"type":"QRM","stem":"Quelles sont les modalités de surveillance à mettre en place ?","options":[{"t":"Surveillance au long cours par scanner ou échographie de contraste à la recherche d'endofuites","ok":true,"why":"C'est la surveillance spécifique recommandée après pose d'une endoprothèse."},{"t":"Antibioprophylaxie lors de tout geste à risque bactérien du fait de la prothèse","ok":true,"why":"Le risque infectieux de la prothèse vasculaire justifie une antibioprophylaxie lors des gestes à risque bactérien."},{"t":"Poursuite du contrôle des facteurs de risque cardiovasculaire","ok":true,"why":"Le risque cardiovasculaire persiste même après un traitement réussi de l'anévrisme."},{"t":"Arrêt de toute surveillance dès la sortie d'hospitalisation","ok":false,"why":"Une surveillance itérative au long cours est au contraire indispensable après endoprothèse."},{"t":"Reprise du tabac désormais sans conséquence","ok":false,"why":"Le contrôle des facteurs de risque, notamment le tabac, reste essentiel après traitement de l'AAA."}],"explanation":"Après endoprothèse, la surveillance associe imagerie itérative (endofuites), antibioprophylaxie lors des gestes à risque bactérien et poursuite du contrôle des facteurs de risque cardiovasculaire."},"reveal":"Un scanner de contrôle à 1 mois ne retrouve pas d'endofuite.","src":"p. 186"},{"id":"225-case-02-s12","phase":5,"narrative":"Un an après l'intervention, la patiente se porte bien et demande si elle est désormais guérie.","question":{"type":"OPEN","prompt":"Expliquez à la patiente pourquoi un suivi cardiovasculaire reste nécessaire malgré le succès du traitement de son anévrisme.","rubric":[{"point":"Le traitement de l'anévrisme ne traite pas la maladie athéromateuse sous-jacente","weight":2},{"point":"Le porteur d'AAA reste à haut risque cardiovasculaire (coronarien, cérébral)","weight":1},{"point":"Nécessité de poursuivre la surveillance de l'endoprothèse et le contrôle des facteurs de risque","weight":1}],"model":"Le traitement de l'anévrisme a supprimé le risque local de rupture, mais il ne traite pas la maladie athéromateuse qui en est la cause. Un patient porteur d'AAA reste exposé à un risque élevé de complication cardiovasculaire, coronarienne ou cérébrale, plus important que le risque local. Il faut donc poursuivre le contrôle des facteurs de risque et la surveillance régulière de l'endoprothèse au long cours."},"reveal":"Le suivi cardiovasculaire et la surveillance de l'endoprothèse sont poursuivis annuellement.","src":"p. 186"}]},{"id":"225-case-03","title":"M. Tanguy, 70 ans, douleurs abdominales après les repas","rank":"A","summary":"Ischémie mésentérique chronique méconnue se compliquant d'un épisode d'ischémie mésentérique aiguë sur probable embolie.","difficulty":3,"timeline":["Consultation pour douleurs abdominales","Bilan diagnostique","Diagnostic et traitement","Complication aiguë","Prise en charge en urgence"],"steps":[{"id":"225-case-03-s01","phase":0,"narrative":"M. Tanguy, 70 ans, polyathéromateux (AOMI connue, tabagisme), consulte pour des douleurs abdominales apparaissant systématiquement 20 à 30 minutes après les repas, associées à un amaigrissement de 6 kg en quelques mois.","question":{"type":"QRM","stem":"Quels éléments orientent vers une ischémie mésentérique chronique ?","options":[{"t":"Le caractère postprandial systématique des douleurs","ok":true,"why":"C'est la présentation typique de l'angor digestif de l'ischémie mésentérique chronique."},{"t":"Le terrain polyathéromateux du patient","ok":true,"why":"Les sténoses digestives partagent le même terrain athéromateux que l'AOMI."},{"t":"L'amaigrissement lié à la restriction alimentaire","ok":true,"why":"La crainte de déclencher la douleur conduit à une restriction alimentaire et à un amaigrissement."},{"t":"La présence de vomissements et diarrhées explosifs depuis plusieurs heures","ok":false,"why":"Ce tableau évoque plutôt une forme aiguë, non la forme chronique progressive décrite ici."},{"t":"Une douleur exclusivement nocturne et positionnelle","ok":false,"why":"Ce n'est pas la présentation typique de l'angor digestif, qui est déclenché par le repas."}],"explanation":"Le caractère postprandial des douleurs, le terrain athéromateux et l'amaigrissement par restriction alimentaire orientent vers une ischémie mésentérique chronique (angor digestif)."},"reveal":"L'examen recherche un souffle abdominal.","src":"p. 166-167"},{"id":"225-case-03-s02","phase":0,"narrative":"L'auscultation abdominale retrouve un souffle épigastrique discret.","question":{"type":"QROC","question":"Quel terme désigne le tableau clinique de douleurs abdominales postprandiales par sténose artérielle digestive ?","answer":"L'angor digestif","accept":["angine digestive"],"keywords":["angor","digestif"],"explanation":"Ce tableau douloureux postprandial lié à une sténose artérielle viscérale est appelé angor digestif."},"reveal":"Le médecin prescrit une exploration vasculaire digestive.","src":"p. 166"},{"id":"225-case-03-s03","phase":1,"narrative":"Le médecin doit choisir l'examen de première intention.","question":{"type":"QRU","stem":"Quel examen prescrire en première intention pour explorer une suspicion de sténose artérielle digestive ?","options":[{"t":"Échodoppler des artères digestives","ok":true,"why":"Il fait partie des examens de première intention pour diagnostiquer une sténose artérielle viscérale, avec l'angioscanner et l'angio-IRM."},{"t":"Artériographie digestive","ok":false,"why":"Elle n'est réalisée que dans le cadre d'un geste de revascularisation par voie endovasculaire."},{"t":"Coloscopie","ok":false,"why":"Non mentionnée comme examen de la sténose artérielle digestive dans ce chapitre."},{"t":"Mesure de l'index de pression systolique","ok":false,"why":"L'IPS rapporte la pression systolique de cheville à celle du bras : il explore les artères des membres inférieurs, pas les artères digestives."},{"t":"Électrocardiogramme","ok":false,"why":"Il ne diagnostique pas une sténose artérielle digestive, qui repose sur l'échodoppler, l'angioscanner ou l'angio-IRM."}],"explanation":"L'échodoppler des artères digestives (ou l'angioscanner/angio-IRM) est l'examen de première intention pour diagnostiquer une sténose artérielle viscérale."},"reveal":"L'échodoppler des artères digestives retrouve une sténose serrée du tronc cœliaque.","src":"p. 166, 170"},{"id":"225-case-03-s04","phase":1,"narrative":"Le diagnostic d'ischémie mésentérique chronique est retenu.","question":{"type":"QRM","stem":"Quelles sont les modalités de traitement adaptées à cette situation ?","options":[{"t":"Revascularisation, de préférence par voie endovasculaire","ok":true,"why":"Le traitement de l'ischémie mésentérique chronique repose sur la revascularisation, préférentiellement endovasculaire."},{"t":"L'artériographie n'est réalisée qu'au cours du geste de revascularisation endovasculaire","ok":true,"why":"Elle n'a pas de place en simple exploration diagnostique."},{"t":"Anticoagulation curative au long cours comme traitement de référence","ok":false,"why":"Le traitement de référence est la revascularisation, pas l'anticoagulation."},{"t":"Résection intestinale systématique","ok":false,"why":"La résection des segments nécrosés concerne la forme aiguë, pas la forme chronique."},{"t":"Abstention thérapeutique malgré l'angor digestif","ok":false,"why":"Une ischémie mésentérique chronique symptomatique relève d'une revascularisation."}],"explanation":"Le traitement de l'ischémie mésentérique chronique repose sur la revascularisation, de préférence endovasculaire ; l'artériographie n'est réalisée qu'au cours du geste endovasculaire. La résection intestinale concerne la forme aiguë."},"reveal":"M. Tanguy bénéficie d'une revascularisation endovasculaire du tronc cœliaque ; ses douleurs postprandiales disparaissent.","src":"p. 166, 187"},{"id":"225-case-03-s05","phase":2,"narrative":"Six mois plus tard, le patient va bien, sans récidive de douleur postprandiale.","question":{"type":"QROC","question":"Quel examen n'est réalisé, dans la prise en charge de l'ischémie mésentérique, que lors d'un geste de revascularisation endovasculaire ?","answer":"L'artériographie","accept":["artériographie digestive"],"keywords":["artériographie"],"explanation":"L'artériographie n'est réalisée que lors d'une procédure de revascularisation par voie endovasculaire, jamais en simple exploration diagnostique."},"reveal":"Le suivi se poursuit sans complication.","src":"p. 166"},{"id":"225-case-03-s06","phase":2,"narrative":"Lors d'une consultation de suivi, le cardiologue découvre une fibrillation atriale paroxystique méconnue.","question":{"type":"QRM","stem":"Quelles sont les conséquences possibles de cette découverte chez ce patient ?","options":[{"t":"Un risque accru d'embolie artérielle, notamment digestive ou des membres","ok":true,"why":"La fibrillation atriale est une cause classique d'embolie sur artères saines ou déjà pathologiques."},{"t":"La nécessité de discuter une anticoagulation au long cours","ok":true,"why":"La fibrillation atriale justifie la discussion d'un traitement anticoagulant préventif des complications emboliques."},{"t":"Une orientation vers une thrombose in situ plutôt qu'une embolie en cas d'ischémie aiguë ultérieure","ok":false,"why":"La fibrillation atriale est une cause cardiaque d'embolie : elle oriente au contraire vers une origine embolique."},{"t":"Une disparition du risque d'ischémie mésentérique aiguë","ok":false,"why":"Au contraire, la fibrillation atriale majore le risque d'ischémie mésentérique aiguë d'origine embolique."},{"t":"L'absence de toute conséquence pratique","ok":false,"why":"La découverte d'une fibrillation atriale a des implications thérapeutiques et de surveillance importantes."}],"explanation":"La fibrillation atriale expose à un risque accru d'embolie artérielle (dont digestive) et impose de discuter une anticoagulation au long cours."},"reveal":"Une anticoagulation est discutée mais différée par le patient, qui refuse initialement le traitement.","src":"p. 167, 181"},{"id":"225-case-03-s07","phase":3,"narrative":"Quelques semaines plus tard, M. Tanguy consulte aux urgences pour une douleur abdominale aiguë intense apparue brutalement, avec vomissements et diarrhée, sans grande anomalie à l'examen abdominal.","question":{"type":"QRM","stem":"Quelle est la conduite à tenir la plus appropriée ?","options":[{"t":"Suspecter une ischémie mésentérique aiguë devant ce contexte emboligène et cette triade clinique","ok":true,"why":"La triade douleur abdominale aiguë pauvre en signes physiques, vidange digestive accélérée et contexte emboligène (fibrillation atriale) est évocatrice d'ischémie mésentérique aiguë."},{"t":"Différer l'imagerie puisque l'examen abdominal est peu parlant","ok":false,"why":"Piège : la douleur aiguë pauvre en signes physiques fait justement partie de la triade ; c'est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge."},{"t":"Demander en urgence un angioscanner abdominal","ok":true,"why":"Le diagnostic d'ischémie mésentérique aiguë est confirmé par l'angioscanner."},{"t":"Rassurer le patient et le renvoyer à domicile avec des antalgiques simples","ok":false,"why":"Ce tableau chez un patient à risque emboligène est une urgence vitale potentielle, à ne pas banaliser."},{"t":"Rechercher des arguments emboligènes complémentaires (auscultation cardiaque, ECG)","ok":true,"why":"Le bilan étiologique en contexte emboligène potentiel fait partie de la prise en charge initiale."}],"explanation":"Devant cette triade évocatrice chez un patient en fibrillation atriale, il faut suspecter une ischémie mésentérique aiguë, demander en urgence un angioscanner qui confirme le diagnostic, et rechercher des arguments emboligènes."},"reveal":"Le patient est immédiatement adressé pour un angioscanner abdominal en urgence.","src":"p. 167, 187"},{"id":"225-case-03-s08","phase":3,"narrative":"L'angioscanner doit être interprété.","question":{"type":"QRU","stem":"Quel examen confirme le diagnostic d'ischémie mésentérique aiguë ?","options":[{"t":"L'angioscanner abdominal","ok":true,"why":"C'est l'examen qui confirme le diagnostic."},{"t":"L'échodoppler des artères digestives","ok":false,"why":"Il sert au diagnostic de la sténose de l'ischémie mésentérique chronique ; la forme aiguë est confirmée par l'angioscanner."},{"t":"L'échocardiographie transthoracique","ok":false,"why":"Elle recherche une source cardiaque d'embolie mais ne confirme pas l'occlusion artérielle digestive."},{"t":"La coloscopie","ok":false,"why":"Elle ne confirme pas une occlusion artérielle digestive."},{"t":"L'artériographie diagnostique en première intention","ok":false,"why":"L'artériographie n'est pas l'examen diagnostique de première intention."}],"explanation":"L'ischémie mésentérique aiguë est une urgence vitale dont le pronostic dépend de la rapidité de la prise en charge ; le diagnostic est confirmé par l'angioscanner."},"reveal":"L'angioscanner confirme une occlusion embolique de l'artère mésentérique supérieure.","src":"p. 166-167, 182, 187"},{"id":"225-case-03-s09","phase":4,"narrative":"Le chirurgien digestif est immédiatement contacté.","question":{"type":"QRM","stem":"Quels éléments composent la prise en charge de cette ischémie mésentérique aiguë ?","options":[{"t":"Résection des segments intestinaux nécrosés","ok":true,"why":"C'est la base du traitement en cas de nécrose digestive constituée."},{"t":"Geste de revascularisation associé, par voie endovasculaire ou chirurgicale","ok":true,"why":"Le traitement associe à la résection des segments nécrosés une revascularisation, chirurgicale ou endovasculaire."},{"t":"Anticoagulation au long cours à discuter à distance, du fait de la fibrillation atriale","ok":true,"why":"À plus long terme, le traitement étiologique d'une cause embolique est à envisager, par exemple une anticoagulation au long cours en cas de fibrillation atriale."},{"t":"Surveillance simple sans aucun geste, la vidange digestive étant rassurante","ok":false,"why":"Le tableau confirmé par l'angioscanner impose un geste urgent (résection et revascularisation), non une simple surveillance."},{"t":"Antibiothérapie seule, sans geste chirurgical","ok":false,"why":"Le traitement de référence associe résection et revascularisation, pas une antibiothérapie isolée."}],"explanation":"La prise en charge associe résection des segments nécrosés et revascularisation en urgence, puis un traitement étiologique au long cours (anticoagulation devant la fibrillation atriale)."},"reveal":"Le patient est opéré en urgence : résection d'un segment grêle nécrosé et revascularisation par voie chirurgicale.","src":"p. 167, 183, 187"},{"id":"225-case-03-s11","phase":4,"narrative":"Avant sa sortie, le patient s'interroge sur la suite de sa prise en charge au long cours.","question":{"type":"OPEN","prompt":"Résumez les grands axes du traitement au long cours à mettre en place chez ce patient après cet épisode d'ischémie mésentérique aiguë d'origine embolique.","rubric":[{"point":"Anticoagulation au long cours du fait de la fibrillation atriale, cause probable de l'embolie","weight":2},{"point":"Poursuite du contrôle des facteurs de risque cardiovasculaire (tabac, etc.)","weight":1}],"model":"Le traitement étiologique au long cours repose avant tout sur une anticoagulation, la fibrillation atriale étant la cause probable de l'embolie mésentérique. Le contrôle des facteurs de risque cardiovasculaire, notamment un sevrage tabagique complet, doit être poursuivi compte tenu du terrain polyathéromateux."},"reveal":"Une anticoagulation au long cours est finalement acceptée par le patient, associée à un suivi cardiovasculaire régulier.","src":"p. 167, 183"}]},{"id":"225-case-51","title":"M. Garnier, 71 ans, douleur lombaire brutale","rank":"A","summary":"Anévrisme de l'aorte abdominale fissuré chez un patient à haut risque, du diagnostic en urgence au traitement endovasculaire, au suivi et à la recherche des autres localisations.","difficulty":2,"timeline":["Accueil aux urgences","Confirmation diagnostique","Histoire naturelle","Traitement en urgence","Suivi post-opératoire","Autres localisations","Prévention et dépistage familial"],"steps":[{"phase":0,"narrative":"M. Garnier, 71 ans, fumeur actif, coronarien et insuffisant respiratoire chronique sévère, est amené aux urgences pour une douleur lombaire gauche brutale et intense. PA 105/65 mmHg, FC 102/min. On palpe une masse para-ombilicale battante et expansive. Il se savait porteur d'un « anévrisme de l'aorte » dont il avait interrompu la surveillance.","question":{"type":"QRU","stem":"Quel diagnostic évoquez-vous en priorité ?","options":[{"t":"Fissuration d'un anévrisme de l'aorte abdominale","ok":true,"why":"Douleur abdominale ou lombaire chez un porteur d'AAA (masse battante et expansive) : fissuration/rupture, urgence vitale."},{"t":"Colique néphrétique","ok":false,"why":"La masse battante et expansive chez un porteur d'AAA impose d'évoquer d'abord une fissuration."},{"t":"Ischémie mésentérique chronique","ok":false,"why":"Elle donne des douleurs postprandiales, non une douleur lombaire brutale."},{"t":"Lombosciatique commune","ok":false,"why":"Ne rend pas compte de la masse battante ni du contexte."},{"t":"Syndrome de Leriche","ok":false,"why":"Il associe claudication fessière et troubles de l'érection."}],"explanation":"La forme symptomatique d'un AAA est souvent révélée par une fissuration/rupture : douleur abdominale ou lombaire ± choc hémorragique, urgence vitale."},"reveal":"L'hémodynamique reste stable à ce stade, sans signe de choc.","src":"p. 183-185","id":"225-case-51-s01"},{"phase":1,"narrative":"Le patient reste hémodynamiquement stable.","question":{"type":"QRU","stem":"Quel examen réalisez-vous pour confirmer le diagnostic et préparer le traitement ?","options":[{"t":"Scanner abdominopelvien injecté","ok":true,"why":"Il confirme le diagnostic, précise l'anatomie de l'anévrisme et constitue l'examen préthérapeutique de référence."},{"t":"Artériographie aortique","ok":false,"why":"Elle ne visualise que la lumière circulante et sous-estime la taille en cas de thrombus mural."},{"t":"IRM abdominale en 1re intention","ok":false,"why":"L'IRM est une alternative en cas de contre-indication au scanner."},{"t":"Échographie abdominale","ok":false,"why":"Elle sert au dépistage, à la mesure du diamètre et au suivi de l'AAA ; le diagnostic de fissuration et le bilan préthérapeutique reposent sur le scanner injecté."},{"t":"Transfert au bloc sans aucune imagerie","ok":false,"why":"Le diagnostic de fissuration ou de rupture doit être confirmé par le scanner avant le traitement ; même chez le patient en choc, seule une imagerie autre que ce scanner est à proscrire."}],"explanation":"Devant une suspicion de fissuration d'AAA, le scanner abdominopelvien injecté confirme le diagnostic et sert de bilan préthérapeutique de référence ; chez un patient en choc hémorragique, aucune imagerie autre que ce scanner ne doit retarder l'intervention."},"reveal":"Le scanner montre un AAA sous-rénal de 64 mm avec un hématome rétropéritonéal : AAA fissuré.","src":"p. 184-186, 188","id":"225-case-51-s02"},{"phase":2,"narrative":"Son épouse demande si ce risque était prévisible : l'anévrisme mesurait 46 mm il y a 5 ans.","question":{"type":"QRM","stem":"Concernant le risque de rupture d'un AAA, quelles propositions sont exactes ?","options":[{"t":"Il est d'environ 15 %/an au-delà de 60 mm.","ok":true,"why":"Chiffre cité."},{"t":"Il est d'environ 3 %/an entre 50 et 59 mm.","ok":true,"why":"Chiffre cité."},{"t":"Il est d'environ 0,4 %/an en dessous de 40 mm.","ok":true,"why":"Chiffre cité."},{"t":"À diamètre égal, il est plus faible chez la femme.","ok":false,"why":"Il est environ 4 fois plus élevé chez la femme à diamètre égal."},{"t":"Le diamètre est le principal facteur prédictif du risque de rupture.","ok":true,"why":"Le texte le précise."}],"explanation":"Le diamètre est le principal facteur prédictif de rupture ; au-delà de 45 mm, la surveillance échographique est renforcée (tous les 6 mois)."},"reveal":"Vous expliquez qu'à 46 mm une surveillance échographique tous les 6 mois était indiquée.","src":"p. 183-187","id":"225-case-51-s03"},{"phase":3,"narrative":"Le patient est à très haut risque périopératoire ; l'anatomie de l'anévrisme est favorable.","question":{"type":"QRU","stem":"Quelle stratégie thérapeutique privilégiez-vous ?","options":[{"t":"Traitement endovasculaire en urgence","ok":true,"why":"De plus en plus proposé même en contexte de rupture, surtout chez le sujet à très haut risque périopératoire."},{"t":"Surveillance échographique rapprochée","ok":false,"why":"L'anévrisme fissuré est une urgence absolue."},{"t":"Intervention programmée à froid dans 3 mois","ok":false,"why":"Il s'agit d'une urgence absolue."},{"t":"Artériographie avant toute décision","ok":false,"why":"L'artériographie n'est pas utile au diagnostic de l'AAA."},{"t":"Traitement médical seul","ok":false,"why":"L'anévrisme fissuré impose une intervention urgente."}],"explanation":"L'AAA rompu ou fissuré est une urgence absolue ; le traitement endovasculaire est de plus en plus proposé, surtout chez le sujet à très haut risque périopératoire."},"reveal":"Une endoprothèse aortique est posée en urgence par voie fémorale, avec succès.","src":"p. 185-187","id":"225-case-51-s04"},{"phase":4,"narrative":"Les suites sont simples. Vous organisez le suivi.","question":{"type":"QRM","stem":"Concernant le suivi après pose d'une endoprothèse aortique, quelles propositions sont exactes ?","options":[{"t":"Une surveillance par scanner ou échographie est nécessaire au long cours.","ok":true,"why":"Le texte le précise."},{"t":"Les endofuites peuvent faire progresser, voire rompre l'anévrisme.","ok":true,"why":"Le texte le précise."},{"t":"Une antibioprophylaxie est justifiée lors des gestes à risque bactérien.","ok":true,"why":"En raison du risque infectieux de la prothèse vasculaire."},{"t":"Le risque cardiovasculaire persiste malgré le succès du traitement.","ok":true,"why":"Le texte le précise."},{"t":"La surveillance peut être interrompue après 1 an si l'imagerie est normale.","ok":false,"why":"La surveillance après endoprothèse se fait au long cours."}],"explanation":"Après endoprothèse : surveillance scanner/écho au long cours (endofuites), antibioprophylaxie des gestes à risque bactérien, prise en charge du risque cardiovasculaire persistant."},"reveal":"Un suivi au long cours est programmé.","src":"p. 185-187","id":"225-case-51-s05"},{"phase":5,"narrative":"Vous recherchez d'autres localisations anévrismales.","question":{"type":"QROC","question":"Quelles localisations anévrismales associées l'échographie recherche-t-elle chez un porteur d'AAA ?","answer":"Anévrismes poplités et iliaques","accept":["artères poplitées et iliaques","poplités et iliaques"],"keywords":["poplit","iliaq"],"explanation":"L'échographie recherche des localisations anévrismales poplitées et iliaques associées."},"reveal":"L'écho-Doppler découvre un anévrisme poplité droit, asymptomatique.","src":"p. 184, 186","id":"225-case-51-s06"},{"phase":5,"narrative":"Vous faites le point sur cet anévrisme poplité.","question":{"type":"QRM","stem":"Concernant l'anévrisme de l'artère poplitée, quelles propositions sont exactes ?","options":[{"t":"Il est associé à un AAA dans environ 30 % des cas.","ok":true,"why":"Chiffre cité, d'où la recherche systématique d'un AAA."},{"t":"Il est bilatéral dans près de la moitié des cas.","ok":true,"why":"L'artère poplitée controlatérale doit donc être explorée."},{"t":"Il peut être découvert par la palpation d'une masse battante au creux poplité.","ok":true,"why":"Le pouls est alors « trop bien perçu » ; l'échodoppler peut aussi le découvrir."},{"t":"Son dépistage repose sur l'artériographie.","ok":false,"why":"Il est découvert par la palpation ou par un échodoppler, notamment en cas d'AAA ou d'anévrisme poplité controlatéral."},{"t":"Il est toujours symptomatique au moment du diagnostic.","ok":false,"why":"Il est souvent découvert à un stade asymptomatique (palpation, échodoppler)."}],"explanation":"L'anévrisme poplité est associé à un AAA dans ≈ 30 % des cas et bilatéral une fois sur deux ; il est découvert par la palpation d'une masse battante, par un échodoppler (dépistage si AAA ou anévrisme poplité controlatéral) ou devant une artériopathie ou une ischémie aiguë."},"reveal":"Un écho-Doppler de l'artère poplitée gauche est programmé, l'anévrisme poplité étant bilatéral dans près de la moitié des cas.","src":"p. 186","id":"225-case-51-s07"},{"phase":6,"narrative":"Vous abordez avec le patient la prévention cardiovasculaire.","question":{"type":"QRM","stem":"Quelles propositions sont exactes chez ce porteur d'AAA ?","options":[{"t":"Son risque de décès cardiovasculaire est environ 10 fois supérieur à celui de rupture.","ok":true,"why":"Chiffre cité."},{"t":"Le contrôle des facteurs de risque est indispensable.","ok":true,"why":"Le texte le précise."},{"t":"L'AAA survient sur un terrain athéromateux dans 80 à 90 % des cas.","ok":true,"why":"Chiffre cité."},{"t":"La recherche d'une atteinte coronarienne, carotidienne ou d'une AOMI associée est inutile.","ok":false,"why":"L'AAA est souvent associé à une AOMI, une atteinte coronarienne ou carotidienne."},{"t":"Le tabagisme actif accélère la croissance anévrismale.","ok":true,"why":"Progression environ 3 fois plus rapide."}],"explanation":"Le porteur d'AAA, athéromateux dans 80–90 % des cas, a un risque de décès CV 10 fois supérieur à celui de rupture : contrôle des facteurs de risque indispensable."},"reveal":"Un sevrage tabagique est engagé.","src":"p. 183-187","id":"225-case-51-s08"},{"phase":6,"narrative":"Son frère, 60 ans, fumeur, demande s'il doit être dépisté.","question":{"type":"QRU","stem":"Quelle attitude proposez-vous ?","options":[{"t":"Une échographie abdominale de dépistage dès maintenant","ok":true,"why":"Le dépistage est recommandé chez l'homme > 65 ans, ou plus jeune en présence de facteurs de risque (tabac, athérome, antécédents familiaux)."},{"t":"Aucun dépistage avant 65 ans, quel que soit le contexte","ok":false,"why":"Le dépistage peut être plus précoce en présence de facteurs de risque."},{"t":"Un scanner injecté de dépistage","ok":false,"why":"Le dépistage repose sur l'échographie abdominale."},{"t":"Une artériographie aortique","ok":false,"why":"L'artériographie n'est pas utile."},{"t":"Un dépistage uniquement en cas de symptômes","ok":false,"why":"L'AAA est le plus souvent asymptomatique, d'où l'intérêt d'un dépistage."}],"explanation":"Dépistage échographique de l'AAA chez l'homme > 65 ans, ou plus jeune en présence de facteurs de risque (tabac, athérome, antécédents familiaux)."},"reveal":"Une échographie abdominale est prescrite à son frère.","src":"p. 183-185","id":"225-case-51-s09"}]}],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":{"id":"225-ff","sections":[{"key":"identite","title":"Carte d'identité flash","src":"p. 167-168, 174, 181, 183, 187","fields":[{"label":"Définition / seuil chiffré","value":"**AOMI** : atteinte athéromateuse entre aorte terminale et artères digitales ; IPS < 0,90 (sévère < 0,70) · **anévrisme** : dilatation focale > 50 % du diamètre d'amont ; AAA : intervention au-delà de 50-55 mm · ischémie aiguë : interruption brutale du flux"},{"label":"Causes reines (2 fréquentes + la plus grave)","value":"**Athérome** : AOMI (tabac, diabète), AAA (tabac, ATCD familiaux) · ischémie aiguë : thrombose in situ (sujet âgé, AOMI) ou embolie sur artères saines (FA) · la plus grave : rupture d'AAA"}]},{"key":"pattern","title":"Le pattern de reconnaissance","src":"p. 167-170, 181, 184","fields":[{"label":"Terrain classique","value":"**AOMI** : homme (pic 60-75 ans ; femme 70-80), 3e localisation de l'athérosclérose · **AAA** : homme > 65 ans, tabac, ATCD familiaux · ischémie aiguë : thrombose = sujet âgé artériopathe ; embolie = sujet plus jeune, artères saines"},{"label":"Triptyque sémiologique","value":"**AOMI** : claudication (crampe du mollet, cède < 5 min ; sévère < 100 m) → douleur de repos → ulcère/gangrène · **ischémie aiguë** : douleur brutale + membre froid livide + pouls abolis · AAA : masse battante expansive para-ombilicale"},{"label":"Mot-clé / signe discriminant","value":"Claudication fessière + troubles de l'érection : syndrome de **Leriche** (aorto-iliaque) · douleur postprandiale + amaigrissement : angor digestif · douleur abdominale intense pauvre en signes + FA : ischémie mésentérique aiguë"}]},{"key":"gravite","title":"Le tri vital & la gravité","src":"p. 168-169, 177-179, 184","fields":[{"label":"Alerte rouge immédiate","value":"**Ischémie aiguë** (nerfs atteints dès 2 h, muscles dès 6-8 h, nécrose cutanée vers 24 h) · **AAA** douloureux ou rompu (douleur abdominale/lombaire ± choc) · ischémie mésentérique aiguë : urgence vitale · ischémie critique : cheville < 50, orteil < 30 mmHg"},{"label":"Score pronostique officiel","value":"**Rutherford** ischémie aiguë : I viable, IIa menaçante, IIb immédiatement menaçante, III irréversible · Leriche-Fontaine (AOMI) : I asymptomatique, II claudication, III douleur de repos, IV ulcération/gangrène · critique : mortalité à 5 ans ≈ 70 %"}]},{"key":"paraclinique","title":"Le paraclinique de certitude","src":"p. 166-167, 170-173, 179-180, 184-185","fields":[{"label":"1re intention en urgence (timing)","value":"**Ischémie aiguë** : diagnostic clinique, aucun examen ne doit retarder l'intervention (écho-doppler seulement si grade I sans déficit neurologique) ; artériographie au bloc ; ECG + coagulation · AAA rompu : scanner ; mésentérique aiguë : angioscanner"},{"label":"Examen qui affirme le diagnostic","value":"**AOMI** : IPS (< 0,90) puis écho-doppler artériel · **AAA** : échographie (dépistage, diamètre, suivi) ; scanner injecté = bilan préthérapeutique · mésentérique chronique : écho-doppler, angioscanner ou angio-IRM"},{"label":"Piège paraclinique à éviter","value":"IPS > 1,40 = **médiacalcose** (diabétique, dialysé) → pression d'orteil · angioscanner/angio-IRM/artériographie seulement si revascularisation · artériographie inutile pour mesurer un AAA"}]},{"key":"orientation","title":"L'aiguillage clinique","src":"p. 179-180, 184-187","fields":[{"label":"Ambulatoire","value":null},{"label":"Hospitalisation conventionnelle","value":null},{"label":"USIC / soins intensifs / réanimation","value":"**Ischémie aiguë** : alerter l'équipe chirurgicale au plus tôt (bloc, revascularisation ; amputation si dépassée) · **AAA** douloureux ou rompu : centre spécialisé de chirurgie vasculaire en urgence · mésentérique aiguë : urgence chirurgicale"}]},{"key":"traitement","title":"Le pack thérapeutique de 1re intention","src":"p. 175-176, 182-183, 185-186","fields":[{"label":"Geste salvateur / conditionnement","value":"**Ischémie aiguë** : héparine non fractionnée dès le diagnostic (bolus 5 000 UI puis 500 UI/kg/j, TCA 2-3) + antalgiques palier 3 ; embolectomie de Fogarty si embolie ; aponévrotomie si revascularisation tardive ; amputation si dépassée"},{"label":"Molécule(s) reine(s) (DCI, voie, dose si cotée)","value":"**AOMI** : antiplaquettaire (aspirine ou clopidogrel) si symptomatique · statine systématique (LDL-C < 0,55 g/L) · IEC/ARA2"},{"label":"Mesure non pharmacologique / étiologique","value":"Arrêt du **tabac**, HbA1c < 7 %, marche 30-45 min ≥ 3×/sem (supervisée) · revascularisation (angioplastie ± stent, pontage) si ischémie permanente ou claudication < 100 m invalidante · **AAA** > 50-55 mm : chirurgie ou endoprothèse"}]},{"key":"securite","title":"Les fautes graves & la sécurité","src":"p. 173, 175, 178-179, 182-183, 186","fields":[{"label":"Contre-indications absolues","value":"Angio-IRM : **gadolinium** contre-indiqué si clairance < 30 mL/min/1,73 m² · angioscanner : vérifier allergies et fonction rénale · bêtabloquant : prudence en ischémie critique non revascularisable"},{"label":"Surveillance non négociable","value":"Après reperfusion : **syndrome de revascularisation** (hyperkaliémie, acidose, myoglobinurie → IRA) : diurèse, ionogramme, urée, créatinine, CPK ; syndrome des loges · AAA traité : écho-doppler/scanner au long cours (endofuites, faux anévrismes)"}]}],"src":"p. 166-187"},"pareto":{"id":"225-pareto","points":[{"id":"225-par-01","rank":"A","cat":"définition","text":"AOMI = atteinte athéromateuse entre l'**aorte terminale et les artères digitales** ; 3e localisation de l'athérosclérose ; FDR principaux : **tabac** + **diabète**","src":"p. 167-168"},{"id":"225-par-02","rank":"A","cat":"examen","text":"IPS (PAS cheville / PAS bras) : **< 0,90** = AOMI, **< 0,70** = sévère ; **> 1,40** = médiacalcose (diabète, dialyse) → pression d'orteil","src":"p. 170-171"},{"id":"225-par-03","rank":"A","cat":"clinique","text":"Claudication = crampe du mollet à la marche, cède en **< 5 min**, sévère si **< 100 m** ; fessière + troubles de l'érection = syndrome de **Leriche** (aorto-iliaque)","src":"p. 168-169"},{"id":"225-par-04","rank":"A","cat":"gravité","text":"Ischémie critique = douleurs de décubitus > 15 j (jambe pendante) ± ulcère/gangrène ; cheville **< 50 mmHg** ou hallux **< 30 mmHg** ; mortalité à 5 ans **≈ 70 %**","src":"p. 169, 171, 178"},{"id":"225-par-05","rank":"A","cat":"examen","text":"1re imagerie = **écho-doppler artériel** ; angioscanner / angio-IRM / artériographie **seulement si revascularisation** ; gadolinium CI si clairance **< 30 mL/min**","src":"p. 172-173"},{"id":"225-par-06","rank":"A","cat":"traitement","text":"AOMI : **arrêt du tabac**, **antiplaquettaire** (aspirine ou clopidogrel) si symptomatique, **statine** (LDL < 0,55 g/L), contrôle diabète/PA (IEC), marche supervisée 3×/sem","src":"p. 175"},{"id":"225-par-07","rank":"A","cat":"traitement","text":"**Revascularisation** (angioplastie ± stent, pontage) si **ischémie permanente** ou claudication sévère invalidante après réadaptation ; **amputation** en dernier recours","src":"p. 176-177"},{"id":"225-par-08","rank":"A","cat":"gravité","text":"Ischémie aiguë = urgence : douleur brutale, membre **froid et livide**, pouls abolis, déficit sensitivomoteur ; **aucun examen ne doit retarder** l'intervention","src":"p. 178-180"},{"id":"225-par-09","rank":"A","cat":"étiologie","text":"Ischémie aiguë : **thrombose in situ** (sujet âgé artériopathe) ou **embolie** sur artères saines (FA, valvulopathie, IDM) → auscultation, **ECG**, palpation abdominale","src":"p. 181-182"},{"id":"225-par-10","rank":"A","cat":"traitement","text":"Ischémie aiguë : **héparine non fractionnée** dès le diagnostic (bolus 5 000 UI, TCA 2-3) + antalgiques niveau 3 ; **embolectomie de Fogarty** si embolie ; amputation si dépassée","src":"p. 182-183"},{"id":"225-par-11","rank":"A","cat":"gravité","text":"Reperfusion : **syndrome de revascularisation** (hyperkaliémie, acidose, myoglobinurie → IRA) et **syndrome des loges** (aponévrotomie) → surveiller diurèse, ionogramme, CPK","src":"p. 178, 183"},{"id":"225-par-12","rank":"A","cat":"définition","text":"AAA = dilatation > **50 %** du diamètre d'amont, sous-rénale ; cause = **athérome** (80-90 %) ; FDR : âge, tabac, ATCD familiaux ; dépistage échographique **homme > 65 ans**","src":"p. 183-184"},{"id":"225-par-13","rank":"A","cat":"chiffre","text":"AAA : rupture selon le diamètre (< 40 mm : 0,4 %/an ; 50-59 : 3 % ; > 60 : **15 %**) ; intervention « à froid » si **> 50-55 mm** ; écho tous les **6 mois** si > 45 mm","src":"p. 184-186"},{"id":"225-par-14","rank":"A","cat":"gravité","text":"**AAA douloureux ou rompu** = urgence absolue : douleur abdominale/lombaire ± choc → centre de chirurgie vasculaire ; seul le **scanner** précède l'intervention ; endoprothèse possible","src":"p. 184-186"},{"id":"225-par-15","rank":"A","cat":"clinique","text":"Ischémie mésentérique : chronique = **angor digestif** (douleur postprandiale, amaigrissement) ; aiguë = douleur + peu de signes + vomissements/diarrhée + FA → **angioscanner**, urgence chirurgicale","src":"p. 166-167"}]},"extra":{"semio":[{"title":"Claudication intermittente et formes atypiques","rank":"A","src":"p. 168-169","content":"L'AOMI reste longtemps **asymptomatique** (circulation collatérale), puis se manifeste à l'effort (**ischémie d'effort**), enfin au repos (**ischémie permanente**).\n\n**Claudication intermittente typique** : **crampe du mollet** à la marche, **cédant en moins de 5 min** à l'arrêt ; **sévère** si distance de marche **< 100 m**.\n\n**Formes atypiques** fréquentes :\n- variabilité de la distance ;\n- localisation **fessière/cuisse** (atteinte **aorto-iliaque**) ;\n- paresthésies, ralentissement du pas.\n\n**Syndrome de Leriche** : atteinte aorto-iliaque + **claudication fessière** + **troubles de l'érection** (et fatigabilité à la marche).\n\n> Une atteinte sévère peut rester **masquée** : collatéralité, comorbidités limitant la marche, **neuropathie**.\n\nL'interrogatoire recherche systématiquement les autres atteintes athéromateuses (**angor, AVC**)."},{"title":"Ischémie permanente (stades III-IV)","rank":"A","src":"p. 169","content":"- **Douleurs de décubitus**, soulagées en **position déclive**.\n- **Ischémie critique** : douleurs durant **plus de 15 jours**, avec **pression de cheville < 50 mmHg** ou **pression d'hallux < 30 mmHg**.\n- **Troubles trophiques** :\n  - peau fine ;\n  - **ulcères aux zones d'appui** ;\n  - **gangrène des orteils**, plus fréquente chez le **diabétique**."},{"title":"Examen physique vasculaire des membres inférieurs","rank":"A","src":"p. 170","content":"Toujours **bilatéral et comparatif** :\n- **Inspection** : couleur, troubles trophiques.\n- **Palpation** : froideur ; pouls **fémoral, poplité, tibial postérieur, pédieux** (le pédieux est **absent congénitalement chez 5 %** des sujets) ; **temps de recoloration cutanée** normalement **< 3 s**.\n- **Auscultation** des trajets vasculaires (souffles).\n- **Palpation abdominale et poplitée** à la recherche d'un **anévrisme**."},{"title":"Ischémie aiguë de membre : tableau clinique","rank":"A","src":"p. 178-179","content":"**Interruption brutale** du flux artériel d'un membre : urgence menaçant le **membre** et le **pronostic vital**.\n\n- **Douleur brutale, intense**, à type de **broiement**, avec **impotence fonctionnelle**.\n- Membre **froid, livide**, **douloureux à la palpation musculaire**.\n- **Pouls abolis** en aval.\n- **Troubles neurologiques** : anesthésie, paralysie, notamment du **nerf fibulaire commun**.\n\n> Occlusion de la **bifurcation aortique** → ischémie **bilatérale** sévère pouvant aller jusqu'au **collapsus**."},{"title":"Ischémie aiguë : thrombose in situ vs embolie","rank":"B","src":"p. 181","content":"| | **Thrombose in situ** | **Embolie sur artère saine** |\n|---|---|---|\n| Terrain | **sujet âgé**, FDR CV, souvent **AOMI préexistante** (à rechercher sur l'autre membre) | **sujet plus jeune**, sans ATCD vasculaire (cardiopathie possible) |\n| Douleur | intensité **moyenne**, installation progressive ou rapide | **brutale, aiguë, sévère**, parfois précédée de **palpitations** |\n| Collatéralité | préalable, développée | **absente** |\n\nLes deux tableaux ne sont pas toujours totalement distincts."},{"title":"Anévrisme de l'aorte abdominale : présentations cliniques","rank":"A","src":"p. 184-185","content":"#### Forme asymptomatique (la plus fréquente)\nDécouverte fortuite : **masse battante et expansive para-ombilicale** (± souffle) à la palpation, ou à l'imagerie.\n\n#### Formes symptomatiques\n- **Fissuration/rupture** : **douleur abdominale ou lombaire** ± **choc hémorragique** ; urgence vitale ; rupture intrapéritonéale souvent **cataclysmique**.\n- **Fistule** : **aorto-cave** → insuffisance cardiaque à **débit élevé** ; **aorto-digestive** → hémorragie digestive.\n- **Embolie** à partir d'une thrombose intra-anévrismale.\n- **Compression** des organes de voisinage.\n- **Syndrome inflammatoire** : fièvre, AEG, élévation VS/CRP."},{"title":"Anévrisme de l'artère poplitée","rank":"A","src":"p. 186","content":"- Associé à un **AAA** dans **≈ 30 %** des cas ; **bilatéral** dans près de **la moitié** des cas.\n- Découverte : **masse battante poplitée**, écho-Doppler systématique (dépistage si AAA ou AP controlatéral connu) ou complication."},{"title":"Ischémies mésentériques chronique et aiguë","rank":"A","src":"p. 166-167","content":"#### Ischémie mésentérique chronique\nSténose du **tronc cœliaque** et/ou des **artères mésentériques**, souvent asymptomatique. Si symptomatique : **angor digestif** :\n- **douleurs abdominales postprandiales** ;\n- **restriction alimentaire** → **amaigrissement**, **dénutrition** ;\n- **souffle abdominal** possible.\n\n#### Ischémie mésentérique aiguë\nOcclusion brutale d'une artère digestive (thrombose in situ ou embolie) ; urgence vitale **rare** grâce aux collatérales. **Triade évocatrice** :\n1. **douleur abdominale aiguë pauvre en signes physiques** ;\n2. **vidange digestive accélérée** (vomissements/diarrhée) ;\n3. **arguments emboligènes** (fibrillation atriale)."},{"title":"Athérome aortique","rank":"A","src":"p. 166","content":"- Plaques pouvant toucher **tous les segments** de l'aorte dès un âge jeune, avec prédilection pour la **bifurcation aortique** et l'**origine des branches** (coronaires, digestives, rénales).\n- **Tabagisme** = facteur le plus associé.\n- Le plus souvent **asymptomatique**, de découverte fortuite à l'imagerie.\n- Complications : **embolies** (cerveau, membres, viscères).\n- Marque un **sur-risque cardiovasculaire global**."}],"criteres":[{"title":"Définition et classifications de l'AOMI","rank":"A","src":"p. 167-168","content":"**AOMI** : toute atteinte **athéromateuse significative** des artères entre l'**aorte terminale** et les **artères digitales**.\n\n| Leriche-Fontaine | Symptômes | Rutherford (grade/catégorie) | Symptômes |\n|---|---|---|---|\n| I | Asymptomatique | 0/0 | Asymptomatique |\n| II | Claudication intermittente | I/1-3 | Claudication légère à sévère |\n| III | Douleur ischémique de repos | II/4 | Douleur ischémique de repos |\n| IV | Ulcération ou gangrène | III/5-6 | Perte de substance faible à majeure |\n\nLa classification de **Rutherford**, plus détaillée, tend à remplacer celle de Leriche-Fontaine."},{"title":"Index de pression systolique (IPS) et pression d'orteil","rank":"A","src":"p. 170-171","content":"**IPS** = pression systolique de **cheville** / pression systolique **brachiale**, au doppler de poche ; examen de **1re intention** devant une suspicion d'AOMI.\n\n| IPS | Interprétation |\n|---|---|\n| **1,00–1,40** | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** → index de pression d'orteil |\n\n- **Index de pression d'orteil** pathologique si **< 0,70** ; **pression d'orteil < 30 mmHg** = ischémie critique.\n- Un IPS abaissé est aussi un **marqueur de risque CV** global."},{"title":"Ischémie critique, test de marche et TcPO2","rank":"A","src":"p. 169-172","content":"**Ischémie critique** : pression de cheville **< 50 mmHg** ou d'hallux/orteil **< 30 mmHg**.\n\n**Test de marche** sur tapis (protocole de **Strandness** : **3,2 km/h**, pente **10 %**) si symptômes avec **IPS de repos normal** ; évocateur d'AOMI si baisse de pression de cheville **> 30 mmHg** ou de l'IPS **> 20 %** après effort. Le **test de marche de 6 min** évalue le handicap fonctionnel global (non spécifique).\n\n**TcPO2** (après hyperémie), utile en ischémie critique :\n\n| TcPO2 (dos du pied) | Interprétation |\n|---|---|\n| > 50 mmHg | normale |\n| > 35 mmHg | bonne compensation |\n| 10–35 mmHg | hypoxie continue |\n| < 10 mmHg | hypoxie critique |"},{"title":"Imagerie de l'AOMI","rank":"A","src":"p. 172-173","content":"- **Échodoppler artériel** : examen de **1re intention** (non invasif, **localise et quantifie** les sténoses).\n- **Angioscanner** et **angio-IRM** (sensibilité/spécificité **≈ 95 %** vs artériographie) : **uniquement en vue d'une revascularisation**.\n  - angio-IRM : gadolinium **contre-indiqué si clairance < 30 mL/min/1,73 m²** ; ne visualise **pas les calcifications** (utiles au chirurgien).\n- **Artériographie** : réservée aux **procédures de revascularisation**, notamment réseau jambier et pédieux."},{"title":"Diagnostics différentiels et étiologiques de l'AOMI","rank":"B","src":"p. 174","content":"#### Différentiels\n- **Douleurs à la marche** : neurologiques (**canal lombaire étroit**, sciatalgie, atteinte médullaire), rhumatologiques (tendinite, arthrose), veineuses (claudication post-thrombotique), piège ou kyste poplité, endofibrose iliaque, syndrome des loges, malformations vasculaires, douleurs musculaires sous **statines**.\n- **Douleurs de décubitus** : neuropathie sensorielle, syndromes douloureux régionaux complexes, compression radiculaire.\n- **Ulcères** : veineux, microcirculatoire, neuropathique, traumatique.\n\n#### Étiologiques\n- **Athérome** : **> 95 %** des artériopathies oblitérantes des MI.\n- Non athéromateuses (rares) : **inflammatoires** (Buerger, Takayasu, Horton, collagénoses), dysplasie fibromusculaire, coarctation, postradiques, post-traumatiques, toxiques (**ergot de seigle**), gelures, compressions extrinsèques, atteintes de l'artère poplitée (piège poplité, kyste sous-adventiciel)."},{"title":"Classification de Rutherford de l'ischémie aiguë (ESC 2024)","rank":"A","src":"p. 179-180","content":"| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate |\n| IIa | Discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Immédiatement menaçante | Présent au-delà des orteils | Modéré | Récupération possible si urgence immédiate |\n| III | Irréversible | Anesthésie importante | Important, paralysie | Perte tissulaire et séquelles inévitables |\n\n**Diagnostic avant tout clinique** : aucune exploration ne doit retarder l'intervention, surtout si **déficit neurologique** (grade II). Échodoppler possible sans perte de temps si grade I sans atteinte neurologique. **Artériographie** le plus souvent **au bloc** pour guider le geste."},{"title":"Bilan étiologique de l'ischémie aiguë","rank":"A","src":"p. 181-182","content":"**Systématique** :\n- auscultation cardiaque, **ECG** ;\n- **palpation abdominale** (anévrisme) ;\n- **bilan de coagulation**.\n\n**Après revascularisation** :\n- **bilan cardiaque** : Holter, ETT ± ETO/IRM ;\n- **bilan artériel** : échodoppler, angioscanner ou artériographie.\n\n**Causes emboliques** [B] : cardiaques (**fibrillation atriale** = principale cause, FOP/anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, anévrisme/dyskinésie du VG) ou aortiques (athérome, anévrisme, aortite, tumeur).\n\n**Causes de thrombose in situ** [B] : AOMI, artériopathies non athéromateuses, anévrisme poplité thrombosé, déshydratation/hémoconcentration du sujet âgé, kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, iatrogènes (cathétérisme, TIH, ergotisme)."},{"title":"Anévrisme : définition, étiologies et diagnostic de l'AAA","rank":"A","src":"p. 183-185","content":"**Anévrisme** : dilatation **localisée et durable** d'une artère, diamètre dépassant de **plus de 50 %** celui du segment sus-jacent, avec **perte du parallélisme** des bords. Sièges (hors cerveau) : **aorte** (surtout **sous-rénale**), **artères poplitées**, **iliaques**.\n\n**Étiologies** [B] : **athérome** dans **80–90 %** ; formes familiales (Marfan, Ehlers-Danlos, Loeys-Dietz) ; aortites (Takayasu, Horton) ; rarement infectieuses (syphilis).\n\n**Dépistage échographique** : homme **> 65 ans**, ou plus jeune si FDR (tabac, athérome, ATCD familiaux).\n\n| Examen | Rôle |\n|---|---|\n| **Échographie abdominale** | dépistage, diamètre maximal, suivi ; recherche localisations poplitées/iliaques |\n| **Scanner abdominopelvien injecté** | **référence préthérapeutique** (diamètre, anatomie) |\n| IRM | alternative si contre-indication au scanner |\n| Artériographie | **pas utile** (lumière circulante seule, sous-estime la taille si thrombus mural) |"},{"title":"Ischémie mésentérique : diagnostic paraclinique","rank":"A","src":"p. 166-167, 187","content":"| | Chronique | Aiguë |\n|---|---|---|\n| Imagerie | **écho-Doppler digestif**, **angioscanner** ou **angio-IRM** ; artériographie seulement pour un geste endovasculaire | **angioscanner** (confirme le diagnostic) |\n| Traitement | **revascularisation** (de préférence endovasculaire) | **résection** des segments infarcis + **revascularisation** (endovasculaire ou chirurgicale) |"}],"chiffres":[{"theme":"Épidémiologie","label":"Rang de l'AOMI parmi les localisations de l'athérosclérose","value":"3e (après cœur et cerveau)","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Pic d'âge de l'AOMI symptomatique chez l'homme","value":"60–75 ans","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Pic d'âge de l'AOMI symptomatique chez la femme","value":"70–80 ans","rank":"A","src":"p. 167"},{"theme":"Épidémiologie","label":"Prévalence de l'AOMI clinique après 60 ans","value":"1–5 %","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Prévalence de l'AOMI (clinique + infraclinique) après 60 ans","value":"10–15 %","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Formes infracliniques pour un cas clinique d'AOMI","value":"2 à 4","rank":"A","src":"p. 168"},{"theme":"Épidémiologie","label":"Part d'origine athéromateuse des artériopathies oblitérantes des MI","value":"> 95 %","rank":"B","src":"p. 174"},{"theme":"Diagnostic","label":"Délai de disparition de la douleur de claudication à l'arrêt","value":"< 5 min","rank":"A","src":"p. 168"},{"theme":"Seuils et définitions","label":"Distance de marche définissant une claudication sévère","value":"< 100 m","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Durée des douleurs de décubitus en ischémie critique","value":"> 15 jours","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Pression de cheville définissant l'ischémie critique","value":"< 50 mmHg","rank":"A","src":"p. 169"},{"theme":"Seuils et définitions","label":"Pression d'hallux/d'orteil définissant l'ischémie critique","value":"< 30 mmHg","rank":"A","src":"p. 169, 171"},{"theme":"Épidémiologie","label":"Absence congénitale du pouls pédieux","value":"5 % des sujets","rank":"A","src":"p. 170"},{"theme":"Examens","label":"Temps de recoloration cutanée normal","value":"< 3 s","rank":"A","src":"p. 170"},{"theme":"Seuils et définitions","label":"IPS normal","value":"1,00 à 1,40","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS diagnostique d'AOMI (au moins une cheville)","value":"< 0,90","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS définissant une AOMI sévère","value":"< 0,70","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"IPS évoquant une médiacalcose","value":"> 1,40","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"Index de pression d'orteil pathologique","value":"< 0,70","rank":"A","src":"p. 171"},{"theme":"Examens","label":"Test de marche de Strandness : vitesse et pente","value":"3,2 km/h ; pente 10 %","rank":"A","src":"p. 171"},{"theme":"Diagnostic","label":"Baisse de pression de cheville après marche évocatrice d'AOMI","value":"> 30 mmHg","rank":"A","src":"p. 171"},{"theme":"Diagnostic","label":"Baisse de l'IPS après marche évocatrice d'AOMI","value":"> 20 %","rank":"A","src":"p. 171"},{"theme":"Examens","label":"Durée du test de marche évaluant le handicap fonctionnel global","value":"6 min","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"TcPO2 normale au dos du pied","value":"> 50 mmHg","rank":"A","src":"p. 171"},{"theme":"Seuils et définitions","label":"TcPO2 de bonne compensation","value":"> 35 mmHg","rank":"A","src":"p. 171-172"},{"theme":"Seuils et définitions","label":"TcPO2 d'hypoxie continue","value":"10–35 mmHg","rank":"A","src":"p. 171-172"},{"theme":"Seuils et définitions","label":"TcPO2 d'hypoxie critique","value":"< 10 mmHg","rank":"A","src":"p. 172"},{"theme":"Examens","label":"Sensibilité/spécificité angioscanner et angio-IRM (vs artériographie)","value":"≈ 95 %","rank":"A","src":"p. 173"},{"theme":"Examens","label":"Clairance contre-indiquant le gadolinium (angio-IRM)","value":"< 30 mL/min/1,73 m²","rank":"A","src":"p. 172-173"},{"theme":"Traitement","label":"Cible d'HbA1c chez l'AOMI","value":"< 7 %","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible tensionnelle chez l'AOMI","value":"PAS 120–129 ; PAD 70–79 mmHg","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible de PA mentionnée avec l'IEC chez l'AOMI","value":"< 140/90 mmHg","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible de LDL-cholestérol chez l'AOMI","value":"< 0,55 g/L (< 1,4 mmol/L)","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Réduction minimale du LDL-c sous statine","value":"≥ 50 %","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Cible d'IMC chez l'AOMI","value":"20–25 kg/m²","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Réentraînement à la marche (traitement général)","value":"3 fois/semaine pendant 12 semaines","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Marche régulière (traitement local)","value":"30–45 min, ≥ 3 fois/semaine","rank":"A","src":"p. 175"},{"theme":"Traitement","label":"Périmètre de marche pour discuter une revascularisation (claudication)","value":"< 100 m","rank":"A","src":"p. 176"},{"theme":"Traitement","label":"Durée de la bithérapie antiplaquettaire après angioplastie","value":"1 à 6 mois","rank":"A","src":"p. 176"},{"theme":"Pronostic","label":"Réduction de l'espérance de vie du claudicant","value":"≈ 10 ans","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Complications CV à 5 ans chez le claudicant","value":"20 %","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Décès à 5 ans chez le claudicant","value":"20 % (pour moitié CV)","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Aggravation locale à 5 ans chez le claudicant","value":"25 % (dont 1/5 d'amputation majeure)","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Risque d'amputation à 5 ans chez le claudicant","value":"≈ 5 %","rank":"A","src":"p. 177"},{"theme":"Pronostic","label":"Mortalité à 5 ans en ischémie critique","value":"≈ 70 %","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : délai de souffrance des cellules nerveuses","value":"dès 2 h","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : délai de souffrance musculaire (rhabdomyolyse)","value":"dès 6–8 h","rank":"A","src":"p. 178"},{"theme":"Pronostic","label":"Ischémie aiguë : apparition de la nécrose cutanée","value":"vers la 24e heure","rank":"A","src":"p. 178"},{"theme":"Seuils et définitions","label":"Nombre de grades de Rutherford (ischémie aiguë)","value":"4 : I, IIa, IIb, III","rank":"A","src":"p. 179"},{"theme":"Doses","label":"Bolus d'héparine non fractionnée en ischémie aiguë","value":"5000 UI","rank":"A","src":"p. 182"},{"theme":"Doses","label":"Perfusion continue d'HNF en ischémie aiguë","value":"500 UI/kg/j","rank":"A","src":"p. 182"},{"theme":"Surveillance","label":"Cible de TCA sous HNF en ischémie aiguë","value":"entre 2 et 3","rank":"A","src":"p. 182"},{"theme":"Traitement","label":"Palier d'antalgiques souvent nécessaire en ischémie aiguë","value":"palier 3","rank":"A","src":"p. 182"},{"theme":"Seuils et définitions","label":"Dilatation définissant un anévrisme","value":"augmentation de diamètre > 50 % par rapport au segment sus-jacent","rank":"A","src":"p. 183"},{"theme":"Épidémiologie","label":"Prévalence de l'AAA chez l'homme > 65 ans","value":"2–5 %","rank":"A","src":"p. 183"},{"theme":"Épidémiologie","label":"Prévalence de l'AAA entre 75 et 84 ans","value":"5 % (homme) ; 3 % (femme)","rank":"A","src":"p. 183-184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA < 40 mm","value":"≈ 0,4 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA de 50–59 mm","value":"3 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque annuel de rupture d'AAA > 60 mm","value":"15 %/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque de rupture chez la femme à diamètre égal","value":"≈ 4 fois plus élevé","rank":"A","src":"p. 184"},{"theme":"Épidémiologie","label":"Décès par rupture d'AAA en Europe","value":"≈ 12 000/an","rank":"A","src":"p. 184"},{"theme":"Pronostic","label":"Risque de décès CV du porteur d'AAA vs risque de rupture","value":"10 fois supérieur","rank":"A","src":"p. 184"},{"theme":"Épidémiologie","label":"Part des AAA sur terrain athéromateux","value":"80–90 %","rank":"B","src":"p. 184"},{"theme":"Diagnostic","label":"Âge du dépistage échographique de l'AAA chez l'homme","value":"> 65 ans (plus jeune si FDR)","rank":"A","src":"p. 184-185"},{"theme":"Pronostic","label":"Croissance moyenne d'un AAA","value":"2–4 mm/an","rank":"B","src":"p. 185-186"},{"theme":"Pronostic","label":"Accélération de la progression de l'AAA par tabagisme actif","value":"≈ 3 fois plus rapide","rank":"B","src":"p. 185-186"},{"theme":"Surveillance","label":"Diamètre d'AAA imposant une surveillance échographique renforcée","value":"> 45 mm","rank":"B","src":"p. 185-186"},{"theme":"Surveillance","label":"Rythme de surveillance renforcée de l'AAA","value":"tous les 6 mois","rank":"B","src":"p. 185-186"},{"theme":"Traitement","label":"Seuil de diamètre pour une intervention « à froid » sur AAA","value":"50–55 mm","rank":"B","src":"p. 185-186"},{"theme":"Épidémiologie","label":"Association anévrisme poplité – AAA","value":"≈ 30 %","rank":"A","src":"p. 185-187"},{"theme":"Épidémiologie","label":"Bilatéralité de l'anévrisme poplité","value":"près de la moitié des cas","rank":"A","src":"p. 185-187"}],"physio":[{"theme":"Mécanismes","title":"AOMI : de l'ischémie d'effort à l'ischémie permanente","rank":"A","src":"p. 167-170","content":"1. Lésions **athéromateuses** comparables aux autres territoires (tabac et diabète = principaux FDR ; diabète → formes plus **distales** et graves).\n2. Développement d'une **circulation collatérale** → longue phase **asymptomatique**.\n3. À l'effort, apport insuffisant → **ischémie d'effort** : **claudication intermittente**.\n4. Stade avancé : apport insuffisant même au repos → **ischémie permanente** : douleurs de **décubitus** (soulagées en position **déclive**), puis **troubles trophiques**.\n\nLa collatéralité, une comorbidité limitant la marche ou une **neuropathie** peuvent masquer une atteinte sévère."},{"theme":"Mécanismes","title":"Ischémie aiguë : déterminants de gravité et chronologie","rank":"A","src":"p. 178","content":"**Gravité** selon : **PA systémique**, abondance de la **collatéralité**, qualité du **lit d'aval**.\n\n**Chronologie des lésions** :\n1. **Nerfs** : souffrance **dès 2 h** (→ troubles sensitivomoteurs).\n2. **Muscles** : souffrance **dès 6–8 h** (**rhabdomyolyse**).\n3. **Peau** : **nécrose** vers la **24e heure**.\n\nThrombose in situ : douleur moins intense grâce à la collatéralité préalable ; embolie sur artère saine : douleur brutale et sévère (pas de collatérales)."},{"theme":"Conséquences","title":"Syndrome des loges et syndrome de revascularisation","rank":"A","src":"p. 178, 182-183","content":"#### Syndrome des loges\n**Œdème musculaire** dans des **loges aponévrotiques inextensibles** → compression → **syndrome des loges**, traité par **aponévrotomie de décharge** (systématique si revascularisation tardive, loge antéro-externe de jambe en général).\n\n#### Syndrome de revascularisation\nÀ la reperfusion, **relargage d'acides et de radicaux libres** :\n- **hyperkaliémie**, **acidose métabolique** ;\n- hyperuricémie, **myoglobinémie/myoglobinurie** ;\n- hypocalcémie, hyperphosphorémie ;\n- voire **CIVD** ;\n- **IRA** (nécrose tubulaire).\n\n**Prise en charge** : sonde urinaire (diurèse), ionogramme, urée, créatininémie, **CPK** ; **bicarbonates IV** ; hyperkaliémie → **polystyrène sulfonate de sodium**, voire **dialyse** ; lavage de membre au sérum physiologique."},{"theme":"Mécanismes","title":"Formation de l'anévrisme","rank":"A","src":"p. 183","content":"- La **média** perd sa **résistance à la distension** :\n  - **destruction des fibres élastiques** ;\n  - **fragmentation du collagène** ;\n  - sous l'effet d'enzymes comme les **métalloprotéases**.\n- Résultat : dilatation **localisée et durable** (diamètre dépassant de > 50 % celui du segment sus-jacent) avec **perte du parallélisme** des bords."},{"theme":"Histoire naturelle","title":"Histoire naturelle de l'AAA","rank":"B","src":"p. 184-186","content":"- Le **diamètre** est le **principal facteur prédictif** du risque de rupture.\n- Croissance moyenne **2–4 mm/an**, variable ; plus rapide chez l'**homme fumeur** avec un anévrisme déjà volumineux (tabagisme actif : **≈ 3 fois** plus rapide).\n- Risque annuel de rupture : **≈ 0,4 %** (< 40 mm), **3 %** (50–59 mm), **15 %** (> 60 mm) ; **≈ 4 fois** plus élevé chez la **femme** à diamètre égal.\n- Le porteur d'AAA a un risque de **décès CV** (coronaire, AVC) **10 fois** supérieur à celui de rupture → contrôle des FDR indispensable.\n- Thrombose intra-anévrismale → **embolies** ; après endoprothèse, les **endofuites** peuvent faire **progresser voire rompre** l'anévrisme."},{"theme":"Mécanismes","title":"Athérome rénal et digestif","rank":"A","src":"p. 166-167","content":"- **Artères rénales** : athérome → **HTA rénovasculaire** par **activation du SRAA**.\n- **Artères digestives** : sténose chronique → apport insuffisant lors de la digestion → **angor digestif** postprandial → restriction alimentaire, amaigrissement.\n- Occlusion brutale (thrombose ou embolie) → **ischémie mésentérique aiguë**, **rare** grâce aux **collatérales** ; évolution vers la **nécrose**."}],"parcours":[{"title":"AOMI : de la claudication à la revascularisation","rank":"A","patient":"M. L., 66 ans, fumeur, diabétique de type 2, consulte pour une crampe du mollet gauche apparaissant après environ 150 m de marche et cédant en 2 minutes à l'arrêt. Il est traité pour une HTA et n'a jamais eu d'exploration vasculaire.","steps":[{"phase":"Interrogatoire","title":"Caractériser la douleur de marche","question":"Le patient décrit une douleur du mollet à la marche. Que recherches-tu à l'interrogatoire ?","answer":"**Claudication intermittente** typique : **crampe du mollet à la marche**, cédant en **moins de 5 minutes** à l'arrêt ; **sévère** si distance de marche **< 100 m**.\n\n**Formes atypiques fréquentes** : variabilité, localisation **fessière/cuisse** (atteinte aorto-iliaque), paresthésies, ralentissement du pas.\n\n**Syndrome de Leriche** : atteinte **aorto-iliaque** + **claudication fessière** + **troubles de l'érection**.\n\n**Ischémie permanente** (stades III-IV) : **douleurs de décubitus soulagées en position déclive** ; troubles trophiques (peau fine, ulcères aux zones d'appui, gangrène des orteils).\n\n**Terrain** : **tabagisme** et **diabète** (2 principaux FDR), hypercholestérolémie, HTA.\n\n**Autres localisations athéromateuses** à rechercher **systématiquement** : angor, AVC.","cas":[{"si":"Si claudication fessière avec troubles de l'érection","alors":"**Syndrome de Leriche** (atteinte aorto-iliaque)."},{"si":"Si comorbidités limitant la marche ou neuropathie","alors":"Une atteinte sévère peut rester **masquée** (collatéralité, absence de marche, neuropathie)."},{"si":"Si douleurs abdominales postprandiales avec restriction alimentaire et amaigrissement","alors":"Évoquer un **angor digestif** (ischémie mésentérique chronique) : écho-Doppler digestif, angioscanner ou angio-IRM ; revascularisation (de préférence endovasculaire)."}],"pieges":["Éliminer une AOMI devant une claudication atypique (fessière, variable, paresthésies).","Conclure à l'absence d'AOMI sévère chez un patient qui ne marche pas ou neuropathe."],"src":"p. 166, 168-170"},{"phase":"Diagnostic positif","title":"Définir et classer l'AOMI","question":"Comment définis-tu l'AOMI et comment classes-tu sa sévérité clinique ?","answer":"**AOMI** = atteinte **athéromateuse significative** des artères entre l'**aorte terminale** et les **artères digitales** ; **3e localisation** de l'athérosclérose (après cœur et cerveau). Prévalence clinique **1–5 %** après 60 ans, **10–15 %** en incluant les formes infracliniques (2 à 4 infracliniques pour 1 clinique → **dépistage ciblé**).\n\n| Leriche-Fontaine | Symptômes | Rutherford (grade/catégorie) | Symptômes |\n|---|---|---|---|\n| I | Asymptomatique | 0/0 | Asymptomatique |\n| II | Claudication intermittente | I/1-3 | Claudication légère à sévère |\n| III | Douleur ischémique de repos | II/4 | Douleur ischémique de repos |\n| IV | Ulcération ou gangrène | III/5-6 | Perte de substance faible à majeure |\n\n**Ischémie d'effort** (stade II) puis **ischémie permanente** (stades III-IV).\n\n**Ischémie critique** : douleurs de décubitus **> 15 jours** avec **pression de cheville < 50 mmHg** ou **d'hallux < 30 mmHg**.","cas":[{"si":"Si patient diabétique","alors":"Formes **plus distales et plus graves** ; gangrène des orteils plus fréquente."}],"pieges":["Confondre les stades de Leriche-Fontaine et les catégories de Rutherford."],"src":"p. 167-170"},{"phase":"Examen clinique","title":"Examen vasculaire","question":"Comment conduis-tu l'examen physique ?","answer":"Examen **toujours bilatéral et comparatif** :\n\n- **inspection** : couleur, troubles trophiques ;\n- **palpation** : froideur ; pouls **fémoral, poplité, tibial postérieur, pédieux** ; **temps de recoloration cutanée** (normal **< 3 s**) ;\n- **auscultation** des trajets vasculaires (souffles) ;\n- **palpation abdominale et poplitée** à la recherche d'un **anévrisme**.","cas":[{"si":"Si pouls pédieux absent isolément","alors":"Il peut être **congénitalement absent chez 5 %** des sujets."}],"pieges":["Conclure à une AOMI sur la seule absence du pouls pédieux.","Oublier la palpation abdominale et poplitée (anévrisme associé)."],"src":"p. 170"},{"phase":"Examens complémentaires","title":"Index de pression systolique et tests fonctionnels","question":"Quel examen fais-tu en 1re intention pour confirmer l'AOMI et comment l'interprètes-tu ?","answer":"**IPS** = pression systolique de **cheville** / pression systolique **brachiale**, au **doppler de poche** — **examen de 1re intention**.\n\n| IPS | Interprétation |\n|---|---|\n| 1,00–1,40 | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** → index de pression d'orteil (pathologique si **< 0,70** ; pression d'orteil **< 30 mmHg** = ischémie critique) |\n\nL'IPS abaissé est aussi un **marqueur de risque CV global**.\n\n**Test de marche** (tapis roulant, **Strandness** : **3,2 km/h, pente 10 %**) si symptômes avec IPS de repos normal : baisse de pression de cheville **> 30 mmHg** ou de l'IPS **> 20 %** après effort = évocatrice d'AOMI. Le **test de marche de 6 minutes** évalue le handicap fonctionnel global (non spécifique).\n\n**TcPO2** (utile en ischémie critique) : normale **> 50 mmHg** au dos du pied ; > 35 = bonne compensation ; 10–35 = hypoxie continue ; **< 10 = hypoxie critique**.","cas":[{"si":"Si IPS > 1,40","alors":"**Médiacalcose** : utiliser l'**index de pression d'orteil**."},{"si":"Si symptômes typiques mais IPS de repos normal","alors":"**Test de marche** sur tapis roulant."}],"pieges":["Rassurer sur un IPS élevé > 1,40 : il traduit des artères incompressibles, pas l'absence d'AOMI.","Écarter une AOMI sur un IPS de repos normal chez un symptomatique sans test de marche."],"src":"p. 171-172"},{"phase":"Examens complémentaires","title":"Imagerie artérielle","question":"Quelle imagerie demandes-tu, et quand ?","answer":"- **Échodoppler artériel** : examen d'imagerie de **1re intention** (non invasif, **localise et quantifie** les sténoses).\n- **Angioscanner** et **angio-IRM** (sensibilité/spécificité **≈ 95 %** vs artériographie) : **uniquement en vue d'une revascularisation**.\n  - angio-IRM : gadolinium **contre-indiqué si clairance < 30 mL/min/1,73 m²** ; ne visualise pas les **calcifications**, utiles au chirurgien.\n- **Artériographie** : réservée aux **procédures de revascularisation**, notamment pour le réseau jambier et pédieux.","cas":[{"si":"Si insuffisance rénale sévère (clairance < 30 mL/min/1,73 m²)","alors":"**Pas de gadolinium** (angio-IRM)."},{"si":"Si projet de revascularisation","alors":"Angioscanner ou angio-IRM ; artériographie lors du geste."}],"pieges":["Demander un angioscanner en 1re intention chez un claudicant sans projet de revascularisation.","Demander une artériographie diagnostique."],"src":"p. 172-173"},{"phase":"Diagnostic différentiel","title":"Diagnostics différentiels [B]","question":"Quels diagnostics différentiels évoques-tu selon le tableau ?","answer":"| Tableau | Diagnostics différentiels |\n|---|---|\n| **Douleurs à la marche** | neurologique (**canal lombaire étroit**, sciatalgie, atteinte médullaire), rhumatologique (tendinite, arthrose), veineuse (claudication post-thrombotique), piège ou kyste poplité, endofibrose iliaque, syndrome des loges, malformations vasculaires, **douleurs musculaires sous statines** |\n| **Douleurs de décubitus** | neuropathie sensorielle, syndromes douloureux régionaux complexes, compression radiculaire |\n| **Ulcères** | veineux, microcirculatoire, neuropathique, traumatique |","cas":[],"pieges":["Oublier les myalgies sous statines chez un patient déjà traité."],"src":"p. 174"},{"phase":"Diagnostic étiologique","title":"Cause de l'artériopathie [B]","question":"L'AOMI est-elle forcément athéromateuse ? Quand évoques-tu une autre cause ?","answer":"- Origine **athéromateuse** : **> 95 %** des artériopathies oblitérantes des membres inférieurs.\n- Artériopathies **non athéromateuses** (rares) : **inflammatoires** (Buerger, Takayasu, Horton, collagénoses), **dysplasie fibromusculaire**, **coarctation de l'aorte**, atteintes **postradiques**, **post-traumatiques**, **toxiques** (dérivés de l'ergot de seigle), **gelures**, **compressions extrinsèques**, atteintes spécifiques de l'artère poplitée (**piège poplité**, **kyste sous-adventiciel**).","cas":[{"si":"Si sujet jeune sans facteur de risque cardiovasculaire","alors":"Évoquer une **artériopathie non athéromateuse** (inflammatoire, piège poplité, kyste adventiciel, dysplasie…)."}],"pieges":[],"src":"p. 174"},{"phase":"Évaluation du risque / pronostic","title":"Pronostic de l'AOMI","question":"Quel est le pronostic de ce patient claudicant ?","answer":"Pronostic **grave**, comparable à certains cancers en ischémie permanente.\n\n**Chez le claudicant** :\n\n- espérance de vie réduite d'**environ 10 ans** ;\n- à 5 ans : **20 %** de complications CV, **20 %** de décès (pour moitié CV), **25 %** d'aggravation locale (dont 1/5 d'amputation majeure), **≈ 5 %** de risque d'amputation.\n\n**En ischémie critique** : mortalité à 5 ans **≈ 70 %**.\n\nUn **IPS abaissé** est un marqueur de **risque CV global** : l'AOMI impose de rechercher les autres localisations athéromateuses (angor, AVC).","cas":[],"pieges":["Réduire l'AOMI à un problème de membre : le pronostic est d'abord cardiovasculaire."],"src":"p. 171, 177-178"},{"phase":"Traitement spécifique","title":"Traitement à visée générale","question":"Quel traitement de fond prescris-tu, avec quelles cibles ?","answer":"**Contrôle des facteurs de risque (tous les stades)** :\n\n| Cible | Objectif |\n|---|---|\n| Tabac | **arrêt** |\n| Diabète | **HbA1c < 7 %** |\n| PA | **PAS 120–129**, **PAD 70–79 mmHg** |\n| LDL-C | **< 0,55 g/L (< 1,4 mmol/L)** avec réduction **≥ 50 %** sous **statine** systématique |\n| Poids | IMC **20–25 kg/m²** |\n| Mode de vie | régime méditerranéen ; réentraînement **3 fois/semaine pendant 12 semaines** |\n\n**Antithrombotiques** :\n\n- **antiplaquettaire** (**aspirine ou clopidogrel**) chez **tout AOMI symptomatique** ; discuté si asymptomatique isolée ;\n\n**Autres** :\n\n- **IEC** : utile sur le plan pronostique (cible PA < 140/90 mmHg) ;\n- **bêtabloquants** possibles si indication formelle (cardiopathie ischémique, insuffisance cardiaque), **prudence en ischémie critique non revascularisable**.","cas":[{"si":"Si AOMI asymptomatique isolée","alors":"Antiplaquettaire **discuté** (non systématique)."},{"si":"Si ischémie critique non revascularisable","alors":"**Prudence** avec les bêtabloquants."}],"pieges":["Contre-indiquer les bêtabloquants chez tout artériopathe : ils restent possibles si indication formelle."],"src":"p. 175"},{"phase":"Traitement spécifique","title":"Traitement à visée locale","question":"Quel traitement proposes-tu pour améliorer la marche ?","answer":"- **Arrêt du tabac** et **marche régulière** : **30–45 min, ≥ 3 fois/semaine**, idéalement en **réadaptation supervisée** + **éducation thérapeutique**.\n- **Traitements vasoactifs** (ex. pentoxifylline) : bénéfice **modeste** sur le périmètre de marche, **sans effet pronostique**.\n- **Prostaglandines** : possibles en **ischémie critique non revascularisable**.","cas":[],"pieges":["Compter sur un vasoactif pour améliorer le pronostic : il n'a aucun effet pronostique."],"src":"p. 175-176"},{"phase":"Traitement spécifique","title":"Revascularisation","question":"Quand et comment revascularises-tu ?","answer":"**Indications** :\n\n- **systématiquement proposée** en cas d'**ischémie permanente** ;\n- **discutée** en cas de **claudication sévère invalidante** (périmètre **< 100 m**), notamment **après échec du traitement médical** bien conduit.\n\n**Techniques** :\n\n| Lésion | Technique |\n|---|---|\n| Courte / proximale | **angioplastie endovasculaire** (± stent) + **bithérapie antiplaquettaire 1–6 mois** |\n| Étendue | **chirurgie** : pontage veineux ou prothétique, endartériectomie |\n\nTechniques **hybrides** possibles. **Surveillance clinique et écho-Doppler systématique** après le geste.\n\n**Soins de plaies** multidisciplinaires ; **amputation** en **dernier recours** (zone saine et bien oxygénée, guidée par la **TcPO2**).","cas":[{"si":"Si ischémie permanente (stade III-IV)","alors":"**Revascularisation systématiquement proposée**."},{"si":"Si claudication non invalidante","alors":"Traitement médical et réadaptation d'abord ; revascularisation discutée seulement si claudication sévère invalidante."}],"pieges":["Revasculariser d'emblée une claudication non invalidante.","Choisir le niveau d'amputation sans évaluation de l'oxygénation (TcPO2)."],"src":"p. 176"},{"phase":"Complications","title":"Complications évolutives","question":"Quelles complications peuvent survenir au cours de l'évolution ?","answer":"- **Aggravation locale** : passage à l'**ischémie permanente** (douleurs de décubitus, troubles trophiques, gangrène) ; amputation.\n- **Ischémie aiguë** de membre par **thrombose in situ** sur AOMI préexistante (cf. parcours ischémie aiguë).\n- **Complications cardiovasculaires** : 20 % à 5 ans chez le claudicant (coronaires, AVC).\n- **Embolies** à partir de plaques d'**athérome aortique** (cerveau, membres, viscères).","cas":[{"si":"Si aggravation brutale avec membre froid, douloureux, pouls abolis","alors":"**Ischémie aiguë** → urgence vasculaire, héparine et avis chirurgical."},{"si":"Si douleur abdominale aiguë pauvre en signes physiques","alors":"Évoquer une **ischémie mésentérique aiguë** (angioscanner)."}],"pieges":[],"src":"p. 166, 177, 181"},{"phase":"Suivi","title":"Éducation et suivi","question":"Quels messages délivres-tu et comment organises-tu le suivi ?","answer":"- **Éducation thérapeutique** : arrêt du tabac, marche régulière (30–45 min, ≥ 3 fois/semaine), idéalement en réadaptation supervisée.\n- Contrôle des cibles : HbA1c, PA, LDL-C.\n- Après revascularisation : **surveillance clinique et écho-Doppler systématique**.\n- Rechercher les autres localisations athéromateuses (angor, AVC).","cas":[],"pieges":[],"src":"p. 170, 175-176"}]},{"title":"Ischémie aiguë de membre inférieur","rank":"A","patient":"M. R., 74 ans, en fibrillation atriale non anticoagulée, est adressé par le SAMU pour une douleur brutale et intense du membre inférieur droit apparue il y a 3 heures. Le pied est froid et pâle, et il ne peut plus le mobiliser normalement.","steps":[{"phase":"Accueil & gravité","title":"Reconnaître l'urgence","question":"Quelle est ta première impression et pourquoi l'horloge compte-t-elle ?","answer":"**Ischémie aiguë de membre** = **interruption brutale du flux artériel** d'un membre : **urgence vasculaire** menaçant le **membre** et le **pronostic vital**.\n\n**Chronologie** :\n\n- cellules **nerveuses** : souffrent **dès 2 h** ;\n- cellules **musculaires** : **dès 6–8 h** (rhabdomyolyse) ;\n- **nécrose cutanée** : vers la **24e heure**.\n\n**Gravité** dépendant de : PA systémique, abondance de la **collatéralité**, qualité du **lit d'aval**.","cas":[{"si":"Si occlusion de la bifurcation aortique","alors":"Ischémie **bilatérale sévère**, pouvant aller jusqu'au **collapsus**."}],"pieges":["Temporiser devant une ischémie aiguë : chaque heure compte."],"src":"p. 178"},{"phase":"Examen clinique","title":"Diagnostic clinique","question":"Quels signes cliniques recherches-tu ?","answer":"- **Douleur brutale intense** à type de **broiement** avec **impotence fonctionnelle** ;\n- membre **froid**, **livide**, **douloureux à la palpation musculaire** ;\n- **pouls abolis en aval** ;\n- **troubles neurologiques** : **anesthésie**, **paralysie**, notamment du **nerf fibulaire commun**.\n\nExamen **bilatéral** : rechercher une AOMI sur l'autre membre (orientation vers une thrombose in situ).","cas":[],"pieges":["Négliger l'examen neurologique du membre : c'est lui qui détermine le degré d'urgence."],"src":"p. 179-181"},{"phase":"Évaluation du risque / pronostic","title":"Classer la sévérité (Rutherford)","question":"Comment classes-tu la sévérité de cette ischémie ?","answer":"**Classification de Rutherford** (ESC 2024) :\n\n| Grade | Catégorie | Déficit sensitif | Déficit moteur | Pronostic |\n|---|---|---|---|---|\n| I | Viable | Absent | Absent | Pas de menace immédiate |\n| IIa | Discrètement menaçante | Absent ou limité aux orteils | Absent | Récupérable si prise en charge |\n| IIb | Immédiatement menaçante | Au-delà des orteils | Modéré | Récupération possible si urgence immédiate |\n| III | Irréversible | Anesthésie importante | Important, paralysie | Perte tissulaire et séquelles inévitables |","cas":[{"si":"Si grade IIb","alors":"**Urgence immédiate** : aucun examen ne doit retarder la revascularisation."},{"si":"Si grade III (ischémie dépassée)","alors":"**Amputation d'emblée**."}],"pieges":["Retarder la revascularisation d'un grade II pour réaliser une imagerie."],"src":"p. 179-180, 182"},{"phase":"Examens complémentaires","title":"Place des examens","question":"Quels examens demandes-tu avant l'intervention ?","answer":"Diagnostic **purement clinique** : **aucune exploration ne doit retarder l'intervention**, surtout en cas de **déficit neurologique** (grade II).\n\n- **Échodoppler** : possible **sans perte de temps** si le tableau le permet (**grade I sans atteinte neurologique**).\n- **Artériographie** : le plus souvent **au bloc** pour guider le geste (localisation, aspect de l'occlusion, qualité du réseau d'aval) et dépister d'autres emboles.\n\n**Bilan étiologique initial systématique** : **auscultation cardiaque**, **ECG**, **palpation abdominale** (anévrisme), **bilan de coagulation**.","cas":[{"si":"Si grade I sans déficit neurologique","alors":"**Échodoppler** réalisable sans retarder la prise en charge."},{"si":"Si déficit neurologique","alors":"**Bloc** sans exploration préalable ; artériographie peropératoire."}],"pieges":["Demander un angioscanner qui retarde le geste chez un patient avec déficit neurologique."],"src":"p. 180-181"},{"phase":"Diagnostic étiologique","title":"Thrombose ou embolie ?","question":"Quels éléments orientent vers une thrombose in situ ou une embolie ?","answer":"| | **Thrombose in situ** | **Embolie sur artère saine** |\n|---|---|---|\n| Terrain | **sujet âgé**, FDR CV, souvent **AOMI préexistante** (à rechercher sur l'autre membre) | **sujet plus jeune**, sans ATCD vasculaire (cardiopathie possible) |\n| Douleur | intensité **moyenne**, installation progressive ou rapide (collatéralité préalable) | **brutale, aiguë, sévère** (absence de collatérales), parfois précédée de **palpitations** |\n| Causes | AOMI, artériopathies non athéromateuses, **anévrisme poplité thrombosé**, déshydratation/hémoconcentration du sujet âgé, kyste adventiciel, dissection aorto-iliaque, thrombophlébite ischémique, coagulopathies, iatrogènes (cathétérisme, **thrombopénie à l'héparine**, ergotisme) | **cardiaques** : **fibrillation atriale**, FOP/anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, myxome, anévrisme/dyskinésie du VG ; **aortiques** : athérome, anévrisme, aortite, tumeur |\n\nLes deux tableaux ne sont **pas toujours totalement distincts**.","cas":[{"si":"Si fibrillation atriale","alors":"Principale cause cardiaque d'**embolie** artérielle des membres."},{"si":"Si anévrisme poplité connu","alors":"Ischémie aiguë par **thrombose** de l'anévrisme poplité (cause de thrombose in situ)."}],"pieges":["Méconnaître une thrombopénie à l'héparine chez un patient sous héparine qui fait une ischémie aiguë."],"src":"p. 181"},{"phase":"Traitement en urgence","title":"Traitement médical immédiat","question":"Que prescris-tu immédiatement, avant la revascularisation ?","answer":"- **Héparine non fractionnée** dès le diagnostic, **après le prélèvement du bilan de coagulation** :\n  - **bolus 5 000 UI** ;\n  - puis **perfusion continue 500 UI/kg/j** ;\n  - **TCA cible entre 2 et 3**.\n- **Antalgiques de palier 3** (souvent nécessaires).\n- **Oxygénothérapie**.\n- **Correction hémodynamique** (remplissage).\n- **Soins locaux** immédiats : **protection**, position **légèrement déclive** (y compris après revascularisation).","cas":[],"pieges":["Débuter l'héparine avant d'avoir prélevé le bilan de coagulation.","Surélever le membre ischémique : la position doit être légèrement déclive."],"src":"p. 182"},{"phase":"Traitement spécifique","title":"Revascularisation","question":"Quelle technique de revascularisation choisis-tu ?","answer":"Adaptée au **grade de sévérité** et au mécanisme :\n\n- **Embolectomie à la sonde de Fogarty** sous contrôle angiographique : **méthode de référence** pour l'**embolie sur artère saine** (utilisable aussi sur artère athéromateuse).\n- **Thrombolyse in situ / thromboaspiration** : si **lit d'aval de mauvaise qualité** et **ischémie peu sévère** (surveillance spécialisée, contrôles angiographiques répétés).\n- **Angioplastie complémentaire** si sténose résiduelle ; **pontage** (souvent distal) en **dernier recours**.\n- **Aponévrotomie de décompression** (loge antéro-externe de jambe en général) **systématique** en cas de **revascularisation tardive** (prévention du syndrome des loges).\n- **Amputation** : **d'emblée** si ischémie dépassée ; **secondairement** si échec de revascularisation ou désordres métaboliques majeurs.","cas":[{"si":"Si embolie sur artère saine (ex. FA)","alors":"**Embolectomie par sonde de Fogarty**."},{"si":"Si lit d'aval de mauvaise qualité et ischémie peu sévère","alors":"**Thrombolyse in situ / thromboaspiration**."},{"si":"Si revascularisation tardive","alors":"**Aponévrotomie de décompression** systématique."},{"si":"Si ischémie aiguë par embolie à partir d'un AAA","alors":"**Revascularisation du membre en urgence** ; la cure de l'AAA est **secondaire**."}],"pieges":["Proposer une thrombolyse in situ à une ischémie sévère avec déficit neurologique.","Oublier l'aponévrotomie après une revascularisation tardive."],"src":"p. 182-183, 186"},{"phase":"Complications","title":"Syndrome des loges et syndrome de revascularisation","question":"Quelles complications crains-tu autour de la revascularisation ?","answer":"**Syndrome des loges** : l'**œdème musculaire** dans les loges aponévrotiques inextensibles peut aboutir à un syndrome des loges → traitement par **aponévrotomie de décharge** (prévention : aponévrotomie systématique si revascularisation tardive).\n\n**Syndrome de revascularisation** (relargage d'acides et de radicaux libres à la reperfusion) :\n\n- **hyperkaliémie** ;\n- **acidose métabolique** ;\n- hyperuricémie ;\n- **myoglobinémie / myoglobinurie** ;\n- hypocalcémie, hyperphosphorémie ;\n- voire **CIVD** ;\n- **insuffisance rénale aiguë** (nécrose tubulaire).","cas":[{"si":"Si désordres métaboliques majeurs","alors":"Envisager une **amputation secondaire**."}],"pieges":["Oublier que le danger métabolique survient à la reperfusion, après le geste."],"src":"p. 178, 182-183"},{"phase":"Hospitalisation & surveillance","title":"Surveillance et correction métabolique","question":"Comment surveilles-tu le patient après revascularisation ?","answer":"- **Diurèse** (sonde urinaire) ;\n- **ionogramme**, **urée**, **créatininémie**, **CPK** ;\n- correction de l'**acidose** : **bicarbonates IV** ;\n- correction de l'**hyperkaliémie** : **chélateur** type **polystyrène sulfonate de sodium**, voire **dialyse** ;\n- **lavage de membre** au sérum physiologique ;\n- **soins locaux** : protection, position légèrement déclive.","cas":[{"si":"Si hyperkaliémie non contrôlée par le chélateur","alors":"**Dialyse**."}],"pieges":["Ne pas doser les CPK et la kaliémie après une revascularisation."],"src":"p. 182-183"},{"phase":"Diagnostic étiologique","title":"Bilan étiologique après revascularisation","question":"Une fois le membre sauvé, quel bilan étiologique complètes-tu ?","answer":"Après revascularisation :\n\n- **bilan cardiaque** : **Holter**, **ETT ± ETO/IRM** (source embolique) ;\n- **bilan artériel** : **échodoppler**, **angioscanner** ou **artériographie** (AOMI, anévrisme, athérome aortique).\n\nL'artériographie peropératoire aura aussi recherché **d'autres emboles**.","cas":[{"si":"Si douleur abdominale aiguë pauvre en signes physiques, vomissements/diarrhée, chez un patient en FA","alors":"Évoquer une **ischémie mésentérique aiguë** (embolie digestive) : diagnostic confirmé par **angioscanner** ; résection des segments infarcis + revascularisation."}],"pieges":["S'arrêter à la revascularisation sans rechercher la source embolique."],"src":"p. 167, 181, 187"},{"phase":"Sortie & ordonnance","title":"Traitement étiologique au long cours","question":"Quel traitement prescris-tu à la sortie ?","answer":"Traitement **étiologique** :\n\n| Mécanisme | Traitement au long cours |\n|---|---|\n| Embolie sur **fibrillation atriale** | **anticoagulation au long cours** |\n| Origine **thrombotique** (AOMI) | **antiplaquettaire** + **contrôle des facteurs de risque** (statine, arrêt du tabac…) |","cas":[],"pieges":["Oublier le traitement étiologique : anticoagulation au long cours si embolie sur fibrillation atriale."],"src":"p. 183"}]},{"title":"Anévrisme de l'aorte abdominale : de la découverte à la rupture","rank":"A","patient":"M. T., 71 ans, fumeur actif, coronarien, consulte pour un bilan systématique. Il est asymptomatique. La palpation abdominale retrouve une masse para-ombilicale battante et expansive.","steps":[{"phase":"Examen clinique","title":"Découverte d'une masse battante","question":"À la palpation abdominale, tu perçois une masse para-ombilicale battante et expansive. Qu'évoques-tu et comment définis-tu un anévrisme ?","answer":"**Anévrisme** = dilatation **localisée et durable** d'une artère, diamètre **> 50 %** de celui du segment sus-jacent, avec **perte du parallélisme** des bords.\n\n- Localisations (hors cerveau) : **aorte** (surtout **sous-rénale**), **poplitées**, **iliaques**.\n- Mécanisme : destruction des fibres élastiques et fragmentation du collagène de la média (métalloprotéases).\n\n**Forme asymptomatique** (la plus fréquente) : découverte à la **palpation** (masse battante et expansive para-ombilicale, ± souffle) ou à l'imagerie.\n\n**Dépistage échographique** recommandé chez l'**homme > 65 ans**, ou plus jeune si FDR (tabac, athérome, ATCD familiaux).\n\n**Épidémiologie** : 2–5 % des hommes > 65 ans ; entre 75–84 ans, 5 % des hommes et 3 % des femmes.","cas":[],"pieges":["Définir l'anévrisme par un diamètre absolu plutôt que par rapport au segment sus-jacent."],"src":"p. 183-184"},{"phase":"Examens complémentaires","title":"Confirmer et mesurer","question":"Quels examens demandes-tu pour confirmer et caractériser l'anévrisme ?","answer":"| Examen | Rôle |\n|---|---|\n| **Échographie abdominale** | **dépistage**, mesure du **diamètre maximal**, **suivi** ; recherche des localisations **poplitées/iliaques** |\n| **Scanner abdominopelvien injecté** | **examen préthérapeutique de référence** (diamètre, anatomie) |\n| IRM | alternative en cas de **contre-indication au scanner** |\n| Artériographie | **inutile** : ne visualise que la lumière circulante, **sous-estime** la taille en cas de thrombus mural |","cas":[{"si":"Si contre-indication au scanner injecté","alors":"**IRM**."}],"pieges":["Demander une artériographie pour mesurer un AAA."],"src":"p. 184-185"},{"phase":"Diagnostic étiologique","title":"Étiologie et lésions associées [B]","question":"Quelle est la cause la plus probable et quelles autres atteintes recherches-tu ?","answer":"- **Athérome** : **80–90 %** des cas (souvent associé à une **AOMI**, une atteinte **coronarienne** ou **carotidienne**).\n- **Formes familiales**, parfois avec maladie du tissu élastique : **Marfan**, **Ehlers-Danlos**, **Loeys-Dietz**.\n- **Aortites** : Takayasu, Horton.\n- Plus rarement **infectieuses** (syphilis, historiquement).\n\n**Autres localisations anévrismales** à rechercher : **poplitées** et **iliaques** (échographie).","cas":[{"si":"Si anévrisme poplité associé (≈ 30 % des AP ont un AAA)","alors":"Rechercher un anévrisme **controlatéral** (bilatéral dans près de la moitié des cas)."},{"si":"Si histoire familiale d'anévrisme","alors":"Forme **familiale**, parfois avec une **maladie du tissu élastique** identifiée (Marfan, Ehlers-Danlos, Loeys-Dietz)."}],"pieges":[],"src":"p. 184, 187"},{"phase":"Évaluation du risque / pronostic","title":"Risque de rupture et risque cardiovasculaire","question":"L'anévrisme mesure 44 mm. Quel est son risque évolutif ?","answer":"**Le diamètre** est le **principal facteur prédictif** de rupture :\n\n| Diamètre | Risque annuel de rupture |\n|---|---|\n| < 40 mm | ≈ **0,4 %/an** |\n| 50–59 mm | **3 %/an** |\n| > 60 mm | **15 %/an** |\n\n- Risque **≈ 4 fois plus élevé chez la femme** à diamètre égal.\n- **Croissance** moyenne **2–4 mm/an** (variable), plus rapide chez l'**homme fumeur** avec anévrisme déjà volumineux (tabagisme actif : progression **≈ 3 fois plus rapide**).\n- ≈ **12 000 décès** par rupture par an en Europe, mais le porteur d'AAA a un risque de **décès CV** (coronaire, AVC) **10 fois supérieur** à celui de rupture.","cas":[{"si":"Si femme","alors":"Risque de rupture **≈ 4 fois plus élevé** à diamètre égal."},{"si":"Si tabagisme actif","alors":"Croissance **≈ 3 fois plus rapide** : arrêt du tabac impératif."}],"pieges":["Oublier que le porteur d'AAA meurt surtout de causes cardiovasculaires, pas de la rupture."],"src":"p. 184-185"},{"phase":"Traitement spécifique","title":"Surveillance de l'AAA asymptomatique [B]","question":"Comment prends-tu en charge cet AAA asymptomatique de petit diamètre ?","answer":"- **Surveillance échographique répétée**, **renforcée tous les 6 mois** si diamètre **> 45 mm**.\n- **Contrôle des facteurs de risque** indispensable pendant le suivi (arrêt du tabac notamment).\n- Prise en charge du **risque cardiovasculaire global** (le risque de décès CV dépasse largement celui de rupture).","cas":[{"si":"Si diamètre > 45 mm","alors":"Surveillance échographique **tous les 6 mois**."}],"pieges":["Négliger l'arrêt du tabac, qui accélère la croissance de l'anévrisme."],"src":"p. 185"},{"phase":"Traitement spécifique","title":"Intervention « à froid » [B]","question":"L'anévrisme atteint 55 mm. Que proposes-tu ?","answer":"Au-delà d'un seuil de **50–55 mm** : intervention **programmée « à froid »**, précédée d'un **scanner injecté** préthérapeutique.\n\n| Technique | Principes |\n|---|---|\n| **Chirurgie conventionnelle** à ciel ouvert | exclusion de la zone anévrismale, **interposition d'une prothèse** |\n| **Traitement endovasculaire** (endoprothèse par voie fémorale) | moins invasif, préféré chez les sujets à **haut risque chirurgical** si **anatomie favorable** ; **surveillance itérative** (scanner, écho de contraste) à la recherche d'**endofuites** |","cas":[{"si":"Si patient à haut risque chirurgical avec anatomie favorable","alors":"**Endoprothèse** préférée."}],"pieges":["Poser une endoprothèse sans prévoir de surveillance au long cours des endofuites."],"src":"p. 185-186"},{"phase":"Accueil & gravité","title":"Rupture d'AAA","question":"Le patient revient aux urgences pour une douleur lombaire brutale avec une PA à 85/50 mmHg. Que fais-tu ?","answer":"**Fissuration / rupture** : douleur **abdominale ou lombaire** ± **choc hémorragique** → **urgence vitale absolue** ; la rupture intrapéritonéale est souvent **cataclysmique**.\n\n- Chez un patient **en choc** : **le scanner ne doit pas retarder l'intervention**.\n- **Traitement endovasculaire** de plus en plus proposé **même en contexte de rupture**, surtout chez le sujet à **très haut risque périopératoire**.","cas":[{"si":"Si patient en choc hémorragique","alors":"**Bloc sans délai** ; ne pas retarder par le scanner."},{"si":"Si sujet à très haut risque périopératoire","alors":"**Endoprothèse** envisageable même en urgence."}],"pieges":["Retarder l'intervention pour un scanner chez un patient en choc.","Se rassurer sur un diamètre < 50 mm : une rupture reste possible."],"src":"p. 184, 186"},{"phase":"Complications","title":"Autres modes de révélation symptomatiques","question":"En dehors de la rupture, quelles complications peuvent révéler un AAA ?","answer":"- **Fistule aorto-cave** → **insuffisance cardiaque à débit élevé** ;\n- **fistule aorto-digestive** → **hémorragie digestive** ;\n- **embolie** à partir d'une **thrombose intra-anévrismale** (ischémie aiguë de membre) ;\n- **compression** des organes de voisinage ;\n- **syndrome inflammatoire** : fièvre, altération de l'état général, élévation VS/CRP.","cas":[{"si":"Si ischémie aiguë de membre par embolie à partir de l'AAA","alors":"**Revascularisation du membre urgente** ; la cure de l'AAA est **secondaire**."}],"pieges":["Traiter l'AAA avant le membre ischémique en cas d'embolie."],"src":"p. 184, 186"},{"phase":"Suivi","title":"Suivi après traitement","question":"Comment surveilles-tu le patient après la cure de l'anévrisme ?","answer":"- **Risque cardiovasculaire persistant** : contrôle des FDR même après traitement réussi.\n- **Après chirurgie conventionnelle** : surveillance **écho-Doppler** (risque de **faux anévrisme anastomotique** ; thrombose exceptionnelle).\n- **Après endoprothèse** : surveillance **scanner/écho au long cours** à la recherche d'**endofuites** (pouvant faire progresser voire rompre l'anévrisme).\n- **Antibioprophylaxie** lors des gestes à risque bactérien (risque infectieux de la prothèse vasculaire).","cas":[{"si":"Si endoprothèse","alors":"Surveillance **itérative au long cours** (scanner, écho de contraste) des endofuites."}],"pieges":["Arrêter la surveillance après endoprothèse : une endofuite peut entraîner une rupture."],"src":"p. 186-187"},{"phase":"Diagnostic étiologique","title":"Anévrisme de l'artère poplitée","question":"L'échographie retrouve aussi une dilatation poplitée. Quelles sont ses particularités et que recherches-tu ?","answer":"- Fréquemment associé à un **AAA** (**≈ 30 %**), **bilatéral** dans près de **la moitié** des cas.\n- Découverte : **masse battante poplitée** (pouls trop bien perçu), écho-Doppler systématique (**dépistage si AAA ou AP controlatéral** connu), ou tableau d'artériopathie progressive, voire d'ischémie aiguë.","cas":[],"pieges":["Oublier de rechercher un AAA (≈ 30 %) et un anévrisme poplité controlatéral (bilatéral une fois sur deux)."],"src":"p. 186"}]}],"examens":[{"theme":"Explorations fonctionnelles","title":"Index de pression systolique (IPS)","rank":"A","content":"#### Indications\n- **Examen de 1re intention** devant une suspicion d'**AOMI**.\n\n#### Technique\n- Rapport **pression systolique de cheville / pression systolique brachiale**, mesuré au **doppler de poche**.\n\n#### Interprétation\n| IPS | Signification |\n|---|---|\n| **1,00–1,40** | normal |\n| **< 0,90** (au moins une cheville) | **AOMI** |\n| **< 0,70** | **AOMI sévère** |\n| **> 1,40** | **médiacalcose** |\n\n- Un IPS abaissé est aussi un **marqueur de risque cardiovasculaire global**.\n- **Ischémie critique** : pression de **cheville < 50 mmHg** (ou d'hallux < 30 mmHg).\n\n#### Pièges\n- **IPS > 1,40** (médiacalcose) → le remplacer par l'**index de pression d'orteil**.\n- Symptômes avec **IPS de repos normal** → **test de marche**.","src":"p. 169-171"},{"theme":"Explorations fonctionnelles","title":"Index de pression d'orteil / pression d'orteil","rank":"A","content":"#### Indications\n- **Médiacalcose** (IPS > 1,40) : remplace l'IPS.\n\n#### Interprétation\n- **Index de pression d'orteil pathologique si < 0,70**.\n- **Pression d'orteil (hallux) < 30 mmHg** = **ischémie critique**.","src":"p. 169-171"},{"theme":"Explorations fonctionnelles","title":"Test de marche sur tapis roulant (Strandness)","rank":"A","content":"#### Indications\n- **Symptômes** évocateurs avec **IPS de repos normal** : sensibilise le diagnostic d'AOMI.\n\n#### Technique\n- Tapis roulant, **protocole de Strandness** : **3,2 km/h, pente 10 %**.\n\n#### Interprétation (évocateur d'AOMI)\n- Baisse de la **pression de cheville > 30 mmHg** après l'effort.\n- Baisse de l'**IPS > 20 %** après l'effort.","src":"p. 171"},{"theme":"Explorations fonctionnelles","title":"Test de marche de 6 minutes","rank":"A","content":"#### Indications\n- Évaluer le **handicap fonctionnel global**.\n\n#### Limites\n- **Non spécifique**.","src":"p. 171"},{"theme":"Explorations fonctionnelles","title":"Pression transcutanée en oxygène (TcPO2)","rank":"A","content":"#### Indications\n- **Ischémie critique** (mesure après hyperémie).\n- Guide le niveau d'**amputation** (zone saine et bien oxygénée).\n\n#### Interprétation (dos du pied)\n| TcPO2 | Signification |\n|---|---|\n| **> 50 mmHg** | normale |\n| > 35 mmHg | bonne compensation |\n| 10–35 mmHg | hypoxie continue |\n| **< 10 mmHg** | **hypoxie critique** |","src":"p. 171-172, 176"},{"theme":"Imagerie","title":"Échodoppler artériel des membres inférieurs","rank":"A","content":"#### Indications\n- **Examen d'imagerie de 1re intention** de l'AOMI : **non invasif**, **localise et quantifie** les sténoses.\n- **Surveillance systématique après revascularisation** (avec la clinique).\n- **Ischémie aiguë** : réalisable **sans perte de temps** si le tableau le permet (**grade I sans atteinte neurologique**) ; bilan artériel étiologique **après revascularisation**.\n- **Anévrisme poplité** : découverte par écho-Doppler systématique ; **dépistage si AAA ou AP controlatéral** connu.\n- **Après chirurgie conventionnelle d'AAA** : surveillance (faux anévrisme anastomotique, thrombose exceptionnelle).\n\n#### Pièges\n- En ischémie aiguë avec **déficit neurologique** (grade II), **aucune exploration ne doit retarder** l'intervention.","src":"p. 172, 176, 180-182, 186-187"},{"theme":"Imagerie","title":"Angioscanner des membres inférieurs","rank":"A","content":"#### Indications\n- **Uniquement en vue d'une revascularisation** (AOMI).\n- **Ischémie aiguë** : bilan artériel étiologique **après revascularisation** (ou artériographie).\n\n#### Performances\n- Sensibilité/spécificité **≈ 95 %** vs artériographie.","src":"p. 172-173, 181-182"},{"theme":"Imagerie","title":"Angio-IRM / IRM","rank":"A","content":"#### Indications\n- **AOMI** : **uniquement en vue d'une revascularisation**.\n- **Ischémie mésentérique chronique** : diagnostic (avec écho-Doppler digestif, angioscanner).\n- **AAA** : **alternative** en cas de **contre-indication au scanner**.\n- **Ischémie aiguë** : bilan cardiaque après revascularisation (**ETT ± ETO/IRM**).\n\n#### Performances / limites\n- Sensibilité/spécificité **≈ 95 %** vs artériographie.\n- **Ne visualise pas les calcifications** (utiles au chirurgien).\n\n#### Contre-indications\n- **Gadolinium contre-indiqué** si clairance **< 30 mL/min/1,73 m²**.","src":"p. 166, 172-173, 182, 185"},{"theme":"Imagerie","title":"Artériographie","rank":"A","content":"#### Indications\n- **AOMI** : **réservée aux procédures de revascularisation**, notamment pour le **réseau jambier et pédieux**.\n- **Ischémie aiguë** : le plus souvent **au bloc** pour guider le geste (localisation, aspect de l'occlusion, qualité du réseau d'aval) et **dépister d'autres emboles** ; contrôle de l'embolectomie (**sous contrôle angiographique**) ; contrôles répétés en thrombolyse in situ.\n- **Ischémie mésentérique chronique** : réalisée **seulement pour un geste endovasculaire**.\n\n#### Limites\n- **AAA** : **pas utile** — ne visualise que la **lumière circulante** et **sous-estime la taille** en cas de **thrombus mural**.","src":"p. 166, 173, 180-182, 185"},{"theme":"Imagerie","title":"Angioscanner abdominal (artères digestives)","rank":"A","content":"#### Indications\n- **Ischémie mésentérique aiguë** : examen qui **confirme le diagnostic**.\n- **Ischémie mésentérique chronique** : diagnostic (avec écho-Doppler digestif, angio-IRM).","src":"p. 166"},{"theme":"Imagerie","title":"Écho-Doppler digestif","rank":"A","content":"#### Indications\n- Diagnostic de l'**ischémie mésentérique chronique** (sténose du tronc cœliaque et/ou des artères mésentériques), avec angioscanner ou angio-IRM.","src":"p. 166"},{"theme":"Imagerie","title":"Échographie abdominale (AAA)","rank":"A","content":"#### Indications\n- **Dépistage** : recommandé chez l'**homme > 65 ans**, ou plus jeune si facteurs de risque (tabac, athérome, antécédents familiaux).\n- **Mesure du diamètre maximal** et **suivi** de l'AAA ; recherche des localisations **poplitées/iliaques** associées.\n\n#### Rythme de surveillance [B]\n- Surveillance échographique répétée, **renforcée tous les 6 mois** si diamètre **> 45 mm**.\n- Intervention « à froid » au-delà de **50–55 mm**.\n\n#### Interprétation (risque annuel de rupture)\n| Diamètre | Rupture/an |\n|---|---|\n| < 40 mm | ≈ 0,4 % |\n| 50–59 mm | 3 % |\n| > 60 mm | 15 % |\n\n- Risque **≈ 4 fois plus élevé chez la femme** à diamètre égal.\n- Croissance moyenne **2–4 mm/an** ; environ **3 fois plus rapide** en cas de tabagisme actif.","src":"p. 184-186"},{"theme":"Imagerie","title":"Scanner abdominopelvien injecté (angioscanner aortique)","rank":"A","content":"#### Indications\n- **Examen préthérapeutique de référence** de l'AAA (diamètre, anatomie).\n- **Surveillance après endoprothèse** (scanner, écho de contraste) : recherche d'**endofuites**.\n- AAA **rompu** (urgence absolue) : le scanner confirme le diagnostic mais **ne doit pas retarder l'intervention** chez un patient **en choc**.\n\n#### Contre-indications\n- En cas de contre-indication au scanner → **IRM**.","src":"p. 185-186"},{"theme":"ECG & explorations électriques","title":"ECG et Holter (ischémie aiguë de membre)","rank":"A","content":"#### Indications\n- **ECG** : **bilan étiologique systématique** d'une ischémie aiguë (avec auscultation cardiaque, palpation abdominale, bilan de coagulation).\n- **Holter** : bilan cardiaque **après revascularisation**.\n\n#### Ce qu'on recherche\n- Cause **emboligène** : **fibrillation atriale** (principale cause cardiaque d'embolie artérielle des membres).","src":"p. 181-182"},{"theme":"Imagerie","title":"Échocardiographie (ETT ± ETO) – ischémie aiguë de membre","rank":"A","content":"#### Indications\n- **Bilan cardiaque après revascularisation** d'une ischémie aiguë : **ETT ± ETO/IRM**.\n\n#### Ce qu'on recherche (causes cardiaques d'embolie)\n- Foramen ovale perméable / anévrisme du septum, infarctus avec faux anévrisme, endocardite, valvulopathies/prothèses, **myxome de l'atrium**, anévrisme/dyskinésie du VG.","src":"p. 181-182"},{"theme":"Biologie","title":"Bilan de coagulation et TCA sous héparine","rank":"A","content":"#### Indications\n- **Bilan de coagulation** : partie du bilan étiologique systématique de l'ischémie aiguë ; **prélevé avant** l'anticoagulation.\n- **Surveillance** de l'HNF.\n\n#### Protocole\n- **HNF** dès le diagnostic : **bolus 5000 UI** puis **perfusion 500 UI/kg/j**.\n- **TCA cible entre 2 et 3**.","src":"p. 182"},{"theme":"Biologie","title":"Surveillance métabolique (syndrome de revascularisation)","rank":"A","content":"#### Indications\n- Ischémie aiguë, notamment après **reperfusion** : surveillance de la **diurèse** (sonde urinaire), **ionogramme**, **urée**, **créatininémie**, **CPK**.\n\n#### Ce qu'on recherche\n- **Hyperkaliémie**, **acidose métabolique**, hyperuricémie, **myoglobinémie/myoglobinurie**, hypocalcémie, hyperphosphorémie, voire **CIVD**.\n- **Insuffisance rénale aiguë** (nécrose tubulaire) ; **rhabdomyolyse** (cellules musculaires dès 6–8 h).\n\n#### Conséquences\n- Correction de l'acidose (**bicarbonates IV**), de l'hyperkaliémie (chélateur type **polystyrène sulfonate de sodium**, voire **dialyse**), lavage de membre au sérum physiologique.","src":"p. 178, 183"},{"theme":"Biologie","title":"Cibles biologiques de l'AOMI (HbA1c, LDL-C)","rank":"A","content":"#### Cibles\n- **HbA1c < 7 %**.\n- **LDL-cholestérol < 0,55 g/L (< 1,4 mmol/L)** avec réduction **≥ 50 %** sous **statine** systématique.","src":"p. 175"},{"theme":"Biologie","title":"VS / CRP (AAA inflammatoire)","rank":"A","content":"#### Interprétation\n- Un AAA peut se révéler par un **syndrome inflammatoire** : fièvre, altération de l'état général, **élévation de la VS/CRP**.","src":"p. 184"},{"theme":"Gestes & procédures","title":"Angioplastie endovasculaire des membres inférieurs","rank":"A","content":"#### Indications\n- Revascularisation **systématiquement proposée** en **ischémie permanente** ; **discutée** en **claudication sévère invalidante** (périmètre < 100 m), notamment après échec du traitement médical.\n- Lésions **courtes/proximales**.\n- Ischémie aiguë : angioplastie **complémentaire** en cas de **sténose résiduelle**.\n\n#### Modalités\n- **± stent**, **bithérapie antiplaquettaire 1 à 6 mois**.\n- **Surveillance clinique et écho-Doppler systématique** après le geste.","src":"p. 176, 182"},{"theme":"Gestes & procédures","title":"Revascularisation chirurgicale (pontage, endartériectomie)","rank":"A","content":"#### Indications\n- **Lésions étendues** (AOMI) ; techniques **hybrides** possibles.\n- Ischémie aiguë : **pontage** (souvent distal) **en dernier recours**.\n\n#### Modalités\n- **Pontage veineux ou prothétique**, **endartériectomie**.\n- **Surveillance clinique et écho-Doppler systématique** après le geste.","src":"p. 176, 182, 187"},{"theme":"Gestes & procédures","title":"Embolectomie à la sonde de Fogarty","rank":"A","content":"#### Indications\n- **Méthode de référence** de l'ischémie aiguë par **embolie sur artère saine** (utilisable aussi sur artère athéromateuse).\n\n#### Modalités\n- **Sous contrôle angiographique**.","src":"p. 182"},{"theme":"Gestes & procédures","title":"Thrombolyse in situ / thromboaspiration","rank":"A","content":"#### Indications\n- Ischémie aiguë avec **lit d'aval de mauvaise qualité** et ischémie **peu sévère**.\n\n#### Précautions\n- **Surveillance spécialisée**, **contrôles angiographiques répétés**.","src":"p. 182"},{"theme":"Gestes & procédures","title":"Aponévrotomie de décompression","rank":"A","content":"#### Indications\n- **Syndrome des loges** (œdème musculaire dans des loges aponévrotiques inextensibles).\n- **Systématique** en cas de **revascularisation tardive**, pour prévenir le syndrome des loges.\n\n#### Modalités\n- Loge **antéro-externe de jambe** en général.","src":"p. 178, 183"},{"theme":"Gestes & procédures","title":"Amputation","rank":"A","content":"#### Indications\n- **AOMI** : **en dernier recours**.\n- **Ischémie aiguë** : **d'emblée** si ischémie **dépassée** ; **secondairement** si échec de revascularisation / désordres métaboliques majeurs.\n\n#### Modalités\n- En **zone saine et bien oxygénée**, guidée par la **TcPO2**.","src":"p. 176, 179, 183"},{"theme":"Gestes & procédures","title":"Chirurgie conventionnelle de l'AAA","rank":"B","content":"#### Indications\n- AAA asymptomatique au-delà de **50–55 mm** : intervention « à froid ».\n\n#### Modalités\n- À ciel ouvert : **exclusion de la zone anévrismale**, **interposition d'une prothèse**.\n\n#### Complications / suivi\n- Surveillance **écho-Doppler** : **faux anévrisme anastomotique**, thrombose exceptionnelle.\n- Risque **infectieux** de la prothèse → **antibioprophylaxie** lors des gestes à risque bactérien.","src":"p. 185-187"},{"theme":"Gestes & procédures","title":"Endoprothèse aortique (traitement endovasculaire de l'AAA)","rank":"B","content":"#### Indications\n- AAA > **50–55 mm** : **moins invasif**, préféré chez les sujets **à haut risque chirurgical** si l'**anatomie est favorable**.\n- De plus en plus proposé **même en contexte de rupture**, surtout chez le sujet à très haut risque périopératoire.\n\n#### Modalités\n- **Voie fémorale**.\n\n#### Complications / suivi\n- Surveillance **itérative au long cours** (**scanner**, **écho de contraste**) à la recherche d'**endofuites**, pouvant faire progresser voire **rompre** l'anévrisme.\n- Antibioprophylaxie lors des gestes à risque bactérien (prothèse vasculaire).","src":"p. 185-187"},{"theme":"Gestes & procédures","title":"Revascularisation des artères digestives","rank":"A","content":"#### Indications\n- **Ischémie mésentérique chronique** symptomatique : revascularisation **de préférence endovasculaire**.\n- **Ischémie mésentérique aiguë** : **résection** des segments intestinaux infarcis + revascularisation (**endovasculaire ou chirurgicale**).","src":"p. 166-167, 187"}]}});
